package com.bautopilot.baautopilot.model;

/**
 * Per-wave penance counts and healer hit points (OSRS Wiki, Barbarian Assault/Strategies and
 * Advanced strategies). Index 0 is unused so a wave number indexes directly.
 */
public final class WaveInfo
{
	public static final int TICKS_PER_CALL = 50;
	public static final int POISON_INTERVAL_TICKS = 5;
	public static final int FOOD_DAMAGE = 4;

	private static final int[] HEALER_HP = {0, 27, 32, 37, 43, 49, 55, 60, 67, 76, 60};
	private static final int[] HEALERS_INITIAL = {0, 2, 3, 2, 3, 4, 4, 4, 5, 6, 4};
	private static final int[] HEALERS_TOTAL = {0, 2, 3, 3, 4, 5, 6, 7, 7, 8, 7};
	private static final int[] RUNNERS_INITIAL = {0, 2, 2, 2, 3, 4, 4, 5, 5, 5, 5};
	private static final int[] RUNNERS_TOTAL = {0, 2, 3, 4, 4, 5, 6, 6, 7, 9, 6};
	/** Out at once (OSRS Wiki wave table "initial+reserves"); the reserves come only after kills. */
	private static final int[] FIGHTERS_INITIAL = {0, 2, 2, 5, 5, 3, 5, 5, 7, 6, 5};
	private static final int[] RANGERS_INITIAL = {0, 2, 3, 3, 3, 5, 5, 6, 5, 7, 6};
	private static final int[] FIGHTERS_TOTAL = {0, 4, 5, 5, 6, 6, 6, 7, 7, 8, 7};
	private static final int[] RANGERS_TOTAL = {0, 4, 4, 6, 6, 6, 7, 7, 8, 8, 7};
	/** Logs the defender should carry: 2 until wave 4, then 4. */
	private static final int[] DEFENDER_LOGS = {0, 2, 2, 2, 2, 4, 4, 4, 4, 4, 4};

	private WaveInfo()
	{
	}

	public static boolean valid(int wave)
	{
		return wave >= 1 && wave <= 10;
	}

	public static int healerHp(int wave)
	{
		return valid(wave) ? HEALER_HP[wave] : 0;
	}

	public static int healersInitial(int wave)
	{
		return valid(wave) ? HEALERS_INITIAL[wave] : 0;
	}

	public static int healersTotal(int wave)
	{
		return valid(wave) ? HEALERS_TOTAL[wave] : 0;
	}

	public static int runnersInitial(int wave)
	{
		return valid(wave) ? RUNNERS_INITIAL[wave] : 0;
	}

	public static int runnersTotal(int wave)
	{
		return valid(wave) ? RUNNERS_TOTAL[wave] : 0;
	}

	public static int fightersTotal(int wave)
	{
		return valid(wave) ? FIGHTERS_TOTAL[wave] : 0;
	}

	public static int rangersTotal(int wave)
	{
		return valid(wave) ? RANGERS_TOTAL[wave] : 0;
	}

	/** Out at once for a penance type this wave (the rest are reserves, out only after kills). */
	public static int initial(PenanceType type, int wave)
	{
		if (!valid(wave))
		{
			return 0;
		}
		switch (type)
		{
			case FIGHTER:
				return FIGHTERS_INITIAL[wave];
			case RANGER:
				return RANGERS_INITIAL[wave];
			case RUNNER:
				return RUNNERS_INITIAL[wave];
			default:
				return HEALERS_INITIAL[wave];
		}
	}

	public static int total(PenanceType type, int wave)
	{
		switch (type)
		{
			case FIGHTER:
				return fightersTotal(wave);
			case RANGER:
				return rangersTotal(wave);
			case RUNNER:
				return runnersTotal(wave);
			default:
				return healersTotal(wave);
		}
	}

	public static int defenderLogs(int wave)
	{
		return valid(wave) ? DEFENDER_LOGS[wave] : 2;
	}

	/** Gau Cho's log counts (User:Gau Cho/Defender): 0, 1 x3, 2 x3, 3, 4, then 2 on wave 10. */
	private static final int[] GAU_CHO_LOGS = {0, 0, 1, 1, 1, 2, 2, 2, 3, 4, 2};

	public static int defenderLogs(int wave, DefenderGuide guide)
	{
		if (guide.isGauCho())
		{
			return valid(wave) ? GAU_CHO_LOGS[wave] : 1;
		}
		return defenderLogs(wave);
	}

	/**
	 * Total poison damage one food deals when it is never topped up: 4 on use, then 20 hits
	 * every 5 ticks of 4,4,4,4,4,3,3,3,3,3,2,...,1 = 50.
	 */
	public static int fullPoisonDamage()
	{
		return FOOD_DAMAGE + 5 * (4 + 3 + 2 + 1);
	}

	/** Damage of the n-th (1-based) poison hit after the last food. */
	public static int poisonHit(int n)
	{
		if (n < 1 || n > 20)
		{
			return 0;
		}
		return 4 - (n - 1) / 5;
	}

	/**
	 * Advanced-strategies kill order for attackers: which type to finish next given how many
	 * fighters and rangers have died so far. Wave 1 alternates starting with a fighter; wave 2
	 * kills two fighters then alternates ranger-fighter; wave 3 alternates ranger-fighter; wave 4+
	 * alternates fighter-ranger.
	 */
	public static PenanceType attackerNext(int wave, int kills)
	{
		switch (wave)
		{
			case 1:
				return kills % 2 == 0 ? PenanceType.FIGHTER : PenanceType.RANGER;
			case 2:
				if (kills < 2)
				{
					return PenanceType.FIGHTER;
				}
				return (kills - 2) % 2 == 0 ? PenanceType.RANGER : PenanceType.FIGHTER;
			case 3:
				return kills % 2 == 0 ? PenanceType.RANGER : PenanceType.FIGHTER;
			default:
				return kills % 2 == 0 ? PenanceType.FIGHTER : PenanceType.RANGER;
		}
	}
}

package com.bautopilot.baautopilot.overlay;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * The box's main line, to read at a glance: the item to use, large, then the step's tag as a
 * chip in the action's colour and the instruction after it ("[LOAD] your eggs into the hopper"),
 * wrapping beside the icon.
 */
class ActionRow implements LayoutableRenderableEntity
{
	private static final int ICON = 30;
	private static final int ICON_GAP = 7;
	private static final int CHIP_PAD = 4;
	private static final Color ICON_BACKING = new Color(255, 255, 255, 40);

	private final BufferedImage icon;
	private final String tag;
	private final String text;
	private final Color colour;

	@Getter
	private final Rectangle bounds = new Rectangle();
	@Setter
	private Point preferredLocation = new Point();
	@Setter
	private Dimension preferredSize = new Dimension(200, 0);

	ActionRow(BufferedImage icon, String tag, String text, Color colour)
	{
		this.icon = icon;
		this.tag = tag;
		this.text = text;
		this.colour = colour;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Font bold = FontManager.getRunescapeBoldFont();
		Font small = FontManager.getRunescapeSmallFont();
		FontMetrics fm = g.getFontMetrics(bold);
		FontMetrics sm = g.getFontMetrics(small);
		int x0 = preferredLocation.x;
		int y0 = preferredLocation.y;
		int textX = x0;
		if (icon != null)
		{
			BufferedImage img = IconRow.trimmed(icon);
			float scale = Math.min(ICON / (float) Math.max(1, img.getWidth()), ICON / (float) Math.max(1, img.getHeight()));
			int w = Math.max(1, Math.round(img.getWidth() * scale));
			int h = Math.max(1, Math.round(img.getHeight() * scale));
			g.setColor(ICON_BACKING);
			g.fillRoundRect(x0, y0, ICON + 4, ICON + 4, 9, 9);
			g.drawImage(img, x0 + 2 + (ICON - w) / 2, y0 + 2 + (ICON - h) / 2, w, h, null);
			textX = x0 + ICON + 4 + ICON_GAP;
		}
		int right = x0 + preferredSize.width;
		int line = fm.getHeight() + 1;

		// The tag chip starts the first line; the words flow after it and wrap under the text column
		int x = textX;
		int y = y0;
		if (tag != null && !tag.isEmpty())
		{
			int cw = sm.stringWidth(tag) + 2 * CHIP_PAD;
			int ch = sm.getAscent() + 4;
			int cy = y + (line - ch) / 2;
			g.setColor(colour);
			g.fillRoundRect(x, cy, cw, ch, 5, 5);
			g.setFont(small);
			g.setColor(new Color(20, 16, 10));
			g.drawString(tag, x + CHIP_PAD, cy + ch - 3);
			x += cw + 5;
		}
		g.setFont(bold);
		int space = fm.stringWidth(" ");
		for (String word : wordsOf(text))
		{
			int w = fm.stringWidth(word);
			if (x > textX && x + w > right)
			{
				x = textX;
				y += line;
			}
			int base = y + (line + fm.getAscent() - fm.getDescent()) / 2;
			g.setColor(Color.BLACK);
			g.drawString(word, x + 1, base + 1);
			g.setColor(Palette.CREAM);
			g.drawString(word, x, base);
			x += w + space;
		}
		int height = Math.max(icon == null ? 0 : ICON + 4, y - y0 + line);
		bounds.setLocation(preferredLocation);
		bounds.setSize(preferredSize.width, height);
		return new Dimension(preferredSize.width, height);
	}

	private static List<String> wordsOf(String text)
	{
		List<String> out = new ArrayList<>();
		if (text != null)
		{
			for (String w : text.split(" "))
			{
				if (!w.isEmpty())
				{
					out.add(w);
				}
			}
		}
		return out;
	}
}

package com.bautopilot.baautopilot.overlay;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/** Small pieces of the box: the gold divider and the thin call-timer bar. */
final class BoxParts
{
	private BoxParts()
	{
	}

	/** A gold line across the box with a dark line under it, like the game's interfaces. */
	static LayoutableRenderableEntity divider()
	{
		return new Part(3)
		{
			@Override
			void draw(Graphics2D g, int x, int y, int w)
			{
				g.setColor(Palette.GOLD_EDGE);
				g.drawLine(x, y + 1, x + w - 1, y + 1);
				g.setColor(Palette.DARK_EDGE);
				g.drawLine(x, y + 2, x + w - 1, y + 2);
			}
		};
	}

	/** How much of the call is left, as a thin bar; red when nearly over. */
	static LayoutableRenderableEntity timer(double left, boolean late)
	{
		return new Part(5)
		{
			@Override
			void draw(Graphics2D g, int x, int y, int w)
			{
				g.setColor(Palette.DARK_EDGE);
				g.fillRect(x, y + 1, w, 4);
				g.setColor(late ? Palette.BAD : new Color(80, 150, 230));
				g.fillRect(x, y + 1, (int) Math.round(w * Math.max(0, Math.min(1, left))), 4);
			}
		};
	}

	private abstract static class Part implements LayoutableRenderableEntity
	{
		private final int height;
		@Getter
		private final Rectangle bounds = new Rectangle();
		@Setter
		private Point preferredLocation = new Point();
		@Setter
		private Dimension preferredSize = new Dimension(200, 0);

		Part(int height)
		{
			this.height = height;
		}

		abstract void draw(Graphics2D g, int x, int y, int w);

		@Override
		public Dimension render(Graphics2D g)
		{
			draw(g, preferredLocation.x, preferredLocation.y, preferredSize.width);
			bounds.setLocation(preferredLocation);
			bounds.setSize(preferredSize.width, height);
			return new Dimension(preferredSize.width, height);
		}
	}
}

package com.bautopilot.baautopilot.overlay;

import com.bautopilot.baautopilot.model.DefenderGuide;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.model.WaveInfo;
import com.bautopilot.baautopilot.plan.Instruction;
import com.bautopilot.baautopilot.plan.Target;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import java.awt.Color;
import java.awt.Font;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.function.IntFunction;
import net.runelite.client.ui.FontManager;

/**
 * Live numbers inside the instruction box, only what your role acts on (one box, not two):
 * <ul>
 * <li>attacker: damage per second (you / team) and a row per fighter and ranger: HP %, damage per
 * second on it, seconds to kill, your share; the current target marked;</li>
 * <li>collector: eggs loaded in the launcher per colour (out of 5), omega when there is one;</li>
 * <li>defender: trap charges, logs taken of the wave's target, bait held per kind.</li>
 * </ul>
 * The healer's vial and healer table are drawn by the box itself.
 */
final class CombatRows
{
	private static final int MAX_ROWS = 6;

	private CombatRows()
	{
	}

	static List<IconRow> rows(Snapshot s, Instruction ins, IntFunction<BufferedImage> items, DefenderGuide guide)
	{
		List<IconRow> out = new ArrayList<>();
		if (s.getRole() == null)
		{
			return out;
		}
		Font bold = FontManager.getRunescapeBoldFont();
		switch (s.getRole())
		{
			case COLLECTOR:
				out.add(launcher(s, items, bold));
				out.add(carrying(s, items, bold));
				break;
			case DEFENDER:
				out.add(defender(s, items, bold, guide));
				break;
			case ATTACKER:
				out.add(new IconRow()
					.text("DPS", Palette.MUTED)
					.group().text("you " + oneDecimal(s.getMyDps()), s.getMyDps() > 0 ? Palette.TEXT : Palette.MUTED, bold)
					.group().text("team " + oneDecimal(s.getTeamDps()), Palette.TEXT)
					.right(s.getMyDamage() + " dmg", Palette.MUTED));
				penance(out, s, ins, bold, PenanceType.FIGHTER, PenanceType.RANGER);
				break;
			default:
				break;
		}
		return out;
	}

	/**
	 * The eggs you carry, inventory and bag together (loading empties both), and the free slots:
	 * kept in view instead of the explanation lines that used to spell them out.
	 */
	private static IconRow carrying(Snapshot s, IntFunction<BufferedImage> items, Font bold)
	{
		IconRow row = new IconRow().text("Carrying", Palette.MUTED);
		int[][] eggs = {
			{BaIds.EGG_RED, s.count(BaIds.EGG_RED) + s.getBagRed()},
			{BaIds.EGG_GREEN, s.count(BaIds.EGG_GREEN) + s.getBagGreen()},
			{BaIds.EGG_BLUE, s.count(BaIds.EGG_BLUE) + s.getBagBlue()}};
		for (int[] egg : eggs)
		{
			row.group().icon(items.apply(egg[0])).text(String.valueOf(egg[1]), egg[1] > 0 ? Palette.TEXT : Palette.MUTED, egg[1] > 0 ? bold : null);
		}
		int free = s.getFreeSlots();
		return row.right(free + " free", free <= 3 ? Palette.BAD : Palette.MUTED);
	}

	private static IconRow launcher(Snapshot s, IntFunction<BufferedImage> items, Font bold)
	{
		IconRow row = new IconRow().text("Launcher", Palette.MUTED)
			.group().icon(items.apply(BaIds.EGG_RED)).text(s.getEggsRed() + "/5", eggColour(s.getEggsRed()), bold)
			.group().icon(items.apply(BaIds.EGG_GREEN)).text(s.getEggsGreen() + "/5", eggColour(s.getEggsGreen()), bold);
		if (s.getEggsOmega() > 0)
		{
			row.group().icon(items.apply(BaIds.EGG_OMEGA)).text(String.valueOf(s.getEggsOmega()), Palette.GOOD, bold);
		}
		return row;
	}

	private static IconRow defender(Snapshot s, IntFunction<BufferedImage> items, Font bold, DefenderGuide guide)
	{
		IconRow row = new IconRow();
		int charges = s.getTrapCharges();
		if (charges >= 0)
		{
			row.text("Trap", Palette.MUTED).text(charges + "/2", charges == 0 ? Palette.BAD : charges == 1 ? Palette.OK : Palette.GOOD, bold);
		}
		int want = WaveInfo.defenderLogs(s.getWave(), guide);
		int taken = Math.max(s.getLogsTaken(), s.count(BaIds.LOGS));
		row.group().icon(items.apply(BaIds.LOGS)).text(taken + "/" + want, taken >= want ? Palette.TEXT : Palette.OK, bold);
		BaCall call = s.getListenCall();
		for (BaCall bait : new BaCall[]{BaCall.BAIT_TOFU, BaCall.BAIT_CRACKERS, BaCall.BAIT_WORMS})
		{
			int n = s.count(bait.getItemId());
			boolean called = call == bait;
			row.group().icon(items.apply(bait.getItemId()))
				.text(String.valueOf(n), n == 0 ? Palette.BAD : called ? Palette.GOOD : Palette.TEXT, called ? bold : null);
		}
		return row;
	}

	private static void penance(List<IconRow> out, Snapshot s, Instruction ins, Font bold, PenanceType... types)
	{
		int target = ins != null && ins.getTarget().getKind() == Target.Kind.NPC ? ins.getTarget().getId() : -1;
		List<PenanceView> list = new ArrayList<>();
		for (PenanceType type : types)
		{
			List<PenanceView> of = s.alive(type);
			of.sort(Comparator.comparing(PenanceView::isUnseen).thenComparingDouble(PenanceView::hpFraction));
			list.addAll(of);
		}
		int shown = 0;
		for (PenanceView p : list)
		{
			if (shown++ == MAX_ROWS)
			{
				out.add(new IconRow().text("+" + (list.size() - MAX_ROWS) + " more", Palette.MUTED));
				break;
			}
			out.add(row(p, p.getNpcIndex() == target, bold));
		}
	}

	private static IconRow row(PenanceView p, boolean target, Font bold)
	{
		Color name = p.isUnseen() ? Palette.MUTED : Palette.role(Role.ATTACKER);
		IconRow row = new IconRow().text((target ? "▶ " : "") + (p.getType() == PenanceType.FIGHTER ? "Fighter" : "Ranger"),
			name, target ? bold : null);
		row.group().text(Math.round(p.hpFraction() * 100) + "%", p.isUnseen() ? Palette.MUTED : hpColour(p.hpFraction()), bold);
		if (p.getDps() > 0)
		{
			row.group().text(oneDecimal(p.getDps()) + "/s", Palette.TEXT);
		}
		double eta = p.secondsToKill();
		if (eta >= 0)
		{
			row.group().text("~" + Math.round(eta) + "s", Palette.MUTED);
		}
		if (p.isUnseen())
		{
			row.right("out of view", Palette.MUTED);
		}
		else if (p.getDamageTaken() > 0)
		{
			row.right("you " + Math.round(100.0 * p.getDamageMine() / p.getDamageTaken()) + "%", Palette.MUTED);
		}
		return row;
	}

	private static Color hpColour(double fraction)
	{
		return fraction > 0.6 ? Palette.GOOD : fraction > 0.3 ? Palette.OK : Palette.BAD;
	}

	private static Color eggColour(int loaded)
	{
		// Empty: nothing to fire. One left: the next shot empties it
		return loaded == 0 ? Palette.BAD : loaded == 1 ? Palette.OK : Palette.TEXT;
	}

	private static String oneDecimal(double v)
	{
		return String.format(Locale.ROOT, "%.1f", v);
	}
}

package com.bautopilot.baautopilot.overlay;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * One overlay line of icons and short texts, left to right, e.g. [egg] 24 [bag] 4 [crosshair] 1.
 * Item sprites are drawn scaled to the line height; an item image that is still loading simply
 * draws once it arrives.
 */
public class IconRow implements LayoutableRenderableEntity
{
	static final int ICON = 20;
	/** Light rounded backing behind item sprites, so dark items read on the dark box. */
	private static final Color ICON_BACKING = new Color(255, 255, 255, 46);
	/** Sprites at least this big are items (symbols are drawn smaller and get no backing). */
	private static final int ITEM_MIN = 16;
	private static final int GAP = 3;
	private static final int GROUP_GAP = 7;
	/**
	 * Item sprites trimmed to their visible pixels (game item images are 36x32 with a wide clear
	 * border, which made each icon take far more room than it shows). Only cached once loaded.
	 */
	private static final java.util.Map<BufferedImage, BufferedImage> TRIMMED = new java.util.WeakHashMap<>();

	private static final class Segment
	{
		final BufferedImage image;
		final int size;
		final String text;
		final Color color;
		final Font font;
		final boolean groupStart;

		Segment(BufferedImage image, int size, String text, Color color, Font font, boolean groupStart)
		{
			this.image = image;
			this.size = size;
			this.text = text;
			this.color = color;
			this.font = font;
			this.groupStart = groupStart;
		}
	}

	private final List<Segment> segments = new ArrayList<>();
	private boolean nextStartsGroup;
	/** Text-only rows as tall as their font, not an icon: for tables of small numbers. */
	private boolean tight;
	private String right;
	private Color rightColor;

	@Getter
	private final Rectangle bounds = new Rectangle();
	@Setter
	private Point preferredLocation = new Point();
	@Setter
	private Dimension preferredSize = new Dimension(200, 0);

	/** Continues at least this far from the left edge, so rows line up in a column. */
	public IconRow column(int x)
	{
		segments.add(new Segment(null, x, null, null, null, false));
		return this;
	}

	/** Lines as tall as the text (no icons on this row). */
	public IconRow tight()
	{
		tight = true;
		return this;
	}

	/** Starts a new visual group (wider gap before it). */
	public IconRow group()
	{
		nextStartsGroup = !segments.isEmpty();
		return this;
	}

	public IconRow icon(BufferedImage image)
	{
		return icon(image, ICON);
	}

	public IconRow icon(BufferedImage image, int size)
	{
		if (image != null)
		{
			segments.add(new Segment(image, size, null, null, null, take()));
		}
		return this;
	}

	public IconRow text(String text, Color color)
	{
		return text(text, color, null);
	}

	public IconRow text(String text, Color color, Font font)
	{
		if (text != null && !text.isEmpty())
		{
			segments.add(new Segment(null, 0, text, color, font, take()));
		}
		return this;
	}

	/** Right-aligned text at the end of the line. */
	public IconRow right(String text, Color color)
	{
		right = text;
		rightColor = color;
		return this;
	}

	public boolean isEmpty()
	{
		return segments.isEmpty() && right == null;
	}

	/** The image cut down to its non-transparent pixels; the original while it is still loading. */
	static BufferedImage trimmed(BufferedImage image)
	{
		BufferedImage cached = TRIMMED.get(image);
		if (cached != null)
		{
			return cached;
		}
		int w = image.getWidth();
		int h = image.getHeight();
		int minX = w;
		int minY = h;
		int maxX = -1;
		int maxY = -1;
		for (int yy = 0; yy < h; yy++)
		{
			for (int xx = 0; xx < w; xx++)
			{
				if ((image.getRGB(xx, yy) >>> 24) > 16)
				{
					minX = Math.min(minX, xx);
					minY = Math.min(minY, yy);
					maxX = Math.max(maxX, xx);
					maxY = Math.max(maxY, yy);
				}
			}
		}
		if (maxX < 0)
		{
			// Not loaded yet (or empty): try again next frame
			return image;
		}
		BufferedImage out = image.getSubimage(minX, minY, maxX - minX + 1, maxY - minY + 1);
		TRIMMED.put(image, out);
		return out;
	}

	/** Width of the group starting at {@code from} when it has an icon (icon groups are short); 0 for text groups. */
	private int iconGroupWidth(Graphics2D g, Font base, int from)
	{
		int width = 0;
		boolean icon = false;
		for (int i = from; i < segments.size(); i++)
		{
			Segment s = segments.get(i);
			if (i > from && s.groupStart)
			{
				break;
			}
			if (s.image != null)
			{
				icon = true;
				width += s.size + GAP;
			}
			else if (s.text != null)
			{
				width += g.getFontMetrics(s.font != null ? s.font : base).stringWidth(s.text) + GAP;
			}
		}
		return icon ? width : 0;
	}

	private boolean take()
	{
		boolean g = nextStartsGroup;
		nextStartsGroup = false;
		return g;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		// The regular RuneScape font, not the small one: easier to read at a glance
		Font base = net.runelite.client.ui.FontManager.getRunescapeFont();
		g.setFont(base);
		FontMetrics fm = g.getFontMetrics(base);
		int lineHeight = tight ? fm.getHeight() - 2 : Math.max(ICON, fm.getHeight()) + 2;
		int left = preferredLocation.x;
		int maxX = left + preferredSize.width;
		int x = left;
		int y = preferredLocation.y;
		for (int i = 0; i < segments.size(); i++)
		{
			Segment s = segments.get(i);
			if (s.image == null && s.text == null)
			{
				x = Math.max(x, left + s.size);
				continue;
			}
			if (s.groupStart)
			{
				x += GROUP_GAP - GAP;
				// An icon and its number stay together: a group that doesn't fit starts the next line
				int gw = iconGroupWidth(g, base, i);
				if (gw > 0 && x > left && x + gw > maxX)
				{
					x = left;
					y += lineHeight;
				}
			}
			if (s.image != null)
			{
				// Fitted inside a size x size square, keeping its shape; the slot is as wide as it shows
				BufferedImage img = s.size >= ITEM_MIN ? trimmed(s.image) : s.image;
				int iw = Math.max(1, img.getWidth());
				int ih = Math.max(1, img.getHeight());
				float scale = Math.min(s.size / (float) iw, s.size / (float) ih);
				int w = Math.max(1, Math.round(iw * scale));
				int h = Math.max(1, Math.round(ih * scale));
				if (x > left && x + w > maxX)
				{
					// Out of room: the icon and what follows go on the next line
					x = left;
					y += lineHeight;
				}
				int iy = y + (lineHeight - s.size) / 2;
				if (s.size >= ITEM_MIN)
				{
					g.setColor(ICON_BACKING);
					g.fillRoundRect(x - 1, iy - 1, w + 2, s.size + 2, 7, 7);
				}
				g.drawImage(img, x, iy + (s.size - h) / 2, w, h, null);
				x += w + GAP;
				continue;
			}
			// Text wraps under itself (hanging indent at the column where it started)
			Font f = s.font != null ? s.font : base;
			g.setFont(f);
			FontMetrics m = g.getFontMetrics(f);
			int indent = x;
			int space = m.stringWidth(" ");
			for (String word : s.text.split(" "))
			{
				int w = m.stringWidth(word);
				if (x > indent && x + w > maxX)
				{
					x = indent;
					y += m.getHeight();
				}
				int baseline = y + (lineHeight + m.getAscent() - m.getDescent()) / 2;
				g.setColor(Color.BLACK);
				g.drawString(word, x + 1, baseline + 1);
				g.setColor(s.color);
				g.drawString(word, x, baseline);
				x += w + space;
			}
			x += GAP - space;
			g.setFont(base);
		}
		if (right != null)
		{
			int w = fm.stringWidth(right);
			int rx = maxX - w;
			int lineY = preferredLocation.y;
			if (y == preferredLocation.y && x + GROUP_GAP > rx)
			{
				// It would run into the line's own text: put it on a line of its own
				y += lineHeight;
				lineY = y;
			}
			int baseline = lineY + (lineHeight + fm.getAscent() - fm.getDescent()) / 2;
			g.setColor(Color.BLACK);
			g.drawString(right, rx + 1, baseline + 1);
			g.setColor(rightColor);
			g.drawString(right, rx, baseline);
		}
		int height = y - preferredLocation.y + lineHeight;
		bounds.setLocation(preferredLocation);
		bounds.setSize(preferredSize.width, height);
		return new Dimension(preferredSize.width, height);
	}
}

package com.bautopilot.baautopilot.overlay;

import com.bautopilot.baautopilot.BaAutopilotConfig;
