/**
 * The instruction box, icons first:
 * <ol>
 * <li>role and wave, wave time on the right;</li>
 * <li>the item to use + action tag + headline, in the action's colour;</li>
 * <li>explanation lines, only while the step is new (or urgent);</li>
 * <li>calls: [out] item ✓/! &nbsp; [in] item;</li>
 * <li>a bar counting down to the next call;</li>
 * <li>stats: stopwatch call speed, then role counters as item icons with numbers.</li>
 * </ol>
 */
public class InstructionOverlay extends OverlayPanel
{
	private static final int WIDTH = 230;
	private static final int WARN_TICKS = 8;

	private final BaAutopilotPlugin plugin;
	private final BaAutopilotConfig config;
	/** Null in previews. */
	@Nullable
	private final BaTracker tracker;

	/** Whether the box being drawn is the live one (not a tutorial page's). */
	private boolean live = true;

	/** Item sprites; swappable so previews can render without a client. */
	@Setter
	private IntFunction<BufferedImage> itemImages;

	/** The role panel's mouth and ear; null in previews. */
	@Nullable
	private final SpriteManager sprites;

	/** The tutorial page's box, shown instead of the live one while the tutorial runs; null in previews. */
	@Nullable
	private final TutorialPilots tutorialPilots;

	@Inject
	InstructionOverlay(BaAutopilotPlugin plugin, BaAutopilotConfig config, @Nullable ItemManager itemManager,
		@Nullable BaTracker tracker, @Nullable SpriteManager sprites, @Nullable TutorialPilots tutorialPilots)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.tracker = tracker;
		this.sprites = sprites;
		this.tutorialPilots = tutorialPilots;
		this.itemImages = itemManager == null ? id -> null : itemManager::getImage;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (tutorialPilots != null && plugin.isTutorialShown())
		{
			// The tutorial's page, in the box's own place: moving it here moves the real one. Pages
			// without a box hide it, so the lobby's own line doesn't read as part of the lesson
			TutorialPilots.View page = tutorialPilots.current();
			if (page == null)
			{
				return null;
			}
			Dimension size = render(g, page.getInstruction(), page.getSnapshot(), false);
			if (page.isHighlight())
			{
				spotlight(g, size);
			}
			return size;
		}
		return render(g, plugin.getInstruction(), plugin.getSnapshot(), true);
	}

	/**
	 * The box for any instruction: the live one, or a tutorial page's (live false: no tracker, no
	 * last-wave row), so the tutorial shows exactly what the plugin would.
	 */
	public Dimension render(Graphics2D g, Instruction ins, Snapshot s, boolean live)
	{
		if (ins == null || s == null || ins.getStep() == Step.NOT_IN_GAME || live && !s.isInArena())
		{
			return null;
		}
		this.live = live;
		Font bold = FontManager.getRunescapeBoldFont();
		// Red is for the owed call alone: the one moment a partner is waiting on you (reported
		// 2026-10-17: the box went red too often to mean anything)
		boolean urgent = ins.getStep() == Step.CALL;
		panelComponent.setBackgroundColor(urgent ? Palette.STONE_CALL : Palette.STONE);
		panelComponent.setBorder(new Rectangle(8, 6, 8, 7));
		panelComponent.setGap(new Point(0, 3));

		// Read in a second (reported 2026-10-19: too dense for steps that last a few seconds): who
		// and when, then the one thing to do and the calls; numbers come last. No explanation lines
		// (reported 2026-10-19: nobody has time to read them): what matters stays as numbers below
		Role role = s.getRole();
		if (s.isInArena())
		{
			WaveStats w = s.getWaveStats();
			add(new IconRow()
				.icon(roleBadge(role), 18)
				.text(role == null ? "BA" : role.getLabel().toUpperCase(), Palette.role(role), bold)
				.text(s.getWave() > 0 ? "Wave " + s.getWave() : "", Palette.DIM)
				.right(w == null ? "" : WaveStats.clock(w.durationTicks(s.getTick())), Palette.DIM));
			add(BoxParts.divider());
		}

		String tag = ins.getStep().getTag();
		add(new ActionRow(item(keyItem(ins, s)), tag, withoutTag(tag, ins.getHeadline()),
			urgent ? Palette.BAD : Palette.action(ins, ins.getStep().getKind().getColor())));
		if (live && s.isInLobby() && plugin.getLastWave() != null)
		{
			lastWave(plugin.getLastWave(), bold);
		}

		if (ins.getAdvice() != null)
		{
			// Low HP: alongside the step, not instead of it
			add(new IconRow().icon(Symbols.ALERT, 14).text(ins.getAdvice(), Palette.OK, bold));
		}
		if (ins.getAlsoCall() != null)
		{
			// The call rides along with the step: one horn click, on the move
			add(new IconRow()
				.icon(item(ins.getAlsoCall().getItemId()), 18)
				.text("+ Call " + ins.getAlsoCall().getKeyword() + "! (horn)", Palette.BAD, bold));
		}

		boolean calls = s.isInArena() && !s.isQueenAlive();
		boolean compact = !s.isInArena() || config.compactHud();
		if (calls)
		{
			// The call remains useful during healing, tool trips and other primary actions,
			// including in compact mode or when the called item is missing from inventory.
			// Calls stop mattering once the Queen is out
			calls(s, !compact);
		}
		if (!compact)
		{
			int mark = panelComponent.getChildren().size();
			if (config.liveStats())
			{
				stats(s);
			}
			if (config.waveInfo() && !s.isQueenAlive())
			{
				waveInfo(s);
			}
			if (config.liveCombat())
			{
				CombatRows.rows(s, ins, this::item, config.defenderGuide()).forEach(this::add);
			}
			if (role == Role.HEALER)
			{
				vialAndTeam(s);
			}
			if (role == Role.HEALER && config.healerTable())
			{
				healerTable(s);
			}
			if (panelComponent.getChildren().size() > mark)
			{
				// Numbers under a line of their own, apart from what to do
				panelComponent.getChildren().add(mark, BoxParts.divider());
			}
		}
		Dimension size = super.render(g);
		frame(g, size);
		return size;
	}

	/**
	 * "This box", for tutorial pages about it: a bright gold border and a light gold wash flashing
	 * on and off (on for most of each second, so it reads as a flash, not a flicker).
	 */
	private static void spotlight(Graphics2D g, Dimension size)
	{
		if (size == null || size.width <= 8 || size.height <= 8
			|| System.currentTimeMillis() % SPOTLIGHT_MS >= SPOTLIGHT_ON_MS)
		{
			return;
		}
		g.setColor(Palette.fill(Palette.GOLD, 38));
		g.fillRect(2, 2, size.width - 4, size.height - 4);
		java.awt.Stroke old = g.getStroke();
		g.setStroke(new java.awt.BasicStroke(3f));
		g.setColor(Palette.GOLD);
		g.drawRect(3, 3, size.width - 7, size.height - 7);
		g.setStroke(old);
	}

	private static final long SPOTLIGHT_MS = 1000;
	private static final long SPOTLIGHT_ON_MS = 600;

	/** The gold inner edge and dark outer edge of the game's interfaces. */
	private static void frame(Graphics2D g, Dimension size)
	{
		if (size == null || size.width <= 2 || size.height <= 2)
		{
			return;
		}
		g.setColor(Palette.GOLD_EDGE);
		g.drawRect(1, 1, size.width - 3, size.height - 3);
		g.setColor(Palette.DARK_EDGE);
		g.drawRect(0, 0, size.width - 1, size.height - 1);
	}

	/** "LOAD" + "Load your eggs" -> "your eggs" (the tag chip says the rest); otherwise the headline. */
	static String withoutTag(String tag, String headline)
	{
		if (headline == null)
		{
			return "";
		}
		if (!tag.isEmpty() && headline.toUpperCase().startsWith(tag + " "))
		{
			return headline.substring(tag.length() + 1);
		}
		return headline;
	}

	/**
	 * [out] shout item ✓ or !     [in] heard item (faded "old" when it is last call's)     18s,
	 * then the call's time left as a thin bar.
	 */
	private void calls(Snapshot s, boolean timer)
	{
		IconRow row = new IconRow();
		int left = s.getTicksToCallChange();
		boolean showTimer = timer && left >= 0;
		if (showTimer)
		{
			row.right((left * 3 / 5) + "s", left <= WARN_TICKS ? Palette.BAD : Palette.DIM);
		}
		callsRows(s, row);
		if (showTimer)
		{
			add(BoxParts.timer(left / (double) WaveInfo.TICKS_PER_CALL, left <= WARN_TICKS));
		}
	}

	/**
	 * The two calls, one a line, as the game's role panel shows them (reported 2026-10-19: the
	 * arrows didn't say which was which): the mouth and "Call" for the one you give, the ear and
	 * "Heard" for the one you act on, each with its item and word.
	 */
	private void callsRows(Snapshot s, IconRow first)
	{
		Font bold = FontManager.getRunescapeBoldFont();
		Font small = FontManager.getRunescapeSmallFont();
		boolean changing = live && tracker != null && tracker.callTextsChanging(s);
		IconRow mine = label(first, SpriteID.BarbassaultIcons.MOUTH, "Call");
		BaCall shout = s.getShoutCall();
		if (changing || shout == null)
		{
			// The HUD already shows the new call; the snapshot catches up next tick
			mine.text("...", Palette.DIM);
		}
		else
		{
			boolean covered = s.getShoutCoveredBy() != null;
			boolean done = s.isShoutDone() || covered;
			mine.icon(item(shout.getItemId())).text(shout.getKeyword(), done ? Palette.CREAM : Palette.BAD, bold)
				.icon(done ? Symbols.CHECK : Symbols.ALERT, 14);
			if (covered && !s.isShoutDone())
			{
				mine.text("by " + s.getShoutCoveredBy(), Palette.DIM, small);
			}
		}
		add(mine);

		IconRow heardRow = label(new IconRow(), SpriteID.BarbassaultIcons.EAR, "Heard");
		BaCall heard = s.getListenCall();
		if (changing || heard == null)
		{
			heardRow.text("...", Palette.DIM);
		}
		else
		{
			heardRow.icon(item(heard.getItemId()))
				.text(heard.getKeyword(), s.isListenFresh() ? Palette.CREAM : Palette.DIM, bold);
			if (!s.isListenFresh())
			{
				heardRow.text("old", Palette.OK, small);
			}
		}
		add(heardRow);
	}

	/** The role panel's own badge for a role, once loaded; null otherwise. */
	private BufferedImage roleBadge(Role role)
	{
		if (role == null || sprites == null)
		{
			return null;
		}
		switch (role)
		{
			case ATTACKER:
				return sprites.getSprite(SpriteID.BarbassaultIcons.HORN_FOR_ATTACKER, 0);
			case COLLECTOR:
				return sprites.getSprite(SpriteID.BarbassaultIcons.HORN_FOR_COLLECTOR, 0);
			case DEFENDER:
				return sprites.getSprite(SpriteID.BarbassaultIcons.HORN_FOR_DEFENDER, 0);
			default:
				return sprites.getSprite(SpriteID.BarbassaultIcons.HORN_FOR_HEALER, 0);
		}
	}

	/** The role panel's mouth or ear (once loaded), then the word, as a call line's label. */
	private IconRow label(IconRow row, int sprite, String word)
	{
		BufferedImage icon = sprites == null ? null : sprites.getSprite(sprite, 0);
		return row.icon(icon, 18).text(word, Palette.DIM, FontManager.getRunescapeSmallFont()).column(CALL_COLUMN);
	}

	/** Where both call lines' items start, so the two calls line up. */
	private static final int CALL_COLUMN = 56;

	/**
	 * Two penance types a line: how many are out, dead of the wave's total, and "+N" reserves (out
	 * only after a kill; OSRS Wiki wave table).
	 */
	private void waveInfo(Snapshot s)
	{
		int wave = s.getWave();
		if (!WaveInfo.valid(wave))
		{
			return;
		}
		// Two types a line: "Fighters 2 out 1/6 +1     Rangers - 0/6 +3"
		PenanceType[][] lines = {{PenanceType.FIGHTER, PenanceType.RANGER}, {PenanceType.RUNNER, PenanceType.HEALER}};
		Font small = FontManager.getRunescapeSmallFont();
		for (PenanceType[] pair : lines)
		{
			IconRow row = new IconRow().tight();
			for (PenanceType type : pair)
			{
				int total = WaveInfo.total(type, wave);
				int initial = WaveInfo.initial(type, wave);
				int dead = Math.min(total, s.getKillsByType().getOrDefault(type, 0));
				int out = s.alive(type).size();
				int spawned = Math.min(total, dead + out);
				int reserves = Math.min(total - initial, total - spawned);
				// The next-spawn seconds were dropped from here (2026-10-19): two types a line didn't fit them
				String count = dead + "/" + total + (reserves > 0 ? " +" + reserves : "");
				row.group().text(WAVE_NAMES[type.ordinal()], Palette.DIM, small)
					.text(out > 0 ? String.valueOf(out) : "-", out > 0 ? Palette.CREAM : Palette.DIM, out > 0 ? FontManager.getRunescapeBoldFont() : small)
					.text(count, dead >= total ? Palette.GOOD : Palette.DIM, small);
				if (type == pair[0])
				{
					row.group().text(" ", Palette.DIM, small);
				}
			}
			add(row);
		}
	}

	/** Short names in {@link PenanceType} order. */
	private static final String[] WAVE_NAMES = waveNames();

	private static String[] waveNames()
	{
		String[] names = new String[PenanceType.values().length];
		for (PenanceType t : PenanceType.values())
		{
			String n = t.name();
			names[t.ordinal()] = n.charAt(0) + n.substring(1).toLowerCase() + "s";
		}
		return names;
	}

	private void stats(Snapshot s)
	{
		WaveStats w = s.getWaveStats();
		if (w == null)
		{
			return;
		}
		double avg = WaveStats.meanSeconds(w.getCallReactions());
		IconRow row = new IconRow()
			.icon(Symbols.STOPWATCH, 14)
			.text(avg < 0 ? "-" : String.format("%.1fs", avg), Palette.seconds(avg));
		if (w.getCallsWrong() > 0)
		{
			row.icon(Symbols.ALERT, 12).text(String.valueOf(w.getCallsWrong()), Palette.BAD);
		}
		int mistakes = 0;
		switch (s.getRole())
		{
			case COLLECTOR:
				// Points count picked minus exploded, up to 60 (OSRS Wiki)
				int counted = Math.max(0, w.getEggsPicked() - w.getEggsWrong());
				row.group().icon(item(BaIds.EGG_RED)).text(s.getWave() == 10 ? String.valueOf(w.getEggsPicked()) : Math.min(counted, 60) + "/60",
						counted >= 60 && s.getWave() != 10 ? Palette.GOOD : Palette.TEXT)
					.group().icon(item(ItemID.BARBASSAULT_COLL_BAG_01)).text(String.valueOf(w.getLoads()), Palette.TEXT)
					.group().icon(Symbols.CROSSHAIR, 14).text(String.valueOf(w.getShots()), Palette.TEXT);
				mistakes = w.getEggsWrong();
				break;
			case HEALER:
				row.group().icon(item(ItemID.BARBASSAULT_POISION_03)).text(String.valueOf(w.getFoods()), Palette.TEXT);
				if (w.getHpHealed() > 0)
				{
					row.group().text("+" + w.getHpHealed() + " hp", Palette.GOOD);
				}
				mistakes = w.getWrongFoods();
				break;
			case DEFENDER:
				row.group().icon(item(ItemID.BARBASSAULT_RUNNER_FOOD)).text(String.valueOf(w.getRunnerKills()), Palette.TEXT);
				break;
			default:
				row.group().icon(item(ItemID.BARBASSAULT_BARBED_ARROW)).text(String.valueOf(w.getFighterRangerKills()), Palette.TEXT);
				mistakes = w.getImmuneHits();
				break;
		}
		if (mistakes > 0)
		{
			row.group().icon(Symbols.CROSS, 14).text(String.valueOf(mistakes), Palette.BAD);
		}
		add(row);
	}

	/** Between waves: W3 Collector 2:14 [stopwatch] 3.6s [egg] 19 [x] 1 */
	private void lastWave(WaveStats w, Font bold)
	{
		double calls = WaveStats.meanSeconds(w.getCallReactions());
		IconRow row = new IconRow()
			.text("W" + w.getWave(), Palette.role(w.getRole()), bold)
			.text(WaveStats.clock(w.durationTicks(0)), Palette.TEXT)
			.group().icon(Symbols.STOPWATCH, 14)
			.text(calls < 0 ? "-" : String.format("%.1fs", calls), Palette.seconds(calls));
		int mistakes = 0;
		switch (w.getRole())
		{
			case COLLECTOR:
				row.group().icon(item(BaIds.EGG_RED)).text(String.valueOf(w.getEggsPicked()), Palette.TEXT);
				mistakes = w.getEggsWrong();
				break;
			case HEALER:
				row.group().icon(item(ItemID.BARBASSAULT_POISION_03)).text(String.valueOf(w.getFoods()), Palette.TEXT);
				mistakes = w.getWrongFoods();
				break;
			case DEFENDER:
				row.group().icon(item(ItemID.BARBASSAULT_RUNNER_FOOD)).text(String.valueOf(w.getRunnerKills()), Palette.TEXT);
				break;
			default:
				row.group().icon(item(ItemID.BARBASSAULT_BARBED_ARROW)).text(String.valueOf(w.getFighterRangerKills()), Palette.TEXT);
				mistakes = w.getImmuneHits();
				break;
		}
		if (mistakes > 0)
		{
			row.group().icon(Symbols.CROSS, 14).text(String.valueOf(mistakes), Palette.BAD);
		}
		add(row);
	}

	/** [vial] 3/4   Zezima 45%   Lynx 70%: doses left and the two most hurt teammates. */
	private void vialAndTeam(Snapshot s)
	{
		int charges = BaIds.vialCharges(s::has);
		IconRow row = new IconRow();
		if (charges >= 0)
		{
			row.icon(item(BaIds.vialItem(s::has)), 22)
				.text(charges + "/4", charges == 0 ? Palette.BAD : charges == 1 ? Palette.OK : Palette.TEXT,
					FontManager.getRunescapeBoldFont());
		}
		s.getTeammates().stream()
			.filter(t -> t.getMaxHp() > 0)
			.sorted(Comparator.comparingDouble(TeammateView::fraction))
			.limit(2)
			.forEach(t -> row.group()
				.text(shortName(t.getName()), Palette.MUTED)
				.text(Math.round(t.fraction() * 100) + "%",
					t.fraction() < 0.35 ? Palette.BAD : t.fraction() < 0.70 ? Palette.OK : Palette.GOOD));
		if (!row.isEmpty())
		{
			add(row);
		}
	}

	private static String shortName(String name)
	{
		return name.length() <= 8 ? name : name.substring(0, 7) + ".";
	}

	/** #1 ● 2 [food] 80% per penance healer. */
	private void healerTable(Snapshot s)
	{
		BaCall food = s.getListenCall();
		List<PenanceView> healers = s.penance(PenanceType.HEALER);
		healers.sort(Comparator.comparingInt(PenanceView::getOrder));
		for (PenanceView h : healers)
		{
			add(new IconRow()
				.text("#" + h.getOrder(), Palette.MUTED)
				.icon(Symbols.dot(h.nextPoisonHit(s.getTick()) > 0 ? Palette.GOOD : Palette.OK), 14)
				.text(String.valueOf(h.getFoods()), Palette.TEXT)
				.icon(food == null ? null : item(food.getItemId()), 14)
				.right(Math.round(h.hpFraction() * 100) + "%", Palette.TEXT));
		}
	}

	/** The item the instruction is about, for its icon: what to use, pick up or call. */
	public static int keyItem(Instruction ins, Snapshot s)
	{
		if (ins.getStep() == Step.CALL && s.getShoutCall() != null)
		{
			return s.getShoutCall().getItemId();
		}
		if (ins.getTarget().getKind() == Target.Kind.GROUND_ITEM)
		{
			return ins.getTarget().getId();
		}
		for (int id : ins.getItems())
		{
			if (!BaIds.HORNS.contains(id))
			{
				return id;
			}
		}
		switch (ins.getStep())
		{
			case COL_FIRE:
				return s.getEggsRed() > 0 ? BaIds.EGG_RED : BaIds.EGG_GREEN;
			case QUEEN_FIRE:
				return BaIds.EGG_OMEGA;
			case ATT_ATTACK:
			case ATT_GET_ARROWS:
			case DEF_TAKE_BAIT:
			case HEAL_TAKE_FOOD:
				return s.getListenCall() == null ? -1 : s.getListenCall().getItemId();
			case DEF_LOGS:
			case DEF_REPAIR:
				return BaIds.LOGS;
			case DEF_HAMMER:
				return BaIds.HAMMER;
			default:
				return -1;
		}
	}

	private BufferedImage item(int id)
	{
		return id <= 0 ? null : itemImages.apply(id);
	}

	private void add(LayoutableRenderableEntity e)
	{
		panelComponent.getChildren().add(e);
	}
}

package com.bautopilot.baautopilot.overlay;

import com.bautopilot.baautopilot.BaAutopilotConfig;
import com.bautopilot.baautopilot.BaAutopilotPlugin;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.plan.Instruction;
import com.bautopilot.baautopilot.plan.Step;
import com.bautopilot.baautopilot.state.BaTracker;
import com.bautopilot.baautopilot.state.Snapshot;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/** Current-call knowledge stays visible alongside the primary action's inventory items. */
public class ItemHighlightOverlay extends WidgetItemOverlay
{
	public enum Highlight { NONE, ACTION, CALL, CORRECT, GOOD_BAIT, BAD_BAIT }

	private final BaAutopilotPlugin plugin;
	private final BaAutopilotConfig config;
	private final ItemManager itemManager;
	private final BaTracker tracker;

	@Inject
	ItemHighlightOverlay(BaAutopilotPlugin plugin, BaAutopilotConfig config, ItemManager itemManager, BaTracker tracker)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		this.tracker = tracker;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem widgetItem)
	{
		Instruction ins = plugin.getInstruction();
		Snapshot s = plugin.getSnapshot();
		if (!config.highlightItems() || s == null)
		{
			return;
		}
		Highlight highlight = highlight(itemId, ins, s, tracker.callTextsChanging(s));
		if (highlight == Highlight.NONE) return;
		draw(g, itemManager, itemId, widgetItem.getQuantity(), widgetItem.getCanvasBounds(), highlight, config);
	}

	/** The outline (and GOOD / BAD label) for an item drawn at {@code bounds}; the tutorial's inventory uses it too. */
	public static void draw(Graphics2D g, ItemManager itemManager, int itemId, int quantity, Rectangle bounds,
		Highlight highlight, BaAutopilotConfig config)
	{
		if (highlight == Highlight.NONE) return;
		Color color = color(highlight, config);
		BufferedImage outline = itemManager.getItemOutline(itemId, quantity, color);
		g.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
		if (highlight == Highlight.GOOD_BAIT || highlight == Highlight.BAD_BAIT)
		{
			Font previous = g.getFont();
			g.setFont(FontManager.getRunescapeSmallFont());
			OverlayUtil.renderTextLocation(g, new net.runelite.api.Point(bounds.x + 1, bounds.y + bounds.height - 1),
				highlight == Highlight.GOOD_BAIT ? "GOOD" : "BAD", color);
			g.setFont(previous);
		}
	}

	static Color color(Highlight highlight, BaAutopilotConfig config)
	{
		return highlight == Highlight.CALL ? config.urgentColor()
			: highlight == Highlight.BAD_BAIT ? Palette.BAD_BAIT
			: highlight == Highlight.CORRECT || highlight == Highlight.GOOD_BAIT ? Palette.GOOD
			: config.highlightColor();
	}

	/** Context is derived afresh from the call, never from a suspended or previous instruction. */
	public static Highlight highlight(int itemId, Instruction ins, Snapshot s, boolean callChanging)
	{
		if (ins == null || s == null || !s.isInArena()) return Highlight.NONE;
		BaCall call = s.getListenCall();
		boolean roleItem = BaCall.isItemOf(s.getRole(), itemId);
		boolean current = !s.isQueenAlive() && !callChanging && s.isListenFresh()
			&& call != null && call.getReceiver() == s.getRole();
		if (current && roleItem)
		{
			if (s.getRole() == Role.DEFENDER)
			{
				// Either uncalled bait is valid bad food, regardless of the planner's example item.
				return itemId == call.getItemId() ? Highlight.GOOD_BAIT : Highlight.BAD_BAIT;
			}
			if (itemId == call.getItemId()) return Highlight.CORRECT;
		}
		// A late HUD update or stale call must not leave old food/arrows marked as usable.
		// Collector deletion/loading is independent of the called egg colour.
		if (roleItem && !current && s.getRole() != Role.COLLECTOR) return Highlight.NONE;
		if (!ins.getItems().contains(itemId)) return Highlight.NONE;
		return ins.getStep() == Step.CALL && BaIds.HORNS.contains(itemId) ? Highlight.CALL : Highlight.ACTION;
	}
}

package com.bautopilot.baautopilot.overlay;

import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.plan.Instruction;
import com.bautopilot.baautopilot.plan.Step;
import java.awt.Color;

/** Colours shared by the in-game box, the world highlights and the side panel. */
public final class Palette
{
	public static final Color GOOD = new Color(90, 220, 120);
	/** Defender bait which does not match the current call; distinct from an urgent horn call. */
	public static final Color BAD_BAIT = new Color(190, 120, 255);

	public static Color action(Instruction instruction, Color fallback)
	{
		return instruction.isBadBait() && (instruction.getStep() != Step.CALL || instruction.getThen() != null)
			? BAD_BAIT : fallback;
	}
	public static final Color OK = new Color(240, 190, 70);
	public static final Color BAD = new Color(240, 90, 80);
	public static final Color MUTED = new Color(160, 160, 160);
	public static final Color TEXT = new Color(235, 235, 235);
	public static final Color BACKGROUND = new Color(20, 20, 22, 215);
	/** The instruction box, after the game's stone-and-gold interfaces; dark red stone while a call is owed. */
	public static final Color STONE = new Color(46, 39, 30, 235);
	public static final Color STONE_CALL = new Color(82, 26, 20, 238);
	public static final Color GOLD_EDGE = new Color(146, 118, 66);
	public static final Color DARK_EDGE = new Color(14, 12, 9);
	public static final Color CREAM = new Color(240, 230, 205);
	public static final Color GOLD = new Color(255, 152, 31);
	/** Secondary numbers under the divider. */
	public static final Color DIM = new Color(150, 138, 115);

	/** A call made within this many seconds is good, within OK_SECONDS acceptable. */
	public static final double GOOD_SECONDS = 1.5;
	public static final double OK_SECONDS = 3.0;

	private Palette()
	{
	}

	public static Color role(Role role)
	{
		if (role == null)
		{
			return MUTED;
		}
		switch (role)
		{
			case ATTACKER:
				return new Color(235, 95, 85);
			case COLLECTOR:
				return new Color(240, 205, 70);
			case DEFENDER:
				return new Color(95, 155, 255);
			default:
				return new Color(95, 215, 125);
		}
	}

	/** Green / amber / red for a reaction time in seconds; muted when there is none (-1). */
	public static Color seconds(double seconds)
	{
		if (seconds < 0)
		{
			return MUTED;
		}
		return seconds <= GOOD_SECONDS ? GOOD : seconds <= OK_SECONDS ? OK : BAD;
	}

	/** Green at zero, amber up to {@code okUpTo}, red beyond: for mistakes (wrong eggs, runners passed). */
	public static Color mistakes(int count, int okUpTo)
	{
		return count <= 0 ? GOOD : count <= okUpTo ? OK : BAD;
	}

	/** An egg's own colour (red, green, blue, yellow), or null for anything else. */
	public static Color egg(int itemId)
	{
		switch (itemId)
		{
			case BaIds.EGG_RED:
				return new Color(235, 60, 55);
			case BaIds.EGG_GREEN:
				return new Color(80, 215, 80);
			case BaIds.EGG_BLUE:
				return new Color(85, 145, 255);
			case BaIds.EGG_YELLOW:
				return new Color(245, 220, 60);
			default:
				return null;
		}
	}

	/** The same colour, slightly see-through, for fills. */
	public static Color fill(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}
}

package com.bautopilot.baautopilot.overlay;

import com.bautopilot.baautopilot.BaAutopilotConfig;
import com.bautopilot.baautopilot.BaAutopilotPlugin;
import com.bautopilot.baautopilot.plan.Instruction;
import com.bautopilot.baautopilot.plan.Step;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** The walking route to the current target: a line through tile centres in the action's colour. */
public class PathOverlay extends Overlay
{
	private final Client client;
	private final BaAutopilotPlugin plugin;
	private final BaAutopilotConfig config;
	private final RouteFinder routes;

	@Inject
	PathOverlay(Client client, BaAutopilotPlugin plugin, BaAutopilotConfig config, RouteFinder routes)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.routes = routes;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Instruction ins = plugin.getInstruction();
		List<LocalPoint> route = routes.route();
		if (!config.showPath() || ins == null || route.size() < 2)
		{
			return null;
		}
		Color colour = Palette.action(ins, ins.getStep() == Step.CALL ? config.urgentColor() : ins.getStep().getKind().getColor());
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int plane = client.getTopLevelWorldView().getPlane();

		// The line itself, with a dark under-stroke so it reads on any floor
		Path2D line = new Path2D.Double();
		boolean started = false;
		for (LocalPoint lp : route)
		{
			Point p = Perspective.localToCanvas(client, lp, plane);
			if (p == null)
			{
				started = false;
				continue;
			}
			if (!started)
			{
				line.moveTo(p.getX(), p.getY());
				started = true;
			}
			else
			{
				line.lineTo(p.getX(), p.getY());
			}
		}
		g.setStroke(new BasicStroke(5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(new Color(0, 0, 0, 120));
		g.draw(line);
		g.setStroke(new BasicStroke(2.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(colour);
		g.draw(line);
		return null;
	}
}

package com.bautopilot.baautopilot.overlay;

import com.bautopilot.baautopilot.BaAutopilotConfig;
import com.bautopilot.baautopilot.BaAutopilotPlugin;
import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.state.BaTracker;
import com.bautopilot.baautopilot.state.PenanceDiagnostics;
import com.bautopilot.baautopilot.state.Snapshot;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Debug-only world labels and fixed runner search zones, independent of the primary instruction. */
public class PenanceDebugOverlay extends Overlay
{
	private final Client client;
	private final BaAutopilotPlugin plugin;
	private final BaAutopilotConfig config;
	private final BaTracker tracker;

	@Inject
	PenanceDebugOverlay(Client client, BaAutopilotPlugin plugin, BaAutopilotConfig config, BaTracker tracker)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.tracker = tracker;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Snapshot s = plugin.getSnapshot();
		if (!config.debugPriorities() || s == null || !s.isInArena()) return null;
		Font previous = g.getFont();
		g.setFont(FontManager.getRunescapeSmallFont());
		zones(g, s);
		for (PenanceDiagnostics.Label label : PenanceDiagnostics.labels(s))
		{
			NPC npc = tracker.getNpcs().get(label.getNpcIndex());
			if (npc == null) continue;
			Point at = npc.getCanvasTextLocation(g, label.getTitle(), npc.getLogicalHeight() + 105);
			if (at == null) continue;
			Color color = label.getTone().equals("good") ? Palette.GOOD : label.getTone().equals("bad") ? Palette.BAD : Palette.TEXT;
			label(g, at, label.getTitle(), label.getDetail(), color);
		}
		g.setFont(previous);
		return null;
	}

	private void zones(Graphics2D g, Snapshot s)
	{
		if (s.getPlayerTile() == null) return;
		int region = s.getPlayerTile().getRegionID();
		java.awt.Stroke previous = g.getStroke();
		g.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10, new float[]{5, 5}, 0));
		for (int x = 0; x < 8; x++) for (int y = 0; y < 8; y++)
		{
			LocalPoint tile = Scenes.toLocal(client, ArenaTiles.p(region, x * 8 + 4, y * 8 + 4));
			if (tile == null) continue;
			// Area centre is between the four middle tiles, rather than at a tile centre.
			LocalPoint centre = tile.dx(-64).dy(-64);
			Polygon area = Perspective.getCanvasTileAreaPoly(client, centre, PenanceDiagnostics.ZONE_SIZE);
			if (area == null) continue;
			g.setColor(new Color(150, 180, 205, 105));
			g.drawPolygon(area);
			String text = "Z" + x + "," + y;
			Point at = Perspective.getCanvasTextLocation(client, g, centre, text, 0);
			if (at != null) net.runelite.client.ui.overlay.OverlayUtil.renderTextLocation(g, at, text, Palette.MUTED);
		}
		g.setStroke(previous);
	}

	private static void label(Graphics2D g, Point at, String title, String detail, Color color)
	{
		int line = g.getFontMetrics().getHeight();
		int width = Math.max(g.getFontMetrics().stringWidth(title), g.getFontMetrics().stringWidth(detail));
		int x = at.getX() + (g.getFontMetrics().stringWidth(title) - width) / 2;
		int y = at.getY();
		g.setColor(new Color(0, 0, 0, 185));
		g.fillRoundRect(x - 3, y - line + 2, width + 6, line * 2 + 3, 5, 5);
		net.runelite.client.ui.overlay.OverlayUtil.renderTextLocation(g, new Point(x, y), title, color);
		net.runelite.client.ui.overlay.OverlayUtil.renderTextLocation(g, new Point(x, y + line), detail, color);
	}
}

package com.bautopilot.baautopilot.overlay;

import com.bautopilot.baautopilot.BaAutopilotConfig;
import com.bautopilot.baautopilot.BaAutopilotPlugin;
import com.bautopilot.baautopilot.plan.Instruction;
import com.bautopilot.baautopilot.plan.PriorityLine;
import com.bautopilot.baautopilot.plan.Tier;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * Priorities debugger: every candidate the chooser weighed this tick, best first, with its tier,
 * deadline (ticks), walking cost (tiles) and whether it is a committed task; the shown step and
 * the reason it won (or the layer that overrode the chooser: survival, the Queen, an owed call).
 */
public class PriorityOverlay extends OverlayPanel
{
	private static final int WIDTH = 270;
	private static final int MAX_ROWS = 10;
	private static final int HEADLINE_CHARS = 22;

	private final BaAutopilotPlugin plugin;
	private final BaAutopilotConfig config;

	@Inject
	PriorityOverlay(BaAutopilotPlugin plugin, BaAutopilotConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_RIGHT);
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Instruction ins = plugin.getInstruction();
		if (!config.debugPriorities() || ins == null || plugin.getSnapshot() == null || !plugin.getSnapshot().isInArena())
		{
			return null;
		}
		panelComponent.setBackgroundColor(Palette.BACKGROUND);
		Font bold = FontManager.getRunescapeBoldFont();
		panelComponent.getChildren().add(new IconRow().text("PRIORITIES", Palette.TEXT, bold)
			.right(ins.getTask() == null ? "" : ins.getTask(), Palette.MUTED));
		panelComponent.getChildren().add(LineComponent.builder()
			.left(ins.getDecidedBy() == null ? "Outside the chooser" : ins.getDecidedBy())
			.leftColor(Palette.MUTED).build());
		ins.getTasks().getEntries().forEach((id, task) -> panelComponent.getChildren().add(LineComponent.builder()
			.left(id + ": " + task.getStatus().name().toLowerCase())
			.leftColor(task.getStatus() == com.bautopilot.baautopilot.plan.TaskMemory.Status.RUNNING ? Palette.GOOD : Palette.MUTED)
			.build()));

		int shown = 0;
		for (PriorityLine p : ins.getPriorities())
		{
			if (shown++ == MAX_ROWS)
			{
				panelComponent.getChildren().add(new IconRow().text("+" + (ins.getPriorities().size() - MAX_ROWS) + " more", Palette.MUTED));
				break;
			}
			String headline = p.getHeadline() == null ? "" : p.getHeadline();
			if (headline.length() > HEADLINE_CHARS)
			{
				headline = headline.substring(0, HEADLINE_CHARS - 1) + "…";
			}
			StringBuilder right = new StringBuilder();
			if (p.getScore() != null) right.append(String.format(java.util.Locale.ROOT, "%.1f  ", p.getScore()));
			if (p.getDeadline() != Integer.MAX_VALUE)
			{
				right.append("dl ").append(p.getDeadline()).append("  ");
			}
			right.append(p.getWalk()).append("t");
			if (p.isSticky())
			{
				right.append(" ★");
			}
			panelComponent.getChildren().add(new IconRow()
				.text(p.isChosen() ? "▶" : "·", p.isChosen() ? Palette.GOOD : Palette.MUTED, bold)
				.text(p.getScore() == null ? abbrev(p.getTier()) : "VAL", colour(p.getTier()), bold)
				.text(headline, p.isChosen() ? Palette.TEXT : Palette.MUTED, p.isChosen() ? bold : null)
				.right(right.toString(), Palette.MUTED));
		}
		return super.render(g);
	}

	private static String abbrev(Tier t)
	{
		switch (t)
		{
			case SAFETY:
				return "SAFE";
			case TEAM_BLOCKING:
				return "TEAM";
			case TIME_CRITICAL:
				return "TIME";
			case MAINTENANCE:
				return "MAINT";
			default:
				return "IDLE";
		}
	}

	private static Color colour(Tier t)
	{
		switch (t)
		{
			case SAFETY:
				return Palette.BAD;
			case TEAM_BLOCKING:
				return new Color(240, 140, 60);
			case TIME_CRITICAL:
				return Palette.OK;
			case MAINTENANCE:
				return new Color(95, 155, 255);
			default:
				return Palette.MUTED;
		}
	}
}

package com.bautopilot.baautopilot.overlay;

import com.bautopilot.baautopilot.plan.Instruction;
import com.bautopilot.baautopilot.plan.Target;
import com.bautopilot.baautopilot.state.ArenaPath;
import com.bautopilot.baautopilot.state.BaTracker;
import com.bautopilot.baautopilot.state.DefenderArea;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * Walking route from you to the current instruction's target, on the scene collision map. Run on
 * the client thread once per tick; the overlay draws the latest route.
 */
@Singleton
public class RouteFinder
{
	/** Longer routes aren't drawn: the arena is about 60 tiles across. */
	static final int MAX_STEPS = 80;

	private final Client client;
	private final BaTracker tracker;
	private volatile List<LocalPoint> route = Collections.emptyList();

	@Inject
	RouteFinder(Client client, BaTracker tracker)
	{
		this.client = client;
		this.tracker = tracker;
	}

	public List<LocalPoint> route()
	{
		return route;
	}

	public void clear()
	{
		route = Collections.emptyList();
	}

	public void update(Instruction ins, Snapshot snapshot)
	{
		route = compute(ins, snapshot);
	}

	/** The same protected map is used for cost ranking, route search, and line smoothing. */
	public int[][] navigationFlags(Snapshot snapshot, boolean approachPlayer)
	{
		WorldView wv = client.getTopLevelWorldView();
		CollisionData[] maps = wv.getCollisionMaps();
		int plane = wv.getPlane();
		if (maps == null || plane < 0 || plane >= maps.length || maps[plane] == null)
		{
			return null;
		}
		int[][] flags = maps[plane].getFlags();
		Player me = client.getLocalPlayer();
		if (snapshot == null || me == null || me.getLocalLocation() == null)
		{
			return flags;
		}
		List<WorldPoint> others = new ArrayList<>();
		for (Player player : wv.players())
		{
			if (player != null && player != me && player.getLocalLocation() != null)
			{
				others.add(WorldPoint.fromLocalInstance(client, player.getLocalLocation()));
			}
		}
		WorldPoint held = DefenderArea.heldTile(snapshot, others);
		LocalPoint holding = held == null ? null : Scenes.toLocal(client, held);
		if (holding == null)
		{
			return flags;
		}
		LocalPoint start = me.getLocalLocation();
		return DefenderArea.avoid(flags, holding.getSceneX(), holding.getSceneY(),
			start.getSceneX(), start.getSceneY(), approachPlayer);
	}

	private List<LocalPoint> compute(Instruction ins, Snapshot snapshot)
	{
		Player me = client.getLocalPlayer();
		if (ins == null || me == null || me.getLocalLocation() == null)
		{
			return Collections.emptyList();
		}
		WorldView wv = client.getTopLevelWorldView();
		int[][] flags = navigationFlags(snapshot, ins.getTarget().getKind() == Target.Kind.PLAYER);
		if (flags == null)
		{
			return Collections.emptyList();
		}
		int[] area = goalArea(ins.getTarget(), wv);
		if (area == null)
		{
			return Collections.emptyList();
		}
		int minX = area[0];
		int minY = area[1];
		int maxX = area[2];
		int maxY = area[3];
		boolean adjacent = area[4] == 1;
		ArenaPath.Goal goal = (x, y) -> adjacent
			? x >= minX - 1 && x <= maxX + 1 && y >= minY - 1 && y <= maxY + 1
			&& !(x >= minX && x <= maxX && y >= minY && y <= maxY)
			: x >= minX && x <= maxX && y >= minY && y <= maxY;
		LocalPoint start = me.getLocalLocation();
		if (goal.reached(start.getSceneX(), start.getSceneY()))
		{
			return Collections.emptyList();
		}
		List<int[]> steps = ArenaPath.waypoints(flags,
			ArenaPath.find(flags, start.getSceneX(), start.getSceneY(), goal, MAX_STEPS));
		List<LocalPoint> out = new ArrayList<>(steps.size());
		for (int[] p : steps)
		{
			out.add(LocalPoint.fromScene(p[0], p[1], wv));
		}
		return out;
	}

	/** {minX, minY, maxX, maxY, adjacent?1:0} in scene tiles, or null. */
	private int[] goalArea(Target t, WorldView wv)
	{
		switch (t.getKind())
		{
			case NPC:
			{
				NPC npc = tracker.getNpcs().get(t.getId());
				if (npc == null || npc.getLocalLocation() == null)
				{
					// Out of view: head for where it was last seen
					LocalPoint lp = t.getTile() == null ? null : Scenes.toLocal(client, t.getTile());
					return lp == null ? null : new int[]{lp.getSceneX(), lp.getSceneY(), lp.getSceneX(), lp.getSceneY(), 0};
				}
				int size = npc.getComposition() == null ? 1 : Math.max(1, npc.getComposition().getSize());
				int x = npc.getLocalLocation().getSceneX() - (size - 1) / 2;
				int y = npc.getLocalLocation().getSceneY() - (size - 1) / 2;
				return new int[]{x, y, x + size - 1, y + size - 1, 1};
			}
			case OBJECT:
			{
				TileObject obj = t.getTile() == null ? null : tracker.findObject(t.getId(), t.getTile());
				if (obj instanceof GameObject)
				{
					GameObject go = (GameObject) obj;
					int x = go.getSceneMinLocation().getX();
					int y = go.getSceneMinLocation().getY();
					return new int[]{x, y, x + go.sizeX() - 1, y + go.sizeY() - 1, 1};
				}
				LocalPoint lp = obj != null ? obj.getLocalLocation() : Scenes.toLocal(client, t.getTile());
				return lp == null ? null : new int[]{lp.getSceneX(), lp.getSceneY(), lp.getSceneX(), lp.getSceneY(), 1};
			}
			case TILE:
			case GROUND_ITEM:
			{
				LocalPoint live = t.getKind() == Target.Kind.GROUND_ITEM ? tracker.groundItemLocation(t.getId(), t.getTile()) : null;
				LocalPoint lp = live != null ? live : Scenes.toLocal(client, t.getTile());
				return lp == null ? null : new int[]{lp.getSceneX(), lp.getSceneY(), lp.getSceneX(), lp.getSceneY(), 0};
			}
			case PLAYER:
				for (Player p : wv.players())
				{
					if (p != null && t.getLabel() != null && t.getLabel().equalsIgnoreCase(p.getName()) && p.getLocalLocation() != null)
					{
						int x = p.getLocalLocation().getSceneX();
						int y = p.getLocalLocation().getSceneY();
						return new int[]{x, y, x, y, 1};
					}
				}
				return null;
			default:
				return null;
		}
	}
}

