/** Highlights the current target and the plan tiles in the world. */
public class SceneOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 4;
	private static final int OUTLINE_FEATHER = 2;
	private static final int BADGE_ICON = 18;
	private static final Color MARK_DONE = new Color(60, 220, 90, 160);
	/** Defender bait range outline. */
	private static final Color LURE_RANGE = new Color(95, 155, 255, 110);
	/** Poison's next hit 0..4: red, orange, yellow, light green, green. */
	private static final Color[] POISON_LEVEL = {
		new Color(230, 50, 50), new Color(255, 150, 40), new Color(240, 220, 60), new Color(150, 230, 90), new Color(40, 200, 70)};
	/** Runner states in {@link com.bautopilot.baautopilot.plan.RunnerState} order: escaping .. stacked. */
	private static final Color[] RUNNER_STATE = {
		new Color(230, 50, 50), new Color(255, 150, 40), new Color(240, 220, 60), new Color(150, 230, 90), new Color(40, 200, 70)};
	private static final Color LURE_GOOD = new Color(90, 220, 120, 190);
	private static final Color LURE_BAD = Palette.fill(Palette.BAD_BAIT, 190);
	private static final Color BAIT_GOOD_TEXT = new Color(90, 220, 120);
	private static final Color BAIT_BAD_TEXT = Palette.BAD_BAIT;
	private static final Color MARK_GOOD = new Color(255, 200, 40, 200);
	private static final Color MARK_BAD = new Color(190, 120, 255, 200);

	private final Client client;
	private final BaAutopilotPlugin plugin;
	private final BaAutopilotConfig config;
	private final BaTracker tracker;
	private final ModelOutlineRenderer outlines;

	private final IntFunction<BufferedImage> itemImages;
	private BufferedImage badgeIcon;

	@Inject
	SceneOverlay(Client client, BaAutopilotPlugin plugin, BaAutopilotConfig config, BaTracker tracker,
		ModelOutlineRenderer outlines, ItemManager itemManager)
	{
		this.itemImages = itemManager::getImage;
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.tracker = tracker;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Instruction ins = plugin.getInstruction();
		if (ins == null || plugin.getSnapshot() == null || !plugin.getSnapshot().isInArena())
		{
			return null;
		}
		if (config.showMarks())
		{
			for (TileMark mark : ins.getMarks())
			{
				Color c = markColour(mark);
				tile(g, mark.getTile(), c, mark.getLabel());
			}
		}
		if (config.colourEggs())
		{
			calledEggs(g, plugin.getSnapshot());
		}
		if (config.showLureRange())
		{
			lureRange(g, plugin.getSnapshot());
		}
		if (config.baitCounts() && plugin.getSnapshot().getRole() == Role.DEFENDER)
		{
			baitCounts(g, plugin.getSnapshot());
		}
		if (config.poisonOutline() && plugin.getSnapshot().getRole() == Role.HEALER)
		{
			poisonOutlines(plugin.getSnapshot());
		}
		if (config.runnerOutline() && plugin.getSnapshot().getRole() == Role.DEFENDER)
		{
			runnerOutlines(plugin.getSnapshot());
		}
		if (config.highlightTarget())
		{
			List<Target> attackWarnings = attackWarnings(plugin.getSnapshot(), ins, tracker.callTextsChanging(plugin.getSnapshot()));
			// A call is made from wherever you are: its target is the next step's, marked as that step
			boolean calling = ins.getStep() == Step.CALL && ins.getThen() != null;
			Step shown = calling ? ins.getThen() : ins.getStep();
			Color color = ins.getStep() == Step.CALL && !calling ? config.urgentColor()
				: config.colourByAction() ? shown.getKind().getColor() : config.highlightColor();
			color = Palette.action(ins, color);
			int key = calling ? -1 : InstructionOverlay.keyItem(ins, plugin.getSnapshot());
			badgeIcon = key > 0 ? itemImages.apply(key) : null;
			if (!attackWarnings.contains(ins.getTarget()))
			{
				target(g, ins.getTarget(), color, targetTag(ins));
			}
			// Missing call context survives gear, calls and movement instructions. During the
			// short HUD/snapshot mismatch, replace any old ATTACK badge with the same warning.
			badgeIcon = null;
			for (Target warning : attackWarnings)
			{
				target(g, warning, Palette.MUTED, "DON'T ATTACK");
			}
		}
		return null;
	}

	static Color markColour(TileMark mark)
	{
		return !mark.isGood() ? Palette.fill(MARK_BAD, mark.isDone() ? 125 : 200) : mark.isDone() ? MARK_DONE : MARK_GOOD;
	}

	/** Use the planner's safe count rather than the static step tag or parsing its headline. */
	static String targetTag(Instruction instruction)
	{
		Step shown = instruction.getStep() == Step.CALL && instruction.getThen() != null
			? instruction.getThen() : instruction.getStep();
		boolean eggs = (shown == Step.COL_COLLECT || shown == Step.QUEEN_COLLECT)
			&& instruction.getTarget().getKind() == Target.Kind.GROUND_ITEM;
		return shown.getTag() + (eggs && instruction.getPickupCount() > 1 ? " ×" + instruction.getPickupCount() : "")
			+ (eggs && instruction.isRightClick() ? " (right-click)" : "");
	}

	/** Only warn over living, visible Attacker enemies, preferring actual and suggested targets. */
	static List<Target> attackWarnings(Snapshot s, Instruction ins, boolean callChanging)
	{
		List<Target> warnings = new ArrayList<>();
		if (s == null || ins == null || !s.isInArena() || s.getRole() != Role.ATTACKER || s.isQueenAlive()) return warnings;
		BaCall call = s.getListenCall();
		if (!callChanging && s.isListenFresh() && call != null && call.getReceiver() == Role.ATTACKER) return warnings;
		int suggested = ins.getTarget().getKind() == Target.Kind.NPC ? ins.getTarget().getId() : -1;
		for (int id : new int[]{s.getInteractingNpc(), suggested})
		{
			addAttackWarning(warnings, s, id);
		}
		if (warnings.isEmpty()) addAttackWarning(warnings, s, s.getLastTargetNpc());
		return warnings;
	}

	private static void addAttackWarning(List<Target> warnings, Snapshot s, int npcIndex)
	{
		for (PenanceView p : s.getPenance())
		{
			if (p.getNpcIndex() == npcIndex && !p.isDying() && !p.isUnseen()
				&& (p.getType() == PenanceType.FIGHTER || p.getType() == PenanceType.RANGER)
				&& warnings.stream().noneMatch(t -> t.getId() == npcIndex))
			{
				warnings.add(Target.npc(p.getNpcIndex(), p.getTile()));
				return;
			}
		}
	}

	private void target(Graphics2D g, Target t, Color color, String tag)
	{
		switch (t.getKind())
		{
			case NPC:
				NPC npc = tracker.getNpcs().get(t.getId());
				if (npc != null)
				{
					safeOutline(() -> outlines.drawOutline(npc, OUTLINE_WIDTH, color, OUTLINE_FEATHER));
					badge(g, npc.getCanvasTextLocation(g, tag, npc.getLogicalHeight() + 40), tag, color);
				}
				else if (t.getTile() != null)
				{
					// Out of view: mark where it was last seen
					tile(g, t.getTile(), color, tag + ": last seen", true);
				}
				break;
			case OBJECT:
				TileObject obj = t.getTile() == null ? null : tracker.findObject(t.getId(), t.getTile());
				Shape hull = obj == null ? null : obj.getClickbox();
				if (hull != null)
				{
					OverlayUtil.renderPolygon(g, hull, color, Palette.fill(color, 50), new BasicStroke(3));
					badge(g, obj.getCanvasTextLocation(g, tag, 160), tag, color);
				}
				else
				{
					tile(g, t.getTile(), color, tag, true);
				}
				break;
			case GROUND_ITEM:
			{
				// Drawn where the game put the item, falling back to converting its tile
				LocalPoint live = tracker.groundItemLocation(t.getId(), t.getTile());
				if (live != null)
				{
					tileAt(g, live, color, t.getLabel() == null ? tag : tag + ": " + t.getLabel(), true);
					break;
				}
				tile(g, t.getTile(), color, t.getLabel() == null ? tag : tag + ": " + t.getLabel(), true);
				break;
			}
			case TILE:
				tile(g, t.getTile(), color, t.getLabel() == null ? tag : tag + ": " + t.getLabel(), true);
				break;
			case PLAYER:
				for (Player p : client.getTopLevelWorldView().players())
				{
					if (p != null && t.getLabel() != null && t.getLabel().equalsIgnoreCase(p.getName()))
					{
						safeOutline(() -> outlines.drawOutline(p, OUTLINE_WIDTH, color, OUTLINE_FEATHER));
						badge(g, p.getCanvasTextLocation(g, tag, p.getLogicalHeight() + 40), tag, color);
					}
				}
				break;
			default:
				break;
		}
	}

	/**
	 * Defender: each bait on the ground with the square of tiles in which a runner notices it (4 at
	 * defender level 1, 5 from level 2) - green for good bait, purple for bad. While you're told to
	 * drop bait, a fainter square around you previews where the next one lands.
	 */
	private void lureRange(Graphics2D g, Snapshot s)
	{
		if (s.getRole() != Role.DEFENDER)
		{
			return;
		}
		int size = 2 * s.baitRange() + 1;
		BasicStroke dashed = new BasicStroke(1.5f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f, new float[]{6f, 4f}, 0f);
		java.util.Set<WorldPoint> drawn = new java.util.HashSet<>();
		for (com.bautopilot.baautopilot.state.GroundItemView bait : s.getGroundItems())
		{
			if (!com.bautopilot.baautopilot.model.BaIds.BAIT.contains(bait.getItemId()) || !drawn.add(bait.getTile()))
			{
				continue;
			}
			LocalPoint lp = tracker.groundItemLocation(bait.getItemId(), bait.getTile());
			if (lp == null)
			{
				lp = Scenes.toLocal(client, bait.getTile());
			}
			Polygon area = lp == null ? null : Perspective.getCanvasTileAreaPoly(client, lp, size);
			if (area != null)
			{
				g.setStroke(dashed);
				g.setColor(bait.isGood() ? LURE_GOOD : LURE_BAD);
				g.draw(area);
			}
		}
		Instruction ins = plugin.getInstruction();
		boolean dropping = ins != null && (ins.getStep() == Step.DEF_DROP || ins.getStep() == Step.DEF_RELURE);
		LocalPoint me = client.getLocalPlayer() == null ? null : client.getLocalPlayer().getLocalLocation();
		if (dropping && me != null)
		{
			Polygon area = Perspective.getCanvasTileAreaPoly(client, me, size);
			if (area != null)
			{
				g.setStroke(dashed);
				g.setColor(LURE_RANGE);
				g.draw(area);
			}
		}
	}

	/**
	 * Healer: every penance healer outlined by its poison's next hit, so you see at a glance which
	 * one needs food (red: none left or never fed) and which is still working (green: fresh).
	 */
	/** A Penance Healer's poison outline colour: red at 0 (unfed or worn off) up to green at 4. */
	public static Color poisonColour(int poison)
	{
		return POISON_LEVEL[Math.max(0, Math.min(4, poison))];
	}

	private void poisonOutlines(Snapshot s)
	{
		for (com.bautopilot.baautopilot.state.PenanceView h : s.penance(com.bautopilot.baautopilot.model.PenanceType.HEALER))
		{
			NPC npc = tracker.getNpcs().get(h.getNpcIndex());
			if (npc == null)
			{
				continue;
			}
			Color c = poisonColour(h.nextPoisonHit(s.getTick()));
			safeOutline(() -> outlines.drawOutline(npc, 2, c, 2));
		}
	}

	/** Defender: every runner outlined by how well the food trail holds it ({@link RunnerState}). */
	private void runnerOutlines(Snapshot s)
	{
		for (com.bautopilot.baautopilot.state.PenanceView r : s.penance(com.bautopilot.baautopilot.model.PenanceType.RUNNER))
		{
			NPC npc = tracker.getNpcs().get(r.getNpcIndex());
			if (npc == null)
			{
				continue;
			}
			Color c = RUNNER_STATE[com.bautopilot.baautopilot.plan.RunnerState.of(s, r).ordinal()];
			safeOutline(() -> outlines.drawOutline(npc, 2, c, 2));
		}
	}

	/**
	 * Defender: how many good and bad bait lie on each tile ("4" green, "1" purple), on a dark
	 * backing just above the tile, so a spot's count reads at a glance without hovering the pile.
	 */
	private void baitCounts(Graphics2D g, Snapshot s)
	{
		java.util.Map<WorldPoint, int[]> counts = new java.util.LinkedHashMap<>();
		for (GroundItemView bait : s.getGroundItems())
		{
			if (bait.getTile() != null && com.bautopilot.baautopilot.model.BaIds.BAIT.contains(bait.getItemId()))
			{
				counts.computeIfAbsent(bait.getTile(), t -> new int[2])[bait.isGood() ? 0 : 1] += Math.max(1, bait.getQuantity());
			}
		}
		Font old = g.getFont();
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = g.getFontMetrics();
		for (java.util.Map.Entry<WorldPoint, int[]> e : counts.entrySet())
		{
			LocalPoint lp = Scenes.toLocal(client, e.getKey());
			if (lp == null)
			{
				continue;
			}
			int good = e.getValue()[0];
			int bad = e.getValue()[1];
			String goodText = good > 0 ? good + " good" : "";
			String badText = bad > 0 ? bad + " bad" : "";
			String gap = good > 0 && bad > 0 ? "  " : "";
			Point at = Perspective.getCanvasTextLocation(client, g, lp, goodText + gap + badText, 30);
			if (at == null)
			{
				continue;
			}
			int w = fm.stringWidth(goodText + gap + badText);
			int h = fm.getHeight();
			g.setColor(new Color(0, 0, 0, 175));
			g.fillRoundRect(at.getX() - 4, at.getY() - h + 2, w + 8, h + 2, 6, 6);
			int x = at.getX();
			x = shadowed(g, goodText, x, at.getY(), BAIT_GOOD_TEXT);
			x = shadowed(g, gap, x, at.getY(), Color.WHITE);
			shadowed(g, badText, x, at.getY(), BAIT_BAD_TEXT);
		}
		g.setFont(old);
	}

	/** Draws text with a 1px shadow; returns the x after it. */
	private static int shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		if (text.isEmpty())
		{
			return x;
		}
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
		return x + g.getFontMetrics().stringWidth(text);
	}

	/** A called egg a left-click takes. */
	public static final Color EGG_LEFT_CLICK = new Color(90, 220, 120);
	/** A called egg under another item: right-click the pile and choose Take. */
	public static final Color EGG_RIGHT_CLICK = new Color(245, 215, 60);

	/** The dot on a called egg: green when a left-click takes it, yellow when it needs a right-click. */
	public static Color eggDotColour(boolean underneath)
	{
		return underneath ? EGG_RIGHT_CLICK : EGG_LEFT_CLICK;
	}

	/**
	 * Collector: a dot on every egg of the called colour, so they stand out of the pile: green when a
	 * left-click takes it, yellow when another item is on top and it needs a right-click and Take.
	 * (Reported 2026-10-19: replaces reordering the menu, which may not pass a Plugin Hub review.)
	 */
	private void calledEggs(Graphics2D g, Snapshot s)
	{
		BaCall call = s.getListenCall();
		if (s.getRole() != Role.COLLECTOR || call == null || !s.isListenFresh() || Palette.egg(call.getItemId()) == null)
		{
			return;
		}
		for (GroundItemView egg : s.getGroundItems())
		{
			if (egg.getItemId() != call.getItemId())
			{
				continue;
			}
			LocalPoint lp = Scenes.toLocal(client, egg.getTile());
			Point p = lp == null ? null : Perspective.localToCanvas(client, lp, client.getTopLevelWorldView().getPlane(), 20);
			if (p == null)
			{
				continue;
			}
			eggDot(g, p, eggDotColour(egg.isUnderneath()));
		}
	}

	private void tile(Graphics2D g, WorldPoint template, Color color, String label)
	{
		tile(g, template, color, label, false);
	}

	private void tile(Graphics2D g, WorldPoint template, Color color, String label, boolean asBadge)
	{
		LocalPoint lp = Scenes.toLocal(client, template);
		if (lp != null)
		{
			tileAt(g, lp, color, label, asBadge);
		}
	}

	private void tileAt(Graphics2D g, LocalPoint lp, Color color, String label, boolean asBadge)
	{
		Polygon poly = Perspective.getCanvasTilePoly(client, lp);
		if (poly != null)
		{
			OverlayUtil.renderPolygon(g, poly, color, Palette.fill(color, asBadge ? 70 : 40), new BasicStroke(asBadge ? 3 : 2));
		}
		if (label != null && !label.isEmpty())
		{
			Point text = Perspective.getCanvasTextLocation(client, g, lp, label, asBadge ? 60 : 0);
			if (asBadge)
			{
				badge(g, text, label, color);
			}
			else if (text != null)
			{
				OverlayUtil.renderTextLocation(g, text, label, color);
			}
		}
	}

	private void badge(Graphics2D g, Point at, String text, Color color)
	{
		badge(g, at, text, color, badgeIcon);
	}

	/**
	 * [item icon] + bold coloured tag on a dark rounded backing, readable against any part of the
	 * arena. The tutorial's marks use it too, so they look like the plugin's.
	 */
	public static void badge(Graphics2D g, Point at, String text, Color color, BufferedImage badgeIcon)
	{
		if (at == null || text == null || text.isEmpty())
		{
			return;
		}
		Font old = g.getFont();
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = g.getFontMetrics();
		int icon = badgeIcon == null ? 0 : BADGE_ICON + 3;
		int w = fm.stringWidth(text) + icon;
		int h = Math.max(fm.getHeight(), icon == 0 ? 0 : BADGE_ICON + 2);
		int x = at.getX() - icon / 2;
		int y = at.getY();
		g.setColor(new Color(0, 0, 0, 175));
		g.fillRoundRect(x - 4, y - h + 2, w + 8, h + 2, 6, 6);
		g.setColor(color);
		g.drawRoundRect(x - 4, y - h + 2, w + 8, h + 2, 6, 6);
		if (badgeIcon != null)
		{
			g.drawImage(badgeIcon, x, y - h + 3, BADGE_ICON, BADGE_ICON, null);
		}
		g.setColor(Color.BLACK);
		g.drawString(text, x + icon + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x + icon, y);
		g.setFont(old);
	}

	/** The dot the plugin puts on every egg of the called colour, centred on a canvas point. */
	public static void eggDot(Graphics2D g, Point p, Color colour)
	{
		g.setColor(Color.BLACK);
		g.fillOval(p.getX() - 6, p.getY() - 6, 12, 12);
		g.setColor(colour);
		g.fillOval(p.getX() - 5, p.getY() - 5, 10, 10);
	}

	private static void safeOutline(Runnable r)
	{
		try
		{
			r.run();
		}
		catch (RuntimeException ignored)
		{
			// the model can unload between the lookup and the draw
		}
	}
}

package com.bautopilot.baautopilot.overlay;

import java.util.Collection;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/** Template (instance) coordinates back to the live scene. */
public final class Scenes
{
	private Scenes()
	{
	}

	/**
	 * The live tile for a template tile. An instance can use the same template chunk more than once,
	 * so of all its copies take the one in the loaded scene nearest to you (taking the first copy
	 * could land outside the scene, and then nothing was drawn).
	 */
	public static WorldPoint toWorld(Client client, WorldPoint template)
	{
		if (template == null)
		{
			return null;
		}
		WorldView wv = client.getTopLevelWorldView();
		Collection<WorldPoint> live = WorldPoint.toLocalInstance(wv, template);
		Player me = client.getLocalPlayer();
		WorldPoint here = me == null ? null : me.getWorldLocation();
		WorldPoint best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (WorldPoint w : live)
		{
			if (LocalPoint.fromWorld(wv, w) == null)
			{
				continue;
			}
			int d = here == null ? 0 : here.distanceTo2D(w);
			if (d < bestDistance)
			{
				best = w;
				bestDistance = d;
			}
		}
		return best;
	}

	public static LocalPoint toLocal(Client client, WorldPoint template)
	{
		WorldPoint world = toWorld(client, template);
		return world == null ? null : LocalPoint.fromWorld(client.getTopLevelWorldView(), world);
	}
}

package com.bautopilot.baautopilot.overlay;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * Small painted symbols for the overlay (the RuneScape font has no check marks or arrows).
 * 14 px, built once.
 */
public final class Symbols
{
	static final int SIZE = 14;

	/** Call made. */
	public static final BufferedImage CHECK = paint(g ->
	{
		g.setColor(Palette.GOOD);
		g.setStroke(new BasicStroke(2.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.drawPolyline(new int[]{2, 5, 12}, new int[]{7, 11, 3}, 3);
	});

	/** Call owed / attention. */
	public static final BufferedImage ALERT = paint(g ->
	{
		g.setColor(Palette.BAD);
		g.fillOval(0, 0, SIZE - 1, SIZE - 1);
		g.setColor(Color.WHITE);
		g.fillRect(6, 3, 2, 5);
		g.fillRect(6, 9, 2, 2);
	});

	/** Your call speed. */
	public static final BufferedImage STOPWATCH = paint(g ->
	{
		g.setColor(Palette.TEXT);
		g.setStroke(new BasicStroke(1.6f));
		g.drawOval(1, 2, 11, 11);
		g.fillRect(5, 0, 4, 2);
		g.drawLine(7, 7, 7, 4);
		g.drawLine(7, 7, 10, 7);
	});

	/** Shots fired. */
	public static final BufferedImage CROSSHAIR = paint(g ->
	{
		g.setColor(new Color(255, 125, 55));
		g.setStroke(new BasicStroke(1.6f));
		g.drawOval(2, 2, 9, 9);
		g.drawLine(7, 0, 7, 4);
		g.drawLine(7, 9, 7, 13);
		g.drawLine(0, 7, 4, 7);
		g.drawLine(9, 7, 13, 7);
	});

	/** A mistake (wrong egg, wrong food, blocked hit). */
	public static final BufferedImage CROSS = paint(g ->
	{
		g.setColor(Palette.BAD);
		g.setStroke(new BasicStroke(2.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.drawLine(3, 3, 11, 11);
		g.drawLine(11, 3, 3, 11);
	});

	/** A coloured dot, e.g. poisoned / clean. */
	public static BufferedImage dot(Color c)
	{
		return paint(g ->
		{
			g.setColor(c);
			g.fillOval(3, 3, 8, 8);
		});
	}

	private Symbols()
	{
	}

	private interface Painter
	{
		void paint(Graphics2D g);
	}

	private static BufferedImage paint(Painter p)
	{
		BufferedImage img = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		p.paint(g);
		g.dispose();
		return img;
	}
}

package com.bautopilot.baautopilot.overlay;

import com.bautopilot.baautopilot.BaAutopilotConfig;
import com.bautopilot.baautopilot.BaAutopilotPlugin;
import com.bautopilot.baautopilot.TintMode;
import com.bautopilot.baautopilot.plan.Instruction;
import com.bautopilot.baautopilot.plan.Step;
import com.bautopilot.baautopilot.state.Snapshot;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Tints the game view red only while the primary instruction is an owed horn call.
 * Drawn under the interfaces, so the inventory itself stays clear.
 */
public class TintOverlay extends Overlay
{
	private static final Color RED = new Color(220, 30, 30);
	private static final int EDGE = 70;

	private final Client client;
	private final BaAutopilotPlugin plugin;
	private final BaAutopilotConfig config;

	@Inject
	TintOverlay(Client client, BaAutopilotPlugin plugin, BaAutopilotConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		TintMode mode = config.inventoryTint();
		Instruction ins = plugin.getInstruction();
		Snapshot s = plugin.getSnapshot();
		if (mode == TintMode.OFF || ins == null || s == null || !s.isInArena() || ins.getStep() != Step.CALL)
		{
			return null;
		}
		int x = client.getViewportXOffset();
		int y = client.getViewportYOffset();
		int w = client.getViewportWidth();
		int h = client.getViewportHeight();
		int alpha = Math.max(0, Math.min(255, config.tintStrength() * 255 / 100));
		Color solid = Palette.fill(RED, alpha);
		if (mode == TintMode.FULL)
		{
			g.setColor(solid);
			g.fillRect(x, y, w, h);
			return null;
		}
		Color clear = Palette.fill(RED, 0);
		Paint old = g.getPaint();
		int e = Math.min(EDGE, Math.min(w, h) / 4);
		g.setPaint(new GradientPaint(x, 0, solid, x + e, 0, clear));
		g.fillRect(x, y, e, h);
		g.setPaint(new GradientPaint(x + w, 0, solid, x + w - e, 0, clear));
		g.fillRect(x + w - e, y, e, h);
		g.setPaint(new GradientPaint(0, y, solid, 0, y + e, clear));
		g.fillRect(x, y, w, e);
		g.setPaint(new GradientPaint(0, y + h, solid, 0, y + h - e, clear));
		g.fillRect(x, y + h - e, w, e);
		g.setPaint(old);
		return null;
	}
}

package com.bautopilot.baautopilot.overlay;

import com.bautopilot.baautopilot.BaAutopilotConfig;
import com.bautopilot.baautopilot.BaAutopilotPlugin;
import com.bautopilot.baautopilot.plan.ActionKind;
import com.bautopilot.baautopilot.plan.TurretChoice;
import com.bautopilot.baautopilot.state.Snapshot;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** In the egg launcher's aiming window: outline the button to press, cross out the stun buttons. */
public class TurretOverlay extends Overlay
{
	private final Client client;
	private final BaAutopilotPlugin plugin;
	private final BaAutopilotConfig config;

	@Inject
	TurretOverlay(Client client, BaAutopilotPlugin plugin, BaAutopilotConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Snapshot s = plugin.getSnapshot();
		if (!config.highlightTarget() || s == null || !s.isInArena())
		{
			return null;
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		for (int stun : TurretChoice.STUN)
		{
			Rectangle r = bounds(stun);
			if (r != null)
			{
				g.setColor(Palette.fill(Palette.BAD, 170));
				g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.drawLine(r.x + 4, r.y + 4, r.x + r.width - 4, r.y + r.height - 4);
				g.drawLine(r.x + r.width - 4, r.y + 4, r.x + 4, r.y + r.height - 4);
			}
		}
		Rectangle r = bounds(TurretChoice.pick(s));
		if (r != null)
		{
			Color c = ActionKind.FIGHT.getColor();
			g.setColor(Palette.fill(c, 60));
			g.fillRoundRect(r.x - 2, r.y - 2, r.width + 4, r.height + 4, 8, 8);
			g.setColor(c);
			g.setStroke(new BasicStroke(3f));
			g.drawRoundRect(r.x - 2, r.y - 2, r.width + 4, r.height + 4, 8, 8);
		}
		return null;
	}

	private Rectangle bounds(int component)
	{
		if (component == TurretChoice.NONE)
		{
			return null;
		}
		Widget w = client.getWidget(component);
		if (w == null || w.isHidden())
		{
			return null;
		}
		Rectangle r = w.getBounds();
		return r == null || r.width <= 0 ? null : r;
	}
}

package com.bautopilot.baautopilot.plan;

import java.awt.Color;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/** What sort of thing an instruction asks for; drives its colour everywhere it is drawn. */
@Getter
@RequiredArgsConstructor
public enum ActionKind
{
	CALL(new Color(255, 196, 0)),
	GET(new Color(90, 170, 255)),
	USE(new Color(80, 225, 120)),
	FIGHT(new Color(255, 125, 55)),
	MOVE(new Color(70, 215, 230)),
	WAIT(new Color(175, 175, 175)),
	DANGER(new Color(255, 70, 70));

	private final Color color;
}

package com.bautopilot.baautopilot.plan;

public enum AttackMethod
{
	RANGED,
	MELEE,
	MAGIC
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.WaveInfo;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Attacker: match the collector's call, never hit with the wrong style (2 HP and a team point
 * each), stop as the call flips, and kill fighters/rangers in the order that ends the wave
 * soonest.
 */
class AttackerPlanner
{
	/** Ticks before a call change during which a new attack would likely land on the wrong call. */
	static final int HOLD_TICKS = 2;

	/**
	 * The kill pipeline (arrows for the call, hold as it flips, attack) is time critical while a
	 * fighter or ranger is up; with none up, the launcher, wave 10's spikes and gear for the next
	 * spawn are upkeep, and waiting is idle.
	 */
	List<Candidate> candidates(Snapshot s, Settings c)
	{
		List<Candidate> out = new ArrayList<>();
		BaCall call = s.getListenCall();
		boolean anyArrows = BaIds.ARROWS.stream().anyMatch(s::has) || BaIds.ARROWS.contains(s.getAmmoId());
		// Out-of-view ones stay targets: they're alive (recorded: hundreds left view and came back)
		List<PenanceView> targets = new ArrayList<>(s.alive(PenanceType.FIGHTER));
		targets.addAll(s.alive(PenanceType.RANGER));
		if (c.getAttackMethod() == AttackMethod.RANGED && !anyArrows && (!targets.isEmpty() || fightersRemain(s)))
		{
			out.add(Candidate.task(Tier.TIME_CRITICAL, "att.arrows", takeArrows(s, "all four arrow types",
				"Get arrows first, then take the western route behind the cannon hill")));
			return out;
		}
		Instruction opening = opening(s);
		if (opening != null)
		{
			out.add(Candidate.of(Tier.TIME_CRITICAL, "att.opening", opening));
			return out;
		}

		// Recorded: 372 of 507 arrow prompts came with no fighter or ranger alive. Gear only matters
		// while there is something to shoot
		if (targets.isEmpty())
		{
			support(s, call, c, anyArrows, out);
			return out;
		}

		if (call == null)
		{
			boolean attacking = targets.stream().anyMatch(p -> p.getNpcIndex() == s.getInteractingNpc());
			if (c.getAttackMethod() == AttackMethod.RANGED && !anyArrows)
			{
				out.add(Candidate.task(Tier.MAINTENANCE, "att.arrows",
					takeArrows(s, "all four arrow types", "Grab them now so you can switch the moment the collector calls")));
			}
			out.add(Candidate.of(Tier.IDLE, "att.wait", Instruction.builder()
				.step(Step.ATT_WAIT_CALL)
				.headline(attacking ? "Stop attacking: wait for the collector's call" : "Wait for the collector's call")
				.detail(attacking ? "Click a safe tile to disengage, then wait for a fresh call"
					: "Head to the marked tile by the fighter and ranger caves meanwhile")
				.target(Target.tile(ArenaTiles.attackerWait(s.getWave()), "Wait here"))
				.urgency(attacking ? Urgency.HIGH : Urgency.INFO)
				.build()));
			return out;
		}

		out.add(kill(s, c, call, targets));
		return out;
	}

	private static boolean fightersRemain(Snapshot s)
	{
		return !(s.getCleared().contains(PenanceType.FIGHTER) && s.getCleared().contains(PenanceType.RANGER))
			&& s.getFighterRangerKills() < WaveInfo.fightersTotal(s.getWave()) + WaveInfo.rangersTotal(s.getWave());
	}

	/** Open from the western dispenser corridor, then leave later combat movement alone. */
	private static Instruction opening(Snapshot s)
	{
		if (s.isAttackerOpeningComplete() || s.getPlayerTile() == null || s.getWaveTick() < 0 || s.getWaveTick() >= WaveInfo.TICKS_PER_CALL
			|| s.getFighterRangerKills() > 0 || s.getInteractingNpc() >= 0 || (s.getPlayerTile().getY() & 63) >= 37
			|| (s.getPlayerTile().getX() & 63) > 33) return null;
		boolean west = (s.getPlayerTile().getX() & 63) <= 19
			&& (s.getPlayerTile().getY() & 63) >= (s.getWave() == 10 ? 30 : 28);
		return Instruction.builder().step(Step.ATT_POSITION)
			.headline(west ? "Move north behind the west cannon hill" : "Go west around the cannon hill")
			.detail("Use the western approach before fighting to reduce pulling Penance Healers to the left side")
			.target(Target.tile(west ? ArenaTiles.collectorBehindHill(s.getWave()) : ArenaTiles.collectorWestApproach(s.getWave()), "West route"))
			.build();
	}

	/** One step of the kill pipeline: the called arrows, then hold as the call flips, then attack. */
	private Candidate kill(Snapshot s, Settings c, BaCall call, List<PenanceView> targets)
	{
		Instruction gear = gear(s, c, call);
		if (gear != null)
		{
			return Candidate.task(Tier.TIME_CRITICAL, gear.getStep() == Step.ATT_GET_ARROWS ? "att.arrows" : "att.equip", gear);
		}

		if (s.getTicksToCallChange() >= 0 && s.getTicksToCallChange() <= HOLD_TICKS)
		{
			return Candidate.of(Tier.TIME_CRITICAL, "att.hold", Instruction.builder()
				.step(Step.ATT_HOLD)
				.headline("Hold: the call changes now")
				.detail("Don't start a new attack until the collector's next call")
				.urgency(Urgency.HIGH)
				.build()).withDeadline(s.getTicksToCallChange());
		}

		PenanceType want = WaveInfo.attackerNext(s.getWave(), s.getFighterRangerKills());
		// With other attackers on the team, take your share (same answer on every client); help with
		// theirs only when none of yours is up
		TargetSplit.Slot slot = c.isSplitTargets() ? TargetSplit.slot(s) : TargetSplit.NONE;
		List<PenanceView> mine = targets;
		if (slot.of > 1)
		{
			mine = new ArrayList<>();
			for (PenanceView p : targets)
			{
				if (TargetSplit.owner(p.getNpcIndex(), slot.of) == slot.index)
				{
					mine.add(p);
				}
			}
		}
		boolean helping = mine.isEmpty();
		PenanceView pick = pick(s, helping ? targets : mine, want);
		String name = pick.getType() == PenanceType.FIGHTER ? "Penance Fighter" : "Penance Ranger";
		String why = slot.of > 1
			? (helping ? "Helping the other attacker: none of yours is up" : "Your share of " + slot.of + " attackers")
			: "Kill order this wave: " + order(s);
		return Candidate.of(Tier.TIME_CRITICAL, "att.attack", Instruction.builder()
			.step(Step.ATT_ATTACK)
			.headline(pick.isUnseen() ? "Head to the " + name + " (out of view)" : "Attack the " + name)
			.detail(styleHint(c, call) + " · " + why + (pick.isUnseen() ? ". Walk to where it was last seen" : ""))
			.target(Target.npc(pick.getNpcIndex(), pick.getTile()))
			.build());
	}

	private Instruction gear(Snapshot s, Settings c, BaCall call)
	{
		switch (c.getAttackMethod())
		{
			case RANGED:
				if (s.getAmmoId() == call.getItemId())
				{
					return null;
				}
				if (s.has(call.getItemId()))
				{
					return Instruction.builder()
						.step(Step.ATT_EQUIP)
						.headline("Equip " + call.getItemName())
						.detail("The call is " + call.getKeyword())
						.items(Planner.items(call.getItemId()))
						.urgency(Urgency.HIGH)
						.build();
				}
				return takeArrows(s, call.getItemName(), "The call is " + call.getKeyword());
			default:
				// Melee style and autocast can't be read reliably across weapons: the attack step names them
				return null;
		}
	}

	private static String styleHint(Settings c, BaCall call)
	{
		switch (c.getAttackMethod())
		{
			case MELEE:
				return call.getKeyword() + " combat style";
			case MAGIC:
				return call.getExtra() + " spells";
			default:
				return call.getItemName();
		}
	}

	private static Instruction takeArrows(Snapshot s, String what, String detail)
	{
		ObjectView machine = s.nearestObject(BaIds.ATTACKER_MACHINE);
		return Instruction.builder()
			.step(Step.ATT_GET_ARROWS)
			.headline("Take " + what + " from the attacker machine")
			.detail(detail)
			.target(machine == null ? Target.NONE : Target.object(machine.getId(), machine.getTile()))
			.build();
	}

	/**
	 * Stick with a target until it dies (recorded: the suggestion jumped 160 times while the previous
	 * target was still alive): the one you're attacking first, then the one already suggested, and
	 * only then a fresh pick by kill order, lowest HP, distance.
	 */
	private static PenanceView pick(Snapshot s, List<PenanceView> targets, PenanceType want)
	{
		for (int keep : new int[]{s.getInteractingNpc(), s.getLastTargetNpc()})
		{
			for (PenanceView p : targets)
			{
				if (keep >= 0 && p.getNpcIndex() == keep)
				{
					return p;
				}
			}
		}
		// A fresh pick prefers one you can see and hit now
		Comparator<PenanceView> byPreference = Comparator
			.comparing(PenanceView::isUnseen)
			.thenComparing((PenanceView p) -> p.getType() == want ? 0 : 1)
			.thenComparingDouble(PenanceView::hpFraction)
			.thenComparingInt(p -> s.walk(p.getTile()));
		return targets.stream().min(byPreference).orElse(targets.get(0));
	}

	private static String order(Snapshot s)
	{
		switch (s.getWave())
		{
			case 1:
				return "alternate, fighter first";
			case 2:
				return "two fighters, then ranger/fighter";
			case 3:
				return "alternate, ranger first";
			default:
				return "alternate, fighter first";
		}
	}

	/**
	 * Nothing to attack. Recorded: fighters and rangers are often all dead by mid-wave; the rest of
	 * the wave is runners and healers, which only the launcher lets an attacker hurt.
	 */
	private static void support(Snapshot s, BaCall call, Settings c, boolean anyArrows, List<Candidate> out)
	{
		boolean queenNext = s.getWave() == 10 && !s.isQueenAlive();
		boolean more = fightersRemain(s);
		if (queenNext && !more && s.count(BaIds.SPIKES) < QueenPlanner.SPIKES_WANTED)
		{
			ObjectView shroom = s.nearestObject(BaIds.MUSHROOMS);
			out.add(Candidate.task(Tier.MAINTENANCE, "att.spikes", Instruction.builder()
				.step(Step.ATT_SPIKES)
				.headline("Collect spikes from a petrified mushroom")
				.detail("Up to 8 before the queen spawns (" + s.count(BaIds.SPIKES) + " so far)")
				.target(shroom == null ? Target.NONE : Target.object(shroom.getId(), shroom.getTile()))
				.build()));
		}
		boolean loaded = s.getEggsRed() + s.getEggsGreen() > 0;
		boolean softTargets = !s.alive(PenanceType.RUNNER).isEmpty() || !s.alive(PenanceType.HEALER).isEmpty();
		ObjectView launcher = s.nearestObject(BaIds.LAUNCHERS);
		ObjectView inRange = TurretChoice.bestLauncher(s);
		if (loaded && inRange != null)
		{
			Instruction fire = CollectorPlanner.fire(s, inRange);
			out.add(Candidate.of(Tier.MAINTENANCE, "att.fire",
				fire.toBuilder().step(Step.ATT_FIRE).detail("Nothing to attack. " + fire.getDetail()).build()));
		}
		if (queenNext && !more)
		{
			// Wiki: gather around the healing pool before the Queen spawns, so the healer reaches everyone
			ObjectView spring = s.nearestObject(BaIds.SPRING);
			out.add(Candidate.of(Tier.IDLE, "att.gather", Instruction.builder()
				.step(Step.ATT_SUPPORT)
				.headline("Gather at the healer spring")
				.detail("Spikes ready. The Queen comes next: stay by the healer, not on the same tile")
				.target(spring == null ? Target.NONE : Target.object(spring.getId(), spring.getTile()))
				.urgency(Urgency.INFO)
				.build()));
			return;
		}
		if (more && c.getAttackMethod() == AttackMethod.RANGED && !anyArrows)
		{
			// Recorded 2026-10-16: a new attacker got no arrow prompt until the first spawn. Holding
			// nothing at all is the one gear gap worth fixing before anything is alive
			out.add(Candidate.task(Tier.MAINTENANCE, "att.arrows",
				takeArrows(s, "all four arrow types", "Before the first fighter or ranger spawns, so you can switch on every call")));
		}
		if (more)
		{
			boolean ready = call == null || c.getAttackMethod() != AttackMethod.RANGED || s.getAmmoId() == call.getItemId();
			out.add(Candidate.of(Tier.IDLE, "att.wait", Instruction.builder()
				.step(Step.ATT_SUPPORT)
				.headline("Next fighter or ranger is coming")
				.detail("Wait on the marked tile by their caves" + (ready ? "" : ". Have " + call.getItemName() + " on when it spawns"))
				.target(Target.tile(ArenaTiles.attackerWait(s.getWave()), "Wait here"))
				.urgency(Urgency.INFO)
				.build()));
			return;
		}
		out.add(Candidate.of(Tier.IDLE, "att.done", Instruction.builder()
			.step(Step.ATT_SUPPORT)
			.headline(softTargets ? "Kills done: stand by the launcher" : "Kills done")
			.detail(softTargets ? "Fire when the collector loads it" : "Wait for the wave to end")
			.target(softTargets && launcher != null ? Target.object(launcher.getId(), launcher.getTile()) : Target.NONE)
			.urgency(Urgency.INFO)
			.build()));
	}
}

package com.bautopilot.baautopilot.plan;

import lombok.Value;
import lombok.With;

/**
 * One thing a role could do this tick. Planners list every candidate that applies; the
 * {@link Chooser} picks one. A task's done condition is its planner no longer listing it.
 */
@Value
class Candidate
{
	static final int NO_DEADLINE = Integer.MAX_VALUE;

	Tier tier;
	/** Stable id across ticks ("def.tools", "def.relure"), for keeping a committed task. */
	String task;
	Instruction instruction;
	/** Ticks left before it stops being worth doing (or does harm), {@link #NO_DEADLINE} when none. */
	@With
	int deadline;
	/** Once chosen it is kept until done or a higher tier candidate shows up. */
	@With
	boolean sticky;

	static Candidate of(Tier tier, String task, Instruction instruction)
	{
		return new Candidate(tier, task, instruction, NO_DEADLINE, false);
	}

	/** A multi-tick task the chooser keeps until it is done (a trip, the pattern, a relure). */
	static Candidate task(Tier tier, String task, Instruction instruction)
	{
		return new Candidate(tier, task, instruction, NO_DEADLINE, true);
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.state.Snapshot;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;

/**
 * Picks one candidate: the highest tier present; a committed task (still listed and sticky),
 * including one suspended by an interruption; otherwise the earliest deadline, then the shortest
 * walk, then listing order. Weighted roles instead compare scores directly, with continuity in
 * the score rather than an unconditional commitment. All history comes through the snapshot.
 */
final class Chooser
{
	private Chooser()
	{
	}

	static Instruction choose(Snapshot s, List<Candidate> candidates)
	{
		if (candidates.stream().filter(Objects::nonNull).anyMatch(c -> c.getInstruction().getScore() != null))
			return weighted(s, candidates);
		Candidate best = pick(s, candidates);
		if (best == null)
		{
			return null;
		}
		List<PriorityLine> lines = candidates.stream()
			.filter(Objects::nonNull)
			.sorted(Comparator.comparingInt((Candidate c) -> c.getTier().ordinal())
				.thenComparingInt(Candidate::getDeadline).thenComparingInt(c -> cost(s, c)))
			.map(c -> new PriorityLine(c.getTier(), c.getTask(), c.getInstruction().getHeadline(), c.getDeadline(),
				cost(s, c), c.isSticky(), c == best, null, c.getInstruction().getScoreTerms()))
			.collect(Collectors.toList());
		return best.getInstruction().toBuilder().task(best.getTask()).tier(best.getTier())
			.priorities(lines).decidedBy(reason(s, candidates, best)).build();
	}

	private static Instruction weighted(Snapshot s, List<Candidate> candidates)
	{
		List<Candidate> ranked = candidates.stream().filter(Objects::nonNull).collect(Collectors.toList());
		if (ranked.stream().anyMatch(c -> c.getInstruction().getScore() == null || !Double.isFinite(c.getInstruction().getScore())))
			throw new IllegalArgumentException("Weighted choices require a finite score on every candidate");
		ranked.sort(Comparator.comparingDouble((Candidate c) -> c.getInstruction().getScore()).reversed()
			.thenComparingInt(c -> cost(s, c)));
		Candidate best = ranked.get(0);
		List<PriorityLine> lines = ranked.stream().map(c -> new PriorityLine(c.getTier(), c.getTask(),
			c.getInstruction().getHeadline(), c.getDeadline(), cost(s, c), false, c == best,
			c.getInstruction().getScore(), c.getInstruction().getScoreTerms())).collect(Collectors.toList());
		return best.getInstruction().toBuilder().task(best.getTask()).tier(best.getTier()).priorities(lines)
			.decidedBy(String.format(java.util.Locale.ROOT, "Highest score %.1f%s", best.getInstruction().getScore(),
				ranked.size() < 2 ? "" : String.format(java.util.Locale.ROOT, " vs %.1f", ranked.get(1).getInstruction().getScore())))
			.build();
	}

	/** Why {@code best} won, in the chooser's own order of rules. */
	static String reason(Snapshot s, List<Candidate> candidates, Candidate best)
	{
		if (best.isSticky() && best.getTask() != null && best.getTask().equals(s.getLastTask()))
		{
			return "Committed task " + best.getTask() + " kept (no higher tier)";
		}
		if (best.isSticky() && s.getTasks().lastActive(best.getTask()) >= 0)
		{
			return "Resume task " + best.getTask() + " after interruption";
		}
		List<Candidate> rivals = candidates.stream()
			.filter(c -> c != null && c != best && c.getTier() == best.getTier())
			.collect(Collectors.toList());
		if (rivals.isEmpty())
		{
			return "Only " + best.getTier() + " candidate";
		}
		if (rivals.stream().allMatch(c -> c.getDeadline() > best.getDeadline()))
		{
			return "Earliest deadline in " + best.getTier();
		}
		if (rivals.stream().allMatch(c -> cost(s, c) > cost(s, best)))
		{
			return "Shortest walk in " + best.getTier();
		}
		return "First listed in " + best.getTier();
	}

	static Candidate pick(Snapshot s, List<Candidate> candidates)
	{
		Tier top = null;
		Candidate committed = null;
		for (Candidate c : candidates)
		{
			if (c == null)
			{
				continue;
			}
			if (top == null || c.getTier().ordinal() < top.ordinal())
			{
				top = c.getTier();
			}
			if (c.isSticky() && c.getTask() != null && commitment(s, c) >= 0
				&& (committed == null || c.getTier().ordinal() < committed.getTier().ordinal()
					|| c.getTier() == committed.getTier() && commitment(s, c) > commitment(s, committed)))
			{
				committed = c;
			}
		}
		if (top == null)
		{
			return null;
		}
		if (committed != null && committed.getTier().ordinal() <= top.ordinal())
		{
			return committed;
		}
		final Tier tier = top;
		return candidates.stream()
			.filter(Objects::nonNull)
			.filter(c -> c.getTier() == tier)
			.min(Comparator.comparingInt(Candidate::getDeadline).thenComparingInt(c -> cost(s, c)))
			.orElse(null);
	}

	private static int commitment(Snapshot s, Candidate c)
	{
		return c.getTask().equals(s.getLastTask()) ? Integer.MAX_VALUE : s.getTasks().lastActive(c.getTask());
	}

	/** Tiles to walk to the target; inventory clicks and unknown tiles cost nothing. */
	static int cost(Snapshot s, Candidate c)
	{
		WorldPoint tile = c.getInstruction().getTarget().getTile();
		return tile == null ? 0 : s.walk(tile);
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.WaveInfo;
import com.bautopilot.baautopilot.state.GroundItemView;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;

/**
 * Collector: only the called colour (a wrong egg costs 5 HP and an egg), preferably from where the
 * attackers fight (eggs near runners and healers lure them or block the defender), keep the
 * hoppers stocked with red/green so anyone can fire at runners and healers. Gather reds, load a
 * batch during blue calls, and load near capacity during green calls. Blue eggs are spare work.
 *
 * <p>Feasible actions compete on weighted value. Opening red scarcity, diminishing reserve value,
 * travel, inventory pressure, batch size and cannon threats trade off continuously. Shooting is
 * costly Collector time; teammates should normally use the ammunition. Calls, survival and Queen
 * eligibility still belong to the outer planner.
 */
class CollectorPlanner
{
	/** Each colour holds up to five loads in the shared hopper (recorded: "can't load any more" at 5). */
	static final int HOPPER_CAP = 5;
	/** Ground eggs vanish this many ticks after they drop (recorded: untouched eggs went at 179-199). */
	static final int EGG_LIFETIME_TICKS = 200;
	/** Running speed, and slack, for deciding whether an egg can still be reached before it vanishes. */
	static final int RUN_TILES_PER_TICK = 2;
	static final int EXPIRY_MARGIN = 3;
	/** Ordinary pickups stay local; yellow Queen eggs have their own collection policy. */
	static final int MAX_EGG_WALK = 12;
	/** Expiry metadata for the debugger; the score determines precedence. */
	static final int EXPIRY_URGENT_TICKS = 10;
	static final int LOW_RED_AMMO = 2;
	/** Confirmed ammunition consumption within 4.8 seconds is active firing. */
	static final int ACTIVE_SHOOTING_TICKS = 8;
	/** Collector points stop at this many eggs a wave (OSRS Wiki: x capped at 60). */
	static final int POINTS_CAP = 60;
	/** Crowded eggs receive a value penalty, rather than an absolute exclusion. */
	static final int AVOID_RADIUS = 2;

	/** Enumerate feasible alternatives; do not remove one merely because another has priority. */
	List<Candidate> candidates(Snapshot s, Settings c)
	{
		List<Candidate> out = new ArrayList<>();
		BaCall call = s.getListenCall();
		boolean blueCall = call == BaCall.BLUE_EGG;
		int blueInv = s.count(BaIds.EGG_BLUE);
		int red = CollectorScoring.reds(s), green = CollectorScoring.greens(s);
		boolean preparing = s.getWave() == 10 && !s.isQueenAlive() && nothingLeftToShoot(s);
		Instruction preload = preload(s);
		if (preload != null) out.add(CollectorScoring.preload(s, preload));
		if (preparing && loadedAmmo(s) > 0)
		{
			// Nothing left to shoot and the cannon preloaded: ordinary eggs of every colour are dead weight,
			// and the Queen's yellow eggs need the room (reported 2026-10-19: not only blue)
			Instruction spare = destroySpare(s);
			return spare == null ? List.of(CollectorScoring.follow(s, queenReady(s)))
				: List.of(CollectorScoring.blue(s, spare), CollectorScoring.follow(s, queenReady(s)));
		}
		String full = fullHoppers(s, red, green);
		Snapshot afterDiscard = s.toBuilder().freeSlots(Math.max(1, s.getFreeSlots()))
			.ticksToCallChange(s.getTicksToCallChange() < 0 ? -1 : Math.max(0, s.getTicksToCallChange() - 1)).build();
		GroundItemView roomRed = call == BaCall.RED_EGG && s.isListenFresh() && s.getFreeSlots() <= 2
			&& (s.getWave() != 10 || CollectorScoring.redValue(s) > 8)
			? s.getGroundItems().stream().filter(g -> g.getItemId() == BaIds.EGG_RED && pickable(afterDiscard, g) > 0)
				.min(java.util.Comparator.comparingInt(g -> s.walk(g.getTile()))).orElse(null) : null;
		if (call != null && s.isListenFresh() && s.getFreeSlots() > 0)
		{
			for (GroundItemView egg : s.ground(g -> g.getItemId() == call.getItemId() && pickable(s, g) > 0))
			{
				int slack = ticksLeft(s, egg) - travelTicks(s, egg);
				int take = preparing ? 1 : usefulPickups(s, pickable(s, egg));
				if (take == 0) continue;
				out.add(CollectorScoring.collect(s, collect(s, call, egg, take, full), slack, !safe(s, egg), egg.isUnderneath()));
			}
		}
		int redFit = Math.min(red, Math.max(0, HOPPER_CAP - s.getEggsRed()));
		int greenFit = Math.min(green, Math.max(0, HOPPER_CAP - s.getEggsGreen()));
		int fit = redFit + greenFit;
		// Both hoppers replenish the same ammunition. The threat is shared; only travel differs.
		double supplyRisk = s.getObjects().stream().filter(o -> BaIds.contains(BaIds.LAUNCHERS, o.getId()))
			.mapToDouble(o -> CollectorScoring.escapeRisk(s, o.getTile())).max().orElse(0);
		for (ObjectView object : s.getObjects())
		{
			if (fit > 0 && BaIds.contains(BaIds.HOPPERS, object.getId()))
			{
				Instruction load = Instruction.builder().step(Step.COL_LOAD).headline("Load your eggs into the hopper")
					.detail((blueCall ? "Blue call: " : "") + redFit + " red + " + greenFit + " green fit. "
						+ "Both cannons share ammunition; use the nearest hopper.\n" + holdings(s))
					.items(Planner.items(BaIds.EGG_RED, BaIds.EGG_GREEN)).target(Target.object(object.getId(), object.getTile())).build();
				out.add(CollectorScoring.load(s, c, load, fit, redFit, supplyRisk));
			}
			if (BaIds.contains(BaIds.LAUNCHERS, object.getId()) && TurretChoice.pick(s, object.getTile()) != TurretChoice.NONE)
				out.add(CollectorScoring.fire(s, fire(s, object), CollectorScoring.escapeRisk(s, object.getTile())));
		}
		if (blueInv > 0) out.add(roomRed == null ? CollectorScoring.blue(s, destroyBlue(blueInv, blueCall, s.getWave()))
			: CollectorScoring.makeRoom(s, discardForRed(s, BaIds.EGG_BLUE), roomRed, false));
		if (roomRed != null && s.count(BaIds.EGG_GREEN) > 0)
			out.add(CollectorScoring.makeRoom(s, discardForRed(s, BaIds.EGG_GREEN), roomRed, true));
		Instruction fallback = preparing ? queenReady(s) : positioning(s, call);
		double bestPickup = out.stream().filter(candidate -> "col.collect".equals(candidate.getTask()))
			.mapToDouble(candidate -> candidate.getInstruction().getScore()).max().orElse(Double.POSITIVE_INFINITY);
		out.add(CollectorScoring.follow(s, fallback, bestPickup));
		return out;
	}
	static final String LOAD_TASK = "col.load";
	static final String SUPPORT_TASK = "col.support";

	/** Absence from the scene is not evidence that every runner and healer has died. */
	static boolean cannonTargetsRemain(Snapshot s)
	{
		return WaveInfo.valid(s.getWave()) && ((!s.getCleared().contains(PenanceType.RUNNER)
			&& s.getRunnersKilled() < WaveInfo.runnersTotal(s.getWave()))
			|| (!s.getCleared().contains(PenanceType.HEALER) && s.getHealersKilled() < WaveInfo.healersTotal(s.getWave())));
	}

	static int loadedAmmo(Snapshot s)
	{
		return s.getEggsRed() + s.getEggsGreen() + s.getEggsBlue() + s.getEggsOmega();
	}

	/** Wave 10 piles are ammunition, not points. A blue only helps enable an empty cannon. */
	private static int usefulPickups(Snapshot s, int safe)
	{
		if (s.getWave() != 10) return safe;
		int needed = s.getListenCall() == BaCall.RED_EGG ? HOPPER_CAP - CollectorScoring.reds(s) - s.getEggsRed()
			: s.getListenCall() == BaCall.GREEN_EGG ? 2 - CollectorScoring.greens(s) - s.getEggsGreen()
			: loadedAmmo(s) == 0 && CollectorScoring.reds(s) + CollectorScoring.greens(s)
				+ s.count(BaIds.EGG_BLUE) + s.getBagBlue() == 0 ? 1 : 0;
		return Math.min(safe, Math.max(0, needed));
	}

	/** Any ordinary colour enables the aiming interface, including blue during wave 10. */
	static Instruction preload(Snapshot s)
	{
		if (s.getWave() != 10 || s.isQueenDead() || loadedAmmo(s) > 0
			|| CollectorScoring.reds(s) + CollectorScoring.greens(s) + s.count(BaIds.EGG_BLUE) + s.getBagBlue() <= 0) return null;
		ObjectView hopper = s.nearestObject(BaIds.HOPPERS);
		if (hopper == null) return null;
		// One egg of any single colour is enough; highlighting every held colour read as "one of each".
		int egg = CollectorScoring.reds(s) > 0 ? BaIds.EGG_RED : CollectorScoring.greens(s) > 0 ? BaIds.EGG_GREEN : BaIds.EGG_BLUE;
		return Instruction.builder().step(Step.COL_LOAD).headline("Preload the cannon with an egg")
			.detail("One egg is enough, any colour: teammates can then open the aiming interface and pre-click Omega. Reds also help clear Penance.\n" + holdings(s))
			.items(Planner.items(egg)).target(Target.object(hopper.getId(), hopper.getTile())).build();
	}

	private static Instruction queenReady(Snapshot s)
	{
		boolean loaded = loadedAmmo(s) > 0;
		return Instruction.builder().step(Step.COL_QUEEN_READY).headline(loaded ? "Get ready for the Queen" : "Keep one egg ready for cannon preloading")
			.detail(loaded ? "Cannon preloaded. Stop ordinary egg collection and wait for yellow drops"
				: "The cannon needs an egg of any colour. Pick up only a safely called egg, then load it before the Queen")
			.target(s.walk(ArenaTiles.queenCollectorWatch()) <= 2 ? Target.NONE : Target.tile(ArenaTiles.queenCollectorWatch(), "Watch for yellow eggs"))
			.urgency(Urgency.INFO).build();
	}

	/** Supply must address the escaping threat or the low-red shortage; green-only loads cannot refill reds. */
	static boolean supportReady(Snapshot s)
	{
		if (!WaveInfo.valid(s.getWave())) return false;
		int reds = s.count(BaIds.EGG_RED) + s.getBagRed();
		boolean refillRed = reds > 0 && s.getEggsRed() <= LOW_RED_AMMO;
		if (refillRed && activelyFiring(s)) return true;
		if (escapingLauncher(s, true) == null) return false;
		return refillRed || s.getEggsRed() + s.getEggsGreen() == 0;
	}

	static boolean activelyFiring(Snapshot s)
	{
		int age = s.getTick() - s.getLastLauncherShotTick();
		return s.getLastLauncherShotTick() >= 0 && age >= 0 && age <= ACTIVE_SHOOTING_TICKS;
	}

	private static ObjectView escapingLauncher(Snapshot s, boolean includeHeld)
	{
		if (!WaveInfo.valid(s.getWave())) return null;
		List<PenanceView> escaping = s.getPenance().stream().filter(p -> p.getType() == PenanceType.RUNNER
			&& !p.isDying() && !p.isUnseen() && RunnerState.of(s, p) == RunnerState.ESCAPING).collect(Collectors.toList());
		if (escaping.isEmpty()) return null;
		Snapshot targets = s.toBuilder().penance(escaping).unseenPenance(List.of()).build();
		if (!includeHeld) return TurretChoice.bestLauncher(targets);
		Snapshot supplied = targets.toBuilder()
			.eggsRed(s.getEggsRed() + Math.min(s.count(BaIds.EGG_RED) + s.getBagRed(), Math.max(0, HOPPER_CAP - s.getEggsRed())))
			.eggsGreen(s.getEggsGreen() + Math.min(s.count(BaIds.EGG_GREEN) + s.getBagGreen(), Math.max(0, HOPPER_CAP - s.getEggsGreen())))
			.build();
		return TurretChoice.bestLauncher(supplied);
	}

	private static Instruction collect(Snapshot s, BaCall call, GroundItemView egg, int pickable, String full)
	{
		boolean risky = !safe(s, egg);
		// Wave 10 points are fixed, so no counter there
		int counted = s.getWaveStats() == null || s.getWave() == 10 ? -1
			: Math.max(0, s.getWaveStats().getEggsPicked() - s.getWaveStats().getEggsWrong());
		String points = counted < 0 ? ""
			: counted >= POINTS_CAP ? POINTS_CAP + "/" + POINTS_CAP + " for points: more eggs only feed the launcher"
			: counted + "/" + POINTS_CAP + " for points";
		// Most useful first: the box shows only the first line at a glance, the rest is for diagnostics
		List<String> lines = new ArrayList<>();
		if (risky) lines.add("Careful: a runner or healer is next to it");
		if (egg.getQuantity() > 1) lines.add(egg.getQuantity() + " on this tile; take " + pickable + " while the call is safe");
		if (!full.isEmpty()) lines.add(full + (s.getWave() == 10 ? " Collect only for useful ammunition" : " Keep collecting: they still count"));
		if (!points.isEmpty()) lines.add(points);
		lines.add(holdings(s));
		if (s.getTicksToCallChange() >= 0) lines.add(s.getTicksToCallChange() + " ticks to call change; ~" + travelTicks(s, egg) + " ticks travel");
		// Under another item, a left-click would take that one: say how to take this egg
		return Instruction.builder()
			.step(Step.COL_COLLECT)
			.headline("Pick up " + call.getItemName() + (pickable > 1 ? " ×" + pickable : "")
				+ (egg.isUnderneath() ? ": right-click, Take" : ""))
			.detail(String.join("\n", lines))
			.target(Target.groundItem(egg.getItemId(), egg.getTile()))
			.pickupCount(pickable)
			.rightClick(egg.isUnderneath())
			.build();
	}

	private static Instruction positioning(Snapshot s, BaCall call)
	{
		if (!s.isCollectorOpeningComplete() && s.getPlayerTile() != null && s.getWaveTick() >= 0 && s.getWaveTick() < WaveInfo.TICKS_PER_CALL
			&& (s.getPlayerTile().getY() & 63) < 37)
		{
			boolean west = (s.getPlayerTile().getX() & 63) <= 19
				&& (s.getPlayerTile().getY() & 63) >= (s.getWave() == 10 ? 30 : 28);
			return Instruction.builder().step(Step.COL_POSITION)
				.headline(west ? "Move north behind the west cannon hill" : "Go west around the cannon hill")
				.detail("Use the western approach to the attackers. You can move before their egg call")
				.target(Target.tile(west ? ArenaTiles.collectorBehindHill(s.getWave()) : ArenaTiles.collectorWestApproach(s.getWave()), "West route"))
				.urgency(Urgency.INFO).build();
		}
		if (call != null) return follow(s, call);
		return Instruction.builder().step(Step.COL_WAIT_CALL).headline("Wait for the attacker's call")
			.detail("Stay where the eggs are dropping; only pick up after a fresh colour call.\n" + holdings(s))
			.urgency(Urgency.INFO).build();
	}

	private static Instruction follow(Snapshot s, BaCall call)
	{
		String full = fullHoppers(s, s.count(BaIds.EGG_RED) + s.getBagRed(), s.count(BaIds.EGG_GREEN) + s.getBagGreen());
		return Instruction.builder()
			.step(Step.COL_FOLLOW)
			.headline("Wait near the attackers for " + call.getItemName())
			.detail((s.getWave() == 10 ? "Keep a small red supply for remaining Penance and one loaded egg for Queen preloading. Ordinary eggs do not score on wave 10."
				: call == BaCall.RED_EGG ? (s.getCallPeriod() < 2
				? "Opening red call: stay for drops and build your red stockpile. Save cannon trips for blue."
				: "Stay for red drops and stockpile reds.") + (full.isEmpty() ? "" : " " + full + " Keep your eggs.")
				: "Eggs drop where fighters and rangers die, by their caves") + "\n" + holdings(s))
			.urgency(Urgency.INFO).build();
	}

	/**
	 * Which shot: runners first (5 HP, and every escape costs the team), then healers; red before
	 * green (red hits for about 3 and splashes, green only poisons). Never blue.
	 */
	static Instruction fire(Snapshot s, ObjectView launcher)
	{
		// Same choice as the aiming window highlight, for targets in this launcher's range
		int button = TurretChoice.pick(s, launcher.getTile());
		String label = TurretChoice.label(button);
		String colour = label.startsWith("Red") ? "red" : "green";
		String at = label.endsWith("Healer") ? "healers" : "runners";
		boolean healersToo = at.equals("runners") && TurretChoice.pick(s.toBuilder().penance(
			s.penance(PenanceType.HEALER)).build(), launcher.getTile()) != TurretChoice.NONE;
		String side = side(s, launcher);
		return Instruction.builder()
			.step(Step.COL_FIRE)
			.headline("Fire the launcher: " + colour + " at " + at)
			.detail((side.isEmpty() ? "" : "The " + side + " one is in range. ") + "Shoot, then " + colour + " at " + at
				+ (healersToo ? " (healers next)" : "") + ". Never blue")
			.target(Target.object(launcher.getId(), launcher.getTile()))
			.build();
	}

	private static String holdings(Snapshot s)
	{
		return "Inventory: " + s.count(BaIds.EGG_RED) + " red / " + s.count(BaIds.EGG_GREEN) + " green / " + s.count(BaIds.EGG_BLUE)
			+ " blue; " + s.getFreeSlots() + " free slots\nBag: " + s.getBagRed() + " red / " + s.getBagGreen() + " green / " + s.getBagBlue() + " blue";
	}

	private static Instruction discardForRed(Snapshot s, int item)
	{
		String colour = item == BaIds.EGG_GREEN ? "green" : "blue";
		return Instruction.builder().step(Step.COL_DISCARD).headline("Destroy a " + colour + " egg to make room for reds")
			.detail("Shift-click an inventory " + colour + " egg, then collect red. Bag eggs do not free inventory slots.\n" + holdings(s))
			.items(Planner.items(item)).build();
	}

	/** "west" / "east" for the two launchers, "" when only one is known. */
	private static String side(Snapshot s, ObjectView launcher)
	{
		long launchers = s.getObjects().stream().filter(o -> BaIds.contains(BaIds.LAUNCHERS, o.getId())).count();
		if (launchers < 2)
		{
			return "";
		}
		boolean westmost = s.getObjects().stream()
			.filter(o -> BaIds.contains(BaIds.LAUNCHERS, o.getId()))
			.allMatch(o -> o.getTile().getX() >= launcher.getTile().getX());
		return westmost ? "west" : "east";
	}

	/** Every ordinary egg in the inventory (bag eggs take no slot), or null when there are none. */
	private static Instruction destroySpare(Snapshot s)
	{
		java.util.List<Integer> held = new ArrayList<>();
		for (int egg : new int[]{BaIds.EGG_RED, BaIds.EGG_GREEN, BaIds.EGG_BLUE})
		{
			if (s.has(egg))
			{
				held.add(egg);
			}
		}
		if (held.isEmpty())
		{
			return null;
		}
		int count = s.count(BaIds.EGG_RED) + s.count(BaIds.EGG_GREEN) + s.count(BaIds.EGG_BLUE);
		return Instruction.builder()
			.step(Step.COL_DISCARD)
			.headline("Destroy your spare egg" + (count == 1 ? "" : "s"))
			.detail("Shift-click, Destroy. Ordinary eggs no longer do anything: make room for the Queen's yellow eggs")
			.items(Planner.items(held.stream().mapToInt(Integer::intValue).toArray()))
			.build();
	}

	private static Instruction destroyBlue(int blue, boolean blueCall, int wave)
	{
		return Instruction.builder()
			.step(Step.COL_BLUE)
			.headline("Destroy your blue egg" + (blue == 1 ? "" : "s"))
			.detail("Shift-click, Destroy. " + (wave == 10 ? "Make inventory room." : blueCall ? "They already counted." : "Costs nothing.")
				+ (wave == 10 ? "\nKeep one loaded egg of any colour for Queen preloading. Spare blues have no point value" : "\nOr load them with the rest: no real use, but it frees space"))
			.items(Planner.items(BaIds.EGG_BLUE))
			.build();
	}

	/** "Red hopper is full (5/5)." for each colour you hold that can't be loaded, or "". */
	private static String fullHoppers(Snapshot s, int red, int green)
	{
		StringBuilder b = new StringBuilder();
		if (red > 0 && s.getEggsRed() >= HOPPER_CAP)
		{
			b.append("Red");
		}
		if (green > 0 && s.getEggsGreen() >= HOPPER_CAP)
		{
			b.append(b.length() > 0 ? " and green" : "Green");
		}
		return b.length() == 0 ? "" : b + " hopper" + (b.indexOf(" and ") > 0 ? "s are" : " is") + " full (5/5).";
	}

	/** Every fighter, ranger, runner and healer of the wave is dead: no egg drops, no launcher target. */
	static boolean nothingLeftToShoot(Snapshot s)
	{
		int wave = s.getWave();
		for (PenanceType type : new PenanceType[]{PenanceType.FIGHTER, PenanceType.RANGER, PenanceType.RUNNER, PenanceType.HEALER})
		{
			if (!s.alive(type).isEmpty())
			{
				return false;
			}
		}
		return s.getFighterRangerKills() >= WaveInfo.fightersTotal(wave) + WaveInfo.rangersTotal(wave)
			&& s.getRunnersKilled() >= WaveInfo.runnersTotal(wave)
			&& s.getHealersKilled() >= WaveInfo.healersTotal(wave);
	}

	/** Ticks until a ground egg vanishes. */
	private static int ticksLeft(Snapshot s, GroundItemView egg)
	{
		return EGG_LIFETIME_TICKS - (s.getTick() - egg.getSpawnTick());
	}

	private static int travelTicks(Snapshot s, GroundItemView egg)
	{
		return (s.walk(egg.getTile()) + RUN_TILES_PER_TICK - 1) / RUN_TILES_PER_TICK;
	}

	/** Capacity, running, reaction/interaction slack and one tick per pickup, before either deadline. */
	static int pickable(Snapshot s, GroundItemView egg)
	{
		if (egg.getTile() == null || egg.getQuantity() <= 0 || s.getFreeSlots() <= 0) return 0;
		if (s.walk(egg.getTile()) > MAX_EGG_WALK) return 0;
		int deadline = ticksLeft(s, egg);
		if (s.getTicksToCallChange() >= 0) deadline = Math.min(deadline, s.getTicksToCallChange());
		return Math.max(0, Math.min(Math.min(egg.getQuantity(), s.getFreeSlots()), deadline - travelTicks(s, egg) - EXPIRY_MARGIN));
	}

	private static boolean safe(Snapshot s, GroundItemView egg)
	{
		for (PenanceView p : s.getPenance())
		{
			if ((p.getType() == PenanceType.RUNNER || p.getType() == PenanceType.HEALER)
				&& ArenaTiles.distance(p.getTile(), egg.getTile()) <= AVOID_RADIUS)
			{
				return false;
			}
		}
		return true;
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import com.google.common.collect.ImmutableMap;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

/** Comparable action values, not probabilities or predicted wave scores. Constants are tuning weights. */
final class CollectorScoring
{
	private CollectorScoring() { }

	static int reds(Snapshot s) { return s.count(BaIds.EGG_RED) + s.getBagRed(); }
	static int greens(Snapshot s) { return s.count(BaIds.EGG_GREEN) + s.getBagGreen(); }

	static double redValue(Snapshot s)
	{
		if (s.getWave() == 10) return 2 + 90 / Math.pow(1 + (reds(s) + s.getEggsRed()) / 2.0, 2);
		double opening = 1 + .8 * Math.exp(-.7 * Math.max(0, s.getCallPeriod()));
		return 12 + 230 * opening / Math.pow(1 + reds(s) / 3.5, 2);
	}

	static double eggValue(Snapshot s)
	{
		if (s.getWave() == 10) return s.getListenCall() == BaCall.RED_EGG ? redValue(s)
			: s.getListenCall() == BaCall.GREEN_EGG ? 1 + 18 / Math.pow(1 + (greens(s) + s.getEggsGreen()) / 2.0, 2) : 0;
		return s.getListenCall() == BaCall.RED_EGG ? redValue(s)
			: s.getListenCall() == BaCall.GREEN_EGG ? 16 + 24 / (1 + greens(s) / 4.0) : 4;
	}

	/** Continuous severity south of the trap; only visible, live runners reachable by this cannon. */
	static double escapeRisk(Snapshot s, WorldPoint cannon)
	{
		double risk = 0;
		for (PenanceView p : s.getPenance())
		{
			if (p.getType() != PenanceType.RUNNER || p.isDying() || p.isUnseen() || p.getTile() == null
				|| cannon == null || ArenaTiles.distance(cannon, p.getTile()) > TurretChoice.RANGE) continue;
			double south = Math.max(0, ArenaTiles.trapFood(s.getWave()).getY() - p.getTile().getY() - 1);
			double movingSouth = p.getPreviousTile() != null && p.getPreviousTile().getY() > p.getTile().getY() ? 1.15 : 1;
			risk = Math.max(risk, Math.min(1, (1 - Math.exp(-south / 6)) * movingSouth));
		}
		return risk;
	}

	static double activity(Snapshot s)
	{
		int age = s.getTick() - s.getLastLauncherShotTick();
		return s.getLastLauncherShotTick() < 0 || age < 0 ? 0 : Math.exp(-age / 4.0);
	}

	/**
	 * An egg under another item needs a right-click and Take: worth about this many tiles of walking,
	 * so a left-clickable egg comes first unless it is much further away (reported 2026-10-19).
	 */
	static final double RIGHT_CLICK_TILES = 4;

	static Candidate collect(Snapshot s, Instruction ins, int slack, boolean risky)
	{
		return collect(s, ins, slack, risky, false);
	}

	static Candidate collect(Snapshot s, Instruction ins, int slack, boolean risky, boolean rightClick)
	{
		Map<String, Double> terms = new LinkedHashMap<>();
		terms.put("next egg / reserve", eggValue(s));
		terms.put("needs right-click", rightClick ? -1.1 * RIGHT_CLICK_TILES : 0);
		// Expiry breaks close ties; it must not send us past a nearby egg for an old distant one.
		terms.put("expiry", s.getListenCall() == BaCall.BLUE_EGG ? 0 : 2 * Math.exp(-Math.max(0, slack) / 8.0));
		terms.put("crowding", risky ? -12.0 : 0);
		double preload = s.getWave() == 10 && CollectorPlanner.loadedAmmo(s) == 0 && reds(s) + greens(s)
			+ s.count(BaIds.EGG_BLUE) + s.getBagBlue() == 0 ? preloadValue(s) : 0;
		double detour = Math.max(0, s.walk(ins.getTarget().getTile()) - 6) / 4.0;
		terms.put("distant egg detour", -(eggValue(s) + preload) * (1 - Math.exp(-detour * detour)));
		if (s.getWave() == 10)
		{
			terms.put("pickup time / no wave-10 points", -8.0);
			terms.put("enable Queen preloading", preload);
		}
		return score(s, "col.collect", s.getListenCall() == BaCall.BLUE_EGG ? Tier.IDLE
			: slack <= CollectorPlanner.EXPIRY_URGENT_TICKS ? Tier.TIME_CRITICAL : Tier.MAINTENANCE, ins, terms);
	}

	static Candidate load(Snapshot s, Settings settings, Instruction ins, int fit, int redFit, double risk)
	{
		Map<String, Double> terms = new LinkedHashMap<>();
		terms.put("batch", 4.0 * fit);
		if (s.getWave() == 10) terms.put("useful wave-10 ammunition", 18.0 * redFit / (s.getEggsRed() + 1)
			+ 6.0 * (fit - redFit) / (s.getEggsGreen() + 1));
		terms.put("inventory pressure", 240.0 / Math.pow(s.getFreeSlots() + 1, 1.5));
		double batch = 1 / (1 + Math.exp(-(reds(s) + greens(s) - settings.getCollectorLoadAt()) / 3.0));
		terms.put("blue window", s.getListenCall() == BaCall.BLUE_EGG ? 42 * batch * fit / (fit + 2.0) : 0);
		double shortage = Math.pow(Math.max(0, 5 - s.getEggsRed()) / 5.0, 2);
		double reserve = Math.pow(reds(s) / 8.0, 6);
		terms.put("proactive red supply", CollectorPlanner.cannonTargetsRemain(s)
			? 65 * redFit * shortage * reserve / (reserve + 1) : 0);
		terms.put("escaping runners", 110 * risk * shortage * Math.min(1, redFit / 2.0));
		terms.put("active shooter", 55 * activity(s) * shortage * Math.min(1, redFit / 3.0));
		terms.put("trip / interaction", -18.0);
		terms.put("collection opportunity", s.getListenCall() == BaCall.RED_EGG ? -.4 * redValue(s) : s.getListenCall() == BaCall.GREEN_EGG ? -5.0 : 0);
		boolean support = risk > 0 || (redFit > 0 && s.getEggsRed() <= CollectorPlanner.LOW_RED_AMMO && CollectorPlanner.activelyFiring(s));
		return score(s, support ? CollectorPlanner.SUPPORT_TASK : CollectorPlanner.LOAD_TASK,
			support ? Tier.TEAM_BLOCKING : s.getListenCall() == BaCall.BLUE_EGG || s.getFreeSlots() <= 3
				? Tier.TIME_CRITICAL : Tier.MAINTENANCE, ins, terms);
	}

	static Candidate fire(Snapshot s, Instruction ins, double risk)
	{
		Map<String, Double> terms = new LinkedHashMap<>();
		// A rescue may be over before a long trip ends; nearby teammates should take that shot.
		terms.put("escaping runners", 65 * risk * Math.exp(-s.walk(ins.getTarget().getTile()) / 12.0));
		terms.put("self-shooting cost", -28.0);
		terms.put("loaded reds", s.getEggsRed() > 0 ? 3.0 : 0);
		terms.put("leave shooting to others", -15 * activity(s));
		terms.put("collection opportunity", s.getListenCall() == BaCall.RED_EGG ? -.6 * redValue(s)
			: s.getListenCall() == BaCall.GREEN_EGG ? -.4 * eggValue(s) : 0);
		return score(s, risk > 0 ? "col.escape.fire" : "col.fire", risk > 0 ? Tier.TEAM_BLOCKING : Tier.MAINTENANCE, ins, terms);
	}

	static Candidate blue(Snapshot s, Instruction ins)
	{
		Map<String, Double> terms = new LinkedHashMap<>();
		terms.put("spare cleanup", .5);
		terms.put("free inventory", (180 + .6 * eggValue(s)) / Math.pow(s.getFreeSlots() + 1, 2));
		return score(s, "col.blue", Tier.IDLE, ins, terms);
	}

	static Candidate preload(Snapshot s, Instruction ins)
	{
		Map<String, Double> terms = new LinkedHashMap<>();
		terms.put("enable Queen preloading", preloadValue(s));
		terms.put("load interaction", -8.0);
		return score(s, "col.preload", Tier.MAINTENANCE, ins, terms);
	}

	/** Gather a useful red batch early; guarantee aiming ammo once the regular wave ends. */
	private static double preloadValue(Snapshot s)
	{
		return s.isQueenAlive() || CollectorPlanner.nothingLeftToShoot(s) ? 500 : 16;
	}

	static Candidate makeRoom(Snapshot s, Instruction ins, com.bautopilot.baautopilot.state.GroundItemView red, boolean green)
	{
		Map<String, Double> terms = new LinkedHashMap<>();
		terms.put("inventory pressure", 240.0 / Math.pow(s.getFreeSlots() + 1, 1.5));
		terms.put("room for red eggs", .8 * redValue(s) / (s.getFreeSlots() + 1));
		terms.put("discarded egg value", green ? -(16 + 24 / (1 + greens(s) / 4.0)) : 0);
		terms.put("discard interaction", -6.0);
		terms.put("then reach reds", -1.1 * s.walk(red.getTile()));
		return finish(green ? "col.room.green" : "col.room.blue", Tier.MAINTENANCE, ins, terms);
	}

	static Candidate follow(Snapshot s, Instruction ins)
	{
		return follow(s, ins, Double.POSITIVE_INFINITY);
	}

	static Candidate follow(Snapshot s, Instruction ins, double bestPickupScore)
	{
		Map<String, Double> terms = new LinkedHashMap<>();
		double waiting = s.getWave() != 10 && s.getListenCall() == BaCall.RED_EGG ? .3 * redValue(s) : 0;
		terms.put("wait for useful drops", waiting);
		// Waiting for a future drop cannot beat a called, reachable pickup already on the ground.
		// Keep its score visible; useful loading/cleanup still competes with the pickup normally.
		if (ins.getStep() == Step.COL_FOLLOW && Double.isFinite(bestPickupScore))
			terms.put("visible egg before waiting", Math.min(0, bestPickupScore - 1 - waiting));
		// A positioning fallback is not penalised for walking: it remains preferable to pointless work.
		return finish("col.follow", Tier.IDLE, ins, terms);
	}

	private static Candidate score(Snapshot s, String task, Tier tier, Instruction ins, Map<String, Double> terms)
	{
		int walk = s.walk(ins.getTarget().getTile());
		terms.put("travel", -(task.equals("col.collect") && s.getListenCall() != BaCall.BLUE_EGG ? 1.1 : .65) * walk);
		boolean same = task.equals(s.getLastTask()) && s.getLastStep() == ins.getStep() && s.getLastActionTarget() != null
			&& ins.getTarget().getKind() == s.getLastActionTarget().getKind() && ins.getTarget().getId() == s.getLastActionTarget().getId()
			&& ins.getTarget().getTile() != null && ins.getTarget().getTile().equals(s.getLastActionTarget().getTile());
		double continuation = same ? task.equals("col.collect") ? walk <= 2 ? 18.0
			: s.getListenCall() == BaCall.BLUE_EGG ? 2.0 : 4.0 : 2.0 : 0;
		if (s.getWave() == 10 && task.equals("col.collect")) continuation = Math.min(continuation, Math.max(0, eggValue(s) - 8));
		terms.put("continue same target", continuation);
		return finish(task, tier, ins, terms);
	}

	private static Candidate finish(String task, Tier tier, Instruction ins, Map<String, Double> terms)
	{
		double total = terms.values().stream().mapToDouble(Double::doubleValue).sum();
		return Candidate.of(tier, task, ins.toBuilder().score(total).scoreTerms(ImmutableMap.copyOf(terms)).build());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.ArenaTiles.FoodSpot;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.WaveInfo;
import com.bautopilot.baautopilot.state.GroundItemView;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import com.google.common.collect.ImmutableList;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

/**
 * Defender: lure runners onto the trap with good (called) bait and kill them there.
 *
 * <p>Drop the wiki pattern (1-4-1-4-1, or 1-4-4-1 on wave 10) during the first call, grab logs and
	 * a hammer, then keep food and charges available while standing clear. Advanced multikills add
	 * holding and timed releases. The same plan with any team: the only thing a defender needs
 * from partners is the healer's call, and a late call already just shortens the pattern window.
 */
class DefenderPlanner
{
	/** Good bait to keep on the trap tile while runners are alive. */
	static final int TRAP_FOOD_MIN = 2;
	/** Runners within this many tiles of the trap food count as stacked. */
	static final int STACK_RADIUS = 2;
	/** Arrived runners wait immediately beside the blocked food, rather than two tiles out. */
	static final int RELEASE_RADIUS = 1;
	/** Close enough to the trap to fix it before chasing an escaping runner. */
	static final int NEAR_TRAP = 5;
	/** During the pattern, a missing bad-bait spot this close is dropped on the way. */
	static final int PASSING_BAD = 2;
	/** The pattern is a first-call job; after this it is maintenance only. */
	static final int PATTERN_DEADLINE_TICKS = WaveInfo.TICKS_PER_CALL;
	/**
	 * Slow multi-kill (BA Torso / Level 5 guide): runners leave their cave at 30, 24, 18, 12 and 6
	 * seconds on the call timer; step off the trap food at 27, 21, 15, 9 or 3, so the whole stack
	 * eats together. 6 seconds = 10 ticks, the first mark 3 seconds (5 ticks) into the call.
	 */
	static final int STEP_OFF_EVERY = 10;
	/** Logs taken in the opening trip (both log spawns lie together by the mainstack). */
	static final int OPENING_LOGS = 2;
	static final int STEP_OFF_OFFSET = 5;
	/** Give late or unconfirmed arrivals one runner cycle before releasing a ready batch. */
	static final int MAX_STACK_WAIT = STEP_OFF_EVERY;

	/** The settings of the current candidates() call (the planner runs on one thread, one call at a time). */
	private Settings settings = Settings.builder().build();

	/**
	 * Every step that applies now, each with its tier (see {@link Tier}); the {@link Chooser} picks.
	 * Multi-tick jobs (the pattern, the hammer-and-logs trip, restocks, a relure) are sticky tasks:
	 * once started they run until done unless something of a higher tier comes up.
	 */
	List<Candidate> candidates(Snapshot s, Settings c)
	{
		settings = c;
		List<Candidate> out = options(s, c);
		WorldPoint food = ArenaTiles.trapFood(s.getWave());
		List<PenanceView> runners = s.alive(PenanceType.RUNNER);
		if (!c.isDefenderMultiKill())
		{
			// Local trap work must not detour for an uncalled bait's routine reserve.
			if (ArenaTiles.distance(s.getPlayerTile(), food) <= NEAR_TRAP
				&& (!runners.isEmpty() || s.getRunnersKilled() < WaveInfo.runnersTotal(s.getWave())))
				out.removeIf(p -> "def.reserve".equals(p.getTask()));
			return out;
		}
		boolean holding = food.equals(s.getPlayerTile()) && runners.stream().anyMatch(p -> onApproach(p, food))
			&& (s.getWaveTick() >= PATTERN_DEADLINE_TICKS || runners.stream().anyMatch(p -> p.getTile() != null
				&& ArenaTiles.distance(p.getTile(), food) <= STACK_RADIUS));
		if (!holding) return out;
		int need = Math.max(TRAP_FOOD_MIN, (int) runners.stream().filter(p -> !p.isUnseen() && p.getTile() != null
			&& ArenaTiles.distance(p.getTile(), food) <= STACK_RADIUS).count());
		if (s.getTrapCharges() != 0 && goodAt(s, food) < need && out.stream().noneMatch(p -> "def.trapfood".equals(p.getTask())))
			trap(s, s.getListenCall(), s.getWave(), out);
		// Suggested routine trips must not keep a commitment that breaks an active hold.
		out.removeIf(p -> !List.of("def.repair", "def.fix", "def.trapfood", "def.last", "def.step", "def.guard").contains(p.getTask())
			&& !(p.getInstruction().getStep() == Step.DEF_DROP && food.equals(p.getInstruction().getTarget().getTile())));
		if (out.isEmpty())
			out.add(Candidate.of(Tier.TIME_CRITICAL, "def.guard", hold(s, approaching(s, food))).withDeadline(0));
		return out;
	}

	private List<Candidate> options(Snapshot s, Settings c)
	{
		settings = c;
		List<Candidate> out = new ArrayList<>();
		BaCall call = s.getListenCall();
		int wave = s.getWave();
		boolean firstCall = s.getWaveTick() >= 0 && s.getWaveTick() < PATTERN_DEADLINE_TICKS;
		int callLeft = firstCall ? PATTERN_DEADLINE_TICKS - s.getWaveTick() : Candidate.NO_DEADLINE;
		boolean runnersLeft = !s.alive(PenanceType.RUNNER).isEmpty() || s.getRunnersKilled() < WaveInfo.runnersTotal(wave);

		// Stock-Up fills the inventory with all three baits in one click and needs no call: do it
		// from the first tick (recorded: the pattern started at wave tick 15-17 and the mainstack
		// was reached at 47-48, after the runners had left their cave)
		if (!holdsBait(s) && (call == null || firstCall))
		{
			out.add(Candidate.task(Tier.TIME_CRITICAL, "def.stock", stockUp(s, call)).withDeadline(callLeft));
		}
		// Cleanup must not pull the defender away from an unfinished or broken main setup.
		Candidate relure = relure(s, call, wave);
		if (relure != null)
		{
			out.add(relure);
		}
		// Runners walk straight past a broken trap: due before the next one reaches it, and at once
		// when it's a click away (tools in hand, next to it), even before chasing an escaping runner
		if (runnersLeft && s.getTrapCharges() == 0)
		{
			// Only fetching the tools is a trip to see through; the fix itself is one click
			ObjectView trap = trap(s);
			boolean equipped = s.isHasHammer() && s.has(BaIds.LOGS);
			boolean oneClick = equipped && trap != null && s.walk(trap.getTile()) <= NEAR_TRAP;
			out.add(Candidate.of(Tier.TEAM_BLOCKING, "def.repair", repair(s))
				.withSticky(!equipped).withDeadline(oneClick ? 0 : runnerArrival(s, wave)));
			out.removeIf(p -> !"def.repair".equals(p.getTask()));
			return out;
		}
		Candidate singleton = c.isDefenderMultiKill() ? releaseSingleton(s, wave) : null;
		if (singleton != null)
		{
			out.add(singleton);
		}
		if (call != null && c.isDefenderPattern() && firstCall)
		{
			Instruction pattern = pattern(s, call);
			if (pattern != null)
			{
				// The pattern owns the first call, and a spot stays
				// done once runners eat it (recorded: eaten trap bait sent the defender back and the
				// mainstack never came up), so the trap's own upkeep waits until it's down
				out.add(Candidate.task(Tier.TIME_CRITICAL, "def.pattern", pattern).withDeadline(callLeft));
				return out;
			}
		}
		if (!runnersLeft)
		{
			out.add(Candidate.of(Tier.IDLE, "def.support", Instruction.builder()
				.step(Step.DEF_SUPPORT)
				.headline("All runners are dead")
				.detail("Hide behind the corner east of the trap so healers stick on the wall, then help on the launcher")
				.urgency(Urgency.INFO)
				.build()));
			return out;
		}

		// Start walking to the first bait spot before the call arrives. It still takes a fresh call
		// to distinguish good bait from bad bait; do not start the tools trip while waiting.
		boolean opening = firstCall && call == null;
		if (opening && c.isDefenderPattern())
		{
			boolean safety = c.isSafetyBait() && placed(s, ArenaTiles.defenderPattern(wave).get(0)) == 0;
			out.add(Candidate.of(Tier.TIME_CRITICAL, "def.wait", Instruction.builder().step(Step.DEF_WAIT_CALL)
				.headline(safety ? "Head to the safety bait south of the trap" : "Head to the trap: drop when the healer calls")
				.detail(safety ? "Wait for the healer's call, then drop 1 of either uncalled bait type" : "Wait for the healer's call before dropping good food")
				.target(Target.tile(safety ? ArenaTiles.safety(wave) : ArenaTiles.trapFood(wave), safety ? "Safety" : "Trap food"))
				.urgency(Urgency.INFO).build()));
			return out;
		}
		Candidate tools = opening ? null : toolsTrip(s, wave);
		if (tools != null)
		{
			out.add(tools);
		}
		if (call == null)
		{
			// Old ground bait keeps its classification. Repairs and releasing a ready trap do not
			// require a new drop, so keep servicing them while the partner's call is missing.
			trap(s, null, wave, out);
			if (out.stream().noneMatch(p -> "def.wait".equals(p.getTask()))) out.add(Candidate.of(Tier.IDLE, "def.wait", Instruction.builder()
				.step(Step.DEF_WAIT_CALL)
				.headline(opening ? "Head to the trap: drop when the healer calls" : "Wait for the healer's call")
				.detail("Bait only works if it matches the call when it hits the ground")
				.target(opening ? Target.tile(ArenaTiles.trapFood(wave), "Trap food") : Target.NONE)
				.urgency(Urgency.INFO)
				.build()));
			return out;
		}
		trap(s, call, wave, out);
		Instruction restock = restockMainstack(s, call, wave);
		if (restock != null)
		{
			out.add(Candidate.task(Tier.MAINTENANCE, "def.restock", restock));
		}
		Instruction trail = restockTrail(s, call, wave);
		if (trail != null)
		{
			out.add(Candidate.task(Tier.MAINTENANCE, "def.trail", trail));
		}
		// Keep a reserve of every bait kind: the call rotates through all three (recorded waves 5-9:
		// 20-118 ticks without the called bait)
		Instruction reserve = topUpBait(s, call);
		if (reserve != null)
		{
			out.add(Candidate.task(Tier.MAINTENANCE, "def.reserve", reserve));
		}
		return out;
	}

	/**
	 * Tending the trap, in the wiki's order: enough good food on it for every runner stacked, step
	 * south on a stack of 2+ with both charges, repair a worn trap to full, otherwise stand on the
	 * trap food. An active hold keeps routine trips from releasing an incomplete arriving group.
	 */
	private void trap(Snapshot s, BaCall call, int wave, List<Candidate> out)
	{
		if (!settings.isDefenderMultiKill())
		{
			continuousTrap(s, call, wave, out);
			return;
		}
		int good = call == null ? -1 : call.getItemId();
		WorldPoint trapFood = ArenaTiles.trapFood(wave);
		boolean runnersOut = !s.alive(PenanceType.RUNNER).isEmpty();
		List<PenanceView> stacked = s.getPenance().stream()
			.filter(p -> p.getType() == PenanceType.RUNNER && !p.isDying()
				&& ArenaTiles.distance(p.getTile(), trapFood) <= STACK_RADIUS)
			.collect(ImmutableList.toImmutableList());
		// Wiki: before stepping off, enough good food under you for every runner in the stack
		int need = Math.max(TRAP_FOOD_MIN, stacked.size());
		int onTrap = goodAt(s, trapFood);
		boolean onFood = trapFood.equals(s.getPlayerTile());
		boolean releasePending = releaseInProgress(s);
		if (releasePending && !onFood && onTrap > 0 && s.getTrapCharges() > 0 && readyRunners(s) > 0)
		{
			out.add(Candidate.task(Tier.TIME_CRITICAL, "def.step", Instruction.builder().step(Step.DEF_HOLD)
				.headline("Stay off the food while the runners eat")
				.detail("Let this batch finish before standing back on the food")
				.target(Target.tile(ArenaTiles.trapStep(wave), "Stay beside trap")).build()).withDeadline(0));
			return;
		}
		if (onTrap < need)
		{
			if (call == null)
			{
				return;
			}
			Instruction stock = !s.has(good)
				? takeBait(s, call, Math.max(4, need - onTrap), 0)
				: Instruction.builder()
					.step(Step.DEF_DROP)
					.headline("Drop " + call.getItemName() + " on the trap food tile")
					.detail(onTrap + " good bait there now; " + (need > TRAP_FOOD_MIN
						? stacked.size() + " runners stacked: one each before you step off"
						: "keep at least " + TRAP_FOOD_MIN))
					.target(Target.tile(trapFood, "Trap food"))
					.items(Planner.items(good))
					.build();
			// An empty trap tile with runners out kills nothing: that outranks even a tools trip
			out.add(!runnersOut ? Candidate.task(Tier.MAINTENANCE, "def.trapfood", stock)
				: Candidate.task(onTrap == 0 ? Tier.TEAM_BLOCKING : Tier.TIME_CRITICAL, "def.trapfood", stock)
					.withDeadline(runnerArrival(s, wave)));
			return;
		}

		boolean waited = stackWait(s) >= MAX_STACK_WAIT;
		if (onFood && readyRunners(s) >= 2 && s.getTrapCharges() == 2
			&& (approaching(s, trapFood) == 0 || waited || releasePending))
		{
			int wait = releasePending ? 0 : ticksToStepOff(s);
			out.add(Candidate.of(Tier.TIME_CRITICAL, "def.step", wait == 0
				? Instruction.builder()
					.step(Step.DEF_STEP)
					.headline("Step one tile south: let them eat")
					.detail(readyRunners(s) + " runners ready, trap has 2 charges. Step back on after the kill"
						+ (approaching(s, trapFood) > 0 ? "; handle late or out-of-view runners in the next batch" : ""))
					.target(Target.tile(ArenaTiles.trapStep(wave), "Step"))
					.urgency(Urgency.HIGH)
					.build()
				: Instruction.builder()
					.step(Step.DEF_HOLD)
					.headline("Stay on the food: step off at " + stepOffSecond(s) + "s")
					.detail(stacked.size() + " runners stacked. Step south when the call timer reads "
						+ stepOffSecond(s) + " (in " + wait + " ticks), so they all eat together")
					.target(Target.tile(trapFood, "Hold here"))
					.urgency(wait <= 2 ? Urgency.HIGH : Urgency.NORMAL)
					.build()).withDeadline(wait));
			return;
		}

		// A fix uses a log whatever the charges, so at 1 charge it only pays with a stack waiting
		// (a stack step needs both charges) or a log to spare; otherwise let the trap take its
		// second runner and fix it broken (guide: "we want the trap to be fully broken")
		if (s.getTrapCharges() == 1 && (stacked.size() >= 2
			|| s.isHasHammer() && s.has(BaIds.LOGS) && s.count(BaIds.LOGS) > logsNeeded(s, wave)))
		{
			if (!s.isHasHammer() || !s.has(BaIds.LOGS))
			{
				Instruction repair = repair(s);
				Instruction tools = repair.toBuilder().detail("The trap has 1 charge. Get the missing repair tools before any multi-kill. "
					+ repair.getDetail()).build();
				out.add(Candidate.task(Tier.TIME_CRITICAL, "def.fix", tools).withDeadline(0));
				return;
			}
			Instruction fix = repair(s);
			if (fix.getStep() == Step.DEF_REPAIR) fix = fix.toBuilder().headline("Fix the trap to full")
				.detail("Stay on the food tile and click the trap's Fix option. " + (stacked.size() >= 2
					? "It has 1 charge; a stack step needs 2" : "You have a log to spare for the runners left"))
				.urgency(stacked.size() >= 2 ? Urgency.HIGH : Urgency.NORMAL).build();
			// Under a stack it's now: they're eating and the next two need the charges
			out.add(stacked.size() >= 2
				? Candidate.task(Tier.TIME_CRITICAL, "def.fix", fix).withDeadline(0)
				: Candidate.task(Tier.MAINTENANCE, "def.fix", fix));
			return;
		}

		// Use a hold's downtime to prepare bait for the arriving group, without a supply trip or
		// spending the last two of a currently useful bait. Ready releases and repairs go first.
		int arrivingGroup = (int) s.alive(PenanceType.RUNNER).stream().filter(p -> onApproach(p, trapFood)).count();
		int prepared = Math.min(arrivingGroup, onTrap + Math.max(0, s.count(good) - BAIT_RESERVE));
		if (onFood && s.getTrapCharges() == 2 && call != null && approaching(s, trapFood) > 0 && prepared > onTrap)
		{
			out.add(Candidate.of(Tier.MAINTENANCE, "def.prepare", Instruction.builder().step(Step.DEF_DROP)
				.headline("Top up trap food: drop " + (prepared - onTrap) + " " + call.getItemName())
				.detail(onTrap + "/" + prepared + " good bait for the arriving group. Stay on this tile; keep "
					+ BAIT_RESERVE + " " + call.getItemName() + " in reserve")
				.target(Target.tile(trapFood, "Trap food")).items(Planner.items(good)).build()));
			return;
		}

		// With the trap coping, the one thing left before standing on it: the safety bait, after all
		// upkeep (it is optional in most guides)
		Instruction safety = call != null && settings.isSafetyBait() ? safetyBait(s, call, wave, trapFood) : null;
		if (safety != null)
		{
			out.add(Candidate.task(Tier.IDLE, "def.safety", safety));
			return;
		}
		Tier guard = runnersOut && !trapCopes(s, trapFood) ? Tier.MAINTENANCE : Tier.IDLE;
		out.add(Candidate.of(guard, "def.guard", onFood
			? hold(s, approaching(s, trapFood))
			: Instruction.builder()
				.step(Step.DEF_STAND)
				.headline("Stand on the trap food")
				.detail("Runners gather around you; you block them until you step off")
				.target(Target.tile(trapFood, "Trap food"))
				.build()));
	}

	/** Keep the trap working; stand on its food only for dropping bait or doing a repair. */
	private void continuousTrap(Snapshot s, BaCall call, int wave, List<Candidate> out)
	{
		WorldPoint food = ArenaTiles.trapFood(wave);
		int there = goodAt(s, food);
		boolean onFood = food.equals(s.getPlayerTile());
		if (there == 0 && call == null)
		{
			String task = s.getWaveTick() >= 0 && s.getWaveTick() < PATTERN_DEADLINE_TICKS ? "def.wait" : "def.trapfood";
			out.add(Candidate.of(Tier.TIME_CRITICAL, task, Instruction.builder().step(Step.DEF_WAIT_CALL)
				.headline(onFood ? "Wait here for the healer's call, then add food" : "Go to the food tile; drop after the healer calls")
				.detail("The trap food is empty. Block it only while waiting to add correctly called bait, then step aside")
				.target(Target.tile(food, "Restock food")).urgency(Urgency.INFO).build()));
			return;
		}
		int incoming = (int) s.alive(PenanceType.RUNNER).stream().filter(p -> onApproach(p, food)).count();
		int desired = Math.max(TRAP_FOOD_MIN, Math.min(4, incoming));
		if (there >= TRAP_FOOD_MIN && call != null)
			desired = Math.min(desired, there + Math.max(0, s.count(call.getItemId()) - BAIT_RESERVE));
		if (call != null && there < desired)
		{
			Instruction bait = !s.has(call.getItemId()) ? takeBait(s, call, Math.max(4, desired - there), 0)
				: Instruction.builder().step(Step.DEF_DROP)
					.headline("Drop " + call.getItemName() + " on the trap food tile")
					.detail(there + "/" + desired + " good food. " + (onFood ? "Drop here, then step off the food" : "Walk to the marked tile, drop the food, then step aside"))
					.target(Target.tile(food, "Trap food")).items(Planner.items(call.getItemId())).build();
			out.add(Candidate.task(there == 0 ? Tier.TEAM_BLOCKING : Tier.TIME_CRITICAL, "def.trapfood", bait).withDeadline(runnerArrival(s, wave)));
			return;
		}
		// A spare log can restore the worn trap early; otherwise use both charges before repairing.
		if (s.getTrapCharges() == 1 && s.isHasHammer() && s.count(BaIds.LOGS) > logsNeeded(s, wave))
		{
			out.add(Candidate.of(Tier.TIME_CRITICAL, "def.fix", repair(s)).withDeadline(0));
			return;
		}
		if (onFood)
		{
			out.add(Candidate.of(Tier.TIME_CRITICAL, "def.clear", Instruction.builder().step(Step.DEF_SERVICE)
				.headline("Step off the food: let runners eat")
				.detail("Walk one tile north to the marked spot. Keep the food tile clear; repair when the trap breaks")
				.target(Target.tile(ArenaTiles.defenderService(wave), "Stand clear")).build()).withDeadline(0));
			return;
		}
		Instruction safety = call != null && settings.isSafetyBait() ? safetyBait(s, call, wave, food) : null;
		if (safety != null) out.add(Candidate.task(Tier.IDLE, "def.safety", safety));
		boolean nearby = ArenaTiles.distance(s.getPlayerTile(), food) <= 2;
		out.add(Candidate.of(Tier.IDLE, "def.watch", Instruction.builder().step(nearby ? Step.DEF_WATCH : Step.DEF_SERVICE)
			.headline(nearby ? "Keep the trap working; leave the food clear" : "Return beside the trap")
			.detail(there + " good food. " + (s.getTrapCharges() < 0 ? "Trap charges are out of view; check them when nearby"
				: "Trap has " + s.getTrapCharges() + " charge(s). Watch for the next repair")
				+ (call == null && there < TRAP_FOOD_MIN ? ". Wait for the healer's call before adding food" : ""))
			.target(nearby ? Target.NONE : Target.tile(ArenaTiles.defenderService(wave), "Stand clear")).urgency(Urgency.INFO).build()));
	}

	private static long approaching(Snapshot s, WorldPoint food)
	{
		return s.alive(PenanceType.RUNNER).stream().filter(p -> onApproach(p, food)
			&& (p.isUnseen() ? p.getUnseenTicks() <= MAX_STACK_WAIT
				: p.getTile() == null || ArenaTiles.distance(p.getTile(), food) > RELEASE_RADIUS)).count();
	}

	private static Instruction hold(Snapshot s, long incoming)
	{
		String detail = s.getTrapCharges() < 0 ? "Trap charges are unknown. Confirm 2 charges before releasing a stack"
			: s.getTrapCharges() < 2 ? "Trap has " + s.getTrapCharges() + " charge(s). A multi-kill needs 2; repair before releasing a stack"
			: incoming > 0 ? incoming + " runner(s) still approaching or out of view. Give them up to "
				+ Math.max(0, MAX_STACK_WAIT - stackWait(s)) + " more ticks once a runner is ready, then release the gathered batch"
			: "Wait for at least two runners to gather beside the food. Keep holding until the stack is ready";
		return Instruction.builder().step(Step.DEF_HOLD).headline("Hold on the trap food")
			.detail(detail + ". Routine restocking can wait")
			.target(Target.tile(ArenaTiles.trapFood(s.getWave()), "Hold here")).urgency(Urgency.INFO).build();
	}

	/** Release the last member of the main group, including when only deferred outliers remain. */
	private static Candidate releaseSingleton(Snapshot s, int wave)
	{
		WorldPoint food = ArenaTiles.trapFood(wave);
		List<PenanceView> alive = s.alive(PenanceType.RUNNER);
		if (wave < 1 || wave > 10 || s.getTrapCharges() <= 0 || goodAt(s, food) == 0
			|| readyRunners(s) != 1)
		{
			return null;
		}
		boolean last = s.getRunnersKilled() + s.getUncertainRunners() + alive.size() >= WaveInfo.runnersTotal(wave)
			&& alive.stream().noneMatch(PenanceView::isUnseen) && approaching(s, food) == 0;
		if (!last && stackWait(s) < MAX_STACK_WAIT)
		{
			return null;
		}
		boolean blocking = food.equals(s.getPlayerTile());
		WorldPoint beside = ArenaTiles.trapStep(wave);
		return Candidate.of(Tier.TEAM_BLOCKING, "def.last", Instruction.builder()
			.step(blocking ? Step.DEF_STEP : beside.equals(s.getPlayerTile()) ? Step.DEF_HOLD : Step.DEF_STAND)
			.headline(blocking ? "Step off the food: let the " + (last ? "last" : "waiting") + " runner eat"
				: "Let the last runner reach the trap")
			.detail("The trap has a charge and good bait. Stay beside it; don't wait for a second runner"
				+ (last ? "" : ". Handle late or out-of-view runners in the next batch"))
			.target(Target.tile(beside, "Beside trap"))
			.urgency(blocking ? Urgency.HIGH : Urgency.NORMAL)
			.build()).withDeadline(0);
	}

	/** Observed arrivals at the blocked food, excluding stale positions of unseen runners. */
	static int readyRunners(Snapshot s)
	{
		WorldPoint food = ArenaTiles.trapFood(s.getWave());
		return (int) s.alive(PenanceType.RUNNER).stream().filter(p -> !p.isUnseen() && p.getTile() != null
			&& ArenaTiles.distance(p.getTile(), food) <= RELEASE_RADIUS).count();
	}

	static boolean waitingStack(Snapshot s, Settings c)
	{
		int ready = readyRunners(s);
		return c.isDefenderMultiKill() && !s.isQueenAlive() && s.getTrapCharges() > 0 && ready > 0
			&& ArenaTiles.trapFood(s.getWave()).equals(s.getPlayerTile()) && goodAt(s, s.getPlayerTile()) >= ready;
	}

	static boolean releaseInProgress(Snapshot s)
	{
		return sameGoal(s.getTasks().target("def.step"), Target.tile(ArenaTiles.trapStep(s.getWave()), "Step"));
	}

	private static int stackWait(Snapshot s)
	{
		TaskMemory.Progress progress = s.getTasks().getEntries().get("def.stack");
		return progress == null ? 0 : Math.max(0, s.getTick() - progress.getLastProgressTick());
	}

	private static boolean onApproach(PenanceView p, WorldPoint food)
	{
		return p.isUnseen() || p.getTile() == null || p.getTile().getY() >= food.getY() - 1
			|| ArenaTiles.distance(p.getTile(), food) <= STACK_RADIUS;
	}

	/**
	 * The hammer-and-logs trip, one sticky task so the two pickups are one walk (they lie together
	 * on the north wall). Upkeep, except once it is overdue (two calls in without them) or the trap
	 * is worn and you couldn't fix it: then it outranks holding the trap.
	 */
	private Candidate toolsTrip(Snapshot s, int wave)
	{
		Instruction tools = tools(s, wave);
		if (tools == null)
		{
			return null;
		}
		// Before the trap needs them, not after: once runners are out the trip outranks guarding (the
		// trap takes two on its own while you're away; recorded 2026-10-16 waves 7 and 9: tools came
		// after the trap broke under a stack of 5, and the rest walked past it). A stack step at its
		// mark still goes first (it has a deadline); with nothing out it's upkeep, nearest first
		boolean runnersOut = !s.alive(PenanceType.RUNNER).isEmpty();
		// The opening trip (no hammer, or no log used yet) is time-critical; a later log is upkeep
		boolean opening = !s.isHasHammer() || s.getLogsTaken() <= s.count(BaIds.LOGS);
		return Candidate.task(runnersOut && opening ? Tier.TIME_CRITICAL : Tier.MAINTENANCE, "def.tools", tools);
	}

	/** Ticks until the next step-off mark on the call timer; 0 when the timer is unknown (step now). */
	static int ticksToStepOff(Snapshot s)
	{
		int into = s.ticksIntoCall();
		if (into < 0)
		{
			return 0;
		}
		return Math.floorMod(STEP_OFF_OFFSET - into, STEP_OFF_EVERY);
	}

	/** The call timer's seconds at the next step-off mark (27, 21, 15, 9 or 3). */
	static int stepOffSecond(Snapshot s)
	{
		// The next mark can fall in the next call (27s on its timer, not -3s on this one)
		int at = (Math.max(0, s.ticksIntoCall()) + ticksToStepOff(s)) % WaveInfo.TICKS_PER_CALL;
		return (int) Math.round((WaveInfo.TICKS_PER_CALL - at) * 0.6);
	}

	/** Logs still needed: one fix (2 charges) per two runners the trap's charges don't cover. */
	static int logsNeeded(Snapshot s, int wave)
	{
		int left = Math.max(0, WaveInfo.runnersTotal(wave) - s.getRunnersKilled());
		// Charges not seen yet: the trap starts full
		int uncovered = Math.max(0, left - (s.getTrapCharges() < 0 ? 2 : s.getTrapCharges()));
		return (uncovered + 1) / 2;
	}

	/** Runners walk about a tile a tick: ticks until the nearest one in view reaches the trap food. */
	private static int runnerArrival(Snapshot s, int wave)
	{
		WorldPoint food = ArenaTiles.trapFood(wave);
		return s.penance(PenanceType.RUNNER).stream()
			.filter(p -> p.getTile() != null)
			.mapToInt(p -> ArenaTiles.distance(p.getTile(), food))
			.min().orElse(Candidate.NO_DEADLINE);
	}

	/**
	 * Wiki: "If good food near the runner spawn runs out, drop more there as soon as possible" -
	 * while more runners are still to spawn.
	 */
	private static Instruction restockMainstack(Snapshot s, BaCall call, int wave)
	{
		int coming = WaveInfo.runnersTotal(wave) - s.getRunnersKilled() - s.getUncertainRunners() - s.alive(PenanceType.RUNNER).size();
		WorldPoint mainstack = ArenaTiles.mainstack(wave);
		if (coming <= 0 || s.getGroundItems().stream()
			.anyMatch(g -> BaIds.BAIT.contains(g.getItemId()) && g.isGood() && ArenaTiles.distance(g.getTile(), mainstack) <= 1))
		{
			return null;
		}
		if (!s.has(call.getItemId()))
		{
			return takeBait(s, call, 4, 0).toBuilder().detail("For the runner spawn: its good food is gone").build();
		}
		return Instruction.builder()
			.step(Step.DEF_DROP)
			.headline("Restock the runner spawn: drop " + call.getItemName())
			.detail("Its good food is gone and " + coming + " more runner" + (coming == 1 ? "" : "s") + " will spawn")
			.target(Target.tile(mainstack, "Mainstack"))
			.items(Planner.items(call.getItemId()))
			.build();
	}

	/**
	 * The trail's bad bait (between the mainstack and the trap) pulls runners from the spawn to the
	 * trap; once eaten, drop another while runners are still to spawn (recorded 2026-10-17 wave 7:
	 * eaten at tick 81, re-dropped by hand at 113).
	 */
	private Instruction restockTrail(Snapshot s, BaCall call, int wave)
	{
		FoodSpot trail = ArenaTiles.defenderPattern(wave, settings.getDefenderGuide(), settings.isSafetyBait()).stream()
			.filter(f -> f.getName().equals("Trail")).findFirst().orElse(null);
		int coming = WaveInfo.runnersTotal(wave) - s.getRunnersKilled() - s.getUncertainRunners() - s.alive(PenanceType.RUNNER).size();
		// Only a trail you laid this wave and that is gone now
		if (trail == null || coming <= 0 || placed(s, trail) == 0 || s.getGroundItems().stream()
			.anyMatch(g -> BaIds.BAIT.contains(g.getItemId()) && ArenaTiles.distance(g.getTile(), trail.getTile()) <= 1))
		{
			return null;
		}
		int bad = firstBad(s, call.getItemId());
		if (bad <= 0)
		{
			return null;
		}
		return Instruction.builder()
			.step(Step.DEF_DROP)
			.headline("Restock the trail: drop 1 bad")
			.detail("Its bait is gone and " + coming + " more runner" + (coming == 1 ? "" : "s") + " will spawn: it leads them to the trap")
			.target(Target.tile(trail.getTile(), "Trail"))
			.badBait(true)
			.items(Planner.items(bad))
			.build();
	}

	/** A runner this many tiles south of the trap food (and not stacked on you) is heading out. */
	static final int RELURE_SOUTH = 2;
	/** Drop the bad bait once the runner is this close: bait range is 4 tiles (5 from level 2). */
	static final int RELURE_DROP_RANGE = 3;
	/** Stand this many tiles north of the runner, between it and the trap. */
	static final int RELURE_AHEAD = 2;

	/**
	 * Lure a runner that is heading for the exit back north with bad bait (wiki: bad bait sends a
	 * runner several tiles north). Recorded 2026-10-16, 30 drops: bait 2-5 tiles north of the runner
	 * turned it back every time, often all the way to the trap; bait on or south of it, or once it
	 * was ~15 tiles south of the trap, didn't. So: start as soon as it's 2 tiles south of the trap
	 * food, get ahead of it (north), drop within 3 tiles, then let it eat before dropping another.
	 */
	private static Candidate relure(Snapshot s, BaCall call, int wave)
	{
		WorldPoint food = ArenaTiles.trapFood(wave);
		List<PenanceView> alive = s.alive(PenanceType.RUNNER);
		int repairs = logsNeeded(s, wave);
		if (wave < 1 || wave > 10 || call == null || !s.isListenFresh() || s.getWaveTick() < PATTERN_DEADLINE_TICKS
			|| s.getTrapCharges() <= 0 || goodAt(s, food) < TRAP_FOOD_MIN
			|| (repairs > 0 && (!s.isHasHammer() || !s.has(BaIds.LOGS)))
			|| s.getRunnersKilled() + s.getUncertainRunners() + alive.size() < WaveInfo.runnersTotal(wave)
			|| alive.stream().anyMatch(p -> onApproach(p, food)))
		{
			return null;
		}
		Instruction ins = relureStep(s, call, wave);
		if (ins == null)
		{
			return null;
		}
		// Ticks before it walks out of the exit: runners move about a tile a tick
		int exitY = ArenaTiles.safety(wave).getY() - ESCAPE_SOUTH_OF_SAFETY;
		return Candidate.task(Tier.MAINTENANCE, RELURE_TASK, ins)
			.withDeadline(Math.max(0, escapingRunner(s, wave).getTile().getY() - exitY));
	}

	/** Same line as RoundLogic's escape check: last seen this far south of the safety bait. */
	static final int ESCAPE_SOUTH_OF_SAFETY = 5;

	static final String RELURE_TASK = "def.relure";
	/** A runner out of view this long no longer counts as escaping: it may be gone. */
	static final int RELURE_UNSEEN_TICKS = 3;

	/**
	 * The southernmost runner heading for the exit, or null. During a relure, one that just walked
	 * out of view still counts at its last seen tile (recorded: one tick out of view dropped the
	 * relure for a bait trip); one long out of view, or one that left view before any relure,
	 * doesn't (recorded: a 36-tick relure for a runner never seen again).
	 */
	private static PenanceView escapingRunner(Snapshot s, int wave)
	{
		WorldPoint trapFood = ArenaTiles.trapFood(wave);
		int unseenOk = RELURE_TASK.equals(s.getLastTask()) ? RELURE_UNSEEN_TICKS : -1;
		return s.alive(PenanceType.RUNNER).stream()
			.filter(p -> p.getTile() != null && (!p.isUnseen() || p.getUnseenTicks() <= unseenOk) && p.getTile().getY() <= trapFood.getY() - RELURE_SOUTH
				&& ArenaTiles.distance(p.getTile(), trapFood) > STACK_RADIUS)
			.min(Comparator.comparingInt(p -> p.getTile().getY()))
			.orElse(null);
	}

	private static Instruction relureStep(Snapshot s, BaCall call, int wave)
	{
		PenanceView escaping = escapingRunner(s, wave);
		int bad = escaping == null ? -1 : firstBad(s, call == null ? -1 : call.getItemId());
		if (bad < 0)
		{
			return null;
		}
		WorldPoint runner = escaping.getTile();
		boolean baitWaiting = s.getGroundItems().stream()
			.anyMatch(g -> BaIds.BAIT.contains(g.getItemId()) && !g.isGood()
				&& g.getTile().getY() >= runner.getY() && ArenaTiles.distance(g.getTile(), runner) <= RELURE_DROP_RANGE + 1);
		if (baitWaiting)
		{
			return Instruction.builder()
				.step(Step.DEF_RELURE)
				.headline("Runner going for your bad bait: wait")
				.detail("It eats it and turns north, back to the trap. Drop another if it keeps going south")
				.target(Target.npc(escaping.getNpcIndex(), runner))
				.urgency(Urgency.INFO)
				.build();
		}
		WorldPoint me = s.getPlayerTile();
		// One tile inside the runner's notice range (4 tiles, 5 from defender level 2)
		int dropRange = Math.max(RELURE_DROP_RANGE, s.baitRange() - 1);
		boolean inRange = me != null && ArenaTiles.distance(me, runner) <= dropRange && me.getY() >= runner.getY();
		if (inRange)
		{
			return Instruction.builder()
				.step(Step.DEF_RELURE)
				.headline("Drop bad bait now: the runner is in range")
				.detail("Bad bait sends it north, back to the trap. An escape costs the team 3 points")
				.target(Target.tile(me, "Drop here"))
				.badBait(true)
				.items(Planner.items(bad))
				.urgency(Urgency.HIGH)
				.build();
		}
		return Instruction.builder()
			.step(Step.DEF_RELURE)
			.headline("Runner escaping: get ahead of it")
			.detail("Stand on the marked tile north of it, then drop bad bait (within " + Math.max(RELURE_DROP_RANGE, s.baitRange() - 1) + " tiles)")
			.target(Target.tile(runner.dy(RELURE_AHEAD), "Get here"))
			.badBait(true)
			.items(Planner.items(bad))
			.urgency(Urgency.HIGH)
			.build();
	}

	/**
	 * Put safety bait south of the trap first, then work north through trap, trail, mainstack and
	 * west relure. The no-safety guides begin at the trap instead.
	 */
	static final List<String> ROUTE = ImmutableList.of("Safety", "Trap", "Trail", "Mainstack", "West relure");
	/** With this few ticks left in the call, skip bad bait to reach the remaining good spots. */
	static final int SHORT_TICKS = 12;

	/**
	 * The pattern as one route: its next unfinished spot, and once the good bait is all down, the
	 * hammer and logs when they're a few tiles off it (they spawn by the mainstack; Gau Cho's guide:
	 * mainstack, then logs, then hammer. Reported 2026-10-16: from the middle bait the hammer is ~6
	 * tiles away too, and it was sent there before the mainstack).
	 */
	private Instruction pattern(Snapshot s, BaCall call)
	{
		Instruction spot = patternSpot(s, call);
		if (spot == null)
		{
			return null;
		}
		// Guide: drop the good food, then grab the hammer and logs (they lie by the mainstack) before
		// going back to the trap - recorded 2026-10-16 wave 7: the trip flipped back to the relure
		// once the walk passed 6 tiles, and the tools only came after the trap broke under a stack
		if (!goodSpotsDone(s))
		{
			return spot;
		}
		// The opening tools trip, the player's route (2026-10-17): from the mainstack to the log on
		// the West relure tile - take it and drop the bad bait there in the same stop - then the
		// other log, then the hammer, which is on the way back to the trap
		boolean badHere = spot.getStep() == Step.DEF_DROP && !spot.getItems().contains(call.getItemId())
			&& spot.getTarget().getTile() != null && ArenaTiles.distance(s.getPlayerTile(), spot.getTarget().getTile()) <= PASSING_BAD;
		Instruction tools = tools(s, s.getWave(), false, true);
		Target committed = rememberedTarget(s, "def.pattern");
		// The pattern is one task, but its selected stop must also survive a proximity boundary.
		if (tools != null && sameGoal(committed, tools.getTarget()))
		{
			return tools.toBuilder().marks(spot.getMarks()).build();
		}
		if (sameGoal(committed, spot.getTarget())) return spot;
		if (tools != null && !badHere)
		{
			return tools.toBuilder().marks(spot.getMarks()).build();
		}
		return spot;
	}

	/** The food pattern: next unfinished spot, or restock first if the inventory can't cover it. */
	private Instruction patternSpot(Snapshot s, BaCall call)
	{
		List<FoodSpot> spots = ArenaTiles.defenderPattern(s.getWave(), settings.getDefenderGuide(), settings.isSafetyBait());
		ImmutableList.Builder<TileMark> marks = ImmutableList.builder();
		FoodSpot next = null;
		List<FoodSpot> route = new java.util.ArrayList<>(spots);
		route.sort(Comparator.comparingInt(f -> ROUTE.indexOf(f.getName())));
		boolean shortOnTime = s.getTicksToCallChange() >= 0 && s.getTicksToCallChange() < SHORT_TICKS;
		int needGood = 0;
		int needBad = 0;
		for (FoodSpot spot : spots)
		{
			int there = placed(s, spot);
			int missing = Math.max(0, spot.getCount() - there);
			marks.add(new TileMark(spot.getTile(), spot.getName() + " " + Math.min(there, spot.getCount()) + "/" + spot.label(),
				missing == 0, spot.isGood()));
			if (missing > 0)
			{
				if (spot.isGood())
				{
					needGood += missing;
				}
				else
				{
					needBad += missing;
				}
			}
		}
		boolean goodLeft = route.stream().anyMatch(f -> f.isGood() && placed(s, f) < f.getCount());
		Target committed = rememberedTarget(s, "def.pattern");
		// Safety is the first opening stop even when another tile happens to be nearer. Once it
		// has been dropped, walking back past it cannot interrupt the next committed stop.
		if (!(shortOnTime && goodLeft))
			next = route.stream().filter(f -> f.getName().equals("Safety") && placed(s, f) < f.getCount()).findFirst().orElse(null);
		// Once chosen, finish the spot's observed missing count.
		// A short remaining call can still drop optional bad bait in favour of unfinished good bait.
		for (FoodSpot spot : route)
		{
			if (next != null) break;
			if (sameGoal(committed, Target.tile(spot.getTile(), spot.getName()))
				&& placed(s, spot) < spot.getCount() && !(shortOnTime && !spot.isGood() && goodLeft))
			{
				next = spot;
				break;
			}
		}
		// A nearby unfinished spot is useful when starting a stop, not a reason to turn back midway.
		route.sort(Comparator.comparing((FoodSpot f) -> ArenaTiles.distance(s.getPlayerTile(), f.getTile()) > (f.isGood() ? 1 : PASSING_BAD)));
		for (FoodSpot spot : route)
		{
			if (next != null) break;
			int there = placed(s, spot);
			if (there < spot.getCount() && !(shortOnTime && !spot.isGood() && goodLeft))
			{
				next = spot;
				break;
			}
		}
		if (next == null)
		{
			return null;
		}

		int haveGood = s.count(call.getItemId());
		int haveBad = badInInventory(s, call.getItemId());
		if (haveGood < needGood || haveBad < needBad)
		{
			return takeBait(s, call, Math.max(0, needGood - haveGood), Math.max(0, needBad - haveBad))
				.toBuilder().marks(marks.build()).build();
		}

		int badItem = firstBad(s, call.getItemId());
		int dropItem = next.isGood() ? call.getItemId() : badItem;
		return Instruction.builder()
			.step(Step.DEF_DROP)
			.headline("Drop " + next.label() + " at " + next.getName())
			.detail(next.isGood() ? call.getItemName() + " (the call)" : "Any other bait: it only pulls runners along")
			.target(Target.tile(next.getTile(), next.getName()))
			.badBait(!next.isGood())
			.items(dropItem > 0 ? Planner.items(dropItem) : Planner.items())
			.marks(marks.build())
			.build();
	}

	/** A missing tool, keeping the chosen item through the trip; null when you have them all. */
	private Instruction tools(Snapshot s, int wave)
	{
		return tools(s, wave, false, false);
	}

	private Instruction tools(Snapshot s, int wave, boolean forRepair)
	{
		return tools(s, wave, forRepair, false);
	}

	/**
	 * The wave's log target counts logs picked up this wave, not logs held: repairs use them up,
	 * and that's not a reason to go back (reported 2026-10-16). {@code forRepair}: the trap needs
	 * fixing and you hold none, so one more whatever the target.
	 */
	private Instruction tools(Snapshot s, int wave, boolean forRepair, boolean logsFirst)
	{
		// Logs from what the wave needs (a fix per two runners the charges won't cover), all of them
		// in the opening trip: both logs, the hammer, then wait at the spawn for the respawn and take
		// the extra ones (waves 8-9) before going back - never a trip back mid-wave for them (player,
		// 2026-10-17). Only 2 lie out at a time; they respawn 7-10 ticks after pickup. Once repairs
		// have started, one more only if you run out
		int logs = s.count(BaIds.LOGS);
		int need = logsNeeded(s, wave);
		boolean opening = s.getLogsTaken() <= logs;
		int wantLogs = logTarget(s, wave);
		boolean needLog = logs < wantLogs || (logs == 0 && (need > 0 || forRepair));
		boolean needHammer = !s.isHasHammer() && (need > 0 || forRepair || logs > 0);
		Target committed = rememberedTarget(s, logsFirst ? "def.pattern" : forRepair ? "def.repair" : "def.tools");
		if (committed == null && ("def.pattern".equals(s.getLastTask()) || "def.tools".equals(s.getLastTask())
			|| "def.repair".equals(s.getLastTask())) && s.getLastTargetTile() != null)
		{
			// A broken trap or a finished pattern can rename the trip without completing its item.
			committed = new Target(Target.Kind.NONE, -1, s.getLastTargetTile(), null);
		}
		GroundItemView hammer = needHammer ? toolItem(s, BaIds.HAMMER, committed) : null;
		GroundItemView log = needLog ? toolItem(s, BaIds.LOGS, committed) : null;
		boolean keepHammer = hammer != null && sameGoal(committed, Target.groundItem(BaIds.HAMMER, hammer.getTile()));
		boolean waitingForLogs = needLog && opening && logs > 0 && committed != null
			&& committed.getKind() == Target.Kind.TILE && ArenaTiles.logSpawn(wave).equals(committed.getTile());
		boolean keepLog = log != null && (waitingForLogs || sameGoal(committed, Target.groundItem(BaIds.LOGS, log.getTile())));
		if (waitingForLogs && log == null) return waitForLogs(wave, logs, wantLogs);
		boolean hammerCloser = hammer != null && log != null && !logsFirst
			&& ArenaTiles.distance(s.getPlayerTile(), hammer.getTile()) <= ArenaTiles.distance(s.getPlayerTile(), log.getTile());
		if (hammer != null && (keepHammer || !keepLog && (log == null || hammerCloser)))
		{
			return Instruction.builder()
				.step(Step.DEF_HAMMER)
				.headline("Pick up the hammer")
				.detail(log != null ? "Then the logs next to it, in the same trip" : "You need it to repair the trap")
				.target(Target.groundItem(hammer.getItemId(), hammer.getTile()))
				.build();
		}
		if (log != null)
		{
			return Instruction.builder()
				.step(Step.DEF_LOGS)
				.headline(logs < wantLogs ? "Pick up logs (" + logs + "/" + wantLogs + ")" : "Pick up a log for the repair")
				.detail(logs + 1 < wantLogs ? "Then the other log" + (hammer != null ? " and the hammer" : "") + ", in the same trip"
					: hammer != null ? "Then the hammer, on the way back to the trap" : "Each repair takes one log")
				.target(Target.groundItem(log.getItemId(), log.getTile()))
				// Bait dropped on the same tile (the West relure) would otherwise sit on top
				.build();
		}
		if (needLog && opening && logs > 0)
		{
			// Both taken: wait by the spawn for the respawn rather than come back later
			return waitForLogs(wave, logs, wantLogs);
		}
		return null;
	}

	private static Instruction waitForLogs(int wave, int logs, int wantLogs)
	{
		return Instruction.builder().step(Step.DEF_LOGS)
			.headline("Wait for the logs to respawn (" + logs + "/" + wantLogs + ")")
			.detail("They come back within a few seconds: take them now, no trip back later")
			.target(Target.tile(ArenaTiles.logSpawn(wave), "Logs")).build();
	}

	private static GroundItemView toolItem(Snapshot s, int id, Target committed)
	{
		GroundItemView previous = s.getGroundItems().stream()
			.filter(g -> g.getItemId() == id && sameGoal(committed, Target.groundItem(id, g.getTile())))
			.findFirst().orElse(null);
		return previous == null ? nearest(s, id) : previous;
	}

	private static boolean sameGoal(Target previous, Target next)
	{
		return previous != null && previous.getTile() != null && previous.getTile().equals(next.getTile())
			&& (previous.getKind() == Target.Kind.NONE || previous.getKind() == next.getKind()
				&& (previous.getKind() != Target.Kind.GROUND_ITEM || previous.getId() == next.getId()));
	}

	private static Target rememberedTarget(Snapshot s, String task)
	{
		Target remembered = s.getTasks().target(task);
		if (remembered != null && remembered.getTile() != null) return remembered;
		boolean openingWalk = "def.pattern".equals(task) && ("def.wait".equals(s.getLastTask())
			|| "call".equals(s.getLastTask()) && s.getCallPeriod() == 0);
		return s.getLastTargetTile() != null && (task.equals(s.getLastTask()) || openingWalk)
			? new Target(Target.Kind.NONE, -1, s.getLastTargetTile(), null) : null;
	}

	/**
	 * The trap handles the runners that are out without you: a charge and a good bait for each
	 * (runners out of view count too).
	 */
	private static boolean trapCopes(Snapshot s, WorldPoint trapFood)
	{
		int out = s.alive(PenanceType.RUNNER).size();
		return out == 0 || (s.getTrapCharges() >= out && goodAt(s, trapFood) >= out);
	}

	/** Every good-bait spot of the pattern holds its count. */
	private boolean goodSpotsDone(Snapshot s)
	{
		return ArenaTiles.defenderPattern(s.getWave(), settings.getDefenderGuide(), settings.isSafetyBait()).stream()
			.filter(FoodSpot::isGood)
			.allMatch(f -> placed(s, f) >= f.getCount());
	}

	/** The defender's trap: the trap object next to the trap food (the west one is never used). */
	private static ObjectView trap(Snapshot s)
	{
		WorldPoint food = ArenaTiles.trapFood(s.getWave());
		return s.getObjects().stream()
			.filter(o -> o.getId() == BaIds.TRAP_FULL || o.getId() == BaIds.TRAP_ONE || o.getId() == BaIds.TRAP_BROKEN)
			.min(Comparator.comparingInt(o -> ArenaTiles.distance(o.getTile(), food)))
			.orElse(null);
	}

	private Instruction repair(Snapshot s)
	{
		ObjectView trap = trap(s);
		if (!s.isHasHammer() || !s.has(BaIds.LOGS))
		{
			Instruction tools = tools(s, s.getWave(), true);
			if (tools != null)
			{
				return tools.toBuilder().detail("The trap needs repairing: " + tools.getDetail()).urgency(Urgency.HIGH).build();
			}
			boolean logs = !s.has(BaIds.LOGS);
			return Instruction.builder().step(logs ? Step.DEF_LOGS : Step.DEF_HAMMER)
				.headline(logs ? "Get a log before repairing" : "Find the hammer before repairing")
				.detail("The missing repair tool is not visible. Check the tool area by the log spawn, then return to the repair spot")
				.target(Target.tile(ArenaTiles.logSpawn(s.getWave()), "Repair supplies")).urgency(Urgency.HIGH).build();
		}
		WorldPoint food = ArenaTiles.trapFood(s.getWave());
		if (s.isHasHammer() && s.has(BaIds.LOGS) && !food.equals(s.getPlayerTile()))
		{
			return Instruction.builder().step(Step.DEF_REPAIR_POSITION)
				.headline("Walk onto the marked food tile, then fix the trap")
				.detail("Stand on the repair spot (" + (food.getX() & 63) + ", " + (food.getY() & 63)
					+ ") to block runners briefly. Then click the trap's Fix option")
				.target(Target.tile(food, "Repair spot")).urgency(Urgency.HIGH).build();
		}
		return Instruction.builder()
			.step(Step.DEF_REPAIR)
			.headline("Fix the trap")
			.detail("Stay on the food tile and click the trap's Fix option with logs and hammer in your inventory."
				+ (settings.isDefenderMultiKill() ? " Keep holding until the stack-release prompt"
					: " Once repaired, top up food if needed, then step aside so runners can eat"))
			.target(trap == null ? Target.NONE : Target.object(trap.getId(), trap.getTile()))
			.urgency(Urgency.HIGH)
			.build();
	}

	/**
	 * The safety bait (bad bait several tiles south of the trap, OSRS Wiki 1-4-1-4-1) catches a
	 * runner that walks past the trap and sends it back north. Optional in other guides, so it's
	 * maintenance: re-dropped when gone (eaten, or never dropped), only while runners remain, you
	 * hold bad bait and the trap can do without you. Recorded 2026-10-16: dropped in 2 of 22
	 * defender waves; the one time a runner reached it, it ate it and walked back to the trap.
	 */
	private static Instruction safetyBait(Snapshot s, BaCall call, int wave, WorldPoint trapFood)
	{
		boolean runnersLeft = !s.alive(PenanceType.RUNNER).isEmpty() || s.getRunnersKilled() < WaveInfo.runnersTotal(wave);
		WorldPoint tile = ArenaTiles.safety(wave);
		int bad = firstBad(s, call.getItemId());
		if (!runnersLeft || bad < 0 || badAt(s, tile) > 0 || !trapCopes(s, trapFood))
		{
			return null;
		}
		return Instruction.builder()
			.step(Step.DEF_DROP)
			.headline("Re-drop the safety bait")
			.detail("Bad bait south of the trap: a runner that walks past eats it and turns back north")
			.target(Target.tile(tile, "Safety"))
			.badBait(true)
			.items(Planner.items(bad))
			.urgency(Urgency.INFO)
			.build();
	}

	/** Hold at least this many of each bait kind. */
	static final int BAIT_RESERVE = 2;

	/** Machine trip for whichever bait kinds are under the reserve; null when all are stocked. */
	private static Instruction topUpBait(Snapshot s, BaCall call)
	{
		List<BaCall> low = new java.util.ArrayList<>();
		for (BaCall bait : new BaCall[]{BaCall.BAIT_TOFU, BaCall.BAIT_CRACKERS, BaCall.BAIT_WORMS})
		{
			if (s.count(bait.getItemId()) < BAIT_RESERVE)
			{
				low.add(bait);
			}
		}
		if (low.isEmpty() || s.getFreeSlots() < 3)
		{
			return null;
		}
		if (low.size() > 1)
		{
			return stockUp(s, call).toBuilder()
				.detail("Low on " + low.size() + " baits: the call can switch to any of them").build();
		}
		ObjectView machine = s.nearestObject(BaIds.DEFENDER_MACHINE);
		BaCall bait = low.get(0);
		return Instruction.builder()
			.step(Step.DEF_TAKE_BAIT)
			.headline("Take-" + bait.getKeyword() + " at the defender machine")
			.detail(s.count(bait.getItemId()) + " left; the call can switch to it")
			.target(machine == null ? Target.NONE : Target.object(machine.getId(), machine.getTile()))
			.urgency(Urgency.INFO)
			.build();
	}

	private static boolean holdsBait(Snapshot s)
	{
		return BaIds.BAIT.stream().anyMatch(s::has);
	}

	private static Instruction stockUp(Snapshot s, BaCall call)
	{
		ObjectView machine = s.nearestObject(BaIds.DEFENDER_MACHINE);
		return Instruction.builder()
			.step(Step.DEF_TAKE_BAIT)
			.headline("Stock-Up at the defender item machine")
			.detail("One click fills your inventory with all three baits"
				+ (call == null ? "; the healer's call says which is good" : ". The call is " + call.getItemName()))
			.target(machine == null ? Target.NONE : Target.object(machine.getId(), machine.getTile()))
			.build();
	}

	private static Instruction takeBait(Snapshot s, BaCall call, int good, int bad)
	{
		if (bad > 0 || good > 5)
		{
			// Several kinds or a big batch: Stock-Up is one click instead of one per kind
			return stockUp(s, call);
		}
		ObjectView machine = s.nearestObject(BaIds.DEFENDER_MACHINE);
		String what = good > 0 && bad > 0
			? good + " " + call.getItemName() + " + " + bad + " other bait"
			: good > 0 ? good + " " + call.getItemName() : bad + " bait of another kind";
		return Instruction.builder()
			.step(Step.DEF_TAKE_BAIT)
			.headline("Take " + what)
			.detail("From the defender item machine. The call is " + call.getItemName())
			.target(machine == null ? Target.NONE : Target.object(machine.getId(), machine.getTile()))
			.build();
	}

	/** Good bait on a tile, of any kind: bait keeps its good status after the call changes (wiki). */
	private static int goodAt(Snapshot s, WorldPoint tile)
	{
		return s.getGroundItems().stream()
			.filter(g -> BaIds.BAIT.contains(g.getItemId()) && g.isGood() && ArenaTiles.distance(g.getTile(), tile) == 0)
			.mapToInt(GroundItemView::getQuantity).sum();
	}

	/**
	 * Bait of the spot's kind put down on it this wave: what lies there now, or what was dropped
	 * there if more (runners eat it). Recorded 2026-10-16: runners ate the trap bait early, the
	 * trap counted as unfinished again and the mainstack never came up.
	 */
	static int placed(Snapshot s, FoodSpot spot)
	{
		int now = spot.isGood() ? goodAt(s, spot.getTile()) : badAt(s, spot.getTile());
		Integer landed = (spot.isGood() ? s.getGoodBaitLanded() : s.getBadBaitLanded()).get(spot.getTile());
		return Math.max(now, landed == null ? 0 : landed);
	}

	private static int logTarget(Snapshot s, int wave)
	{
		int need = logsNeeded(s, wave);
		return s.getLogsTaken() <= s.count(BaIds.LOGS) ? need : Math.min(OPENING_LOGS, need);
	}

	static boolean toolsReady(Snapshot s)
	{
		int logs = s.count(BaIds.LOGS);
		return logs >= logTarget(s, s.getWave())
			&& (s.isHasHammer() || logsNeeded(s, s.getWave()) == 0 && logs == 0);
	}

	private static int badAt(Snapshot s, WorldPoint tile)
	{
		return s.getGroundItems().stream()
			.filter(g -> BaIds.BAIT.contains(g.getItemId()) && !g.isGood() && ArenaTiles.distance(g.getTile(), tile) == 0)
			.mapToInt(GroundItemView::getQuantity).sum();
	}

	private static int badInInventory(Snapshot s, int good)
	{
		return BaIds.BAIT.stream().filter(id -> id != good).mapToInt(s::count).sum();
	}

	private static int firstBad(Snapshot s, int good)
	{
		return BaIds.BAIT.stream().filter(id -> id != good && s.has(id)).findFirst().orElse(-1);
	}

	private static GroundItemView nearest(Snapshot s, int itemId)
	{
		return s.getGroundItems().stream()
			.filter(g -> g.getItemId() == itemId)
			.min(Comparator.comparingInt(g -> ArenaTiles.distance(s.getPlayerTile(), g.getTile())))
			.orElse(null);
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.HealCode;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.WaveInfo;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.PenanceDiagnostics;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import com.bautopilot.baautopilot.state.TeammateView;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Healer: cover every unpoisoned healer, including those last seen out of view, then refresh
 * poison below 4, lowest strength first. With coverage secure, spare food can finish a nearby
 * healer to release reserves. Optional heal codes only break equivalent-target ties.
 */
class HealerPlanner
{
	/**
	 * A teammate in real danger is safety; food for the current call and needed poison are time
	 * critical; topping up a hurt teammate is upkeep; waiting for the next spawn is idle.
	 */
	List<Candidate> candidates(Snapshot s, Settings c)
	{
		List<Candidate> out = new ArrayList<>();
		if (s.getWave() < 10 && CollectorPlanner.nothingLeftToShoot(s))
		{
			out.add(Candidate.of(Tier.IDLE, "heal.complete", Instruction.builder()
				.step(Step.HEAL_SUPPORT).headline("Wave complete")
				.detail("Wait for the next wave: everyone's HP restores automatically")
				.urgency(Urgency.INFO).build()));
			return out;
		}
		BaCall call = s.getListenCall();
		Instruction medic = medic(s, c, true);
		if (medic != null)
		{
			out.add(Candidate.task(Tier.SAFETY, "heal.medic", medic));
		}

		// Stock-Up needs no call: from the first tick, then up the east side to the healer spawn
		// (recorded 2026-10-17: "Wait for the defender's call" for 7 ticks, then a wait, while the
		// player stocked up by hand)
		boolean healersToCome = !s.alive(PenanceType.HEALER).isEmpty()
			|| s.getHealersKilled() < WaveInfo.healersTotal(s.getWave());
		if (healersToCome && BaIds.POISON_FOOD.stream().noneMatch(s::has) && s.getWaveTick() >= 0
			&& s.getWaveTick() < WaveInfo.TICKS_PER_CALL)
		{
			ObjectView machine = s.nearestObject(BaIds.HEALER_MACHINE);
			out.add(Candidate.task(Tier.TIME_CRITICAL, "heal.stock", Instruction.builder()
				.step(Step.HEAL_TAKE_FOOD)
				.headline("Stock-Up at the healer item machine")
				.detail("All three foods in one click; no call needed")
				.target(machine == null ? Target.NONE : Target.object(machine.getId(), machine.getTile()))
				.build()));
			return out;
		}
		if (call == null)
		{
			if (s.getWaveTick() >= 0 && s.getWaveTick() < WaveInfo.TICKS_PER_CALL)
			{
				out.add(Candidate.of(Tier.IDLE, "heal.wait", Instruction.builder()
					.step(Step.HEAL_WAIT_CALL)
					.headline("Head to the healer spawn")
					.detail("Feed the first healer as soon as the defender calls")
					.target(Target.tile(ArenaTiles.healerWait(s.getWave()), "Healers"))
					.urgency(Urgency.INFO)
					.build()));
				return out;
			}
			out.add(Candidate.of(Tier.IDLE, "heal.wait", Instruction.builder()
				.step(Step.HEAL_WAIT_CALL)
				.headline("Wait for the defender's call")
				.detail("Stand north-east where the healers spawn; wrong food is a penalty")
				.urgency(Urgency.INFO)
				.build()));
			return out;
		}

		int food = call.getItemId();
		String stale = staleFood(s, food);
		List<PenanceView> alive = s.alive(PenanceType.HEALER);
		boolean healersLeft = !alive.isEmpty() || s.getHealersKilled() < WaveInfo.healersTotal(s.getWave());
		if (!s.has(food) && healersLeft)
		{
			ObjectView machine = s.nearestObject(BaIds.HEALER_MACHINE);
			out.add(Candidate.task(Tier.TIME_CRITICAL, "heal.food", Instruction.builder()
				.step(Step.HEAL_TAKE_FOOD)
				.headline("Take " + call.getItemName())
				.detail("Healer item machine: Take-" + call.getKeyword() + (stale.isEmpty() ? "" : "\n" + stale))
				.target(machine == null ? Target.NONE : Target.object(machine.getId(), machine.getTile()))
				.build()));
			return out;
		}

		// Healers that walked out of view stay on the list: they're alive, and dropping them made the
		// target jump to another healer and back (reported 2026-10-16)
		List<PenanceView> healers = s.alive(PenanceType.HEALER).stream()
			.sorted(Comparator.comparingInt(PenanceView::getOrder))
			.collect(Collectors.toList());

		HealCode code = HealCode.of(c.getHealCodeSet(), s.getWave());
		Candidate pick = byPriority(s, healers, call, code);
		if (pick == null) pick = reserveFeed(s, healers, call);
		if (pick != null)
		{
			Instruction ins = pick.getInstruction();
			out.add(stale.isEmpty() ? pick : new Candidate(pick.getTier(), pick.getTask(),
				ins.toBuilder().detail(ins.getDetail() + "\n" + stale).build(), pick.getDeadline(), pick.isSticky()));
		}

		Instruction support = medic(s, c, false);
		if (support != null)
		{
			out.add(Candidate.task(Tier.MAINTENANCE, "heal.medic", support));
		}
		if (pick != null)
		{
			return out;
		}
		boolean more = s.getHealersKilled() + healers.size() < WaveInfo.healersTotal(s.getWave());
		int keep = foodToKeep(s, healers);
		int reserves = reservesWaiting(s);
		// A trip for one or two foods isn't worth leaving the healers for
		if (s.count(food) < keep - TOPUP_SLACK)
		{
			// Nothing to feed now: fill up for the healers still to come instead of running out later
			ObjectView machine = s.nearestObject(BaIds.HEALER_MACHINE);
			out.add(Candidate.task(Tier.MAINTENANCE, "heal.topup", Instruction.builder()
				.step(Step.HEAL_TAKE_FOOD)
				.headline("Top up " + call.getItemName() + " (" + s.count(food) + "/" + keep + ")")
				.detail("Every healer out is poisoned: get food now for the ones still to come")
				.target(machine == null ? Target.NONE : Target.object(machine.getId(), machine.getTile()))
				.build()));
		}
		out.add(Candidate.of(Tier.IDLE, "heal.support", Instruction.builder()
			.step(Step.HEAL_SUPPORT)
			.headline(!healers.isEmpty() ? "All healers poisoned: let it work"
				: more ? "Wait where the next healer spawns" : "All penance healers are down")
			.detail(!healers.isEmpty()
				? "Keeping " + keep + " food for coverage. " + (reserves > 0
					? reserves + " reserves still need a kill; use spare food on a nearby healer when available"
					: "No reserve slot needs opening; refresh when poison falls below 4")
				: more ? "On the marked tile by the healer cave" : "Support the team while the remaining Penance are finished")
			.target(more ? Target.tile(ArenaTiles.healerWait(s.getWave()), "Wait here") : Target.NONE)
			.urgency(Urgency.INFO)
			.build()));
		return out;
	}

	private static Candidate byPriority(Snapshot s, List<PenanceView> healers, BaCall call, HealCode code)
	{
		int tick = s.getTick();
		Target coverage = s.getTasks().target("heal.cover");
		// Strength beats visibility, guide timing and commitment. Within equivalent strength,
		// cover visible healthy newcomers before wounded ones, retaining the target within that
		// health band so small health-bar changes do not make guidance flicker.
		PenanceView h = healers.stream().filter(p -> p.nextPoisonHit(tick) < WaveInfo.FOOD_DAMAGE)
			.min(Comparator.comparingInt((PenanceView p) -> p.nextPoisonHit(tick))
				.thenComparing(PenanceView::isUnseen)
				.thenComparingInt(p -> p.hpFraction() > 0.5 ? 0 : 1)
				.thenComparingInt(p -> p.getNpcIndex() == s.getLastTargetNpc()
					|| coverage != null && p.getNpcIndex() == coverage.getId() ? 0 : 1)
				.thenComparingInt(p -> guideDue(p, s, code) ? 0 : 1)
				.thenComparingInt(PenanceView::getOrder))
			.orElse(null);
		if (h == null)
		{
			return null;
		}
		int strength = h.nextPoisonHit(tick);
		String why = strength == 0 ? (h.poisoned() ? "Poison has expired" : "Initial poison")
			+ ": feed before refreshing poisoned healers. Wait for the food to land"
			: "Poison down to " + strength + " a hit: refresh once to 4. Lower poison comes first";
		if (strength > 0 && guideDue(h, s, code)) why += ". Guide " + code.getName();
		Instruction ins = feed(h, call, why);
		return strength == 0 ? Candidate.task(Tier.TIME_CRITICAL, "heal.cover", ins)
			: Candidate.of(Tier.TIME_CRITICAL, "heal.feed", ins);
	}

	static final String RESERVE_TASK = "heal.reserve";
	/** Extra damage is local work, not a reason to chase a healer across the arena. */
	static final int RESERVE_RANGE = 8;

	/**
	 * Each death releases one reserve, even if the staggered initial spawns are not all out yet.
	 * Dying healers are already included in the snapshot's kill count. A healer guaranteed to
	 * die to its next 4-poison hit also supplies a slot without spending more food.
	 * Observed reserve spawn orders also establish progress if a death was missed out of view.
	 */
	static int reservesWaiting(Snapshot s)
	{
		if (s.getCleared().contains(PenanceType.HEALER)) return 0;
		int initial = WaveInfo.healersInitial(s.getWave());
		int total = WaveInfo.healersTotal(s.getWave());
		List<PenanceView> alive = s.alive(PenanceType.HEALER);
		int imminent = (int) alive.stream().filter(p -> !p.isUnseen() && p.nextPoisonHit(s.getTick()) == 4
			&& knownHpUpper(s, p) > 0 && knownHpUpper(s, p) <= WaveInfo.FOOD_DAMAGE).count();
		int observed = alive.stream().mapToInt(PenanceView::getOrder).max().orElse(0);
		int released = Math.max(s.getHealersKilled(), observed - initial) + imminent;
		return Math.max(0, total - initial - released);
	}

	/** Only called after every first tag and weak-poison refresh has been covered. */
	private static Candidate reserveFeed(Snapshot s, List<PenanceView> healers, BaCall call)
	{
		int reserves = reservesWaiting(s);
		int keep = foodToKeep(s, healers);
		if (reserves == 0 || s.count(call.getItemId()) <= keep) return null;
		Target remembered = s.getTasks().target(RESERVE_TASK);
		PenanceView h = healers.stream().filter(p -> !p.isUnseen() && p.getTile() != null
			&& s.getPlayerTile() != null && s.walk(p.getTile()) <= RESERVE_RANGE
			&& (s.getTicksToCallChange() < 0 || feedTravel(s, p) + 2 < s.getTicksToCallChange())
			&& hpUpper(s, p) > WaveInfo.FOOD_DAMAGE)
			.min(Comparator.comparingDouble((PenanceView p) -> hpUpper(s, p) + WaveInfo.FOOD_DAMAGE * feedTravel(s, p)
				// One food's worth of continuity avoids changing targets on small HP-bar differences.
				- (RESERVE_TASK.equals(s.getLastTask()) && p.getNpcIndex() == s.getLastTargetNpc()
					|| remembered != null && p.getNpcIndex() == remembered.getId() ? WaveInfo.FOOD_DAMAGE : 0))
				.thenComparingInt(PenanceView::getOrder)).orElse(null);
		if (h == null) return null;
		Instruction ins = feed(h, call, "Finish this healer to open a spawn slot: " + reserves
			+ " reserve" + (reserves == 1 ? " still needs a kill" : "s still need kills") + ". Extra food deals 4 direct damage even at 4 poison"
			+ ". Keep " + keep + " food for coverage; switch to any new unpoisoned healer first")
			.toBuilder().headline("Finish healer #" + h.getOrder() + " with " + call.getItemName()).build();
		// Re-evaluate every tick: this commitment cannot bypass new tags, refreshes or safety.
		return Candidate.of(Tier.TIME_CRITICAL, RESERVE_TASK, ins);
	}

	private static int feedTravel(Snapshot s, PenanceView h)
	{
		return 1 + (Math.max(0, s.walk(h.getTile()) - 1) + 1) / 2;
	}

	private static int knownHpUpper(Snapshot s, PenanceView h)
	{
		return PenanceDiagnostics.healer(s, h).getHpMax();
	}

	private static int hpUpper(Snapshot s, PenanceView h)
	{
		int known = knownHpUpper(s, h);
		return known >= 0 ? known : WaveInfo.healerHp(s.getWave());
	}

	/** Codes advise only between equally urgent targets; a future code entry never creates a wait. */
	private static boolean guideDue(PenanceView h, Snapshot s, HealCode code)
	{
		HealCode.Feed f = code == null ? null : code.feed(s.getCallPeriod(), h.getOrder());
		return f != null && f.getAfterSeconds() <= s.waveSeconds()
			&& (f.getCount() == HealCode.SPAM || f.getCount() > h.getFoodsThisPeriod());
	}

	/** Top up only when this many foods short of what the healers still to come need. */
	static final int TOPUP_SLACK = 2;

	/** HP left: the damage-based estimate when known, else the health bar times the wave's HP. */
	static double hpLeft(PenanceView h, int wave)
	{
		int est = h.estimatedHpLeft();
		return est >= 0 ? est : h.hpFraction() * WaveInfo.healerHp(wave);
	}

	/**
	 * One initial tag for each healer still to spawn, plus a refresh for each current healer the
	 * poison won't finish. Reserving two for every unseen future spawn sent the player back to the
	 * machine with enough food for coverage already in hand.
	 */
	static int foodToKeep(Snapshot s, List<PenanceView> healers)
	{
		int toSpawn = Math.max(0, WaveInfo.healersTotal(s.getWave()) - s.getHealersKilled() - healers.size());
		int tick = s.getTick();
		long short_ = healers.stream().filter(h -> h.poisonRemaining(tick) < hpLeft(h, s.getWave())).count();
		return toSpawn + (int) short_;
	}

	private static Instruction feed(PenanceView h, BaCall call, String why)
	{
		return Instruction.builder()
			.step(Step.HEAL_FEED)
			.headline(h.isUnseen()
				? "Head to healer #" + h.getOrder() + " (out of view)"
				: "Use " + call.getItemName() + " on healer #" + h.getOrder())
			.detail(h.isUnseen() ? why + ". Walk to where it was last seen" : why)
			.target(Target.npc(h.getNpcIndex(), h.getTile()))
			.items(Planner.items(call.getItemId()))
			.build();
	}

	/**
	 * Teammate healing. {@code urgentOnly}: only someone in real danger (half the configured
	 * threshold) interrupts the poisoning; otherwise anyone under the threshold, when idle.
	 */
	private static Instruction medic(Snapshot s, Settings c, boolean urgentOnly)
	{
		double limit = urgentOnly ? c.getHealTeammateBelow() / 2 : c.getHealTeammateBelow();
		TeammateView hurt = s.getTeammates().stream()
			.filter(t -> t.getMaxHp() > 0 && t.fraction() < limit)
			.min(Comparator.comparingDouble(TeammateView::fraction))
			.orElse(null);
		if (hurt == null)
		{
			return null;
		}
		boolean water = BaIds.VIALS_WITH_WATER.stream().anyMatch(s::has);
		if (!water)
		{
			ObjectView spring = s.nearestObject(BaIds.SPRING);
			if (!s.has(BaIds.VIAL_EMPTY) || spring == null)
			{
				return null;
			}
			return Instruction.builder()
				.step(Step.HEAL_FILL_VIAL)
				.headline("Fill the vial at the spring")
				.detail(hurt.getName() + " is at " + hurt.getHp() + "/" + hurt.getMaxHp())
				.target(Target.object(spring.getId(), spring.getTile()))
				.items(Planner.items(BaIds.VIAL_EMPTY))
				.urgency(urgentOnly ? Urgency.HIGH : Urgency.NORMAL)
				.build();
		}
		return Instruction.builder()
			.step(Step.HEAL_TEAMMATE)
			.headline("Heal " + hurt.getName() + " with the vial")
			.detail(hurt.getHp() + "/" + hurt.getMaxHp() + " HP. Heals, cures poison and restores run")
			.target(Target.player(hurt.getName()))
			.items(BaIds.VIALS_WITH_WATER)
			.urgency(urgentOnly ? Urgency.HIGH : Urgency.NORMAL)
			.build();
	}

	/** Your own HP is low: drink from the spring (only the healer can). Null when fine. */
	static Instruction selfDrink(Snapshot s, Settings c)
	{
		ObjectView spring = s.nearestObject(BaIds.SPRING);
		double self = c.getRetreatBelow();
		if (s.getMaxHp() > 0 && s.hpFraction() < self && spring != null)
		{
			return Instruction.builder()
				.step(Step.RETREAT)
				.headline("Drink from the spring (" + s.getHp() + " HP)")
				.detail("Only you can. Then back to the team")
				.target(Target.object(spring.getId(), spring.getTile()))
				.urgency(Urgency.HIGH)
				.build();
		}
		return null;
	}

	/** A teammate in real danger: the vial now. Null when nobody is. */
	static Instruction teammateDanger(Snapshot s, Settings c)
	{
		double critical = c.getHealTeammateBelow() / 2;
		TeammateView worst = s.getTeammates().stream()
			.filter(t -> t.getMaxHp() > 0 && t.fraction() < critical)
			.min(Comparator.comparingDouble(TeammateView::fraction))
			.orElse(null);
		if (worst == null)
		{
			return null;
		}
		int charges = BaIds.vialCharges(s::has);
		if (charges < 0)
		{
			ObjectView machine = s.nearestObject(BaIds.HEALER_MACHINE);
			return Instruction.builder()
				.step(Step.HEAL_FILL_VIAL)
				.headline("Take a vial: " + worst.getName() + " is at " + Math.round(worst.fraction() * 100) + "%")
				.detail("Healer item machine: Take-vial, then fill it at the spring")
				.target(machine == null ? Target.NONE : Target.object(machine.getId(), machine.getTile()))
				.urgency(Urgency.HIGH)
				.build();
		}
		return dose(s, worst, charges, Urgency.HIGH);
	}

	/** Heal one teammate, or refill first when the vial is dry. */
	private static Instruction dose(Snapshot s, TeammateView who, int charges, Urgency urgency)
	{
		String hp = who.getHp() + "/" + who.getMaxHp();
		if (charges <= 0)
		{
			ObjectView spring = s.nearestObject(BaIds.SPRING);
			return Instruction.builder()
				.step(Step.HEAL_FILL_VIAL)
				.headline("Refill the vial: " + who.getName() + " needs it")
				.detail(who.getName() + " " + hp + ". Use the vial on the spring")
				.target(spring == null ? Target.NONE : Target.object(spring.getId(), spring.getTile()))
				.items(Planner.items(BaIds.VIAL_EMPTY))
				.urgency(urgency)
				.build();
		}
		return Instruction.builder()
			.step(Step.HEAL_TEAMMATE)
			.headline("Heal " + who.getName() + " (" + Math.round(who.fraction() * 100) + "%)")
			.detail(hp + " HP. Vial " + charges + "/4")
			.target(Target.player(who.getName()))
			.items(BaIds.VIALS_WITH_WATER)
			.urgency(urgency)
			.build();
	}

	private static String staleFood(Snapshot s, int food)
	{
		int other = BaIds.POISON_FOOD.stream().filter(id -> id != food).mapToInt(s::count).sum();
		return other > 0 ? "Don't use your other " + other + " food: wrong type this call" : "";
	}
}

package com.bautopilot.baautopilot.plan;

import com.google.common.collect.ImmutableList;
import com.google.common.collect.ImmutableSet;
import java.util.List;
import java.util.Set;
import lombok.Builder;
import lombok.Value;

@Value
@Builder(toBuilder = true)
public class Instruction
{
	Step step;
	String headline;
	@Builder.Default
	String detail = "";
	@Builder.Default
	Target target = Target.NONE;
	/** Safe pickups from the selected ground pile, after capacity and timing limits. */
	@Builder.Default
	int pickupCount = 1;
	/** Planned bad Defender bait stays purple across movement, labels and opening calls. */
	boolean badBait;
	/** The target ground item is under another item on its pile: right-click the pile and choose Take. */
	boolean rightClick;
	/** Inventory items to outline. */
	@Builder.Default
	Set<Integer> items = ImmutableSet.of();
	@Builder.Default
	Urgency urgency = Urgency.NORMAL;
	@Builder.Default
	List<TileMark> marks = ImmutableList.of();
	/** A call to make on the way (horn click), shown under the headline; null when none. */
	com.bautopilot.baautopilot.model.BaCall alsoCall;
	/** The task this step belongs to (kept across ticks until done), null when none. */
	String task;
	/** Why it won: the tier of the candidate it came from, null for steps outside the chooser. */
	Tier tier;
	/** Every candidate the chooser weighed this tick, best first (priorities debugger). */
	@Builder.Default
	List<PriorityLine> priorities = ImmutableList.of();
	/** Why this step is the one shown: the chooser's reason, or the layer that overrode it. */
	String decidedBy;
	/** Weighted roles compare these totals directly; null retains the tier-based chooser. */
	Double score;
	@Builder.Default
	java.util.Map<String, Double> scoreTerms = com.google.common.collect.ImmutableMap.of();
	/**
	 * On a call: the step it leads (the target belongs to it), so the floor marks say what that
	 * target is for ("PICK UP", "FIX") and not "CALL" - you call from wherever you are.
	 */
	Step then;
	/**
	 * A warning shown under the step without replacing it: low HP says retreat when you can, but a
	 * step about to finish (dipping an egg) shouldn't be pulled away (reported 2026-10-17).
	 */
	String advice;
	/** Independent unfinished role obligations, carried into the next snapshot. */
	@Builder.Default
	TaskMemory tasks = TaskMemory.empty();

	public static Instruction of(Step step, String headline, String detail)
	{
		return Instruction.builder().step(step).headline(headline).detail(detail).build();
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.Snapshot;
import com.google.common.collect.ImmutableSet;

/**
 * Pure decision engine: one snapshot in, one instruction out. Order of precedence:
 * <ol>
 * <li>outside the arena: lobby / nothing</li>
 * <li>critically low HP (not the healer): get to a launcher hill and wait for the medic</li>
 * <li>the call you owe your partner (it is the single most valuable click in the minigame)</li>
 * <li>the Penance Queen egg chain on wave 10, weighed against health and supplies for the Healer</li>
 * <li>the role's own step: its planner lists candidates by {@link Tier}, the {@link Chooser} picks one,
 * keeping a committed task until it is done or a higher tier comes up</li>
 * </ol>
 * The owed call (recorded: "Collector not calling" 8 ticks in; "Healer you need to be on top of
 * calls or it ruins def aggro") leads from the first tick, keeping the role step's target.
 */
public class Planner
{
	/** During the Queen (up to 13 every 2.4 s to everyone near her) retreat earlier than usual. */
	static final double QUEEN_RETREAT = 0.45;
	private static final java.util.Set<Step> WAIT_STEPS = java.util.EnumSet.of(
		Step.ATT_WAIT_CALL, Step.COL_WAIT_CALL, Step.DEF_WAIT_CALL, Step.HEAL_WAIT_CALL);

	private final AttackerPlanner attacker = new AttackerPlanner();
	private final CollectorPlanner collector = new CollectorPlanner();
	private final DefenderPlanner defender = new DefenderPlanner();
	private final HealerPlanner healer = new HealerPlanner();
	private final QueenPlanner queen = new QueenPlanner();

	public Instruction plan(Snapshot s, Settings c)
	{
		TaskMemory tasks = s.getTasks().observe(s, c);
		Snapshot observed = s.toBuilder().tasks(tasks).build();
		Instruction chosen = decide(observed, c);
		return chosen.toBuilder().tasks(tasks.advance(observed, c, chosen)).build();
	}

	private Instruction decide(Snapshot s, Settings c)
	{
		if (!s.isInArena())
		{
			if (s.isInLobby())
			{
				return Instruction.builder()
					.step(Step.LOBBY)
					.headline(lobbyHeadline(s))
					.detail(s.getRole() == null || s.getWave() == 0 ? "Wait in a room for a leader's offer, or take a scroll and lead"
						: lobbyTip(s.getRole()))
					.urgency(Urgency.INFO)
					.build();
			}
			return Instruction.builder().step(Step.NOT_IN_GAME).headline("").urgency(Urgency.INFO).build();
		}

		if (s.getRole() == null)
		{
			return Instruction.builder().step(Step.WAIT_ROLE).headline("Waiting for your role")
				.detail("The role HUD appears a moment after the wave loads").urgency(Urgency.INFO).build();
		}

		// Low HP: any death ends the game for the whole team ("The game ended early because one of
		// your teammates died"). It's shown with the step, not instead of it - a step about to finish
		// (dipping an egg) mustn't be pulled away (reported 2026-10-17); it takes over only when
		// you're idle or close to dying
		double retreatAt = s.isQueenAlive() ? Math.max(c.getRetreatBelow(), QUEEN_RETREAT) : c.getRetreatBelow();
		Instruction danger = null;
		if (s.getRole() != Role.HEALER && s.getMaxHp() > 0 && s.hpFraction() < retreatAt)
		{
			danger = retreat(s).toBuilder().decidedBy("Survival: HP under " + Math.round(retreatAt * 100) + "%").build();
		}
		if (s.getRole() == Role.HEALER && !QueenHealerPlanner.applies(s))
		{
			Instruction drink = HealerPlanner.selfDrink(s, c);
			if (drink != null && s.hpFraction() < c.getRetreatBelow() / 2)
			{
				// Close to dying yourself: nobody else can heal you
				return drink.toBuilder().decidedBy("Survival: your own HP is critical").build();
			}
			Instruction care = HealerPlanner.teammateDanger(s, c);
			if (care != null)
			{
				return care.toBuilder().decidedBy("Survival: a teammate in danger (before everything)").build();
			}
			danger = drink == null ? null : drink.toBuilder().decidedBy("Survival: your own HP").build();
		}
		Instruction main = act(s, c);
		if (danger == null)
		{
			return main;
		}
		boolean idle = main.getTier() == Tier.IDLE || main.getStep().getKind() == ActionKind.WAIT;
		if (idle || s.hpFraction() < retreatAt / 2)
		{
			return danger;
		}
		return main.toBuilder().advice(danger.getHeadline() + " when you can (" + Math.round(s.hpFraction() * 100) + "% HP)").build();
	}

	private Instruction act(Snapshot s, Settings c)
	{
		Instruction call = call(s, c);
		Snapshot acting = gate(s);
		boolean queenPhase = queen.applies(acting) || QueenHealerPlanner.applies(acting);
		Instruction work = queenPhase ? queen.plan(acting, c).toBuilder().decidedBy("Queen phase: the egg chain").build() : roleStep(acting, c);
		if (queenPhase && s.getRole() == Role.HEALER)
		{
			work = QueenHealerPlanner.plan(acting, work);
		}
		work = explainGate(s, acting, work);
		// With the Queen out, the egg chain beats calls: a call only goes first while you're waiting
		if (call != null && queenPhase && work.getStep() != Step.QUEEN_WAIT)
		{
			return work;
		}
		if (call != null)
		{
			// The call leads from the first tick (partners wait on it). Only the wave's first call is
			// made on the move, keeping the work step's target and marks (nothing is urgent yet and
			// the walk to the machine is long); later calls are made on the spot, nothing to walk to
			String next = work.getHeadline() == null || work.getHeadline().isEmpty() ? "" : "Then: " + work.getHeadline();
			Instruction.InstructionBuilder led = call.toBuilder()
				.detail(call.getDetail() + (next.isEmpty() ? "" : "\n" + next)).task("call");
			if (s.getCallPeriod() == 0)
			{
				led.target(work.getTarget()).marks(work.getMarks()).then(work.getStep())
					.pickupCount(work.getPickupCount()).badBait(work.isBadBait()).rightClick(work.isRightClick());
			}
			return led.priorities(work.getPriorities())
				.decidedBy("Owed call leads (partner waits); underneath: " + work.getDecidedBy()).build();
		}
		return work;
	}

	/**
	 * Last period's call is not this period's: right after the call changes, until the partner calls
	 * again, the role acts as if it has no call (food, arrows, eggs and bait from the old call all
	 * cost points). Elapsed time cannot make an old instruction valid again. Work that does not
	 * require a new call, such as repairing or using known ground bait, remains available.
	 */
	static Snapshot gate(Snapshot s)
	{
		if (s.getListenCall() == null || s.isListenFresh())
		{
			return s;
		}
		return s.toBuilder().listenCall(null).build();
	}

	private static Instruction explainGate(Snapshot s, Snapshot acting, Instruction work)
	{
		BaCall last = s.getListenCall();
		if (last == null || s.isListenFresh())
		{
			return work;
		}
		String partner = s.getRole().partner().getLabel().toLowerCase();
		if (acting.getListenCall() == null && WAIT_STEPS.contains(work.getStep()))
		{
			boolean disengage = work.getStep() == Step.ATT_WAIT_CALL && s.getInteractingNpc() >= 0;
			return work.toBuilder()
				.headline((disengage ? "Stop attacking: wait for the " : "Wait for the ") + partner + "'s new call")
				.detail((disengage ? "Click a safe tile to disengage. " : "")
					+ "No fresh call this period. Last call was " + last.getItemName()
					+ "; using it now could be a penalty")
				.build();
		}
		return work;
	}

	private Instruction roleStep(Snapshot s, Settings c)
	{
		switch (s.getRole())
		{
			case ATTACKER:
				return Chooser.choose(s, attacker.candidates(s, c));
			case COLLECTOR:
				return Chooser.choose(s, collector.candidates(s, c));
			case DEFENDER:
				return Chooser.choose(s, defender.candidates(s, c));
			default:
				return Chooser.choose(s, healer.candidates(s, c));
		}
	}

	/**
	 * Calls no longer do anything: the Queen is out, wave 10's penance are all dead, or the game
	 * announced every penance your call is for as killed - the defender's call picks the healer's
	 * poison food, the healer's the defender's runner bait, the collector's the attacker's style.
	 */
	public static boolean callsOver(Snapshot s)
	{
		if (s.isQueenAlive() || (s.getWave() == 10 && CollectorPlanner.nothingLeftToShoot(s)))
		{
			return true;
		}
		if (s.getRole() == null)
		{
			return false;
		}
		switch (s.getRole())
		{
			case DEFENDER:
				return s.getCleared().contains(PenanceType.HEALER);
			case HEALER:
				return s.getCleared().contains(PenanceType.RUNNER);
			case COLLECTOR:
				return s.getCleared().contains(PenanceType.FIGHTER) && s.getCleared().contains(PenanceType.RANGER);
			default:
				return false;
		}
	}

	static Instruction call(Snapshot s, Settings c)
	{
		BaCall shout = s.getShoutCall();
		// Once wave 10's penance are dead (and through the Queen), egg-colour and style calls no longer
		// do anything; a teammate of your role who already made the right call covers it
		if (shout == null || s.isShoutDone() || !s.isShoutSettled() || callsOver(s)
			|| (s.getShoutCoveredBy() != null && c.isSkipCoveredCalls()))
		{
			return null;
		}
		BaCall wrong = s.getShoutWrong();
		return Instruction.builder()
			.step(Step.CALL)
			.headline(wrong != null ? "Wrong call! Call " + shout.getKeyword() + "!"
				: s.isShoutLost() ? "Call didn't go through: call " + shout.getKeyword() + " again!" : "Call " + shout.getKeyword() + "!")
			.detail((wrong != null ? "You said " + wrong.getKeyword() + ". "
				: s.isShoutLost() ? "A click right after the horn cancels it. " : "")
				+ "Horn: " + shout.getHornOption() + ", from where you are")
			.items(BaIds.HORNS)
			.urgency(Urgency.HIGH)
			.build();
	}

	private static Instruction retreat(Snapshot s)
	{
		if (s.isQueenAlive())
		{
			// The Queen's ranged attack reaches the hills; the healer heals by the spring
			ObjectView spring = s.nearestObject(BaIds.SPRING);
			return Instruction.builder()
				.step(Step.RETREAT)
				.headline("Low HP: go to the healer spring")
				.detail("Ask the healer for the vial. Only the healer can drink from the spring")
				.target(spring == null ? Target.NONE : Target.object(spring.getId(), spring.getTile()))
				.urgency(Urgency.HIGH)
				.build();
		}
		ObjectView hill = s.nearestObject(BaIds.LAUNCHERS);
		return Instruction.builder()
			.step(Step.RETREAT)
			.headline("Low HP: get onto a launcher hill")
			.detail("Penance can't follow you up there. Call for the healer's vial, then return")
			.target(hill == null ? Target.NONE : Target.object(hill.getId(), hill.getTile()))
			.urgency(Urgency.HIGH)
			.build();
	}

	private static String lobbyHeadline(Snapshot s)
	{
		if (s.getRole() == null || s.getWave() == 0)
		{
			return "Join a team";
		}
		return s.getWave() >= 10 ? "Round done" : "Wave " + (s.getWave() + 1) + " next";
	}

	private static String lobbyTip(Role role)
	{
		switch (role)
		{
			case ATTACKER:
				return "Attacker: turn auto-retaliate off; bring a bow and your best ranged gear";
			case COLLECTOR:
				return "Collector: keep inventory space free for eggs";
			case DEFENDER:
				return "Defender: empty inventory for bait, logs and a hammer";
			default:
				return "Healer: empty inventory for poisoned food and the vial";
		}
	}

	static ImmutableSet<Integer> items(int... ids)
	{
		ImmutableSet.Builder<Integer> b = ImmutableSet.builder();
		for (int id : ids)
		{
			b.add(id);
		}
		return b.build();
	}
}

package com.bautopilot.baautopilot.plan;

import lombok.Value;

/** One candidate the chooser weighed this tick, for the priorities debugger. */
@Value
public class PriorityLine
{
	Tier tier;
	/** The task id ("def.tools"), or null. */
	String task;
	String headline;
	/** Ticks left, or {@link Candidate#NO_DEADLINE}. */
	int deadline;
	/** Tiles to walk to its target (0 for inventory clicks). */
	int walk;
	boolean sticky;
	boolean chosen;
	Double score;
	java.util.Map<String, Double> scoreTerms;
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.Snapshot;
import com.bautopilot.baautopilot.state.TeammateView;
import com.google.common.collect.ImmutableMap;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.runelite.api.coords.WorldPoint;

/** Queen care has no egg-holding exemption: health, supplies and chain work compete on value. */
final class QueenHealerPlanner
{
	static final double SWITCH_MARGIN = 12;
	private QueenHealerPlanner() { }
	static boolean applies(Snapshot s)
	{
		return s.getRole() == Role.HEALER && s.getWave() == 10 && (s.isQueenAlive()
			|| s.has(BaIds.EGG_YELLOW) || s.has(BaIds.EGG_POISONED) || CollectorPlanner.nothingLeftToShoot(s));
	}

	static boolean preparing(Snapshot s)
	{
		return s.getWave() == 10 && !s.isQueenAlive() && !s.has(BaIds.EGG_YELLOW)
			&& !s.has(BaIds.EGG_POISONED) && CollectorPlanner.nothingLeftToShoot(s);
	}

	static Instruction plan(Snapshot s, Instruction chain)
	{
		// Keep a valid crater destination while walking; passing it near another crater is not completion.
		Target previous = s.getLastActionTarget();
		if (chain.getStep() == Step.QUEEN_DUNK && s.getLastStep() == Step.QUEEN_DUNK
			&& "queen.egg".equals(s.getLastTask()) && previous != null && previous.getKind() == Target.Kind.OBJECT
			&& s.getObjects().stream().anyMatch(o -> o.getId() == previous.getId() && o.getTile().equals(previous.getTile())))
			chain = chain.toBuilder().target(previous).build();
		List<Candidate> out = new ArrayList<>();
		boolean waitingForEggs = chain.getStep() == Step.QUEEN_WAIT;
		int charges = BaIds.vialCharges(s::has);
		ObjectView spring = s.nearestObject(BaIds.SPRING);
		if (spring != null && s.getMaxHp() > 0 && s.getHp() > 0 && s.getHp() < s.getMaxHp())
		{
			Instruction drink = Instruction.builder().step(Step.RETREAT)
				.headline("Drink from the spring (" + s.getHp() + " HP)")
				.detail(preparing(s) ? "Drink from the spring to top up your HP before the Queen"
					: "Top up your own HP, then return to the team and eggs")
				.target(Target.object(spring.getId(), spring.getTile())).urgency(urgency(s.getHp(), s.getMaxHp())).build();
			Map<String, Double> terms = health(s.getHp(), s.getMaxHp(), s.getSelfDamagePerTick(), waitingForEggs);
			terms.put("only you can heal yourself", 4.0 * weakness(s.getHp()));
			terms.put("near spring opportunity", 8.0 / (s.walk(spring.getTile()) + 1));
			out.add(score(s, chain, "queen.self", drink, terms));
		}
		for (TeammateView who : s.getTeammates())
		{
			if (who.getMaxHp() <= 0 || who.getHp() <= 0 || who.getHp() >= who.getMaxHp()) continue;
			Instruction care = care(s, who, charges);
			Map<String, Double> terms = health(who.getHp(), who.getMaxHp(),
				s.getTeammateDamagePerTick().getOrDefault(who.getName(), 0.0), waitingForEggs);
			// A dry/missing vial is the first step of caring for this person, not a reason to dunk eggs.
			terms.put("refill interaction", charges > 0 ? 0 : -3.0);
			out.add(score(s, chain, "queen.heal." + who.getName(), care, terms));
		}
		if (charges < 4)
		{
			Instruction refill = supply(s, charges, null, Urgency.NORMAL);
			Map<String, Double> terms = new LinkedHashMap<>();
			terms.put("vial readiness", 8.0 * (4 - Math.max(0, charges)));
			out.add(score(s, chain, "queen.vial", refill, terms));
		}
		Map<String, Double> egg = new LinkedHashMap<>();
		boolean waiting = chain.getStep() == Step.QUEEN_WAIT;
		egg.put("egg progress", waiting ? 0.0 : chain.getStep() == Step.QUEEN_PASS ? 42.0 : 24.0);
		// With the ordinary wave over, even a small top-up is better than waiting injured.
		if (waiting && preparing(s)) egg.put("unused Queen preparation time", -24.0);
		out.add(score(s, chain, waiting ? "queen.wait" : "queen.egg", chain, egg));
		return Chooser.choose(s, out);
	}

	private static Map<String, Double> health(int hp, int max, double damagePerTick, boolean waiting)
	{
		Map<String, Double> terms = new LinkedHashMap<>();
		// Absolute HP drives danger. Missing HP only breaks otherwise similar top-up choices.
		terms.put("low HP buffer", .5 * Math.pow(Math.max(0, 50 - hp), 2));
		terms.put("missing HP", 8.0 * Math.pow(1 - hp / (double) max, 2));
		double rate = Double.isFinite(damagePerTick) ? Math.max(0, damagePerTick) : 0;
		terms.put("recent damage pressure", 8.0 * weakness(hp) * rate / (rate + 1));
		terms.put("spare healing time", waiting ? 6.0 : 0);
		return terms;
	}

	private static double weakness(int hp) { return Math.min(1, Math.max(0, (55 - hp) / 25.0)); }

	private static Urgency urgency(int hp, int max) { return hp <= 26 || hp / (double) max < .35 ? Urgency.HIGH : Urgency.NORMAL; }

	private static Instruction care(Snapshot s, TeammateView who, int charges)
	{
		Urgency urgency = urgency(who.getHp(), who.getMaxHp());
		if (charges <= 0) return supply(s, charges, who, urgency);
		WorldPoint tile = s.getPlayerTiles().get(who.getName());
		return Instruction.builder().step(Step.HEAL_TEAMMATE)
			.headline("Heal " + who.getName() + " (" + Math.round(who.fraction() * 100) + "%)")
			.detail((preparing(s) ? "Before the Queen: use the vial on " + who.getName() + ". " : "")
				+ who.getHp() + "/" + who.getMaxHp() + " HP. Vial " + charges + "/4")
			.target(new Target(Target.Kind.PLAYER, -1, tile, who.getName()))
			.items(BaIds.VIALS_WITH_WATER).urgency(urgency).build();
	}

	private static Instruction supply(Snapshot s, int charges, TeammateView who, Urgency urgency)
	{
		String need = (preparing(s) ? "Before the Queen: " : "")
			+ (who == null ? "Keep the vial ready for team healing" : who.getName() + " needs it: " + who.getHp() + "/" + who.getMaxHp() + " HP");
		if (charges < 0)
		{
			ObjectView machine = s.nearestObject(BaIds.HEALER_MACHINE);
			return Instruction.builder().step(Step.HEAL_FILL_VIAL).headline("Take a vial from the healer machine")
				.detail(need + ". Take-vial, then fill it at the spring")
				.target(machine == null ? Target.NONE : Target.object(machine.getId(), machine.getTile())).urgency(urgency).build();
		}
		ObjectView spring = s.nearestObject(BaIds.SPRING);
		return Instruction.builder().step(Step.HEAL_FILL_VIAL)
			.headline(who == null ? "Top up the vial (" + charges + "/4)" : "Refill the vial: " + who.getName() + " needs it")
			.detail(need + ". Use the vial on the spring")
			.target(spring == null ? Target.NONE : Target.object(spring.getId(), spring.getTile()))
			.items(Planner.items(BaIds.vialItem(s::has))).urgency(urgency).build();
	}

	private static Candidate score(Snapshot s, Instruction chain, String task, Instruction ins, Map<String, Double> terms)
	{
		boolean waiting = chain.getStep() == Step.QUEEN_WAIT;
		WorldPoint tile = ins.getTarget().getTile();
		boolean sameWaitingTrip = waiting && tile != null && tile.equals(chain.getTarget().getTile());
		// Travel breaks ordinary top-up ties; it must not make a distant endangered player disposable.
		terms.put("extra travel", (waiting && task.equals("queen.wait")) || sameWaitingTrip ? 0 : -Math.min(16, .8 * s.walk(tile)));
		terms.put("interaction", task.startsWith("queen.egg") || task.equals("queen.wait") ? 0 : -4.0);
		// Idle top-ups/readiness are filler. Only egg work or actual low-HP care earns commitment.
		double margin = task.equals("queen.egg") ? SWITCH_MARGIN
			: Math.min(SWITCH_MARGIN, terms.getOrDefault("low HP buffer", 0.0) / 2);
		terms.put("continue current action", sameAction(s, task, ins) && ins.getStep().getKind() != ActionKind.WAIT ? margin : 0);
		double total = terms.values().stream().mapToDouble(Double::doubleValue).sum();
		return Candidate.of(ins.getUrgency() == Urgency.HIGH && !task.equals("queen.egg") ? Tier.SAFETY : Tier.MAINTENANCE,
			task, ins.toBuilder().score(total).scoreTerms(ImmutableMap.copyOf(terms)).build());
	}

	private static boolean sameAction(Snapshot s, String task, Instruction ins)
	{
		if (!task.equals(s.getLastTask()) || ins.getStep() != s.getLastStep()) return false;
		Target a = ins.getTarget(), b = s.getLastActionTarget();
		if (b == null || a.getKind() != b.getKind() || a.getId() != b.getId() || !Objects.equals(a.getLabel(), b.getLabel())) return false;
		// A teammate can move while we are healing/passing; their name still identifies the same action.
		return a.getKind() == Target.Kind.PLAYER || Objects.equals(a.getTile(), b.getTile());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.state.GroundItemView;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.Comparator;

/**
 * Wave 10 Penance Queen egg chain, C-H-A-D-C: the collector picks yellow eggs from under the queen,
 * the healer dunks them in a poison crater (use the egg on it), the attacker adds spikes, the
 * defender dunks them in lava (left-click the crater), and the collector loads the omega eggs.
 * Eight omega hits kill her; the reserve counter tracks eggs spent, not simultaneous player hits.
 */
class QueenPlanner
{
	boolean applies(Snapshot s)
	{
		return s.getWave() == 10 && (s.isQueenAlive() || s.isQueenDead()
			|| s.has(BaIds.EGG_YELLOW) || s.has(BaIds.EGG_POISONED) || s.has(BaIds.EGG_SPIKED) || s.has(BaIds.EGG_OMEGA));
	}

	Instruction plan(Snapshot s, Settings c)
	{
		Role role = s.getRole();
		boolean stack = c.isQueenStack();
		if (s.isQueenDead()) return Instruction.builder().step(Step.QUEEN_WAIT).headline("Queen defeated")
			.detail("Keep any unused reserve eggs; wait for the wave to finish").urgency(Urgency.INFO).build();
		if (role == Role.COLLECTOR)
		{
			if (s.has(BaIds.EGG_OMEGA))
			{
				return load(s, stack || c.isQueenSingleLoads());
			}
			Instruction preload = CollectorPlanner.preload(s);
			if (preload != null) return preload;
			return collectorEggs(s, c);
		}
		if (role == Role.HEALER)
		{
			if (s.has(BaIds.EGG_YELLOW))
			{
				return dunk(s, Step.QUEEN_DUNK, BaIds.POISON_CRATERS, BaIds.EGG_YELLOW, "Use the yellow egg on a poison crater",
					"Use the item on the crater; don't left-click it");
			}
			if (s.has(BaIds.EGG_POISONED))
			{
				return pass(s, BaIds.EGG_POISONED, "poisoned egg", Role.ATTACKER);
			}
			if (QueenHealerPlanner.preparing(s)) return waiting(s, role);
		}
		if (role == Role.ATTACKER)
		{
			if (s.has(BaIds.EGG_POISONED))
			{
				int poisoned = s.count(BaIds.EGG_POISONED);
				int spikes = s.count(BaIds.SPIKES);
				if (spikes == 0)
				{
					ObjectView shroom = s.nearestObject(BaIds.MUSHROOMS);
					return Instruction.builder()
						.step(Step.ATT_SPIKES)
						.headline("Get spikes (need " + poisoned + ")")
						.detail("One per poisoned egg, from a petrified mushroom")
						.target(shroom == null ? Target.NONE : Target.object(shroom.getId(), shroom.getTile()))
						.build();
				}
				return Instruction.builder()
					.step(Step.QUEEN_SPIKE)
					.headline(poisoned == 1 ? "Use spikes on the poisoned egg" : "Spike your " + poisoned + " poisoned eggs")
					.detail(spikes < poisoned
						? spikes + " spikes: use them, then get " + (poisoned - spikes) + " more"
						: "Then pass them all to the defender")
					.items(Planner.items(BaIds.SPIKES, BaIds.EGG_POISONED))
					.build();
			}
			if (s.has(BaIds.EGG_SPIKED))
			{
				return pass(s, BaIds.EGG_SPIKED, "spiked egg", Role.DEFENDER);
			}
		}
		if (role == Role.DEFENDER)
		{
			if (s.has(BaIds.EGG_SPIKED))
			{
				return dunk(s, Step.QUEEN_LAVA, BaIds.LAVA_CRATERS, BaIds.EGG_SPIKED, "Left-click a lava crater with the spiked egg",
					"Turns it into an omega egg");
			}
			if (s.has(BaIds.EGG_OMEGA))
			{
				return pass(s, BaIds.EGG_OMEGA, "omega egg", Role.COLLECTOR);
			}
		}

		// Your eggs are done. Stacking: everyone at the cannon spamming Fire while the collector loads
		// one omega at a time. Not stacking: the collector fires, the rest wait by the healer spring
		// for their next egg (easier for the healer to keep them up)
		ObjectView launcher = s.nearestObject(BaIds.LAUNCHERS);
		if (launcher != null && (stack || role == Role.COLLECTOR && s.getEggsOmega() > 0
			|| role == Role.ATTACKER && cannonReady(s)))
		{
			boolean loaded = s.getEggsOmega() > 0;
			return Instruction.builder()
				.step(Step.QUEEN_FIRE)
				.headline(loaded ? "Spam the Omega button at the Queen" : role == Role.ATTACKER ? "Get ready at the cannon: spam Omega" : "Stack at the cannon: spam Fire")
				.detail(loaded ? s.getEggsOmega() + " loaded. Every click on a loaded egg is a hit; eight kill her"
					: (CollectorPlanner.loadedAmmo(s) == 0 ? "Wait for a loaded egg to enable Shoot, then " : "Open Shoot, then ")
						+ "keep clicking Omega → Queen as the Collector loads one at a time"
						+ (s.getQueenOmegaHandoffTick() >= 0 ? ". Defender-to-Collector hand-off observed" : ""))
				.target(Target.object(launcher.getId(), launcher.getTile()))
				.urgency(loaded ? Urgency.HIGH : Urgency.NORMAL)
				.build();
		}
		return waiting(s, role);
	}

	static boolean cannonReady(Snapshot s)
	{
		return s.getQueenOmegaHandoffTick() >= 0 || s.getEggsOmega() > 0 || s.getQueenOmegaFired() > 0;
	}

	/** Let the final projectile resolve before releasing unused yellow reserves. */
	static final int VOLLEY_SETTLE_TICKS = 3;

	static boolean reserveReady(Snapshot s, Settings c)
	{
		return s.isQueenAlive() && !s.isQueenDead() && s.getQueenOmegaFired() >= Math.max(1, Math.min(8, c.getQueenEggBatch()))
			&& s.getLastQueenOmegaShotTick() >= 0 && s.getTick() - s.getLastQueenOmegaShotTick() >= VOLLEY_SETTLE_TICKS;
	}

	private static Instruction collectorEggs(Snapshot s, Settings c)
	{
		int batch = Math.max(1, Math.min(8, c.getQueenEggBatch()));
		int buffer = Math.max(0, Math.min(8, c.getQueenEggBuffer()));
		int held = s.count(BaIds.EGG_YELLOW);
		int initialLeft = Math.max(0, batch - s.getQueenYellowPassed());
		int reserveLeft = Math.max(0, batch + buffer - Math.max(batch, s.getQueenYellowPassed()));
		boolean initial = initialLeft > 0;
		int wanted = initial ? initialLeft : reserveLeft;
		if (held > 0 && ((initial && (held >= wanted || s.getFreeSlots() == 0 || s.getTasks().lastActive("queen.col.pass") >= 0))
			|| (!initial && wanted > 0 && reserveReady(s, c))))
		{
			int count = Math.min(held, wanted);
			Instruction handoff = pass(s, BaIds.EGG_YELLOW, "yellow egg", Role.HEALER, count);
			return handoff.toBuilder().task("queen.col.pass").detail(handoff.getDetail()
				+ (initial ? ". Initial batch: " + initialLeft + " left to pass. Keep any extras as reserve"
					: ". The initial " + batch + " omegas were fired and the Queen survived; use the reserve now")).build();
		}
		GroundItemView yellow = s.getGroundItems().stream().filter(g -> g.getItemId() == BaIds.EGG_YELLOW && g.getQuantity() > 0)
			.min(Comparator.comparingInt(g -> s.walk(g.getTile()) - (s.getLastStep() == Step.QUEEN_COLLECT
				&& s.getLastActionTarget() != null && g.getTile().equals(s.getLastActionTarget().getTile()) && s.walk(g.getTile()) <= 2 ? 3 : 0)))
			.orElse(null);
		if (held < wanted && yellow != null && s.getFreeSlots() > 0)
		{
			int take = Math.min(yellow.getQuantity(), Math.min(wanted - held, s.getFreeSlots()));
			return Instruction.builder().step(Step.QUEEN_COLLECT)
				.headline((initial ? "Collect yellow eggs (" : "Collect reserve yellow eggs (") + held + "/" + wanted + ")"
					+ (take > 1 ? " · pick up ×" + take : ""))
				.detail(initial ? "Finish the initial " + batch + "-egg batch, then gather " + buffer + " spare yellows"
					: "Hold these yellows. Pass reserves only after the initial " + batch + " omegas are fired and the Queen survives")
				.target(Target.groundItem(yellow.getItemId(), yellow.getTile())).pickupCount(take).build();
		}
		if (s.getEggsOmega() > 0)
		{
			ObjectView launcher = s.nearestObject(BaIds.LAUNCHERS);
			return Instruction.builder().step(Step.QUEEN_FIRE).headline("Fire the loaded omega at the Queen")
				.detail("Keep the yellow reserve until the initial volley is finished")
				.target(launcher == null ? Target.NONE : Target.object(launcher.getId(), launcher.getTile())).build();
		}
		boolean gathering = held < wanted;
		if (wanted == 0) return Instruction.builder().step(Step.QUEEN_WAIT).headline("Wait for the processed omegas")
			.detail("All configured yellow eggs have been passed. Keep the cannon ready for the remaining omegas").urgency(Urgency.INFO).build();
		return Instruction.builder().step(Step.QUEEN_WAIT)
			.headline(initial ? "Watch for yellow eggs (" + held + "/" + wanted + ")"
				: gathering ? "Watch for reserve eggs (" + held + "/" + wanted + ")" : "Hold the Queen reserve")
			.detail(initial ? "Wait at the marked spot for yellow drops. Gather " + initialLeft + " before passing"
				: "Initial omegas fired: " + s.getQueenOmegaFired() + "/" + batch + ". Keep " + held
					+ " yellow eggs until the initial volley lands; then use them only if the Queen survives")
			.target(!gathering || s.walk(ArenaTiles.queenCollectorWatch()) <= 2 ? Target.NONE
				: Target.tile(ArenaTiles.queenCollectorWatch(), "Watch for yellow eggs")).urgency(Urgency.INFO).build();
	}

	/** Ticks with the queen out and no omega loaded before the chain counts as stuck. */
	static final int STUCK_TICKS = 50;
	/** One spike per omega egg; eight omega hits kill the Queen. */
	static final int SPIKES_WANTED = 8;

	/**
	 * Waiting for your link in the chain: say which egg comes from whom, what you will do with it,
	 * and where to stand (by the healer spring, out of the Queen's reach: recorded team advice).
	 */
	private static Instruction waiting(Snapshot s, Role role)
	{
		// Recorded: the attacker started the Queen with 2-3 spikes and ran back once per egg
		if (role == Role.ATTACKER && s.count(BaIds.SPIKES) < SPIKES_WANTED && s.getQueenSpikedPassed() == 0 && !cannonReady(s))
		{
			ObjectView shroom = s.nearestObject(BaIds.MUSHROOMS);
			return Instruction.builder()
				.step(Step.ATT_SPIKES)
				.headline("Get spikes while you wait (" + s.count(BaIds.SPIKES) + "/" + SPIKES_WANTED + ")")
				.detail("One per poisoned egg. Ignore the Queen and her spawns")
				.target(shroom == null ? Target.NONE : Target.object(shroom.getId(), shroom.getTile()))
				.build();
		}
		String headline;
		String detail;
		switch (role)
		{
			case ATTACKER:
				headline = "Wait for the healer's poisoned egg";
				detail = "Spikes: " + s.count(BaIds.SPIKES) + ". Use spikes on the POISONED egg, not a yellow one";
				break;
			case DEFENDER:
				headline = "Wait for the attacker's spiked egg";
				detail = "Then left-click a lava crater with it";
				break;
			case HEALER:
				headline = QueenHealerPlanner.preparing(s) ? "Wait for the Queen by the healer spring" : "Wait for the collector's yellow egg";
				detail = QueenHealerPlanner.preparing(s) ? "The ordinary Penance are finished. The collector will pass you yellow eggs"
					: "Then use it on a poison crater and pass it to the attacker";
				break;
			default:
				headline = "Wait for yellow eggs under the Queen";
				detail = "Pick them up and pass them to the healer";
				break;
		}
		detail += "\nDon't attack the Queen or her spawns. Stand by the healer spring";
		int queenSince = s.getPenance().stream().filter(p -> p.getType() == PenanceType.QUEEN)
			.mapToInt(p -> s.getTick() - p.getSpawnTick()).max().orElse(0);
		if (queenSince >= STUCK_TICKS && s.getEggsOmega() == 0)
		{
			detail += "\nNo omega yet. Chain: collector yellow > healer poison crater > attacker spikes"
				+ " > defender lava > collector loads";
		}
		ObjectView spring = s.nearestObject(BaIds.SPRING);
		return Instruction.builder()
			.step(Step.QUEEN_WAIT)
			.headline(headline)
			.detail(detail)
			.target(spring == null ? Target.NONE : Target.object(spring.getId(), spring.getTile()))
			.urgency(Urgency.INFO)
			.build();
	}

	/**
	 * Stacking (the one-egg method, wiki): load omega eggs one at a time while everyone at the cannon
	 * keeps clicking Fire, so each egg is fired by several players. Otherwise load them all with one
	 * click (spam-clicking the hopper can delete eggs) and fire them yourself.
	 */
	private static Instruction load(Snapshot s, boolean stack)
	{
		ObjectView hopper = s.nearestObject(BaIds.HOPPERS);
		int n = s.count(BaIds.EGG_OMEGA);
		Target at = hopper == null ? Target.NONE : Target.object(hopper.getId(), hopper.getTile());
		if (stack)
		{
			if (hopper == null)
				return Instruction.builder().step(Step.QUEEN_WAIT).headline("Find a hopper for one-at-a-time loading")
					.detail("Keep the omegas. Stand two tiles south of a hopper, then use one egg on it")
					.items(Planner.items(BaIds.EGG_OMEGA)).build();
			net.runelite.api.coords.WorldPoint stand = hopper.getTile().dy(-2);
			if (!stand.equals(s.getPlayerTile()))
				return Instruction.builder().step(Step.QUEEN_LOAD_POSITION)
					.headline("Stand two tiles south of the hopper")
					.detail("Then stay on this tile and use ONE omega egg on the hopper. Let the team fire before loading another (" + n + " left)")
					.target(Target.tile(stand, "Load from here")).items(Planner.items(BaIds.EGG_OMEGA)).build();
			if (s.getEggsOmega() > 0)
			{
				return Instruction.builder()
					.step(Step.QUEEN_WAIT)
					.headline("Hold: an omega is in the launcher")
					.detail("Stay two tiles south of the hopper. Load the next one when it's fired (" + n + " left)")
					.target(at)
					.items(Planner.items(BaIds.EGG_OMEGA))
					.urgency(Urgency.INFO)
					.build();
			}
			return Instruction.builder()
				.step(Step.QUEEN_LOAD_ONE)
				.headline("Load ONE omega egg")
				.detail("Stay two tiles south. Use one egg on the hopper (clicking the hopper loads them all); the team fires it, then load the next (" + n + " left)")
				.target(at)
				.items(Planner.items(BaIds.EGG_OMEGA))
				.urgency(Urgency.HIGH)
				.build();
		}
		return Instruction.builder()
			.step(Step.QUEEN_LOAD)
			.headline(n > 1 ? "Load your " + n + " omega eggs" : "Load the omega egg into a hopper")
			.detail("Click the hopper once: spam-clicking can delete eggs")
			.target(at)
			.items(Planner.items(BaIds.EGG_OMEGA))
			.urgency(Urgency.HIGH)
			.build();
	}

	private static Instruction pass(Snapshot s, int item, String name, Role to)
	{
		return pass(s, item, name, to, s.count(item));
	}

	private static Instruction pass(Snapshot s, int item, String name, Role to, int limit)
	{
		// Recorded: a spiked egg used on the wrong teammate ("You only need to pass ... to a Defender")
		Target remembered = s.getRole() == Role.COLLECTOR ? s.getTasks().target("queen.col.recipient") : null;
		String who = remembered != null && s.getTeam().get(remembered.getLabel()) == to ? remembered.getLabel() : s.getTeam().entrySet().stream()
			.filter(e -> e.getValue() == to)
			.map(java.util.Map.Entry::getKey)
			.sorted(String.CASE_INSENSITIVE_ORDER.thenComparing(Comparator.naturalOrder()))
			.findFirst().orElse(null);
		int n = Math.min(s.count(item), limit);
		String what = n > 1 ? n + " " + name + "s" : "the " + name;
		return Instruction.builder()
			.step(Step.QUEEN_PASS)
			.headline("Pass " + what + " to " + (who != null ? who : "the " + to.getLabel().toLowerCase()))
			.detail((who != null ? "The " + to.getLabel().toLowerCase() + ". " : "") + "Use each egg on them")
			.items(Planner.items(item))
			.target(who != null ? Target.player(who) : Target.NONE)
			.urgency(Urgency.HIGH)
			.build();
	}

	/** Healer uses the egg on the crater (inventory first); defender left-clicks the crater (world). */
	private static Instruction dunk(Snapshot s, Step step, int[] craters, int item, String headline, String detail)
	{
		ObjectView crater = s.nearestObject(craters);
		int n = s.count(item);
		return Instruction.builder()
			.step(step)
			.headline(headline + (n > 1 ? " (" + n + ")" : ""))
			.detail(detail)
			.target(crater == null ? Target.NONE : Target.object(crater.getId(), crater.getTile()))
			.items(Planner.items(item))
			.urgency(Urgency.HIGH)
			.build();
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.state.GroundItemView;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import net.runelite.api.coords.WorldPoint;

/**
 * How well a penance runner is held by the defender's food trail, worst first when it matters:
 * escaping south past the trap, loose (no bait in range: it wanders, mostly south), bad bait only
 * (it gets pulled along, not killed), lured to good bait, or stacked on the trap food.
 */
public enum RunnerState
{
	ESCAPING,
	LOOSE,
	BAD_ONLY,
	LURED,
	STACKED;

	/**
	 * Bait in range uses the defender's lure range (4 tiles at level 1, 5 from level 2), as a
	 * square around the runner (OSRS Wiki, Advanced strategies).
	 */
	public static RunnerState of(Snapshot s, PenanceView runner)
	{
		WorldPoint tile = runner.getTile();
		if (tile == null)
		{
			return LOOSE;
		}
		WorldPoint trapFood = ArenaTiles.trapFood(s.getWave());
		if (ArenaTiles.distance(tile, trapFood) <= DefenderPlanner.STACK_RADIUS)
		{
			return STACKED;
		}
		if (tile.getY() <= trapFood.getY() - DefenderPlanner.RELURE_SOUTH)
		{
			return ESCAPING;
		}
		boolean good = false;
		boolean bad = false;
		for (GroundItemView bait : s.getGroundItems())
		{
			if (bait.getTile() == null || !BaIds.BAIT.contains(bait.getItemId())
				|| ArenaTiles.distance(tile, bait.getTile()) > s.baitRange())
			{
				continue;
			}
			good |= bait.isGood();
			bad |= !bait.isGood();
		}
		return good ? LURED : bad ? BAD_ONLY : LOOSE;
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.DefenderGuide;
import com.bautopilot.baautopilot.model.HealCodeSet;
import lombok.Builder;
import lombok.Value;

/** Config values the planner needs, copied so the planner never touches the config proxy. */
@Value
@Builder(toBuilder = true)
public class Settings
{
	@Builder.Default
	AttackMethod attackMethod = AttackMethod.RANGED;
	/** Retreat and call for a medic below this fraction of max HP (non-healers). */
	@Builder.Default
	double retreatBelow = 0.30;
	/** Healer: heal teammates below this fraction. */
	@Builder.Default
	double healTeammateBelow = 0.50;
	/** Collector: useful eggs held in inventory plus bag for a blue-call batch. */
	@Builder.Default
	int collectorLoadAt = 5;
	/** Collector: gather this many yellows before starting a Queen hand-off. */
	@Builder.Default
	int queenEggBatch = 5;
	/** Collector: yellow reserves held until the initial omega batch is fired and the Queen survives. */
	@Builder.Default
	int queenEggBuffer = 3;
	/** Collector: use one omega at a time from two tiles south of the hopper. */
	@Builder.Default
	boolean queenSingleLoads = true;
	/** Healer: optional code order/timing for needed refreshes (OFF: poison priority). */
	@Builder.Default
	HealCodeSet healCodeSet = HealCodeSet.REGULAR;
	/** Defender: whose bait pattern and log counts to follow. */
	@Builder.Default
	DefenderGuide defenderGuide = DefenderGuide.WIKI;
	/** Defender: keep the safety bait south of the trap. */
	@Builder.Default
	boolean safetyBait = true;

	/** The old boolean remains readable in captures; live settings choose this in the guide dropdown. */
	public boolean isSafetyBait()
	{
		return safetyBait && defenderGuide.isSafetyBait();
	}
	/** Skip your call when another player of your role already made it this period. */
	@Builder.Default
	boolean skipCoveredCalls = true;
	/** Attackers running the plugin split fighters and rangers between them by NPC index. */
	@Builder.Default
	boolean splitTargets = true;
	/** Defender: drop the 1-4-1-4-1 / 1-4-4-1 pattern in the first call. */
	@Builder.Default
	boolean defenderPattern = true;
	/** Advanced Defender strategy: block food to stack runners and time multi-kill releases. */
	@Builder.Default
	boolean defenderMultiKill = false;
	/**
	 * Queen: everyone stacks at the cannon and spams Fire while the collector loads omegas one by
	 * one; off, other roles prepare eggs and wait by the healer spring. Collector loading has its own option.
	 */
	@Builder.Default
	boolean queenStack = false;
}

