package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.Comparator;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID.BarbassaultTurret;

/**
 * Which launcher to use and which button to press in its aiming window (one button per egg and
 * target): omega at the queen when loaded; otherwise red at runners (5 HP, about 3 per hit plus
 * splash, and every escape costs the team), then red at healers. With only green, runners still
 * come first: green poison ticks every 3 s on runners but every 18 s on healers (OSRS Wiki). Never
 * stun, and never fighters or rangers (too much HP; the attackers have them).
 *
 * <p>Each launcher only reaches targets within {@link #RANGE} tiles (recorded 2026-10-15/16: hits up
 * to 15 tiles away, "no targetable Penance Runners within firing range" at 16), and a dying runner
 * can't be targeted.
 */
public final class TurretChoice
{
	public static final int NONE = -1;
	/** Chebyshev tiles a launcher reaches. */
	public static final int RANGE = 15;

	/** The stun buttons, to mark as "don't". */
	public static final int[] STUN = {
		BarbassaultTurret.STUN_HEALER, BarbassaultTurret.STUN_RUNNER,
		BarbassaultTurret.STUN_FIGHTER, BarbassaultTurret.STUN_RANGER,
	};

	private TurretChoice()
	{
	}

	/** The button for the launcher nearest to you (the one whose aiming window is open). */
	public static int pick(Snapshot s)
	{
		ObjectView launcher = s.nearestObject(BaIds.LAUNCHERS);
		return pick(s, launcher == null ? null : launcher.getTile());
	}

	/** The button for a launcher at {@code from} (template tile; null = ignore range). */
	public static int pick(Snapshot s, WorldPoint from)
	{
		if (s.isQueenAlive() && !s.isQueenDead() && (s.getEggsOmega() > 0
			|| s.getRole() == Role.ATTACKER && QueenPlanner.cannonReady(s)))
		{
			return BarbassaultTurret.OMEGA_QUEEN;
		}
		boolean runners = inRange(s, PenanceType.RUNNER, from);
		boolean healers = inRange(s, PenanceType.HEALER, from);
		boolean red = s.getEggsRed() > 0;
		boolean green = s.getEggsGreen() > 0;
		if (runners && red)
		{
			return BarbassaultTurret.EXPLOSIVE_RUNNER;
		}
		if (healers && red)
		{
			return BarbassaultTurret.EXPLOSIVE_HEALER;
		}
		if (runners && green)
		{
			return BarbassaultTurret.POISON_RUNNER;
		}
		if (healers && green)
		{
			return BarbassaultTurret.POISON_HEALER;
		}
		return NONE;
	}

	/**
	 * The launcher to walk to: the one with the best shot (runners beat healers), nearest to you on a
	 * tie; null when neither reaches anything worth firing at.
	 */
	public static ObjectView bestLauncher(Snapshot s)
	{
		return s.getObjects().stream()
			.filter(o -> BaIds.contains(BaIds.LAUNCHERS, o.getId()))
			.filter(o -> pick(s, o.getTile()) != NONE)
			.min(Comparator.comparingInt((ObjectView o) -> rank(pick(s, o.getTile())))
				.thenComparingInt(o -> ArenaTiles.distance(s.getPlayerTile(), o.getTile())))
			.orElse(null);
	}

	private static int rank(int button)
	{
		switch (button)
		{
			case BarbassaultTurret.OMEGA_QUEEN:
				return 0;
			case BarbassaultTurret.EXPLOSIVE_RUNNER:
				return 1;
			case BarbassaultTurret.EXPLOSIVE_HEALER:
				return 2;
			case BarbassaultTurret.POISON_RUNNER:
				return 3;
			default:
				return 4;
		}
	}

	private static boolean inRange(Snapshot s, PenanceType type, WorldPoint from)
	{
		for (PenanceView p : s.penance(type))
		{
			if (from == null || ArenaTiles.distance(from, p.getTile()) <= RANGE)
			{
				return true;
			}
		}
		return false;
	}

	/** Short label for a button, e.g. "Red > Runner". */
	public static String label(int component)
	{
		switch (component)
		{
			case BarbassaultTurret.OMEGA_QUEEN:
				return "Omega > Queen";
			case BarbassaultTurret.EXPLOSIVE_RUNNER:
				return "Red > Runner";
			case BarbassaultTurret.EXPLOSIVE_HEALER:
				return "Red > Healer";
			case BarbassaultTurret.POISON_HEALER:
				return "Green > Healer";
			case BarbassaultTurret.POISON_RUNNER:
				return "Green > Runner";
			default:
				return "";
		}
	}
}

package com.bautopilot.baautopilot.plan;

public enum Urgency
{
	INFO,
	NORMAL,
	HIGH
}

package com.bautopilot.baautopilot.state;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.CollisionDataFlag;

/**
 * Shortest walking route on a scene collision grid ({@code flags[x][y]}, as from
 * {@code CollisionData.getFlags()}): 8-directional breadth-first search that respects walls on tile
 * edges and only cuts a corner when both sides of it are open. Client-free, so it is unit tested
 * on hand-made grids.
 */
public final class ArenaPath
{
	/** Tiles you can't stand on at all. */
	private static final int SOLID = CollisionDataFlag.BLOCK_MOVEMENT_FULL;

	/** A goal test on scene coordinates. */
	public interface Goal
	{
		boolean reached(int x, int y);
	}

	private ArenaPath()
	{
	}

	/**
	 * Route from (sx, sy) to the nearest tile passing {@code goal}, start and goal included; empty
	 * when there is none within {@code maxSteps}.
	 */
	public static List<int[]> find(int[][] flags, int sx, int sy, Goal goal, int maxSteps)
	{
		int w = flags.length;
		int h = w == 0 ? 0 : flags[0].length;
		if (sx < 0 || sy < 0 || sx >= w || sy >= h)
		{
			return Collections.emptyList();
		}
		int[] prev = new int[w * h];
		int[] dist = new int[w * h];
		Arrays.fill(dist, -1);
		int[] queue = new int[w * h];
		int head = 0;
		int tail = 0;
		int start = sx * h + sy;
		dist[start] = 0;
		prev[start] = start;
		queue[tail++] = start;
		while (head < tail)
		{
			int cur = queue[head++];
			int cx = cur / h;
			int cy = cur % h;
			if (goal.reached(cx, cy))
			{
				return straightTrace(flags, dist, cur, start, h);
			}
			if (dist[cur] >= maxSteps)
			{
				continue;
			}
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if ((dx != 0 || dy != 0) && canMove(flags, cx, cy, dx, dy))
					{
						int next = (cx + dx) * h + (cy + dy);
						if (dist[next] < 0)
						{
							dist[next] = dist[cur] + 1;
							prev[next] = cur;
							queue[tail++] = next;
						}
					}
				}
			}
		}
		return Collections.emptyList();
	}

	/**
	 * Waypoints for drawing a route: join the furthest visible tiles directly instead of showing
	 * every arbitrary grid step. Check every crossed tile edge, including both sides of a corner,
	 * so a straight segment never hides a wall or cuts through an obstacle.
	 */
	public static List<int[]> waypoints(int[][] flags, List<int[]> route)
	{
		if (route.size() <= 2)
		{
			return route;
		}
		List<int[]> out = new ArrayList<>();
		int at = 0;
		out.add(route.get(at));
		while (at < route.size() - 1)
		{
			int next = route.size() - 1;
			while (next > at + 1 && !clearLine(flags, route.get(at), route.get(next)))
			{
				next--;
			}
			out.add(route.get(next));
			at = next;
		}
		return out;
	}

	/** Traverse the cells intersected by a line between tile centres, in edge-crossing order. */
	private static boolean clearLine(int[][] flags, int[] from, int[] to)
	{
		int x = from[0];
		int y = from[1];
		int dx = Integer.signum(to[0] - x);
		int dy = Integer.signum(to[1] - y);
		int width = Math.abs(to[0] - x);
		int height = Math.abs(to[1] - y);
		int crossedX = 0;
		int crossedY = 0;
		while (x != to[0] || y != to[1])
		{
			// Compare the next vertical/horizontal boundary times without rounding to a tile.
			long vertical = (2L * crossedX + 1) * height;
			long horizontal = (2L * crossedY + 1) * width;
			int stepX = vertical <= horizontal ? dx : 0;
			int stepY = horizontal <= vertical ? dy : 0;
			if (!canMove(flags, x, y, stepX, stepY))
			{
				return false;
			}
			x += stepX;
			y += stepY;
			crossedX += stepX == 0 ? 0 : 1;
			crossedY += stepY == 0 ? 0 : 1;
		}
		return true;
	}

	/**
	 * Steps from (sx, sy) to every tile within {@code maxSteps} ({@code [x][y]}, -1 where unreached):
	 * one search per tick gives the planner a walking cost for every candidate.
	 */
	public static int[][] distances(int[][] flags, int sx, int sy, int maxSteps)
	{
		int w = flags.length;
		int h = w == 0 ? 0 : flags[0].length;
		int[][] dist = new int[w][h];
		for (int[] column : dist)
		{
			Arrays.fill(column, -1);
		}
		if (sx < 0 || sy < 0 || sx >= w || sy >= h)
		{
			return dist;
		}
		int[] queue = new int[w * h];
		int head = 0;
		int tail = 0;
		dist[sx][sy] = 0;
		queue[tail++] = sx * h + sy;
		while (head < tail)
		{
			int cur = queue[head++];
			int cx = cur / h;
			int cy = cur % h;
			if (dist[cx][cy] >= maxSteps)
			{
				continue;
			}
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if ((dx != 0 || dy != 0) && canMove(flags, cx, cy, dx, dy) && dist[cx + dx][cy + dy] < 0)
					{
						dist[cx + dx][cy + dy] = dist[cx][cy] + 1;
						queue[tail++] = (cx + dx) * h + cy + dy;
					}
				}
			}
		}
		return dist;
	}

	/** Steps to stand on (x, y), or next to it when it is solid (an object); -1 when unreached. */
	public static int stepsTo(int[][] dist, int x, int y)
	{
		if (x < 0 || y < 0 || x >= dist.length || y >= dist[0].length)
		{
			return -1;
		}
		if (dist[x][y] >= 0)
		{
			return dist[x][y];
		}
		int best = -1;
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				int nx = x + dx;
				int ny = y + dy;
				if (nx >= 0 && ny >= 0 && nx < dist.length && ny < dist[0].length && dist[nx][ny] >= 0
					&& (best < 0 || dist[nx][ny] < best))
				{
					best = dist[nx][ny];
				}
			}
		}
		return best;
	}

	/**
	 * Among the equally short routes, the one with the fewest turns: walked back from the goal,
	 * keep the last direction while it still leads home, else take a diagonal before a straight
	 * step. From the start that reads as one straight run, then the diagonal into the target
	 * (reported 2026-10-17: the search's arbitrary tie-break drew zigzags across the arena).
	 */
	private static List<int[]> straightTrace(int[][] flags, int[] dist, int end, int start, int h)
	{
		List<int[]> out = new ArrayList<>();
		int at = end;
		int ldx = 0;
		int ldy = 0;
		out.add(new int[]{at / h, at % h});
		while (at != start)
		{
			int cx = at / h;
			int cy = at % h;
			int best = -1;
			int bdx = 0;
			int bdy = 0;
			int bestScore = Integer.MAX_VALUE;
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					int px = cx - dx;
					int py = cy - dy;
					if ((dx == 0 && dy == 0) || px < 0 || py < 0 || px >= flags.length || py >= h)
					{
						continue;
					}
					int p = px * h + py;
					if (dist[p] != dist[at] - 1 || !canMove(flags, px, py, dx, dy))
					{
						continue;
					}
					int score = (dx == ldx && dy == ldy) ? 0 : (dx != 0 && dy != 0) ? 1 : 2;
					if (score < bestScore)
					{
						bestScore = score;
						best = p;
						bdx = dx;
						bdy = dy;
					}
				}
			}
			if (best < 0)
			{
				break;
			}
			at = best;
			ldx = bdx;
			ldy = bdy;
			out.add(new int[]{at / h, at % h});
		}
		Collections.reverse(out);
		return out;
	}

	private static List<int[]> trace(int[] prev, int end, int start, int h)
	{
		List<int[]> out = new ArrayList<>();
		for (int at = end; ; at = prev[at])
		{
			out.add(new int[]{at / h, at % h});
			if (at == start)
			{
				break;
			}
		}
		Collections.reverse(out);
		return out;
	}

	/** One step from (x, y) by (dx, dy), each -1..1. */
	static boolean canMove(int[][] flags, int x, int y, int dx, int dy)
	{
		int nx = x + dx;
		int ny = y + dy;
		if (nx < 0 || ny < 0 || nx >= flags.length || ny >= flags[0].length || (flags[nx][ny] & SOLID) != 0)
		{
			return false;
		}
		if (dx != 0 && dy != 0)
		{
			// A diagonal needs both cardinal steps around the corner, from either side
			return canMove(flags, x, y, dx, 0) && canMove(flags, x, y, 0, dy)
				&& canMove(flags, x + dx, y, 0, dy) && canMove(flags, x, y + dy, dx, 0);
		}
		if (dx == 1)
		{
			return (flags[x][y] & CollisionDataFlag.BLOCK_MOVEMENT_EAST) == 0
				&& (flags[nx][ny] & CollisionDataFlag.BLOCK_MOVEMENT_WEST) == 0;
		}
		if (dx == -1)
		{
			return (flags[x][y] & CollisionDataFlag.BLOCK_MOVEMENT_WEST) == 0
				&& (flags[nx][ny] & CollisionDataFlag.BLOCK_MOVEMENT_EAST) == 0;
		}
		if (dy == 1)
		{
			return (flags[x][y] & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) == 0
				&& (flags[nx][ny] & CollisionDataFlag.BLOCK_MOVEMENT_SOUTH) == 0;
		}
		return (flags[x][y] & CollisionDataFlag.BLOCK_MOVEMENT_SOUTH) == 0
			&& (flags[nx][ny] & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) == 0;
	}
}

package com.bautopilot.baautopilot.state;

