package com.bautopilot.baautopilot.state;

import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.model.WaveInfo;
import com.bautopilot.baautopilot.plan.RunnerState;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.AnimationID;

/** Observations and conditional forecasts. Healer finishing also uses the bounded HP estimate. */
public final class PenanceDiagnostics
{
	public static final int ZONE_SIZE = 8;
	public enum PoisonResult { UNKNOWN, NO_POISON, KILLS, SURVIVES, UNCERTAIN, DYING }

	@Value
	public static class Label
	{
		int npcIndex;
		WorldPoint tile;
		String title;
		String detail;
		String tone;
	}

	@Value
	public static class HealerForecast
	{
		int maxHp;
		int hpMin;
		int hpMax;
		int poison;
		int damageMin;
		int damageMax;
		int earliestDeathTicks;
		int latestDeathTicks;
		PoisonResult result;
	}

	private PenanceDiagnostics() { }

	/** Fixed world zones, not a square centred on the runner. Zero-based rank: NE, E, SE, N... */
	public static int zoneRank(WorldPoint runner, WorldPoint bait)
	{
		if (runner == null || bait == null || runner.getPlane() != bait.getPlane()) return -1;
		int dx = Math.floorDiv(bait.getX(), ZONE_SIZE) - Math.floorDiv(runner.getX(), ZONE_SIZE);
		int dy = Math.floorDiv(bait.getY(), ZONE_SIZE) - Math.floorDiv(runner.getY(), ZONE_SIZE);
		return Math.abs(dx) > 1 || Math.abs(dy) > 1 ? -1 : (1 - dx) * 3 + 1 - dy;
	}

	/** Candidate only: captured clients do not expose the runner's selected food or its sight test. */
	public static GroundItemView candidateBait(Snapshot s, PenanceView runner)
	{
		if (s.getRole() != Role.DEFENDER || runner.getTile() == null) return null;
		boolean trigger = s.getGroundItems().stream().anyMatch(b -> bait(b) && distance(runner.getTile(), b.getTile()) <= s.baitRange());
		if (!trigger) return null;
		return s.getGroundItems().stream().filter(PenanceDiagnostics::bait)
			.filter(b -> zoneRank(runner.getTile(), b.getTile()) >= 0)
			.min(Comparator.comparingInt((GroundItemView b) -> zoneRank(runner.getTile(), b.getTile()))
				.thenComparing(Comparator.comparingInt(GroundItemView::getSpawnTick).reversed()))
			.orElse(null);
	}

	private static boolean bait(GroundItemView b) { return b.getTile() != null && b.getQuantity() > 0 && BaIds.BAIT.contains(b.getItemId()); }
	private static int distance(WorldPoint a, WorldPoint b) { return a.getPlane() == b.getPlane() ? Math.max(Math.abs(a.getX() - b.getX()), Math.abs(a.getY() - b.getY())) : Integer.MAX_VALUE; }

	public static Label runner(Snapshot s, PenanceView p)
	{
		GroundItemView bait = candidateBait(s, p);
		String motion = direction(p.getPreviousTile(), p.getTile());
		String speech = p.getOverhead() == null ? "" : p.getOverhead().toLowerCase(Locale.ROOT);
		String state;
		if (p.isDying()) state = "DYING";
		else if (p.getAnimation() == AnimationID.BARBASSAULT_PENANCE_RUNNER_EATING)
		{
			state = speech.contains("chomp") ? "EAT GOOD" : speech.contains("blug") ? "EAT BAD" : "EAT";
		}
		else if (p.getPreviousTile() == null) state = "STATE?";
		else if (speech.contains("blug") && !motion.isEmpty()) state = "POST-BAD? " + motion;
		else if (bait != null) state = "HUNT?" + (motion.isEmpty() ? "" : " " + motion);
		else state = motion.isEmpty() ? "IDLE" : "WALK? " + motion;
		String detail = s.getRole() == Role.DEFENDER ? RunnerState.of(s, p).name() + "?" : "bait context?";
		if (bait != null) detail += " " + (bait.isGood() ? "G" : "B") + "@" + (bait.getTile().getX() & 63) + "," + (bait.getTile().getY() & 63);
		String tone = s.getRole() == Role.DEFENDER && RunnerState.of(s, p) == RunnerState.ESCAPING ? "bad" : "muted";
		return new Label(p.getNpcIndex(), p.getTile(), "R " + state, detail, tone);
	}

	private static String direction(WorldPoint previous, WorldPoint current)
	{
		if (previous == null || current == null || previous.getPlane() != current.getPlane()) return "";
		int dx = Integer.signum(current.getX() - previous.getX()), dy = Integer.signum(current.getY() - previous.getY());
		return (dy > 0 ? "N" : dy < 0 ? "S" : "") + (dx > 0 ? "E" : dx < 0 ? "W" : "");
	}

	/**
	 * Bounds use wave HP and the quantised health bar. A known own food supplies a time anchor;
	 * contradictory/partner damage supplies a range of positions within that poison strength.
	 * Forecast assumes no more food, cannon damage, healing, or stun, and no missed poison hits.
	 */
	public static HealerForecast healer(Snapshot s, PenanceView p)
	{
		int max = WaveInfo.healerHp(s.getWave());
		int hpMin = -1, hpMax = -1;
		if (max > 0 && p.getHealthScale() > 0 && p.getHealthRatio() >= 0)
		{
			int ratio = Math.min(p.getHealthRatio(), p.getHealthScale());
			// Invert the server's 1 + (scale - 1) * hp / max for nonzero HP,
			// as RuneLite's OpponentInfoOverlay does, retaining the quantisation interval.
			int scale = p.getHealthScale();
			hpMin = ratio == 0 ? 0 : ratio == 1 || scale <= 1 ? 1 : (max * (ratio - 1) + scale - 2) / (scale - 1);
			hpMax = ratio == 0 ? 0 : scale <= 1 ? max : Math.min(max, (max * ratio - 1) / (scale - 1));
		}
		else if (max > 0 && p.getDamageTaken() > 0)
		{
			hpMin = hpMax = Math.max(1, max - p.getDamageTaken());
		}
		if (p.isDying()) return new HealerForecast(max, 0, 0, 0, 0, 0, 0, 0, PoisonResult.DYING);
		int strength = p.nextPoisonHit(s.getTick());
		if (max <= 0 || hpMin < 0) return new HealerForecast(max, hpMin, hpMax, strength, 0, 0, -1, -1, PoisonResult.UNKNOWN);
		if (strength == 0) return new HealerForecast(max, hpMin, hpMax, 0, 0, 0, -1, -1, PoisonResult.NO_POISON);
		int low, high;
		int food = p.getLastFoodTick(), observed = p.getLastPoisonTick(), damage = p.getLastPoisonDamage();
		boolean anchored = food >= 0 && (observed <= food
			|| damage == WaveInfo.poisonHit(Math.max(0, (observed - food) / WaveInfo.POISON_INTERVAL_TICKS) + 1));
		// A one-damage hit without food history cannot identify the poison's source/duration.
		if (!anchored && damage == 1) return new HealerForecast(max, hpMin, hpMax, strength, 0, 0, -1, -1, PoisonResult.UNKNOWN);
		if (anchored)
		{
			int age = Math.max(0, s.getTick() - food);
			low = age / WaveInfo.POISON_INTERVAL_TICKS;
			high = (age + WaveInfo.POISON_INTERVAL_TICKS - 1) / WaveInfo.POISON_INTERVAL_TICKS;
		}
		else if (observed >= 0 && damage >= 1 && damage <= 4)
		{
			// A current hit may be any of the five at that strength. A 4 may be immediate food.
			int elapsed = Math.max(0, s.getTick() - observed) / WaveInfo.POISON_INTERVAL_TICKS;
			low = (4 - damage) * 5 + (damage == 4 ? 0 : 1) + elapsed;
			high = (5 - damage) * 5 + elapsed;
		}
		else return new HealerForecast(max, hpMin, hpMax, strength, 0, 0, -1, -1, PoisonResult.UNKNOWN);
		low = Math.min(20, low);
		high = Math.min(20, high);
		int min = remaining(high), most = remaining(low);
		int earliest = ticksToKill(low, hpMin, 1), latest = ticksToKill(high, hpMax, WaveInfo.POISON_INTERVAL_TICKS);
		PoisonResult result = min >= hpMax ? PoisonResult.KILLS : most < hpMin ? PoisonResult.SURVIVES : PoisonResult.UNCERTAIN;
		return new HealerForecast(max, hpMin, hpMax, strength, min, most, earliest, latest, result);
	}

	private static int remaining(int done)
	{
		int total = 0;
		for (int n = done + 1; n <= 20; n++) total += WaveInfo.poisonHit(n);
		return total;
	}

	private static int ticksToKill(int done, int hp, int delay)
	{
		if (hp <= 0) return 0;
		for (int n = done + 1; n <= 20; n++)
		{
			hp -= WaveInfo.poisonHit(n);
			if (hp <= 0) return delay + (n - done - 1) * WaveInfo.POISON_INTERVAL_TICKS;
		}
		return -1;
	}

	public static List<Label> labels(Snapshot s)
	{
		List<Label> labels = new ArrayList<>();
		for (PenanceView p : s.getPenance())
		{
			if (p.getTile() == null || p.isUnseen()) continue;
			if (p.getType() == PenanceType.RUNNER) labels.add(runner(s, p));
			if (p.getType() == PenanceType.HEALER)
			{
				HealerForecast f = healer(s, p);
				String hp = f.hpMin < 0 ? "?" : "~" + (f.hpMin + f.hpMax + 1) / 2;
				String detail;
				switch (f.result)
				{
					case DYING: detail = "DYING"; break;
					case NO_POISON: detail = "no active poison"; break;
					case KILLS: detail = "dies ~" + f.earliestDeathTicks + "-" + f.latestDeathTicks + "t"; break;
					case SURVIVES: detail = "survives: short >=" + (f.hpMin - f.damageMax) + " HP"; break;
					case UNCERTAIN: detail = "kill?" + (f.earliestDeathTicks >= 0 ? " earliest ~" + f.earliestDeathTicks + "t" : ""); break;
					default: detail = "poison outcome unknown";
				}
				labels.add(new Label(p.getNpcIndex(), p.getTile(), "H" + p.getOrder() + " HP" + hp + "/" + f.maxHp + " P" + f.poison,
					detail, f.result == PoisonResult.KILLS ? "good" : f.result == PoisonResult.SURVIVES || f.result == PoisonResult.NO_POISON ? "bad" : "muted"));
			}
		}
		return labels;
	}
}

package com.bautopilot.baautopilot.state;

import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.WaveInfo;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/** One live penance NPC, as the planner sees it (template coordinates, no client references). */
@Value
@Builder(toBuilder = true)
public class PenanceView
{
	int npcIndex;
	PenanceType type;
	WorldPoint tile;
	/** Previous consecutive observation, for diagnostic motion rather than an inferred AI timer. */
	WorldPoint previousTile;
	int observedTick;
	@Builder.Default
	int animation = -1;
	String overhead;
	/** Health bar ratio / scale; scale -1 when no bar has been seen yet (full health). */
	@Builder.Default
	int healthRatio = -1;
	@Builder.Default
	int healthScale = -1;
	/** Healers only: 1-based spawn order (NPC index order), 0 otherwise. */
	int order;
	/** Healers only: correct poisoned food this plugin saw land on it. */
	int foods;
	int foodsThisPeriod;
	@Builder.Default
	int lastFoodTick = -1;
	/** Latest observed poison damage; food counts remain confirmed own inventory consumption. */
	@Builder.Default
	int lastPoisonDamage = -1;
	@Builder.Default
	int lastPoisonTick = -1;
	int spawnTick;
	boolean dying;
	/** Walked out of view and presumed alive; {@link #tile} is where it was last seen. */
	boolean unseen;
	/** Ticks since it walked out of view (0 while in view). */
	int unseenTicks;
	/** Hitsplat damage this wave: anyone's, yours, poison. */
	int damageTaken;
	int damageMine;
	int damagePoison;
	/** Damage per second over the last {@link DamageLog#WINDOW_TICKS}. */
	double dps;

	/**
	 * HP left, estimated from the damage taken and the health bar (no HP table needed): -1 before
	 * both are known.
	 */
	public int estimatedHpLeft()
	{
		double f = hpFraction();
		if (damageTaken <= 0 || healthScale <= 0 || f >= 1)
		{
			return -1;
		}
		return (int) Math.round(damageTaken * f / (1 - f));
	}

	/** Seconds to kill at the current damage per second, or -1 when unknown or nothing is hitting it. */
	public double secondsToKill()
	{
		int left = estimatedHpLeft();
		return left < 0 || dps <= 0 ? -1 : left / dps;
	}

	public double hpFraction()
	{
		if (healthScale <= 0 || healthRatio < 0)
		{
			return 1.0;
		}
		return (double) healthRatio / healthScale;
	}

	public boolean poisoned()
	{
		return lastFoodTick >= 0 || lastPoisonTick >= 0;
	}

	/**
	 * Use an observed hit over an older food estimate, including poison applied by a partner.
	 * Outside view, estimate up to five remaining hits at the last observed strength.
	 * A newer confirmed food immediately restores the estimate to 4 until another hit is seen.
	 */
	private int poisonHitsDone(int tick)
	{
		// A confirmed feed wins a tie with an older poison hit in the same game tick.
		if (lastPoisonTick >= 0 && lastPoisonTick > lastFoodTick)
		{
			return (WaveInfo.FOOD_DAMAGE - lastPoisonDamage) * 5
				+ Math.max(0, (tick - lastPoisonTick) / WaveInfo.POISON_INTERVAL_TICKS);
		}
		return Math.max(0, (tick - lastFoodTick) / WaveInfo.POISON_INTERVAL_TICKS);
	}

	/** Poison damage still to come from the latest food at {@code tick}. */
	public int poisonRemaining(int tick)
	{
		if (!poisoned())
		{
			return 0;
		}
		int hitsDone = poisonHitsDone(tick);
		int remaining = 0;
		for (int n = hitsDone + 1; n <= 20; n++)
		{
			remaining += WaveInfo.poisonHit(n);
		}
		return remaining;
	}

	/** Damage of the next poison hit (4 right after feeding, decaying to 1, then 0). */
	public int nextPoisonHit(int tick)
	{
		if (!poisoned())
		{
			return 0;
		}
		int hitsDone = poisonHitsDone(tick);
		return WaveInfo.poisonHit(hitsDone + 1);
	}
}

package com.bautopilot.baautopilot.state;

import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Collects {@link WaveStats} from the same events {@link RoundLogic} sees. Client-free, so the
 * replay harness can recompute a recorded round's numbers.
 */
public class Performance
{
	static final int HISTORY = 40;

	private static final String PUT_IN_BAG = "You put the egg in the bag.";
	/** Healer: "You healed 10 hitpoints." (exact; the BA Minigame plugin counts the same line). */
	private static final java.util.regex.Pattern HEALED = java.util.regex.Pattern.compile("^You healed (\\d+) hitpoints?\\.");
	private static final String EXPLODED = "The egg exploded.";
	private static final String LOADED = "You load the hopper.";
	private static final String IMMUNE = "These Penance are immune to your attacks.";
	private static final String WRONG_FOOD = "wrong type of poisoned food";

	private final List<WaveStats> history = new ArrayList<>();
	private WaveStats current;

	private int period = -1;
	private boolean heardThisPeriod;
	private boolean owedThisPeriod;
	private boolean calledThisPeriod;
	private int owedSince = -1;

	public void reset()
	{
		current = null;
		period = -1;
		owedSince = -1;
	}

	/** Called every arena tick once role and wave are known. */
	public void tick(int tick, int wave, Role role, int callPeriod, int periodStart, boolean heardFresh,
		boolean callOwed, boolean callDone)
	{
		tick(tick, wave, role, callPeriod, periodStart, heardFresh, callOwed, callDone, false);
	}

	/** @param covered a teammate of your role made your call: neither timed nor counted as missed */
	public void tick(int tick, int wave, Role role, int callPeriod, int periodStart, boolean heardFresh,
		boolean callOwed, boolean callDone, boolean covered)
	{
		if (wave <= 0 || role == null)
		{
			return;
		}
		if (current == null || current.wave != wave || current.finished)
		{
			current = new WaveStats(wave, role, periodStart >= 0 ? periodStart : tick);
			period = -1;
		}
		if (callPeriod != period)
		{
			closePeriod();
			period = callPeriod;
			heardThisPeriod = false;
			owedThisPeriod = false;
			calledThisPeriod = false;
			owedSince = -1;
		}
		if (heardFresh && !heardThisPeriod && periodStart >= 0)
		{
			heardThisPeriod = true;
			current.partnerDelays.add(Math.max(0, tick - periodStart));
		}
		if (covered && !callDone)
		{
			owedSince = -1;
			owedThisPeriod = false;
			return;
		}
		if (callOwed && owedSince < 0 && !calledThisPeriod)
		{
			owedSince = tick;
			owedThisPeriod = true;
		}
		if (callDone && owedSince >= 0)
		{
			current.callReactions.add(tick - owedSince);
			owedSince = -1;
			calledThisPeriod = true;
		}
	}

	private void closePeriod()
	{
		if (current == null || period < 0)
		{
			return;
		}
		if (!heardThisPeriod)
		{
			current.partnerMissed++;
		}
		if (owedThisPeriod && !calledThisPeriod)
		{
			current.callsMissed++;
		}
	}

	/** The wave ended (left the arena or the next wave began). */
	public void finish(int tick)
	{
		if (current == null || current.finished)
		{
			return;
		}
		// The last call is cut short by the wave end, so it can't count as missed
		current.endTick = tick;
		current.finished = true;
		history.add(current);
		if (history.size() > HISTORY)
		{
			history.remove(0);
		}
	}

	public void chat(String msg)
	{
		if (current == null || current.finished)
		{
			return;
		}
		java.util.regex.Matcher healed = HEALED.matcher(msg);
		if (healed.find())
		{
			current.hpHealed += Integer.parseInt(healed.group(1));
		}
		if (PUT_IN_BAG.equals(msg))
		{
			current.eggsPicked++;
		}
		else if (EXPLODED.equals(msg))
		{
			current.eggsWrong++;
		}
		else if (LOADED.equals(msg))
		{
			current.loads++;
		}
		else if (IMMUNE.equals(msg))
		{
			current.immuneHits++;
		}
		else if (msg.toLowerCase().contains(WRONG_FOOD))
		{
			current.wrongFoods++;
		}
	}

	public void menu(String option, String target)
	{
		if (current != null && !current.finished && "Shoot".equals(option) && target != null
			&& target.toLowerCase().contains("launcher"))
		{
			current.shots++;
		}
	}

	/** Eggs that appeared in the inventory since last tick (picked up past the bag). */
	public void inventory(Map<Integer, Integer> before, Map<Integer, Integer> now)
	{
		if (current == null || current.finished)
		{
			return;
		}
		for (int id : new int[]{BaIds.EGG_RED, BaIds.EGG_GREEN, BaIds.EGG_BLUE})
		{
			int gained = now.getOrDefault(id, 0) - before.getOrDefault(id, 0);
			if (gained > 0)
			{
				current.eggsPicked += gained;
			}
		}
	}

	public void wrongCall()
	{
		if (current != null && !current.finished)
		{
			current.callsWrong++;
		}
	}

	public void ownFeed()
	{
		if (current != null && !current.finished)
		{
			current.foods++;
		}
	}

	/** A death counted for an NPC that was only out of view. */
	public void undoDeath(PenanceType type)
	{
		if (current == null || current.finished || type == null)
		{
			return;
		}
		if (type == PenanceType.FIGHTER || type == PenanceType.RANGER)
		{
			current.fighterRangerKills = Math.max(0, current.fighterRangerKills - 1);
		}
		else if (type == PenanceType.RUNNER)
		{
			current.runnerKills = Math.max(0, current.runnerKills - 1);
		}
	}

	public void death(PenanceType type, int lifetimeTicks)
	{
		if (current == null || current.finished || type == null)
		{
			return;
		}
		switch (type)
		{
			case FIGHTER:
			case RANGER:
				current.fighterRangerKills++;
				break;
			case RUNNER:
				current.runnerKills++;
				break;
			case HEALER:
				if (lifetimeTicks >= 0)
				{
					current.healerLifetimes.add(lifetimeTicks);
				}
				break;
			default:
				break;
		}
	}

	/** The wave-complete screen's five team numbers, for the wave that just ended. */
	public void teamStats(int failedAttacks, int runnersPassed, int eggs, int hpHealed, int wrongPoison)
	{
		WaveStats last = history.isEmpty() ? null : history.get(history.size() - 1);
		if (last == null || last.hasTeamStats())
		{
			return;
		}
		last.teamFailedAttacks = failedAttacks;
		last.teamRunnersPassed = runnersPassed;
		last.teamEggs = eggs;
		last.teamHpHealed = hpHealed;
		last.teamWrongPoison = wrongPoison;
	}

	/** This wave so far, or null outside a wave. */
	public WaveStats current()
	{
		return current == null || current.finished ? null : current.copy();
	}

	/** Finished waves, oldest first. */
	public List<WaveStats> history()
	{
		List<WaveStats> out = new ArrayList<>(history.size());
		history.forEach(w -> out.add(w.copy()));
		return Collections.unmodifiableList(out);
	}
}

package com.bautopilot.baautopilot.state;

import com.google.common.collect.ImmutableMap;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Recent observed net HP loss. Healing never counts as damage; missing observations are unknown. */
public final class PlayerHealthHistory
{
	public static final int WINDOW_TICKS = 20;
	private final History self = new History();
	private final Map<String, History> team = new LinkedHashMap<>();

	public void reset() { self.clear(); team.clear(); }
	public void observeSelf(int tick, int hp, int max) { self.observe(tick, hp, max); }
	public void observeTeam(int tick, List<TeammateView> players)
	{
		for (TeammateView p : players)
			team.computeIfAbsent(p.getName(), name -> new History()).observe(tick, p.getHp(), p.getMaxHp());
	}
	public double selfRate(int tick) { return self.rate(tick); }
	public Map<String, Double> teamRates(int tick)
	{
		Map<String, Double> rates = new LinkedHashMap<>();
		team.forEach((name, history) -> rates.put(name, history.rate(tick)));
		return ImmutableMap.copyOf(rates);
	}

	private static final class History
	{
		private final Deque<int[]> intervals = new ArrayDeque<>(); // tick, observed loss
		private int lastTick = -1, lastHp, lastMax;
		void clear() { intervals.clear(); lastTick = -1; }
		void observe(int tick, int hp, int max)
		{
			if (max <= 0 || hp <= 0) { lastTick = -1; return; }
			if (tick <= lastTick) return;
			if (lastTick == tick - 1 && max == lastMax)
				intervals.addLast(new int[]{tick, Math.max(0, lastHp - hp)});
			lastTick = tick;
			lastHp = hp;
			lastMax = max;
			expire(tick);
		}
		private void expire(int tick)
		{
			while (!intervals.isEmpty() && intervals.peekFirst()[0] <= tick - WINDOW_TICKS) intervals.removeFirst();
		}
		double rate(int tick)
		{
			expire(tick);
			return intervals.stream().mapToInt(interval -> interval[1]).average().orElse(0);
		}
	}
}

