package com.bautopilot.baautopilot.state;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;
import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.Role;
import lombok.Getter;
import net.runelite.api.gameval.AnimationID;

/** Confirmed Queen hand-offs and ammunition use, including omegas loaded and fired between ticks. */
public final class QueenProgress
{
	static final int LOAD_SETTLE_TICKS = 2;
	private final Deque<Integer> pendingLoads = new ArrayDeque<>();
	@Getter private int yellowPassed;
	@Getter private int spikedPassed;
	@Getter private int omegaHandoffTick = -1;
	@Getter private int omegaFired;
	@Getter private int lastShotTick = -1;
	@Getter private boolean dead;
	private int observedSpent;
	private int settledLoads;
	private int lastAmmo = -1;

	public void reset()
	{
		pendingLoads.clear();
		yellowPassed = spikedPassed = omegaFired = observedSpent = settledLoads = 0;
		omegaHandoffTick = -1;
		lastShotTick = lastAmmo = -1;
		dead = false;
	}

	public void message(String text, boolean passingYellow, int tick)
	{
		if (passingYellow && "You passed the egg to the player.".equals(text)) yellowPassed++;
		if ("The omega egg has been loaded into the hopper.".equals(text)) pendingLoads.addLast(tick);
	}

	public void ammo(int tick, int loaded)
	{
		if (lastAmmo >= 0 && loaded < lastAmmo) observedSpent += lastAmmo - loaded;
		lastAmmo = loaded;
		while (!pendingLoads.isEmpty() && tick - pendingLoads.peekFirst() >= LOAD_SETTLE_TICKS)
		{
			pendingLoads.removeFirst();
			settledLoads++;
		}
		// Independent lower bounds: adding them would count the same egg twice.
		int fired = Math.max(observedSpent, Math.max(0, settledLoads - loaded));
		if (fired > omegaFired) { omegaFired = fired; lastShotTick = tick; }
	}

	public void died() { dead = true; }

	public void passedSpiked() { spikedPassed++; }

	/** A directed use animation is a readiness cue, not proof of the Collector's egg count. */
	public void players(int tick, List<PlayerView> players)
	{
		for (PlayerView giver : players)
		{
			if (giver.getRole() != Role.DEFENDER || giver.getAnimation() != AnimationID.HUMAN_PICKUPTABLE
				|| giver.getInteracting() == null || giver.getTile() == null) continue;
			for (PlayerView receiver : players)
				if (receiver.getRole() == Role.COLLECTOR && giver.getInteracting().equals(receiver.getName())
					&& receiver.getTile() != null && ArenaTiles.distance(giver.getTile(), receiver.getTile()) <= 1)
					omegaHandoffTick = tick;
		}
	}
}

package com.bautopilot.baautopilot.state;

import com.bautopilot.baautopilot.model.Role;
import com.google.common.collect.ImmutableMap;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.VarbitComposition;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;

/** Account progress stays available outside the arena without waking the round tracker. */
final class RoleProgress
{
	private static final Role[] ROLES = {Role.ATTACKER, Role.DEFENDER, Role.COLLECTOR, Role.HEALER};
	/** Four levels, four point remainders, four point multiples of 512, in ROLES order. */
	private static final int[] VARBITS = {
		VarbitID.BARBASSULT_ROLELEVEL_ATT, VarbitID.BARBASSULT_ROLELEVEL_DEF,
		VarbitID.BARBASSULT_ROLELEVEL_COL, VarbitID.BARBASSULT_ROLELEVEL_HEAL,
		VarbitID.BARBASSAULT_POINTS_ATTACKER_BASE, VarbitID.BARBASSAULT_POINTS_DEFENDER_BASE,
		VarbitID.BARBASSAULT_POINTS_COLLECTOR_BASE, VarbitID.BARBASSAULT_POINTS_HEALER_BASE,
		VarbitID.BARBASSAULT_POINTS_ATTACKER_EXTRA, VarbitID.BARBASSAULT_POINTS_DEFENDER_EXTRA,
		VarbitID.BARBASSAULT_POINTS_COLLECTOR_EXTRA, VarbitID.BARBASSAULT_POINTS_HEALER_EXTRA
	};
	private static final Snapshot UNKNOWN = Snapshot.builder().build();
	private final Set<Integer> backingVarps = new HashSet<>();
	private boolean mapped;
	private boolean dirty = true;
	private int[] values;
	private Snapshot current = UNKNOWN;

	void reset()
	{
		current = UNKNOWN;
		values = null;
		backingVarps.clear();
		mapped = false;
		dirty = true;
	}

	void invalidate()
	{
		dirty = true;
	}

	void changed(VarbitChanged event)
	{
		if (event.getVarbitId() >= 0)
		{
			for (int id : VARBITS)
				if (id == event.getVarbitId()) { dirty = true; break; }
		}
		// Server updates often name the backing varp, rather than an individual varbit.
		else if (!mapped || backingVarps.contains(event.getVarpId())) dirty = true;
	}

	Snapshot read(Client client)
	{
		if (!dirty || client.getGameState() != GameState.LOGGED_IN) return current;
		if (!mapped)
		{
			mapped = true;
			for (int id : VARBITS)
			{
				VarbitComposition definition = client.getVarbit(id);
				if (definition == null) mapped = false;
				else backingVarps.add(definition.getIndex());
			}
		}
		int[] next = new int[VARBITS.length];
		for (int i = 0; i < VARBITS.length; i++) next[i] = client.getVarbitValue(VARBITS[i]);
		dirty = false;
		if (Arrays.equals(values, next)) return current;
		values = next;
		ImmutableMap.Builder<Role, Integer> levels = ImmutableMap.builder(), points = ImmutableMap.builder();
		for (int i = 0; i < ROLES.length; i++)
		{
			levels.put(ROLES[i], next[i]);
			points.put(ROLES[i], next[4 + i] + 512 * next[8 + i]);
		}
		current = Snapshot.builder().roleLevels(levels.build()).rolePoints(points.build()).build();
		return current;
	}
}

package com.bautopilot.baautopilot.state;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
