	public int count(int itemId)
	{
		return inventory.getOrDefault(itemId, 0);
	}

	public boolean has(int itemId)
	{
		return count(itemId) > 0;
	}

	/** Tiles to walk from you to a tile: the collision map when known, else straight-line distance. */
	public int walk(WorldPoint tile)
	{
		if (playerTile == null || tile == null)
		{
			return 0;
		}
		int path = walkCost == null ? -1 : walkCost.tilesTo(tile);
		return path >= 0 ? path : ArenaTiles.distance(playerTile, tile);
	}

	public double hpFraction()
	{
		return maxHp <= 0 ? 1.0 : (double) hp / maxHp;
	}

	/** Ticks since the current call began, -1 when unknown. */
	public int ticksIntoCall()
	{
		return ticksToCallChange < 0 ? -1 : WaveInfo.TICKS_PER_CALL - ticksToCallChange;
	}

	public int waveSeconds()
	{
		return waveTick < 0 ? -1 : waveTick * 3 / 5;
	}

	public List<PenanceView> penance(PenanceType type)
	{
		if (cleared.contains(type))
		{
			return new java.util.ArrayList<>();
		}
		return penance.stream().filter(p -> p.getType() == type && !p.isDying()).collect(Collectors.toList());
	}

	/**
	 * Alive penance of a type: in view, then out of view (flagged {@link PenanceView#isUnseen}, last
	 * seen tile). Use for "is any left" and for keeping a target; use {@link #penance} for anything
	 * that needs a live position, like launcher range.
	 */
	/**
	 * Tiles from a bait within which a runner notices it: 4 at defender level 1, 5 at levels 2-5
	 * (OSRS Wiki, Advanced strategies).
	 */
	public int baitRange()
	{
		return roleLevels.getOrDefault(com.bautopilot.baautopilot.model.Role.DEFENDER, 1) >= 2 ? 5 : 4;
	}

	public List<PenanceView> alive(PenanceType type)
	{
		if (cleared.contains(type))
		{
			return new java.util.ArrayList<>();
		}
		List<PenanceView> out = penance(type);
		unseenPenance.stream().filter(p -> p.getType() == type).forEach(out::add);
		return out;
	}

	public List<GroundItemView> ground(Predicate<GroundItemView> filter)
	{
		return groundItems.stream().filter(filter).collect(Collectors.toList());
	}

	public ObjectView nearestObject(Predicate<ObjectView> filter)
	{
		ObjectView best = null;
		int bestD = Integer.MAX_VALUE;
		for (ObjectView o : objects)
		{
			if (!filter.test(o))
			{
				continue;
			}
			int d = playerTile == null ? 0 : ArenaTiles.distance(playerTile, o.getTile());
			if (best == null || d < bestD)
			{
				best = o;
				bestD = d;
			}
		}
		return best;
	}

	public ObjectView nearestObject(int... ids)
	{
		return nearestObject(o ->
		{
			for (int id : ids)
			{
				if (o.getId() == id)
				{
					return true;
				}
			}
			return false;
		});
	}
}

package com.bautopilot.baautopilot.state;

import com.bautopilot.baautopilot.model.Role;
import com.google.common.collect.ImmutableMap;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.gameval.InterfaceID.BarbassaultOverRecruitPlayerNames;
import net.runelite.client.util.Text;

/**
 * Who plays which role, read from the team list shown in the lobby (names in "Leader: x" /
 * "Player n: x" rows, role icons as models 20561/20563/20566/20569; mapping from BA Healer Order).
 * Kept until the team list shows a different team, so the Queen fight can say "pass to <name>".
 */
public class TeamRoster
{
	private static final int SLOTS = 5;
	private static final int ATTACKER_MODEL = 20561;
	private static final int COLLECTOR_MODEL = 20563;
	private static final int DEFENDER_MODEL = 20566;
	private static final int HEALER_MODEL = 20569;

	private Map<String, Role> roles = ImmutableMap.of();

	public void reset()
	{
		roles = ImmutableMap.of();
	}

	public void read(RoundLogic.Hud hud)
	{
		if (!hud.visible(BarbassaultOverRecruitPlayerNames.BARBASSAULT_LEADER_NAME))
		{
			return;
		}
		Map<String, Role> seen = new LinkedHashMap<>();
		for (int i = 0; i < SLOTS; i++)
		{
			String name = name(i, hud.text(BarbassaultOverRecruitPlayerNames.BARBASSAULT_LEADER_NAME + i));
			Role role = role(hud.model(BarbassaultOverRecruitPlayerNames.BARBASSAULT_LEADER_ICON + i));
			if (name != null && role != null)
			{
				seen.put(name, role);
			}
		}
		if (!seen.isEmpty())
		{
			roles = ImmutableMap.copyOf(seen);
		}
	}

	public Map<String, Role> roles()
	{
		return roles;
	}

	/** Your role on the team list, matching names the way the game shows them; null when absent. */
	public Role roleOf(String player)
	{
		if (player == null)
		{
			return null;
		}
		String key = Text.standardize(player);
		return roles.entrySet().stream()
			.filter(e -> Text.standardize(e.getKey()).equals(key))
			.map(Map.Entry::getValue)
			.findFirst().orElse(null);
	}

	/** "Leader: Zezima" / "Player 2: Lynx" / "-----" to the name, or null. */
	static String name(int slot, String text)
	{
		if (text == null)
		{
			return null;
		}
		String t = Text.removeTags(text).replace(' ', ' ').trim();
		String prefix = slot == 0 ? "leader:" : "player " + slot + ":";
		if (t.toLowerCase().startsWith(prefix))
		{
			t = t.substring(prefix.length()).trim();
		}
		return t.isEmpty() || t.startsWith("-") ? null : t;
	}

	static Role role(int model)
	{
		switch (model)
		{
			case ATTACKER_MODEL:
				return Role.ATTACKER;
			case COLLECTOR_MODEL:
				return Role.COLLECTOR;
			case DEFENDER_MODEL:
				return Role.DEFENDER;
			case HEALER_MODEL:
				return Role.HEALER;
			default:
				return null;
		}
	}
}

