	/**
	 * C-H-A-D-C: one egg at a time, worked by each player in turn and passed along to the next -
	 * yellow from the Collector, poisoned by the Healer, spiked by the Attacker, heated by the
	 * Defender, and back to the Collector to load.
	 */
	private void chain(long elapsed, Integer only)
	{
		List<String> eggs = CHAIN_EGGS;
		List<String> players = CHAIN_PLAYERS;
		int steps = eggs.size();
		// One step on repeat (slower, with its tools), or the whole chain
		long at = only != null ? elapsed % CHAIN_PAGE_STEP : elapsed % (CHAIN_STEP * steps);
		long loop = only != null ? elapsed / CHAIN_PAGE_STEP : elapsed / (CHAIN_STEP * steps);
		int step = only != null ? only : (int) (at / CHAIN_STEP);
		long starts = only != null ? 0 : step * CHAIN_STEP;
		// Only the egg of the current step is in the room
		for (int i = 0; i < steps; i++)
		{
			if (i == step)
			{
				hidden.remove(eggs.get(i));
			}
			else
			{
				hidden.add(eggs.get(i));
			}
		}
		TutorialScene.Prop player = scene.prop(players.get(step));
		TutorialScene.Prop egg = scene.prop(eggs.get(step));
		if (player == null || egg == null)
		{
			return;
		}
		// The Healer and Defender use the egg on their crater, when the page shows it
		TutorialScene.Prop crater = step == 1 ? scene.prop("chain-crater") : step == 3 ? scene.prop("chain-lava") : null;
		boolean dunk = crater != null && crater.getObject().isActive();
		TutorialScene.Prop mushroom = step == 2 ? scene.prop("chain-mushroom") : null;
		if (mushroom != null && mushroom.getObject().isActive())
		{
			spikes(player, mushroom, egg, at, loop);
			return;
		}
		face(player, dunk ? crater : egg);
		if (due(loop, step, at, starts))
		{
			// A reach towards the crater or the egg (the game's egg-poisoning animation isn't a player's)
			scene.play(player, step == 0 ? AnimationID.HUMAN_PICKUPFLOOR : FEED);
		}
	}

	/** The Attacker takes spikes from the mushroom, then uses them on the egg. */
	private void spikes(TutorialScene.Prop attacker, TutorialScene.Prop mushroom, TutorialScene.Prop egg, long at, long loop)
	{
		if (due(loop, 0, at, 0))
		{
			hidden.add("chain-spikes");
			face(attacker, mushroom);
			scene.play(attacker, FEED);
		}
		if (due(loop, 1, at, SPIKES_TAKEN))
		{
			hidden.remove("chain-spikes");
			face(attacker, egg);
			scene.play(attacker, FEED);
		}
		if (due(loop, 2, at, SPIKES_USED))
		{
			hidden.add("chain-spikes");
		}
	}

	/**
	 * C-H-A-D-C round the loop: each player in turn works the egg, then it slides to the next
	 * player, as it is after their step - yellow to the Healer, poisoned to the Attacker, spiked to
	 * the Defender, omega back to the Collector.
	 */
	private void pass(long elapsed)
	{
		List<String> players = CHAIN_PLAYERS;
		List<String> eggs = CHAIN_EGGS.subList(0, 4);
		int legs = eggs.size();
		long at = elapsed % (PASS_LEG * legs);
		long loop = elapsed / (PASS_LEG * legs);
		int leg = (int) (at / PASS_LEG);
		long into = at % PASS_LEG;
		TutorialScene.Prop from = scene.prop(players.get(leg));
		TutorialScene.Prop to = scene.prop(players.get(leg + 1));
		TutorialScene.Prop egg = scene.prop(eggs.get(leg));
		if (from == null || to == null || egg == null)
		{
			return;
		}
		for (int i = 0; i < legs; i++)
		{
			if (i == leg)
			{
				hidden.remove(eggs.get(i));
			}
			else
			{
				hidden.add(eggs.get(i));
			}
		}
		face(from, to);
		face(to, from);
		if (due(loop, leg, at, leg * PASS_LEG))
		{
			scene.play(from, FEED);
		}
		// Held, then handed across
		double f = into < PASS_HOLD ? 0 : Math.min(1, (into - PASS_HOLD) / (double) (PASS_LEG - PASS_HOLD - PASS_REST));
		LocalPoint a = from.getObject().getLocation();
		LocalPoint b = to.getObject().getLocation();
		if (a != null && b != null)
		{
			// Over the heads: held up high, a little arc on the way across
			int lift = EGG_OVERHEAD + (int) Math.round(EGG_ARC * Math.sin(Math.PI * f));
			scene.move(egg, TutorialPath.along(java.util.Arrays.asList(a, b), f * f * (3 - 2 * f)), lift);
		}
	}

	/** The healer feeds one penance healer, walks over to the other and feeds it, then walks back. */
	private void poisonTwo(long elapsed, TutorialScene.Prop second)
	{
		TutorialScene.Prop healer = scene.prop("heal-healer");
		TutorialScene.Prop first = scene.prop("heal-pen");
		LocalPoint atFirst = scene.tile("heal-at-1");
		LocalPoint atSecond = scene.tile("heal-at-2");
		if (healer == null || first == null || atFirst == null || atSecond == null)
		{
			return;
		}
		face(scene.prop("heal-defender"), healer);
		long at = elapsed % FEED_ROUND;
		long loop = elapsed / FEED_ROUND;
		if (due(loop, 0, at, 0))
		{
			scene.move(healer, atFirst);
			face(healer, first);
			scene.play(healer, FEED);
		}
		if (due(loop, 1, at, FEED_FIRST_HITS))
		{
			scene.play(first, AnimationID.BARBASSAULT_PENANCE_HEALER_POISION);
			splats.add(new Splat("heal-pen", POISON_SPLAT, "4", System.currentTimeMillis() + SPLAT_MS));
		}
		walk(healer, java.util.Arrays.asList(atFirst, atSecond), at, WALK_TO_SECOND, AT_SECOND, AnimationID.HUMAN_WALK_F);
		if (due(loop, 2, at, AT_SECOND + WALK_SETTLE))
		{
			face(healer, second);
			scene.play(healer, FEED);
		}
		if (due(loop, 3, at, FEED_SECOND_HITS))
		{
			scene.play(second, AnimationID.BARBASSAULT_PENANCE_HEALER_POISION);
			splats.add(new Splat("heal-pen-2", POISON_SPLAT, "4", System.currentTimeMillis() + SPLAT_MS));
		}
		walk(healer, java.util.Arrays.asList(atSecond, atFirst), at, WALK_TO_FIRST, AT_FIRST, AnimationID.HUMAN_WALK_F);
	}

	/** Partners face each other; one horn after another. */
	/**
	 * The callers blow their horns one at a time (in the order of the page's calls); only the
	 * one calling now shows their call and their arrow, so each call reads on its own.
	 */
	private void horns(TutorialSteps.Page page, long elapsed)
	{
		List<String> callers = new ArrayList<>(page.getSpeech().keySet());
		for (TutorialSteps.Arrow a : page.getArrows())
		{
			face(scene.prop(a.getFrom()), scene.prop(a.getTo()));
		}
		if (callers.isEmpty())
		{
			return;
		}
		long at = elapsed % (HORN_EACH * callers.size());
		long loop = elapsed / (HORN_EACH * callers.size());
		int turn = (int) (at / HORN_EACH);
		speaker = callers.get(turn);
		TutorialScene.Prop p = scene.prop(speaker);
		if (p != null && due(loop, turn, at, turn * HORN_EACH))
		{
			scene.play(p, AnimationID.BARBASSAULT_HUMAN_USE_HORN);
		}
	}

	/** Who is calling now on a horn page; null on other pages (everyone's text shows). */
	public String speaker()
	{
		return runningPage != null && runningPage.getAction() == TutorialSteps.Action.HORNS ? speaker : null;
	}

	/** The page's players reach into what they use (a dispenser), every few seconds. */
	private void use(TutorialSteps.Page page, long elapsed)
	{
		long at = elapsed % USE_EVERY;
		long loop = elapsed / USE_EVERY;
		List<TutorialSteps.Arrow> uses = page.getUses();
		for (int i = 0; i < uses.size(); i++)
		{
			TutorialScene.Prop who = scene.prop(uses.get(i).getFrom());
			TutorialScene.Prop what = scene.prop(uses.get(i).getTo());
			face(who, what);
			if (who != null && due(loop, i, at, i * USE_STAGGER))
			{
				scene.play(who, FEED);
			}
		}
	}

	/** The Queen's attacks, one after the other: a strike, then a ranged blast. */
	private void rage(long elapsed)
	{
		TutorialScene.Prop queen = scene.prop("queen");
		if (queen == null)
		{
			return;
		}
		long at = elapsed % RAGE_EVERY;
		long loop = elapsed / RAGE_EVERY;
		if (due(loop, 0, at, RAGE_FIRST))
		{
			scene.play(queen, AnimationID.BARBASSAULT_PENANCE_QUEEN_ATTACK);
		}
		if (due(loop, 1, at, RAGE_SECOND))
		{
			scene.play(queen, AnimationID.BARBASSAULT_PENANCE_QUEEN_RANGEATTACK);
		}
	}

	/** The leader holds the scroll out to you, again and again. */
	private void invite(long elapsed)
	{
		TutorialScene.Prop leader = scene.prop("leader");
		TutorialScene.Prop you = scene.prop("you");
		if (leader == null || you == null)
		{
			return;
		}
		face(leader, you);
		face(you, leader);
		long at = elapsed % INVITE_EVERY;
		long loop = elapsed / INVITE_EVERY;
		if (due(loop, 0, at, 0))
		{
			scene.play(leader, FEED);
		}
	}

	private void poison(long elapsed)
	{
		TutorialScene.Prop second = scene.prop("heal-pen-2");
		if (second != null && second.getObject().isActive())
		{
			poisonTwo(elapsed, second);
			return;
		}
		TutorialScene.Prop healer = scene.prop("heal-healer");
		TutorialScene.Prop penance = scene.prop("heal-pen");
		if (healer == null || penance == null)
		{
			return;
		}
		face(healer, penance);
		face(scene.prop("heal-defender"), healer);
		long at = elapsed % FEED_EVERY;
		long loop = elapsed / FEED_EVERY;
		if (due(loop, 0, at, 0))
		{
			scene.play(healer, FEED);
		}
		if (due(loop, 1, at, POISON_HITS))
		{
			scene.play(penance, AnimationID.BARBASSAULT_PENANCE_HEALER_POISION);
			splats.add(new Splat("heal-pen", POISON_SPLAT, "4", System.currentTimeMillis() + SPLAT_MS));
		}
	}

	/** Event {@code event} of loop {@code loop} is due (time {@code at} into the loop) and hasn't fired yet. */
	private boolean due(long loop, int event, long at, long when)
	{
		if (at < when || loop < lastLoop || (loop == lastLoop && event <= lastEvent))
		{
			return false;
		}
		lastLoop = loop;
		lastEvent = event;
		return true;
	}

	/** The collector loads the hopper, the gunner fires, the egg hits the target. */
	private void cannon(String collectorKey, String gunnerKey, String turretKey, String hopperKey, String targetKey,
		int egg, int defend, long elapsed)
	{
		TutorialScene.Prop collector = scene.prop(collectorKey);
		TutorialScene.Prop gunner = scene.prop(gunnerKey);
		TutorialScene.Prop turret = scene.prop(turretKey);
		TutorialScene.Prop queen = scene.prop(targetKey);
		if (collector == null || gunner == null || turret == null || queen == null)
		{
			return;
		}
		face(collector, scene.prop(hopperKey));
		face(gunner, queen);
		face(turret, queen);
		long at = elapsed % CANNON_EVERY;
		long loop = elapsed / CANNON_EVERY;
		if (due(loop, 0, at, 0))
		{
			scene.play(collector, FEED);
		}
		if (due(loop, 1, at, CANNON_FIRES))
		{
			scene.play(gunner, AnimationID.BARBASSAULT_EGG_CANNON_HUMAN_FIRE);
			scene.play(turret, AnimationID.BARBASSAULT_EGG_CANNON_FIRE);
			fly(egg, turret, queen, EGG_FROM, EGG_TO, 20, 0);
		}
		if (due(loop, 2, at, CANNON_FIRES + EGG_CYCLES * 20L))
		{
			scene.play(queen, defend);
			splats.add(new Splat(targetKey, DAMAGE_SPLAT, "25", System.currentTimeMillis() + SPLAT_MS));
		}
	}

	private void fly(int spotanim, TutorialScene.Prop from, TutorialScene.Prop to, int startHeight, int endHeight,
		int slope, int startPos)
	{
		LocalPoint a = from.getObject().getLocation();
		LocalPoint b = to.getObject().getLocation();
		if (a == null || b == null)
		{
			return;
		}
		int cycle = client.getGameCycle();
		boolean egg = spotanim >= SpotanimID.BARBASSAULT_EGG_PROJ_01 && spotanim <= SpotanimID.BARBASSAULT_EGG_PROJ_ATOMIC;
		int cycles = egg ? EGG_CYCLES : ARROW_CYCLES;
		Projectile p = client.createProjectile(spotanim,
			WorldPoint.fromLocal(client, a), startHeight, null,
			WorldPoint.fromLocal(client, b), endHeight, null,
			cycle, cycle + cycles, slope, startPos);
		client.getProjectiles().addLast(p);
	}

	/** Turns a prop to look at another (0 south, 512 west, 1024 north, 1536 east). */
	private static void face(TutorialScene.Prop who, TutorialScene.Prop at)
	{
		if (who == null || at == null)
		{
			return;
		}
		LocalPoint a = who.getObject().getLocation();
		LocalPoint b = at.getObject().getLocation();
		if (a == null || b == null || a.equals(b))
		{
			return;
		}
		double angle = Math.atan2(-(b.getX() - a.getX()), -(b.getY() - a.getY()));
		who.getObject().setOrientation((int) Math.round(angle * 1024 / Math.PI) & 2047);
	}
}

package com.bautopilot.baautopilot.tutorial;

import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.overlay.Palette;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BooleanSupplier;
import javax.inject.Inject;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * The tutorial page box: page count, title, text, and Back / Next buttons. Clicks on the box are
 * the box's own (consumed), so they never walk you or click the game behind it.
 */
@javax.inject.Singleton
public class TutorialBoxOverlay extends Overlay
{
	private static final int WIDTH = 380;
	private static final int PAD = 12;
	/** Wide enough for "< Introduction", the longest tutorial name on a button. */
	private static final int BUTTON_W = 104;
	private static final int BUTTON_H = 26;
	/** The role panel stand-in (drawn in the column right of the box). */
	private static final int HUD_PAD = 6;
	private static final int HUD_ROW = 26;
	private static final int HUD_HEIGHT = HUD_PAD * 2 + HUD_ROW * 3;
	/** Space kept between the dots and each button. */
	private static final int DOT_MARGIN = 8;
	private static final int HEADER_H = 40;
	/** Space above and below the control row. */
	private static final int CONTROLS_PAD = 8;
	/** The BA badge, drawn at half its 64 px. */
	private static final int BADGE = 36;
	/** Stone and gold, after the game's own interfaces. */
	private static final Color BACKGROUND = new Color(46, 39, 30, 240);
	private static final Color HEADER = new Color(62, 53, 41);
	private static final Color EDGE_DARK = new Color(14, 12, 9);
	private static final Color EDGE_GOLD = new Color(146, 118, 66);
	private static final Color TITLE = new Color(255, 152, 31);
	private static final Color TEXT = new Color(240, 230, 205);
	private static final Color MUTED = new Color(150, 138, 115);
	/** Egg names in the box, bright enough to read on the stone. */
	private static final Color EGG_RED = new Color(255, 95, 85);
	private static final Color EGG_GREEN = new Color(110, 225, 110);
	private static final Color EGG_BLUE = new Color(120, 170, 255);
	private static final Color EGG_YELLOW = new Color(250, 220, 80);
	private static final Color SHADOW = Color.BLACK;
	private static final Color BUTTON = new Color(74, 63, 47);
	private static final Color BUTTON_HOVER = new Color(104, 88, 60);
	private static final Color BUTTON_OFF = new Color(52, 45, 36);
	private static final Color DOT_ON = new Color(255, 152, 31);
	private static final Color DOT_OFF = new Color(96, 84, 64);

	private final TutorialSteps steps;
	private final SpriteManager sprites;
	private BufferedImage badge;
	private BooleanSupplier shown = () -> false;

	/** Button areas inside the box, from the last frame drawn. */
	private final Rectangle back = new Rectangle();
	private final Rectangle next = new Rectangle();
	/** Each page dot's click area inside the box, from the last frame drawn (read on the input thread). */
	private volatile List<Rectangle> dotAreas = new ArrayList<>();
	/** The mouse, in canvas coordinates. */
	private volatile java.awt.Point mouse = new java.awt.Point(-1, -1);
	private final TooltipManager tooltips;

	@Inject
	TutorialBoxOverlay(TutorialSteps steps, SpriteManager sprites, TooltipManager tooltips)
	{
		this.steps = steps;
		this.sprites = sprites;
		this.tooltips = tooltips;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public void setShown(BooleanSupplier shown)
	{
		this.shown = shown;
	}

	/** What Finish on the very last page does: end the tutorial (input thread). */
	private Runnable onFinish = () -> { };

	public void setOnFinish(Runnable onFinish)
	{
		this.onFinish = onFinish;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!shown.getAsBoolean())
		{
			return null;
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		TutorialSteps.Page page = steps.current();
		Font bodyFont = FontManager.getRunescapeFont();
		Font titleFont = FontManager.getRunescapeBoldFont();
		g.setFont(bodyFont);
		FontMetrics body = g.getFontMetrics();
		// Paragraphs are separated by a blank line in the text; null marks the gap between two
		List<String> lines = new ArrayList<>();
		int gaps = 0;
		for (String paragraph : page.getBody().split("\n\n"))
		{
			if (!lines.isEmpty())
			{
				lines.add(null);
				gaps++;
			}
			lines.addAll(wrap(paragraph.replace('\n', ' ').trim(), body, WIDTH - 2 * PAD));
		}
		int paragraphGap = body.getHeight() / 2;
		// Header, then the controls (fixed under it), a divider, then the text
		int controlsTop = HEADER_H + CONTROLS_PAD;
		int divider = controlsTop + BUTTON_H + CONTROLS_PAD;
		int textTop = divider + PAD;
		int height = textTop + (lines.size() - gaps) * body.getHeight() + gaps * paragraphGap + PAD;

		// Frame: dark edge, gold inner edge, stone fill, a lighter header band
		g.setColor(BACKGROUND);
		g.fillRect(0, 0, WIDTH, height);
		g.setColor(HEADER);
		g.fillRect(2, 2, WIDTH - 4, HEADER_H - 2);
		g.setColor(EDGE_GOLD);
		g.drawLine(2, HEADER_H, WIDTH - 3, HEADER_H);
		g.setStroke(new BasicStroke(1f));
		g.drawRect(1, 1, WIDTH - 3, height - 3);
		g.setColor(EDGE_DARK);
		g.drawRect(0, 0, WIDTH - 1, height - 1);

		// Header: the BA badge, title; the page count on the right
		int x = PAD;
		BufferedImage badge = badge();
		if (badge != null)
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.drawImage(badge, x - 4, (HEADER_H - BADGE) / 2 + 1, BADGE, BADGE, null);
			x += BADGE + 2;
		}
		g.setFont(titleFont);
		FontMetrics title = g.getFontMetrics();
		int titleBase = (HEADER_H + title.getAscent() - title.getDescent()) / 2 + 1;
		shadowed(g, page.getTitle(), x, titleBase, TITLE);
		g.setFont(FontManager.getRunescapeSmallFont());
		String count = (steps.index() + 1) + " / " + steps.pages().size();
		int right = WIDTH - PAD - g.getFontMetrics().stringWidth(count);
		shadowed(g, count, right, titleBase, MUTED);

		// Controls: Back, progress dots, Next - always in the same place
		back.setBounds(PAD, controlsTop, BUTTON_W, BUTTON_H);
		next.setBounds(WIDTH - PAD - BUTTON_W, controlsTop, BUTTON_W, BUTTON_H);
		button(g, back, steps.backLabel(), steps.hasBack());
		button(g, next, steps.nextLabel(), steps.hasNext() || steps.isLast());
		dots(g, controlsTop + BUTTON_H / 2);
		g.setColor(EDGE_GOLD);
		g.setStroke(new BasicStroke(1f));
		g.drawLine(PAD, divider, WIDTH - PAD, divider);

		// Body
		g.setFont(bodyFont);
		int y = textTop;
		boolean emphasis = false;
		for (String line : lines)
		{
			if (line == null)
			{
				// A new paragraph: a half-line gap, and any emphasis left open ends with its paragraph
				y += paragraphGap;
				emphasis = false;
				continue;
			}
			emphasis = drawLine(g, line, PAD, y + body.getAscent(), emphasis);
			y += body.getHeight();
		}
		// The role panel and inventory go in the column on the right (TutorialInventoryOverlay); the
		// page's autopilot box is the plugin's own (InstructionOverlay), where it always sits
		return new Dimension(WIDTH, height);
	}

	/** The Barbarian Assault icon from the minigame teleports; null until the sprite has loaded. */
	private BufferedImage badge()
	{
		if (badge == null)
		{
			badge = sprites.getSprite(BaIcon.SPRITE, 0);
		}
		return badge;
	}

	/**
	 * A stand-in for the game's role panel, at the given place (the column right of the box): the
	 * role and the call timer, the call to make (mouth) and the call heard (ear), with the game's
	 * icons. Returns the new bottom.
	 */
	int drawHud(Graphics2D g, TutorialSteps.Hud hud, int left, int top, int width)
	{
		int row = HUD_ROW;
		int height = HUD_HEIGHT;
		g.setColor(BACKGROUND);
		g.fillRect(left, top, width, height);
		g.setColor(EDGE_GOLD);
		g.drawRect(left + 1, top + 1, width - 3, height - 3);
		g.setColor(EDGE_DARK);
		g.drawRect(left, top, width - 1, height - 1);

		int x = left + HUD_PAD;
		int y = top + HUD_PAD;
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = g.getFontMetrics();
		int base = (row + fm.getAscent() - fm.getDescent()) / 2;
		// Role and the round's timer, counting down from 30 on a loop
		icon(g, net.runelite.api.gameval.SpriteID.BarbassaultIcons.WAVE, x, y, row);
		shadowed(g, hud.getRole().getLabel(), x + row + 4, y + base, Palette.role(hud.getRole()));
		String timer = String.format("0:%02d", 30 - (int) (steps.elapsed() / 1000 % 30));
		shadowed(g, timer, left + width - HUD_PAD - fm.stringWidth(timer), y + base, MUTED);
		y += row;
		icon(g, net.runelite.api.gameval.SpriteID.BarbassaultIcons.MOUTH, x, y, row);
		g.setFont(FontManager.getRunescapeFont());
		shadowed(g, "Call: " + hud.getCall(), x + row + 4, y + base, TITLE);
		y += row;
		icon(g, net.runelite.api.gameval.SpriteID.BarbassaultIcons.EAR, x, y, row);
		shadowed(g, "Heard: " + hud.getHeard(), x + row + 4, y + base, TEXT);
		return top + height;
	}


	/** A game sprite fitted into a square, when loaded. */
	private void icon(Graphics2D g, int sprite, int x, int y, int size)
	{
		BufferedImage image = sprites.getSprite(sprite, 0);
		if (image == null)
		{
			return;
		}
		double scale = Math.min(1, (size - 2) / (double) Math.max(image.getWidth(), image.getHeight()));
		int w = (int) Math.round(image.getWidth() * scale);
		int h = (int) Math.round(image.getHeight() * scale);
		g.drawImage(image, x + (size - w) / 2, y + (size - h) / 2, w, h, null);
	}

	/**
	 * One dot per page, the current one lit. Each is a button to its page: hovering lights it and
	 * shows the page's title; its click area is as wide as the spacing, so packed dots stay clickable.
	 */
	private void dots(Graphics2D g, int centreY)
	{
		List<TutorialSteps.Page> pages = steps.pages();
		int n = pages.size();
		// As far apart as fits between the buttons (10 px at most), smaller dots when packed
		int room = WIDTH - 2 * PAD - 2 * BUTTON_W - 2 * DOT_MARGIN;
		double step = n <= 1 ? 0 : Math.min(10, room / (double) (n - 1));
		int small = step >= 8 ? 3 : 2;
		double x = (WIDTH - (n - 1) * step) / 2;
		int areaW = Math.max(4, (int) Math.floor(step));
		List<Rectangle> areas = new ArrayList<>(n);
		for (int i = 0; i < n; i++)
		{
			int cx = (int) Math.round(x + i * step);
			Rectangle area = new Rectangle(cx - areaW / 2, centreY - DOT_HIT / 2, areaW, DOT_HIT);
			areas.add(area);
			boolean hover = onCanvas(area).contains(mouse);
			int r = i == steps.index() || hover ? small + 1 : small;
			g.setColor(i == steps.index() ? DOT_ON : hover ? DOT_HOVER : DOT_OFF);
			g.fillOval(cx - r, centreY - r, 2 * r, 2 * r);
			if (hover)
			{
				tooltips.add(new Tooltip((i + 1) + ". " + pages.get(i).getTitle()));
			}
		}
		dotAreas = areas;
	}

	/** A dot's click area is this tall, well beyond the dot itself. */
	private static final int DOT_HIT = 16;
	private static final Color DOT_HOVER = new Color(200, 160, 90);

	private void button(Graphics2D g, Rectangle r, String text, boolean enabled)
	{
		g.setColor(!enabled ? BUTTON_OFF : onCanvas(r).contains(mouse) ? BUTTON_HOVER : BUTTON);
		g.fillRect(r.x, r.y, r.width, r.height);
		g.setColor(EDGE_DARK);
		g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
		g.setColor(enabled ? EDGE_GOLD : DOT_OFF);
		g.drawRect(r.x + 1, r.y + 1, r.width - 3, r.height - 3);
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = g.getFontMetrics();
		shadowed(g, text, r.x + (r.width - fm.stringWidth(text)) / 2,
			r.y + (r.height + fm.getAscent() - fm.getDescent()) / 2, enabled ? TITLE : MUTED);
	}

	/** Text with the game's one-pixel black shadow, for reading over anything. */
	private static void shadowed(Graphics2D g, String text, int x, int baseline, Color color)
	{
		g.setColor(SHADOW);
		g.drawString(text, x + 1, baseline + 1);
		g.setColor(color);
		g.drawString(text, x, baseline);
	}

	/**
	 * A line of body text: role and egg names in their colours, and *starred* words (which may
	 * run over several lines) in the title gold, for the line a page leans on. Returns whether the
	 * emphasis is still open at the end of the line. "Penance Healers" are monsters, not the role:
	 * plain, like the other Penance (reported 2026-10-19: only they were coloured).
	 */
	private static boolean drawLine(Graphics2D g, String line, int x, int baseline, boolean emphasis)
	{
		FontMetrics fm = g.getFontMetrics();
		String[] words = line.split(" ");
		for (int i = 0; i < words.length; i++)
		{
			String raw = words[i];
			boolean opens = raw.startsWith("*");
			boolean closes = raw.endsWith("*") && raw.length() > 1;
			String bare = raw.replace("*", "");
			emphasis |= opens;
			String word = i < words.length - 1 ? bare + " " : bare;
			boolean penance = i > 0 && words[i - 1].replaceAll("[^A-Za-z]", "").equals("Penance");
			shadowed(g, word, x, baseline, emphasis ? TITLE : penance ? TEXT : colourOf(bare));
			x += fm.stringWidth(word);
			if (closes)
			{
				emphasis = false;
			}
		}
		return emphasis;
	}

	/** Role names in their role's colour, egg colours in the egg's; everything else plain. */
	private static Color colourOf(String word)
	{
		Role role = roleNamed(word);
		if (role != null)
		{
			return Palette.role(role);
		}
		switch (word.replaceAll("[^A-Za-z]", ""))
		{
			case "Red":
				return EGG_RED;
			case "Green":
				return EGG_GREEN;
			case "Blue":
				return EGG_BLUE;
			case "Yellow":
				return EGG_YELLOW;
			default:
				return TEXT;
		}
	}

	/** "Attacker", "Healers,", "Collector." name a role; anything else doesn't. */
	private static Role roleNamed(String word)
	{
		String bare = word.replaceAll("[^A-Za-z]", "");
		for (Role role : Role.values())
		{
			if (bare.equals(role.getLabel()) || bare.equals(role.getLabel() + "s"))
			{
				return role;
			}
		}
		return null;
	}

	/** A rectangle inside the box, moved to where the box was last drawn on the canvas. */
	private Rectangle onCanvas(Rectangle inBox)
	{
		Rectangle box = getBounds();
		return new Rectangle(box.x + inBox.x, box.y + inBox.y, inBox.width, inBox.height);
	}

	private static List<String> wrap(String text, FontMetrics fm, int width)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String tryLine = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(tryLine.replace("*", "")) > width && line.length() > 0)
			{
				lines.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(tryLine);
			}
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	/** Back / Next on press; any click on the box stays with the box. */
	public final MouseListener mouseListener = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			if (!onBox(e))
			{
				return e;
			}
			if (e.getButton() == MouseEvent.BUTTON1)
			{
				if (steps.hasBack() && onCanvas(back).contains(e.getPoint()))
				{
					steps.back();
				}
				else if (steps.isLast() && onCanvas(next).contains(e.getPoint()))
				{
					onFinish.run();
				}
				else if (steps.hasNext() && onCanvas(next).contains(e.getPoint()))
				{
					steps.next();
				}
				else
				{
					List<Rectangle> areas = dotAreas;
					for (int i = 0; i < areas.size(); i++)
					{
						if (onCanvas(areas.get(i)).contains(e.getPoint()))
						{
							steps.open(i);
							break;
						}
					}
				}
			}
			e.consume();
			return e;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent e)
		{
			if (onBox(e))
			{
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseClicked(MouseEvent e)
		{
			if (onBox(e))
			{
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseMoved(MouseEvent e)
		{
			mouse = e.getPoint();
			return e;
		}
	};

	private boolean onBox(MouseEvent e)
	{
		return shown.getAsBoolean() && getBounds().contains(e.getPoint());
	}
}

package com.bautopilot.baautopilot.tutorial;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;

/**
 * Pans the camera to what the tutorial page is about, without moving you: the camera is detached
 * (free camera mode) and its focal point glides to the target; with no target, or when the
 * tutorial ends, the camera goes back to following you. Client thread, every client tick.
 */
@Slf4j
@Singleton
public class TutorialCamera
{
	/** Camera modes: follow the player, or free (detached focal point). */
	private static final int FOLLOW = 0;
	private static final int FREE = 1;
	/** Glide length: this long at least, plus this much per local unit (a room is about 1000), at most this. */
	private static final long GLIDE_MIN_MS = 450;
	private static final double GLIDE_MS_PER_UNIT = 0.8;
	private static final long GLIDE_MAX_MS = 2800;

	private final Client client;
	private boolean detached;
	/**
	 * Which focal point axis runs north-south: the engine's 3D axes have Y as height and Z as
	 * north-south, but rather than trust that, it's the one closer to your own local y when the
	 * camera detaches (it's centred on you then).
	 */
	private boolean northIsZ = true;
	/** The glide in progress: where to, from where, since when and for how long. */
	private LocalPoint glideTo;
	private float fromX;
	private float fromNorth;
	private long glideStart;
	private long glideMs;

	@Inject
	TutorialCamera(Client client)
	{
		this.client = client;
	}

	/**
	 * Glides to the target (null: back to you): a new target starts an eased move from where the
	 * camera is, longer for longer distances, so a pan to another room reads as one smooth sweep.
	 */
	public void update(LocalPoint target)
	{
		if (target == null)
		{
			release();
			return;
		}
		detach();
		long now = System.currentTimeMillis();
		if (!target.equals(glideTo))
		{
			glideTo = target;
			fromX = client.getCameraFocalPointX();
			fromNorth = north();
			glideStart = now;
			double distance = Math.hypot(target.getX() - fromX, target.getY() - fromNorth);
			glideMs = (long) Math.max(GLIDE_MIN_MS, Math.min(GLIDE_MAX_MS, GLIDE_MIN_MS + distance * GLIDE_MS_PER_UNIT));
		}
		double t = Math.min(1, (now - glideStart) / (double) glideMs);
		double eased = t * t * (3 - 2 * t);
		set((float) (fromX + (target.getX() - fromX) * eased), (float) (fromNorth + (target.getY() - fromNorth) * eased));
	}

	/** Puts the camera right on the target: for a tour that is already moving smoothly. */
	public void follow(LocalPoint target)
	{
		if (target == null)
		{
			release();
			return;
		}
		detach();
		glideTo = null;
		set(target.getX(), target.getY());
	}

	/** Where the camera looks now: its focal point while detached, else you; null before login. */
	public LocalPoint here()
	{
		if (detached)
		{
			return new LocalPoint((int) client.getCameraFocalPointX(), (int) north(), client.getTopLevelWorldView());
		}
		Player me = client.getLocalPlayer();
		return me == null ? null : me.getLocalLocation();
	}

	private void detach()
	{
		if (detached)
		{
			return;
		}
		Player me = client.getLocalPlayer();
		LocalPoint here = me == null ? null : me.getLocalLocation();
		if (here != null)
		{
			northIsZ = Math.abs(client.getCameraFocalPointZ() - here.getY())
				<= Math.abs(client.getCameraFocalPointY() - here.getY());
			log.debug("Tutorial camera: focal {}, {}, {} for you at local {}, {}: north-south is {}",
				client.getCameraFocalPointX(), client.getCameraFocalPointY(), client.getCameraFocalPointZ(),
				here.getX(), here.getY(), northIsZ ? "Z" : "Y");
		}
		client.setCameraMode(FREE);
		detached = true;
		glideTo = null;
	}

	private float north()
	{
		return northIsZ ? client.getCameraFocalPointZ() : client.getCameraFocalPointY();
	}

	private void set(float x, float north)
	{
		client.setCameraFocalPointX(x);
		if (northIsZ)
		{
			client.setCameraFocalPointZ(north);
		}
		else
		{
			client.setCameraFocalPointY(north);
		}
	}

	public void release()
	{
		if (detached)
		{
			client.setCameraMode(FOLLOW);
			detached = false;
			glideTo = null;
		}
	}
}

package com.bautopilot.baautopilot.tutorial;

import com.bautopilot.baautopilot.BaAutopilotConfig;
import com.bautopilot.baautopilot.overlay.ItemHighlightOverlay;
import com.bautopilot.baautopilot.overlay.Palette;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.BooleanSupplier;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The page's inventory, in a panel beside the tutorial box: the items the moment calls for, outlined as the
 * plugin outlines them in a wave (ItemHighlightOverlay's own rules), and a right-click menu open
 * on the item the page is about, its option flashing.
 */
public class TutorialInventoryOverlay extends Overlay
{
	private static final int COLUMNS = 4;
	private static final int SLOTS = 28;
	/** The game's inventory grid: 42 x 36 cells, 36 x 32 items. */
	private static final int CELL_W = 42;
	private static final int CELL_H = 36;
	private static final int ITEM_W = 36;
	private static final int ITEM_H = 32;
	private static final Color COVER = new Color(62, 53, 41, 250);
	/** The game's menu: brown body, black title bar, white options, orange item names. */
	private static final Color MENU_BODY = new Color(93, 84, 71);
	private static final Color MENU_TITLE = new Color(0, 0, 0);
	private static final Color MENU_ITEM = new Color(255, 144, 64);
	private static final int MENU_ROW = 15;
	private static final int MENU_TITLE_H = 19;
	private static final long FLASH_MS = 1000;
	private static final long FLASH_ON_MS = 600;

	private final Client client;
	private final ItemManager itemManager;
	private final TutorialSteps steps;
	private final TutorialPilots pilots;
	private final BaAutopilotConfig config;
	/** The panel sits to its right. */
	private final TutorialBoxOverlay tutorialBox;
	private BooleanSupplier shown = () -> false;

	@Inject
	TutorialInventoryOverlay(Client client, ItemManager itemManager, TutorialSteps steps, TutorialPilots pilots,
		BaAutopilotConfig config, TutorialBoxOverlay tutorialBox)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.steps = steps;
		this.pilots = pilots;
		this.config = config;
		this.tutorialBox = tutorialBox;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public void setShown(BooleanSupplier shown)
	{
		this.shown = shown;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!shown.getAsBoolean())
		{
			return null;
		}
		TutorialSteps.Page page = steps.current();
		TutorialPilots.View view = pilots.current();
		Map<Integer, Integer> items = new LinkedHashMap<>();
		if (view != null && view.getSnapshot().getRole() != null)
		{
			// Every player carries their role's horn, and a Collector the collection bag
			items.put(Tutorials.horn(view.getSnapshot().getRole()), 1);
			if (view.getSnapshot().getRole() == com.bautopilot.baautopilot.model.Role.COLLECTOR)
			{
				items.put(net.runelite.api.gameval.ItemID.BARBASSAULT_COLL_BAG_01, 1);
			}
			items.putAll(view.getSnapshot().getInventory());
		}
		else
		{
			items.putAll(page.getItems());
		}
		TutorialSteps.Menu menu = page.getMenu();
		// The column right of the tutorial box: the role panel on top, the inventory under it
		Rectangle box = tutorialBox.getBounds();
		boolean placed = box != null && box.width > 0;
		int columnX = placed ? Math.min(box.x + box.width + GAP, client.getCanvasWidth() - COLUMN_W - 2)
			: client.getCanvasWidth() - COLUMN_W - 10;
		int columnY = placed ? box.y : 10;
		if (page.getHud() != null)
		{
			columnY = tutorialBox.drawHud(g, page.getHud(), columnX, columnY, COLUMN_W) + GAP;
		}
		if (items.isEmpty() && menu == null)
		{
			return null;
		}
		if (menu != null)
		{
			items.putIfAbsent(menu.getItemId(), 1);
		}

		// Slots in inventory order: unstackable items take one slot each
		List<int[]> slots = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			boolean stacks = stackable(e.getKey());
			int copies = stacks ? 1 : Math.max(1, e.getValue());
			for (int c = 0; c < copies && slots.size() < SLOTS; c++)
			{
				slots.add(new int[]{e.getKey(), stacks ? e.getValue() : 1, stacks ? 1 : 0});
			}
		}

		// Beside the tutorial box, only as many rows as the items fill (reported 2026-10-19: over
		// the real inventory it was hard to see)
		int rows = (slots.size() + COLUMNS - 1) / COLUMNS;
		Rectangle panel = new Rectangle(columnX, columnY, COLUMN_W, TITLE_H + rows * CELL_H + PAD);
		g.setColor(COVER);
		g.fillRect(panel.x, panel.y, panel.width, panel.height);
		g.setColor(Palette.GOLD_EDGE);
		g.drawRect(panel.x + 1, panel.y + 1, panel.width - 3, panel.height - 3);
		g.setColor(Palette.DARK_EDGE);
		g.drawRect(panel.x, panel.y, panel.width - 1, panel.height - 1);
		g.setFont(FontManager.getRunescapeBoldFont());
		shadowed(g, "Inventory", panel.x + PAD, panel.y + TITLE_H - 4, Palette.GOLD);
		int gridX = panel.x + (COLUMN_W - COLUMNS * CELL_W) / 2;
		int gridY = panel.y + TITLE_H;

		Rectangle menuSlot = null;
		for (int i = 0; i < slots.size(); i++)
		{
			int id = slots.get(i)[0];
			int quantity = slots.get(i)[1];
			boolean stacks = slots.get(i)[2] == 1;
			Rectangle r = new Rectangle(gridX + (i % COLUMNS) * CELL_W + (CELL_W - ITEM_W) / 2,
				gridY + (i / COLUMNS) * CELL_H + (CELL_H - ITEM_H) / 2, ITEM_W, ITEM_H);
			BufferedImage image = itemManager.getImage(id, quantity, stacks && quantity > 1);
			g.drawImage(image, r.x, r.y, null);
			if (view != null)
			{
				ItemHighlightOverlay.draw(g, itemManager, id, quantity, r,
					ItemHighlightOverlay.highlight(id, view.getInstruction(), view.getSnapshot(), false), config);
			}
			if (menu != null && id == menu.getItemId() && menuSlot == null)
			{
				menuSlot = r;
			}
		}
		if (menu != null && menuSlot != null)
		{
			menu(g, menu, menuSlot);
		}
		return null;
	}

	private static final int PAD = 6;
	private static final int TITLE_H = 20;
	private static final int GAP = 8;
	/** The right-hand column's width: the role panel's call text fits, the inventory grid is centred. */
	private static final int COLUMN_W = 230;

	/** The menu as the game draws it, opened beside the item (not over it); the page's option flashes. */
	private void menu(Graphics2D g, TutorialSteps.Menu menu, Rectangle on)
	{
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = g.getFontMetrics();
		String name = name(menu.getItemId());
		int width = fm.stringWidth("Choose Option");
		for (String option : menu.getOptions())
		{
			width = Math.max(width, fm.stringWidth(option + " " + name));
		}
		width += 8;
		int height = MENU_TITLE_H + menu.getOptions().size() * MENU_ROW + 3;
		// Beside the item so it stays in view (left of it when there's no room on the right)
		int x = on.x + on.width + 6;
		if (x + width > client.getCanvasWidth() - 2)
		{
			x = Math.max(2, on.x - width - 6);
		}
		int y = Math.max(2, Math.min(on.y - 2, client.getCanvasHeight() - height - 2));
		g.setColor(MENU_BODY);
		g.fillRect(x, y, width, height);
		g.setColor(MENU_TITLE);
		g.fillRect(x + 1, y + 1, width - 2, MENU_TITLE_H - 3);
		g.drawRect(x, y, width - 1, height - 1);
		g.setColor(MENU_BODY);
		g.drawString("Choose Option", x + 3, y + MENU_TITLE_H - 5);
		boolean flash = System.currentTimeMillis() % FLASH_MS < FLASH_ON_MS;
		for (int i = 0; i < menu.getOptions().size(); i++)
		{
			int rowY = y + MENU_TITLE_H + i * MENU_ROW;
			String option = menu.getOptions().get(i);
			boolean pick = i == menu.getPick();
			if (pick && flash)
			{
				g.setColor(Palette.fill(Palette.GOLD, 90));
				g.fillRect(x + 1, rowY, width - 2, MENU_ROW);
			}
			int base = rowY + MENU_ROW - 3;
			shadowed(g, option, x + 3, base, pick && flash ? Palette.GOLD : Color.WHITE);
			shadowed(g, name, x + 3 + fm.stringWidth(option + " "), base, MENU_ITEM);
		}
	}

	private boolean stackable(int id)
	{
		ItemComposition item = itemManager.getItemComposition(id);
		return item != null && item.isStackable();
	}

	private String name(int id)
	{
		ItemComposition item = itemManager.getItemComposition(id);
		return item == null ? "" : item.getName();
	}

	private static void shadowed(Graphics2D g, String text, int x, int baseline, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, baseline + 1);
		g.setColor(color);
		g.drawString(text, x, baseline);
	}
}

package com.bautopilot.baautopilot.tutorial;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * Where the tutorial places things, in lobby room 1's own tiles: x 0-7 from the west wall, y 0-7
 * from the south wall. The plugin reads only the bundled tutorial-layout.json; a development tool
 * (test sources only) can hand in an edited copy through {@link #setDevSource}.
 */
@Slf4j
public class TutorialLayout
{
	/** Room 1's south-west tile: room (0, 0). */
	public static final int ORIGIN_X = 2576;
	public static final int ORIGIN_Y = 5291;
	public static final String RESOURCE = "tutorial-layout.json";

	/** An edited layout from a development tool: its JSON, and a number that changes on every edit. */
	public interface DevSource
	{
		String json();

		long version();
	}

	private static volatile DevSource devSource;

	/** Item models' own height is unreliable (inventory models are posed for the icon): a fixed one. */
	public static final int ITEM_LABEL_HEIGHT = 60;

	/** A lobby room's south-west tile: its room (0, 0). */
	public static class Corner
	{
		public int x;
		public int y;
	}

	public static class Npc
	{
		public String key;
		/** Lobby room (1-10) the x / y are in. */
		public int room = 1;
		public int npcId;
		public int animation = -1;
		public int x;
		public int y;
		public int orientation;
		/** Label height above the floor; -1: just above the model. */
		public int labelHeight = -1;
		/** Size in percent of the real thing. */
		public int scale = 100;
		/** Worn models merged in (a bow in the hands): rigged like a player's, so they move with it. */
		public List<Attach> attach = new ArrayList<>();
	}

	/** A worn item's model (an item's male model in the game cache), with its recolours. */
	public static class Attach
	{
		public int modelId;
		public short[] recolorFrom;
		public short[] recolorTo;
	}

	/** A bare model from the game cache (scenery such as the runner trap), with its recolours. */
	public static class Shape
	{
		public String key;
		public int room = 1;
		public int modelId;
		public short[] recolorFrom;
		public short[] recolorTo;
		public int animation = -1;
		/** Play the animation all the time; otherwise only on cue (the trap springing). */
		public boolean loop;
		/** Raise the model this much (128 is a tile's width). */
		public int lift;
		/**
		 * Raise it until its lowest point rests on the floor: for scenery built to sit in a dip in
		 * the arena's ground (the Healer spring), which would otherwise sink below the lobby floor.
		 */
		public boolean onFloor;
		public int x;
		public int y;
		public int orientation;
		public int labelHeight = ITEM_LABEL_HEIGHT;
	}

	public static class Item
	{
		public String key;
		public int room = 1;
		public int itemId;
		public int x;
		public int y;
		public int orientation;
		/** Label height above the floor. */
		public int labelHeight = ITEM_LABEL_HEIGHT;
	}

	public static class Tile
	{
		public String key;
		public int room = 1;
		public int x;
		public int y;
	}

	/**
	 * Room corners by room number. Rooms not listed are found from the game's room objects
	 * (see TutorialScene); listing one here pins it.
	 */
	public Map<String, Corner> rooms = new HashMap<>();
	public List<Npc> npcs = new ArrayList<>();
	public List<Item> items = new ArrayList<>();
	public List<Shape> models = new ArrayList<>();
	public List<Tile> tiles = new ArrayList<>();

	/** A room 1 tile as a world tile. */
	public static WorldPoint world(int x, int y)
	{
		return new WorldPoint(ORIGIN_X + x, ORIGIN_Y + y, 0);
	}

	/** The listed corner of a room; null when it isn't listed. */
	public Corner corner(int room)
	{
		return rooms.get(String.valueOf(room));
	}

	public Tile tile(String key)
	{
		return tiles.stream().filter(t -> key.equals(t.key)).findFirst().orElse(null);
	}

	/**
	 * Entries the bundled layout has and this one doesn't (by key) are added, so props new to the
	 * tutorial still show up in a layout file edited before they existed.
	 */
	public TutorialLayout withMissing(TutorialLayout from)
	{
		from.npcs.stream().filter(n -> npcs.stream().noneMatch(m -> m.key.equals(n.key))).forEach(npcs::add);
		from.items.stream().filter(i -> items.stream().noneMatch(m -> m.key.equals(i.key))).forEach(items::add);
		from.models.stream().filter(i -> models.stream().noneMatch(m -> m.key.equals(i.key))).forEach(models::add);
		from.tiles.stream().filter(t -> tile(t.key) == null).forEach(tiles::add);
		from.rooms.forEach(rooms::putIfAbsent);
		return this;
	}

	public static TutorialLayout parse(Gson gson, Reader json)
	{
		TutorialLayout layout = gson.fromJson(json, TutorialLayout.class);
		return layout == null ? new TutorialLayout() : layout;
	}

	/** The bundled layout. */
	public static TutorialLayout bundled(Gson gson)
	{
		try (InputStream in = TutorialLayout.class.getResourceAsStream(RESOURCE))
		{
			return parse(gson, new InputStreamReader(in, StandardCharsets.UTF_8));
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Bundled tutorial layout unreadable", e);
			return new TutorialLayout();
		}
	}

	/** Set by a development tool to place an edited layout; null returns to the bundled one. */
	public static void setDevSource(DevSource source)
	{
		devSource = source;
	}

	/** Changes whenever a development tool's layout is edited; 0 for the bundled one. */
	public static long version()
	{
		DevSource source = devSource;
		return source == null ? 0 : source.version();
	}

	/** The development tool's layout over the bundled one, or the bundled one. */
	public static TutorialLayout load(Gson gson)
	{
		DevSource source = devSource;
		if (source == null)
		{
			return bundled(gson);
		}
		try
		{
			TutorialLayout layout = gson.fromJson(source.json(), TutorialLayout.class);
			return (layout == null ? new TutorialLayout() : layout).withMissing(bundled(gson));
		}
		catch (RuntimeException e)
		{
			log.warn("Edited tutorial layout unreadable, using the bundled one", e);
			return bundled(gson);
		}
	}
}

package com.bautopilot.baautopilot.tutorial;

import com.google.gson.Gson;
import com.google.gson.TypeAdapter;
import com.google.gson.reflect.TypeToken;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonWriter;
import java.awt.Color;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * The tutorials' pages, read once from tutorial-pages.json (tutorial name to its pages); each
 * page's autopilot box comes from TutorialSituations.
 */
@Singleton
public class TutorialLibrary
{
	private final Gson gson;
	private volatile Map<Tutorial, List<TutorialSteps.Page>> pages;

	@Inject
	public TutorialLibrary(Gson gson)
	{
		this.gson = gson.newBuilder().registerTypeAdapter(Color.class, new ColorAdapter().nullSafe()).create();
	}

	public List<TutorialSteps.Page> pages(Tutorial tutorial)
	{
		if (pages == null)
		{
			pages = load();
		}
		return pages.get(tutorial);
	}

	private Map<Tutorial, List<TutorialSteps.Page>> load()
	{
		Map<String, List<TutorialSteps.Page>> read;
		try (Reader in = new InputStreamReader(TutorialLibrary.class.getResourceAsStream("tutorial-pages.json"),
			StandardCharsets.UTF_8))
		{
			read = gson.fromJson(in, new TypeToken<Map<String, List<TutorialSteps.Page>>>()
			{
			}.getType());
		}
		catch (IOException e)
		{
			throw new IllegalStateException("tutorial-pages.json", e);
		}
		Map<Tutorial, List<TutorialSteps.Page>> out = new EnumMap<>(Tutorial.class);
		for (Tutorial tutorial : Tutorial.values())
		{
			List<TutorialSteps.Page> list = new ArrayList<>();
			for (TutorialSteps.Page page : read.get(tutorial.name()))
			{
				list.add(page.toBuilder().pilot(TutorialSituations.forPage(tutorial, list.size())).build());
			}
			out.put(tutorial, Collections.unmodifiableList(list));
		}
		return out;
	}

	/** Colours as "#AARRGGBB". */
	static final class ColorAdapter extends TypeAdapter<Color>
	{
		@Override
		public void write(JsonWriter out, Color c) throws IOException
		{
			if (c == null)
			{
				out.nullValue();
				return;
			}
			out.value(String.format("#%08X", c.getRGB()));
		}

		@Override
		public Color read(JsonReader in) throws IOException
		{
			String s = in.nextString();
			return new Color((int) Long.parseLong(s.substring(1), 16), true);
		}
	}
}

package com.bautopilot.baautopilot.tutorial;

import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.overlay.Palette;
import com.google.gson.Gson;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A page's arena map, over the middle of the game view, north up: the floor the recordings saw
 * walked, and the arena's landmarks (spawn caves, traps, launchers and hoppers, the Healer spring,
 * dispensers, logs and hammer; in wave 10 the craters, mushrooms and the Queen). The map data is
 * arena-maps.json, built from recorded rounds.
 */
@Slf4j
public class TutorialMapOverlay extends Overlay
{
	/** One arena: floor tiles (region x, y) and its landmarks. */
	static class ArenaMap
	{
		List<int[]> floor = new ArrayList<>();
		List<Element> elements = new ArrayList<>();
	}

	static class Element
	{
		String kind;
		String label;
		double x;
		double y;
		/** Width and height in tiles, for areas (the team's start). */
		int w;
		int h;
	}

	private static final Color PANEL = new Color(30, 26, 20, 235);
	private static final Color EDGE_DARK = new Color(14, 12, 9);
	private static final Color EDGE_GOLD = new Color(146, 118, 66);
	private static final Color FLOOR = new Color(122, 104, 74);
	private static final Color TEXT = new Color(240, 230, 205);
	private static final Color MUTED = new Color(170, 158, 130);
	private static final Color TRAP = new Color(205, 160, 90);
	private static final Color LAUNCHER = new Color(150, 150, 160);
	private static final Color HOPPER = new Color(150, 110, 60);
	private static final Color SPRING = new Color(90, 170, 255);
	private static final Color POISON = new Color(110, 220, 90);
	private static final Color LAVA = new Color(255, 120, 40);
	private static final Color MUSHROOM = new Color(200, 190, 175);
	private static final Color LOGS = new Color(170, 120, 70);
	private static final Color HAMMER = new Color(190, 190, 200);
	private static final int PAD = 14;
	private static final Color START = new Color(255, 200, 80);
	private static final Color START_FILL = new Color(255, 200, 80, 60);
	private static final int TITLE_H = 46;
	private static final Color TITLE_BAND = new Color(62, 53, 41);
	private static final Color TITLE_GOLD = new Color(255, 152, 31);
	private static final Color HILL = new Color(160, 140, 100);
	private static final Color HILL_EDGE = new Color(190, 170, 125);
	/** Tiles from a launcher to its hill's edge. */
	private static final int HILL_RADIUS = 3;
	/** Share of the game view the map may take. */
	private static final double FIT = 0.72;

	private final Client client;
	private final TutorialSteps steps;
	private final Map<String, ArenaMap> maps;
	private final net.runelite.client.game.SpriteManager sprites;
	private BooleanSupplier shown = () -> false;

	@Inject
	TutorialMapOverlay(Client client, TutorialSteps steps, Gson gson, net.runelite.client.game.SpriteManager sprites)
	{
		this.client = client;
		this.steps = steps;
		this.maps = load(gson);
		this.sprites = sprites;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public void setShown(BooleanSupplier shown)
	{
		this.shown = shown;
	}

	private static Map<String, ArenaMap> load(Gson gson)
	{
		try (InputStream in = TutorialMapOverlay.class.getResourceAsStream("arena-maps.json"))
		{
			Map<String, ArenaMap> m = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8),
				new com.google.gson.reflect.TypeToken<Map<String, ArenaMap>>()
				{
				}.getType());
			return m == null ? Collections.emptyMap() : m;
		}
		catch (Exception e)
		{
			log.warn("Arena maps unreadable", e);
			return Collections.emptyMap();
		}
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		String which = shown.getAsBoolean() ? steps.current().getMap() : null;
		ArenaMap map = which == null ? null : maps.get(which);
		if (map == null || map.floor.isEmpty())
		{
			return null;
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int minX = Integer.MAX_VALUE;
		int maxX = Integer.MIN_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxY = Integer.MIN_VALUE;
		for (int[] t : map.floor)
		{
			minX = Math.min(minX, t[0]);
			maxX = Math.max(maxX, t[0]);
			minY = Math.min(minY, t[1]);
			maxY = Math.max(maxY, t[1]);
		}
		int tilesX = maxX - minX + 1;
		int tilesY = maxY - minY + 1;
		int viewW = client.getViewportWidth();
		int viewH = client.getViewportHeight();
		int legend = 22;
		int tile = (int) Math.max(4, Math.min(14, Math.min(viewW * FIT / tilesX, (viewH * FIT - legend - TITLE_H) / tilesY)));
		int w = tilesX * tile + 2 * PAD;
		int h = TITLE_H + tilesY * tile + 2 * PAD + legend;
		int left = client.getViewportXOffset() + (viewW - w) / 2;
		int top = client.getViewportYOffset() + (viewH - h) / 2;

		g.setColor(PANEL);
		g.fillRect(left, top, w, h);
		g.setColor(EDGE_GOLD);
		g.drawRect(left + 1, top + 1, w - 3, h - 3);
		g.setColor(EDGE_DARK);
		g.drawRect(left, top, w - 1, h - 1);
		title(g, which, left, top, w);

		int ox = left + PAD;
		int oy = top + TITLE_H + PAD;
		final int fMinX = minX;
		final int fMaxY = maxY;
		java.util.function.DoubleUnaryOperator sx = x -> ox + (x - fMinX) * tile;
		java.util.function.DoubleUnaryOperator sy = y -> oy + (fMaxY - y) * tile;

		g.setColor(FLOOR);
		for (int[] t : map.floor)
		{
			g.fillRect((int) sx.applyAsDouble(t[0]), (int) sy.applyAsDouble(t[1]), tile, tile);
		}

		g.setFont(FontManager.getRunescapeSmallFont());
		Set<String> labelled = new HashSet<>();
		boolean craters = false;
		for (Element e : map.elements)
		{
			int cx = (int) Math.round(sx.applyAsDouble(e.x) + tile / 2.0);
			int cy = (int) Math.round(sy.applyAsDouble(e.y) + tile / 2.0);
			Color c = colour(e.kind);
			int r;
			switch (e.kind)
			{
				case "start":
				{
					// The team's starting tiles: a dashed gold box
					int bw = Math.max(1, e.w) * tile;
					int bh = Math.max(1, e.h) * tile;
					int bx = cx - bw / 2;
					int by = cy - bh / 2;
					g.setColor(START_FILL);
					g.fillRoundRect(bx, by, bw, bh, 6, 6);
					g.setColor(START);
					g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 1f, new float[]{4f, 3f}, 0f));
					g.drawRoundRect(bx, by, bw, bh, 6, 6);
					g.setStroke(new BasicStroke(1f));
					centred(g, e.label, cx, by - 4, START);
					continue;
				}
				case "hill":
					// A raised mound about three tiles round its launcher, under everything else
					r = HILL_RADIUS * tile;
					g.setColor(HILL);
					g.fillOval(cx - r, cy - r, 2 * r, 2 * r);
					g.setColor(HILL_EDGE);
					g.setStroke(new BasicStroke(1.5f));
					g.drawOval(cx - r, cy - r, 2 * r, 2 * r);
					if (labelled.add(e.kind))
					{
						centred(g, "Hill (safer)", cx, cy + r + 12, TEXT);
					}
					continue;
				case "poison":
				case "lava":
				case "mushroom":
					craters = true;
					dot(g, cx, cy, Math.max(3, tile / 2), c);
					continue;
				case "trap":
				case "hopper":
				case "logs":
				case "hammer":
					r = Math.max(3, tile / 2);
					g.setColor(Color.BLACK);
					g.fillRect(cx - r - 1, cy - r - 1, 2 * r + 2, 2 * r + 2);
					g.setColor(c);
					g.fillRect(cx - r, cy - r, 2 * r, 2 * r);
					break;
				default:
					if (e.kind.startsWith("disp-"))
					{
						r = Math.max(4, tile / 2 + 1);
						g.setColor(Color.BLACK);
						g.fillRect(cx - r - 1, cy - r - 1, 2 * r + 2, 2 * r + 2);
						g.setColor(c);
						g.fillRect(cx - r, cy - r, 2 * r, 2 * r);
						centred(g, e.label, cx, cy + 4, Color.BLACK);
						if (labelled.add("disp"))
						{
							// One label for the row
							shadowed(g, "Dispensers", cx - r, cy + r + 12, TEXT);
						}
						continue;
					}
					r = e.kind.startsWith("spawn-") || "queen".equals(e.kind) || "spring".equals(e.kind)
						? Math.max(5, tile) : Math.max(4, tile * 2 / 3);
					dot(g, cx, cy, r, c);
					break;
			}
			// Each launcher and each trap is named; the hopper shares its launcher's label (they're
			// side by side), and the second log pile goes unnamed
			if ("launcher".equals(e.kind))
			{
				centred(g, "Egg launcher + hopper", cx + tile / 2, cy - r - 4, TEXT);
			}
			else if ("trap".equals(e.kind))
			{
				centred(g, e.label, cx, cy - r - 4, TEXT);
			}
			else if (!"hopper".equals(e.kind) && e.label != null && !e.label.isEmpty() && labelled.add(e.kind))
			{
				centred(g, e.label, cx, cy - r - 4, TEXT);
			}
		}

		// Compass, and a legend for the unlabelled dots
		centred(g, "N", left + w - PAD - 4, top + TITLE_H + PAD + 10, MUTED);
		g.setColor(MUTED);
		g.setStroke(new BasicStroke(2f));
		g.drawLine(left + w - PAD - 4, top + TITLE_H + PAD + 14, left + w - PAD - 4, top + TITLE_H + PAD + 28);
		int ly = top + h - PAD;
		int lx = left + PAD;
		if (craters)
		{
			lx = legend(g, lx, ly, POISON, "Poison crater");
			lx = legend(g, lx, ly, LAVA, "Lava crater");
			legend(g, lx, ly, MUSHROOM, "Petrified mushroom");
		}
		return null;
	}

	/** The title band: the BA badge, "Barbarian Assault" small above the arena's name in gold. */
	private void title(Graphics2D g, String which, int left, int top, int w)
	{
		g.setColor(TITLE_BAND);
		g.fillRect(left + 2, top + 2, w - 4, TITLE_H - 2);
		g.setColor(EDGE_GOLD);
		g.drawLine(left + 2, top + TITLE_H, left + w - 3, top + TITLE_H);
		String name = "1-9".equals(which) ? "The arena: waves 1 to 9" : "The arena: wave 10";
		g.setFont(FontManager.getRunescapeBoldFont().deriveFont(20f));
		FontMetrics big = g.getFontMetrics();
		java.awt.image.BufferedImage badge = sprites.getSprite(BaIcon.SPRITE, 0);
		int badgeSize = TITLE_H - 8;
		int textW = big.stringWidth(name);
		int blockW = (badge == null ? 0 : badgeSize + 8) + textW;
		int x = left + (w - blockW) / 2;
		if (badge != null)
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.drawImage(badge, x, top + 4, badgeSize, badgeSize, null);
			x += badgeSize + 8;
		}
		g.setFont(FontManager.getRunescapeSmallFont());
		shadowed(g, "BARBARIAN ASSAULT", x, top + 15, MUTED);
		g.setFont(FontManager.getRunescapeBoldFont().deriveFont(20f));
		shadowed(g, name, x, top + TITLE_H - 8, TITLE_GOLD);
		g.setFont(FontManager.getRunescapeSmallFont());
	}

	private int legend(Graphics2D g, int x, int y, Color c, String text)
	{
		dot(g, x + 4, y - 4, 4, c);
		shadowed(g, text, x + 12, y, TEXT);
		return x + 12 + g.getFontMetrics().stringWidth(text) + 14;
	}

	private static Color colour(String kind)
	{
		switch (kind)
		{
			case "spawn-fighter":
				return Tutorials.FIGHTER;
			case "spawn-ranger":
				return Tutorials.RANGER;
			case "spawn-runner":
				return Tutorials.RUNNER;
			case "spawn-healer":
				return Tutorials.HEALER;
			case "queen":
				return Tutorials.QUEEN;
			case "launcher":
				return LAUNCHER;
			case "hopper":
				return HOPPER;
			case "trap":
				return TRAP;
			case "spring":
				return SPRING;
			case "disp-attacker":
				return Palette.role(Role.ATTACKER);
			case "disp-defender":
				return Palette.role(Role.DEFENDER);
			case "disp-healer":
				return Palette.role(Role.HEALER);
			case "disp-collector":
				return Palette.role(Role.COLLECTOR);
			case "poison":
				return POISON;
			case "lava":
				return LAVA;
			case "mushroom":
				return MUSHROOM;
			case "logs":
				return LOGS;
			case "hammer":
				return HAMMER;
			default:
				return TEXT;
		}
	}

	private static void dot(Graphics2D g, int x, int y, int r, Color c)
	{
		g.setColor(Color.BLACK);
		g.fillOval(x - r - 1, y - r - 1, 2 * r + 2, 2 * r + 2);
		g.setColor(c);
		g.fillOval(x - r, y - r, 2 * r, 2 * r);
	}

	private static void centred(Graphics2D g, String text, int x, int baseline, Color c)
	{
		FontMetrics fm = g.getFontMetrics();
		shadowed(g, text, x - fm.stringWidth(text) / 2, baseline, c);
	}

	private static void shadowed(Graphics2D g, String text, int x, int baseline, Color c)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, baseline + 1);
		g.setColor(c);
		g.drawString(text, x, baseline);
	}
}

package com.bautopilot.baautopilot.tutorial;

import java.util.List;
import net.runelite.api.coords.LocalPoint;

/** A point part way along a line through several points, by distance, for camera tours. */
public final class TutorialPath
{
	private TutorialPath()
	{
	}

	/** The point {@code fraction} (0 to 1) of the way along the line through {@code points}. */
	public static LocalPoint along(List<LocalPoint> points, double fraction)
	{
		double total = 0;
		for (int i = 1; i < points.size(); i++)
		{
			total += length(points.get(i - 1), points.get(i));
		}
		double left = Math.max(0, Math.min(1, fraction)) * total;
		for (int i = 1; i < points.size(); i++)
		{
			LocalPoint a = points.get(i - 1);
			LocalPoint b = points.get(i);
			double step = length(a, b);
			if (left <= step && step > 0)
			{
				double f = left / step;
				return new LocalPoint((int) Math.round(a.getX() + (b.getX() - a.getX()) * f),
					(int) Math.round(a.getY() + (b.getY() - a.getY()) * f), a.getWorldView());
			}
			left -= step;
		}
		return points.get(points.size() - 1);
	}

	private static double length(LocalPoint a, LocalPoint b)
	{
		return Math.hypot(b.getX() - a.getX(), b.getY() - a.getY());
	}
}

package com.bautopilot.baautopilot.tutorial;

import com.bautopilot.baautopilot.plan.Instruction;
import com.bautopilot.baautopilot.plan.Planner;
import com.bautopilot.baautopilot.plan.Settings;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.IdentityHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;

/**
 * The current tutorial page's autopilot box: the planner's instruction for the page's situation.
 * The plugin's own box shows it in place of the live one while the tutorial runs, so it sits
 * where the box always is and moving it moves the real one.
 */
@Singleton
public class TutorialPilots
{
	/** Default planner settings, so a page shows what its text describes whatever the config. */
	private static final Settings SETTINGS = Settings.builder().build();
	private static final long TICK_MS = 600;

	/** An instruction and the moment it is for; {@code highlight} when the page talks about the box. */
	@Value
	public static class View
	{
		Instruction instruction;
		Snapshot snapshot;
		boolean highlight;
	}

	private final TutorialSteps steps;
	private final Planner planner = new Planner();
	/** Each page's instruction, planned once. Client thread. */
	private final Map<TutorialSteps.Pilot, Instruction> planned = new IdentityHashMap<>();

	@Inject
	TutorialPilots(TutorialSteps steps)
	{
		this.steps = steps;
	}

	/**
	 * The current page's box, as if its step had just begun; only the call timer moves, running
	 * down from the situation's value. Null when the page has no box.
	 */
	public View current()
	{
		TutorialSteps.Page page = steps.current();
		TutorialSteps.Pilot pilot = page.getPilot();
		if (pilot == null)
		{
			return null;
		}
		Instruction ins = planned.computeIfAbsent(pilot, p -> planner.plan(p.getSituation(), SETTINGS));
		Snapshot s = pilot.getSituation();
		int ticks = s.getTicksToCallChange();
		if (ticks > 0)
		{
			long elapsed = steps.elapsed() / TICK_MS;
			s = s.toBuilder().ticksToCallChange(ticks - (int) (elapsed % (ticks + 1))).build();
		}
		return new View(ins, s, page.isHighlightBox());
	}
}

package com.bautopilot.baautopilot.tutorial;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
