				body.add(Box.createVerticalStrut(5));
				body.add(number("queenEggBatch", "Queen yellow batch", 1, 8, BaAutopilotConfig::queenEggBatch,
					"Yellow eggs to gather before passing the batch to one Healer"));
				body.add(Box.createVerticalStrut(5));
