		general.addContent(toggle("queenStack", "Team stacks at Queen cannon", BaAutopilotConfig::queenStack));
		general.addContent(toggle("compactHud", "Compact instruction box", BaAutopilotConfig::compactHud));
		general.addContent(toggle("showPath", "Show walking route", BaAutopilotConfig::showPath));
		general.addContent(toggle("highlightTarget", "Highlight targets", BaAutopilotConfig::highlightTarget));
		general.addContent(toggle("highlightItems", "Highlight inventory items", BaAutopilotConfig::highlightItems));
		general.addContent(toggle("debugPriorities", "Show debug overlays", BaAutopilotConfig::debugPriorities));
		return general;
	}

	private ToggleSwitch toggle(String key, String text, Function<BaAutopilotConfig, Boolean> read)
	{
		ToggleSwitch control = new ToggleSwitch(text);
		control.setText("<html><body style='width:140px'>" + Style.escape(text) + "</body></html>");
		control.setMargin(new Insets(3, 0, 3, 0));
		control.setHorizontalAlignment(SwingConstants.LEFT);
		control.setMaximumSize(new Dimension(Integer.MAX_VALUE, control.getPreferredSize().height));
		control.setName(key);
		control.getAccessibleContext().setAccessibleName(text);
		control.addActionListener(event -> option(key, control.isSelected()));
		readers.add(config -> control.setSelected(read.apply(config)));
		return control;
	}

	private <E> JComponent choice(String key, String text, E[] values, Function<BaAutopilotConfig, E> read)
	{
		StyledComboBox<E> control = new StyledComboBox<>(values);
		control.setName(key);
		control.getAccessibleContext().setAccessibleName(text);
		control.setAlignmentX(LEFT_ALIGNMENT);
		control.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		control.addActionListener(event -> option(key, control.getSelectedItem()));
		readers.add(config -> control.setSelectedItem(read.apply(config)));
		JPanel field = column();
		field.add(label(text));
		field.add(Box.createVerticalStrut(3));
		field.add(control);
		return field;
	}

	private JComponent number(String key, String text, int min, int max, Function<BaAutopilotConfig, Integer> read, String hint)
	{
		JSpinner control = new JSpinner(new SpinnerNumberModel(min, min, max, 1));
		control.setName(key);
		control.setToolTipText(hint);
		control.getAccessibleContext().setAccessibleName(text);
		control.setPreferredSize(new Dimension(58, 25));
		control.setBorder(new LineBorder(Style.BORDER));
		control.setBackground(Style.SURFACE_RAISED);
		JSpinner.NumberEditor editor = new JSpinner.NumberEditor(control, "0");
		control.setEditor(editor);
		editor.getTextField().setFont(FontManager.getRunescapeSmallFont());
		editor.getTextField().setForeground(Style.TEXT);
		editor.getTextField().setBackground(Style.SURFACE_RAISED);
		editor.getTextField().setCaretColor(Style.TEXT);
		editor.getTextField().setBorder(new EmptyBorder(1, 3, 1, 3));
		control.addChangeListener(event -> option(key, control.getValue()));
		readers.add(config -> control.setValue(Math.max(min, Math.min(max, read.apply(config)))));
		JPanel row = Style.transparentPanel(new BorderLayout(6, 0));
		JLabel caption = label(text);
		caption.setLabelFor(control);
		caption.setToolTipText(hint);
		row.add(caption, BorderLayout.CENTER);
		row.add(control, BorderLayout.EAST);
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 25));
		return row;
	}

	private void option(String key, Object value)
	{
		if (!syncing && value != null) onOption.accept(key, value);
	}

	private static CollapsibleSection advanced(String name, String title)
	{
		CollapsibleSection section = new CollapsibleSection(title, "");
		section.setName(name);
		section.setExpanded(false);
		return section;
	}

	private static JLabel label(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Style.SOFT_TEXT);
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	private static JPanel column()
	{
		JPanel panel = Style.transparentPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	/** The game's Barbarian Assault icon, once loaded: in the header (24 px) and the tutorial card (20 px). */
	public void setBaIcon(BufferedImage icon)
	{
		header.getIconLabel().setIcon(new ImageIcon(scaled(icon, 24)));
		tutorialBadge.setIcon(new ImageIcon(scaled(icon, 20)));
		revalidate();
		repaint();
	}

	public static BufferedImage scaled(BufferedImage icon, int size)
	{
		BufferedImage out = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g.drawImage(icon, 0, 0, size, size, null);
		g.dispose();
		return out;
	}

	/** Painted BA glyph shared by the sidebar button and header. */
	public static BufferedImage navIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(150, 40, 35));
		g.fillRoundRect(1, 1, 14, 14, 5, 5);
		g.setColor(Style.GOLD);
		g.setStroke(new BasicStroke(1.4f));
		g.drawRoundRect(1, 1, 14, 14, 5, 5);
		g.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD, 11f));
		g.drawString("BA", 3, 12);
		g.dispose();
		return image;
	}
}

package com.bautopilot.baautopilot.ui.kit;

import com.bautopilot.baautopilot.ui.kit.components.ModernScrollBarUI;
import com.bautopilot.baautopilot.ui.kit.components.RoundedPanel;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.LayoutManager;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import net.runelite.client.ui.FontManager;

/**
 * Design tokens and tiny factories for the FreeArcanes panel look:
 * dark layered surfaces, rounded cards and rows, small-caps eyebrows,
 * accent pills and a slim scrollbar.
 *
 * The visual language originates in Slayer Best in Bank (beta 2 panel)
 * and is shared verbatim so sibling plugins render as one family.
 */
public final class Style
{
	// Surfaces, darkest to lightest. PANEL_BG is the panel root, SURFACE the
	// standard card, SURFACE_RAISED for tiles/hover states layered on a card,
	// ROW for list rows sitting directly on PANEL_BG.
	public static final Color PANEL_BG = new Color(25, 26, 29);
	public static final Color SURFACE = new Color(31, 33, 37);
	public static final Color SURFACE_RAISED = new Color(36, 38, 43);
	public static final Color ROW = new Color(34, 36, 40);
	public static final Color ROW_HOVER = new Color(41, 44, 49);
	public static final Color BORDER = new Color(50, 53, 59);

	// Text, brightest to faintest.
	public static final Color TEXT = new Color(238, 239, 241);
	public static final Color SOFT_TEXT = new Color(193, 196, 201);
	public static final Color MUTED_TEXT = new Color(132, 136, 144);
	public static final Color FAINT_TEXT = new Color(96, 100, 108);
	public static final Color HEADING_TEXT = new Color(165, 165, 165);

	// Accents. GOLD marks the primary pick, TEAL secondary info/locations,
	// BLUE banked/neutral counts, SUCCESS/WARNING/DANGER carry status.
	public static final Color GOLD = new Color(239, 181, 74);
	public static final Color TEAL = new Color(72, 201, 190);
	public static final Color BLUE = new Color(100, 157, 235);
	public static final Color SUCCESS = new Color(97, 194, 123);
	public static final Color WARNING = new Color(231, 166, 74);
	public static final Color DANGER = new Color(220, 103, 93);

	public static final int CARD_RADIUS = 12;
	public static final int ROW_RADIUS = 9;
	// Hard wrap width for body copy inside a card at default panel width.
	public static final int WRAP_WIDTH = 178;

	private Style()
	{
	}

	/** Standard card: SURFACE fill, CARD_RADIUS corners, 1px BORDER stroke. */
	public static RoundedPanel card()
	{
		return card(SURFACE);
	}

	public static RoundedPanel card(Color fill)
	{
		RoundedPanel panel = new RoundedPanel(fill, CARD_RADIUS, BORDER);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
		return panel;
	}

	/** Borderless list row: ROW fill, ROW_RADIUS corners. */
	public static RoundedPanel rowCard()
	{
		RoundedPanel panel = new RoundedPanel(ROW, ROW_RADIUS, null);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
		return panel;
	}

	public static JPanel transparentPanel()
	{
		JPanel panel = new JPanel();
		panel.setOpaque(false);
		return panel;
	}

	public static JPanel transparentPanel(LayoutManager layout)
	{
		JPanel panel = new JPanel(layout);
		panel.setOpaque(false);
		return panel;
	}

	/** Small-caps eyebrow label ("CURRENT TASK", "LOADOUT", ...). */
	public static JLabel smallCaps(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
		label.setForeground(color);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/** Small body-copy label with a hard wrap width in pixels. */
	public static JLabel wrappedLabel(String text, Color color, int width)
	{
		JLabel label = new JLabel(
			"<html><body style='width:" + width + "px'>" + escape(text) + "</body></html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/** Inline "✓ Name" / "! Name" readiness check. */
	public static JLabel checkLabel(String name, boolean ok)
	{
		JLabel label = new JLabel((ok ? "✓ " : "! ") + name);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ok ? SUCCESS : WARNING);
		return label;
	}

	/**
	 * Applies the slim borderless scrollbar to a scroll pane. PluginPanel
	 * subclasses call this with their protected getScrollPane() result.
	 */
	public static void styleScrollPane(JScrollPane scrollPane)
	{
		if (scrollPane == null)
		{
			return;
		}
		scrollPane.setBorder(null);
		scrollPane.setOpaque(false);
		scrollPane.getViewport().setOpaque(false);
		scrollPane.getViewport().setBackground(PANEL_BG);
		JScrollBar bar = scrollPane.getVerticalScrollBar();
		bar.setUI(new ModernScrollBarUI());
		bar.setPreferredSize(new Dimension(7, 0));
		bar.setMinimumSize(new Dimension(7, 0));
		bar.setUnitIncrement(18);
		bar.setBlockIncrement(90);
		bar.setOpaque(false);
	}

	/**
	 * Dark surface tinted toward an accent — the attention-grabbing card
	 * background (e.g. the warm amber behind an emphasized warning).
	 * Amount around 0.12 keeps it clearly dark but visibly colored.
	 */
	public static Color tinted(Color accent, float amount)
	{
		return new Color(
			PANEL_BG.getRed() + Math.round((accent.getRed() - PANEL_BG.getRed()) * amount),
			PANEL_BG.getGreen() + Math.round((accent.getGreen() - PANEL_BG.getGreen()) * amount),
			PANEL_BG.getBlue() + Math.round((accent.getBlue() - PANEL_BG.getBlue()) * amount));
	}

	public static Color withAlpha(Color color, int alpha)
	{
		return new Color(
			color.getRed(),
			color.getGreen(),
			color.getBlue(),
			Math.max(0, Math.min(255, alpha)));
	}

	public static String shorten(String value, int max)
	{
		if (value == null || value.length() <= max)
		{
			return value == null ? "" : value;
		}
		return value.substring(0, Math.max(1, max - 1)) + "…";
	}

	public static String escape(String value)
	{
		if (value == null)
		{
			return "";
		}
		return value
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;")
			.replace("\"", "&quot;")
			.replace("'", "&#39;");
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import com.bautopilot.baautopilot.ui.kit.Style;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.FontManager;

/**
 * Section heading that folds its content away: same typography as
 * {@link SectionHeading} with a chevron, clicking toggles everything
 * added via {@link #addContent}. Collapsed by default.
 */
public class CollapsibleSection extends JPanel
{
	private final JPanel content;
	private final DisclosureButton chevron;
	private boolean expanded;

	public CollapsibleSection(String title, String subtitle)
	{
		setOpaque(false);
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setBorder(new EmptyBorder(8, 0, 0, 0));

		JPanel header = Style.transparentPanel(new BorderLayout(6, 0));
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		JPanel text = Style.transparentPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		JPanel titleRow = Style.transparentPanel();
		titleRow.setLayout(new BoxLayout(titleRow, BoxLayout.X_AXIS));
		titleRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		titleRow.add(new HeadingLabel(title));
		titleRow.add(javax.swing.Box.createHorizontalStrut(6));
		titleRow.add(new HeadingRule());
		text.add(titleRow);
		if (subtitle != null && !subtitle.isEmpty())
		{
			JLabel subtitleLabel = new JLabel(subtitle);
			subtitleLabel.setFont(FontManager.getRunescapeSmallFont());
			subtitleLabel.setForeground(Style.FAINT_TEXT);
			text.add(subtitleLabel);
		}
		header.add(text, BorderLayout.CENTER);

		chevron = new DisclosureButton(() -> setExpanded(!expanded));
		header.add(chevron, BorderLayout.EAST);

		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent event)
			{
				setExpanded(!expanded);
			}
		});
		add(header);

		content = Style.transparentPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBorder(new EmptyBorder(5, 0, 0, 0));
		content.setVisible(false);
		add(content);
	}

	/** Removes the built-in top padding — for a section at the top of a panel. */
	public CollapsibleSection noTopGap()
	{
		setBorder(new EmptyBorder(0, 0, 0, 0));
		return this;
	}

	public CollapsibleSection addContent(Component component)
	{
		content.add(component);
		return this;
	}

	public void setExpanded(boolean expanded)
	{
		this.expanded = expanded;
		content.setVisible(expanded);
		chevron.setExpanded(expanded);
		revalidate();
		repaint();
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import com.bautopilot.baautopilot.ui.kit.Style;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JComponent;

/**
 * Expand/collapse control: a small triangle arrow — down when the
 * content is hidden ("open me"), up when shown — with a soft circular
 * highlight under the cursor.
 */
public class DisclosureButton extends JComponent
{
	private static final int SIZE = 18;
	private static final Color HOVER_CIRCLE = new Color(255, 255, 255, 22);

	private final Runnable onToggle;
	private boolean expanded;
	private boolean hovered;

	public DisclosureButton(Runnable onToggle)
	{
		this.onToggle = onToggle;
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setPreferredSize(new Dimension(SIZE, SIZE));
		setMinimumSize(new Dimension(SIZE, SIZE));
		setMaximumSize(new Dimension(SIZE, SIZE));
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				hovered = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				hovered = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent event)
			{
				onToggle.run();
			}
		});
	}

	public void setExpanded(boolean expanded)
	{
		this.expanded = expanded;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		if (hovered)
		{
			// Always a true circle, even if a layout stretched the button.
			int diameter = Math.min(getWidth(), getHeight());
			g.setColor(HOVER_CIRCLE);
			g.fillOval((getWidth() - diameter) / 2, (getHeight() - diameter) / 2, diameter, diameter);
		}
		// Center the arrow in actual bounds, not the nominal SIZE box.
		int ox = (getWidth() - SIZE) / 2;
		int oy = (getHeight() - SIZE) / 2;
		g.translate(ox, oy);
		g.setColor(expanded ? Style.TEAL : Style.MUTED_TEXT);
		if (expanded)
		{
			g.fillPolygon(new int[]{5, 13, 9}, new int[]{11, 11, 6}, 3);
		}
		else
		{
			g.fillPolygon(new int[]{5, 13, 9}, new int[]{7, 7, 12}, 3);
		}
		g.dispose();
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Rectangle2D;
import javax.swing.Icon;

/**
 * Painted settings gear in any accent color: a filled silhouette —
 * body, six teeth, punched-out hub — which stays readable at small
 * sizes where stroked spokes would blur into a sun.
 */
public class GearIcon implements Icon
{
	private static final int SIZE = 14;

	private final Color color;

	public GearIcon(Color color)
	{
		this.color = color;
	}

	@Override
	public void paintIcon(Component component, Graphics graphics, int x, int y)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(color);

		double cx = x + SIZE / 2.0;
		double cy = y + SIZE / 2.0;

		Area gear = new Area(new Ellipse2D.Double(cx - 4.6, cy - 4.6, 9.2, 9.2));
		Rectangle2D tooth = new Rectangle2D.Double(cx + 3.2, cy - 1.5, 3.6, 3.0);
		for (int i = 0; i < 6; i++)
		{
			AffineTransform rotate = AffineTransform.getRotateInstance(Math.PI / 3 * i, cx, cy);
			gear.add(new Area(rotate.createTransformedShape(tooth)));
		}
		gear.subtract(new Area(new Ellipse2D.Double(cx - 1.9, cy - 1.9, 3.8, 3.8)));

		g.fill(gear);
		g.dispose();
	}

	@Override
	public int getIconWidth()
	{
		return SIZE;
	}

	@Override
	public int getIconHeight()
	{
		return SIZE;
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import com.bautopilot.baautopilot.ui.kit.Style;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.font.TextAttribute;
import java.util.HashMap;
import java.util.Map;
import javax.swing.JLabel;
import net.runelite.client.ui.FontManager;

/**
 * Stylized section-title text: letter-spaced bold caps with a soft
 * drop shadow — the heading voice shared by {@link SectionHeading}
 * and {@link CollapsibleSection}.
 */
public class HeadingLabel extends JLabel
{
	private static final Color SHADOW = new Color(0, 0, 0, 160);
	// Measured string width undershoots on tracked fonts; keep slack so
	// the last glyph is never clipped.
	private static final int WIDTH_SLACK = 8;

	public HeadingLabel(String text)
	{
		super(text);
		setFont(headingFont());
		setForeground(Style.TEXT);
		setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	/** RuneScape bold at 14pt with a touch of tracking, for all-caps headings. */
	public static Font headingFont()
	{
		Map<TextAttribute, Object> attributes = new HashMap<>();
		attributes.put(TextAttribute.TRACKING, 0.07f);
		return FontManager.getRunescapeBoldFont().deriveFont(14f).deriveFont(attributes);
	}

	@Override
	public Dimension getPreferredSize()
	{
		FontMetrics metrics = getFontMetrics(getFont());
		return new Dimension(
			metrics.stringWidth(getText()) + WIDTH_SLACK,
			metrics.getHeight() + 1);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(
			RenderingHints.KEY_TEXT_ANTIALIASING,
			RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setFont(getFont());
		int baseline = g.getFontMetrics().getAscent();
		g.setColor(SHADOW);
		g.drawString(getText(), 1, baseline + 1);
		g.setColor(getForeground());
		g.drawString(getText(), 0, baseline);
		g.dispose();
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import com.bautopilot.baautopilot.ui.kit.Style;
import java.awt.Dimension;
import java.awt.Graphics;
import javax.swing.JComponent;

/**
 * The thin rule that runs from a heading's last letter to the right
 * edge. Stretches horizontally inside a BoxLayout row.
 */
class HeadingRule extends JComponent
{
	HeadingRule()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(12, 15));
		// Short.MAX_VALUE, not Integer: BoxLayout sums child maximums, and
		// two Integer.MAX_VALUE rules overflow int — all space then lands
		// on one rule instead of splitting evenly.
		setMaximumSize(new Dimension(Short.MAX_VALUE, 15));
		setAlignmentY(CENTER_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		graphics.setColor(Style.BORDER);
		// +3, not center: RuneScape glyphs sit low in their line box, so the
		// rule must drop below box center to hit the caps' optical middle.
		int y = getHeight() / 2 + 3;
		graphics.drawLine(0, y, getWidth(), y);
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.Icon;
import javax.swing.JButton;

/**
 * Small square button that shows just an icon, with the same soft
 * circular hover highlight as {@link DisclosureButton}. Swap the icon
 * with {@code setIcon} to reflect state (e.g. gear muted → teal).
 */
public class IconButton extends JButton
{
	private static final int SIZE = 20;
	private static final Color HOVER_CIRCLE = new Color(255, 255, 255, 22);

	private boolean hovered;

	public IconButton(Icon icon, String tooltip)
	{
		super(icon);
		setToolTipText(tooltip);
		setPreferredSize(new Dimension(SIZE, SIZE));
		setMinimumSize(new Dimension(SIZE, SIZE));
		setMaximumSize(new Dimension(SIZE, SIZE));
		setFocusPainted(false);
		setBorderPainted(false);
		setContentAreaFilled(false);
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				hovered = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				hovered = false;
				repaint();
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		if (hovered && isEnabled())
		{
			// Always a true circle, even if a layout stretched the button.
			int diameter = Math.min(getWidth(), getHeight());
			g.setColor(HOVER_CIRCLE);
			g.fillOval((getWidth() - diameter) / 2, (getHeight() - diameter) / 2, diameter, diameter);
		}
		Icon icon = getIcon();
		if (icon != null)
		{
			icon.paintIcon(this, g, (getWidth() - icon.getIconWidth()) / 2, (getHeight() - icon.getIconHeight()) / 2);
		}
		g.dispose();
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import com.bautopilot.baautopilot.ui.kit.Style;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.plaf.basic.BasicScrollBarUI;

/**
 * Slim rounded scrollbar without arrow buttons. Usually applied through
 * {@link Style#styleScrollPane}.
 */
public class ModernScrollBarUI extends BasicScrollBarUI
{
	@Override
	protected void configureScrollBarColors()
	{
		trackColor = Style.PANEL_BG;
		thumbColor = new Color(82, 85, 92);
	}

	@Override
	protected JButton createDecreaseButton(int orientation)
	{
		return zeroButton();
	}

	@Override
	protected JButton createIncreaseButton(int orientation)
	{
		return zeroButton();
	}

	@Override
	protected void paintTrack(Graphics graphics, JComponent component, Rectangle bounds)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setColor(Style.PANEL_BG);
		g.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
		g.dispose();
	}

	@Override
	protected void paintThumb(Graphics graphics, JComponent component, Rectangle bounds)
	{
		if (!component.isEnabled() || bounds.width <= 0 || bounds.height <= 0)
		{
			return;
		}
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(isDragging ? new Color(118, 122, 132) : new Color(78, 81, 89));
		int x = bounds.x + 1;
		int width = Math.max(3, bounds.width - 2);
		g.fillRoundRect(x, bounds.y + 1, width, Math.max(4, bounds.height - 2), 7, 7);
		g.dispose();
	}

	private static JButton zeroButton()
	{
		JButton button = new JButton();
		button.setPreferredSize(new Dimension(0, 0));
		button.setMinimumSize(new Dimension(0, 0));
		button.setMaximumSize(new Dimension(0, 0));
		return button;
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import com.bautopilot.baautopilot.ui.kit.Style;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Rectangle;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * Panel skeleton with pinned regions: components added to
 * {@link #getHeader()} stay fixed at the top and {@link #getFooter()}
 * at the bottom, while {@link #getContent()} scrolls between them with
 * the kit scrollbar.
 *
 * Use inside a {@code PluginPanel(false)} (unwrapped) so RuneLite does
 * not add its own outer scroll pane around the pinned regions.
 */
public class PanelShell extends JPanel
{
	private final JPanel header = Style.transparentPanel();
	private final JPanel footer = Style.transparentPanel();
	private final ScrollableColumn content = new ScrollableColumn();

	public PanelShell()
	{
		super(new BorderLayout(0, 8));
		setBackground(Style.PANEL_BG);
		setBorder(new EmptyBorder(5, 3, 9, 3));

		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		footer.setLayout(new BoxLayout(footer, BoxLayout.Y_AXIS));

		JScrollPane scroll = new JScrollPane(
			content,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,
			JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		Style.styleScrollPane(scroll);

		add(header, BorderLayout.NORTH);
		add(scroll, BorderLayout.CENTER);
		add(footer, BorderLayout.SOUTH);
	}

	/** Pinned area above the scroll region. */
	public JPanel getHeader()
	{
		return header;
	}

	/** The scrolling middle column (vertical BoxLayout). */
	public JPanel getContent()
	{
		return content;
	}

	/** Pinned area below the scroll region. */
	public JPanel getFooter()
	{
		return footer;
	}

	/** Column that fits the viewport width so cards never scroll sideways. */
	private static final class ScrollableColumn extends JPanel implements Scrollable
	{
		private ScrollableColumn()
		{
			setOpaque(false);
			setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction)
		{
			return 18;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
		{
			return 90;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

