package com.bautopilot.baautopilot.ui.kit.components;

import com.bautopilot.baautopilot.ui.kit.Style;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JButton;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.FontManager;

/**
 * Flat rounded button with a subtle raise on hover.
 *
 * Three looks:
 * - default: SURFACE fill + BORDER stroke; communicate state through the
 *   foreground color (SUCCESS when a toggle is on, MUTED_TEXT when off)
 * - {@link #primary}: strong accent wash with a solid accent border, for
 *   the one main call to action on a panel
 * - {@link #accent}: translucent accent wash (StatusPill-style), for
 *   secondary emphasized actions such as a danger button
 */
public class RoundedButton extends JButton
{
	private Color fill = Style.SURFACE;
	private Color hoverFill = Style.SURFACE_RAISED;
	private Color stroke = Style.BORDER;
	private boolean hovered;

	public RoundedButton()
	{
		// Same size as row/item titles so button labels read as first-class text.
		setFont(FontManager.getRunescapeBoldFont());
		setFocusPainted(false);
		setBorderPainted(false);
		setContentAreaFilled(false);
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setBorder(new EmptyBorder(5, 9, 5, 9));
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				hovered = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				hovered = false;
				repaint();
			}
		});
	}

	public RoundedButton(String text)
	{
		this();
		setText(text);
	}

	/** Strong accent wash with a solid accent border — the main call to action. */
	public static RoundedButton primary(String text)
	{
		return primary(text, Style.GOLD);
	}

	public static RoundedButton primary(String text, Color accent)
	{
		RoundedButton button = new RoundedButton(text);
		button.fill = Style.withAlpha(accent, 42);
		button.hoverFill = Style.withAlpha(accent, 64);
		button.stroke = accent;
		button.setForeground(accent);
		return button;
	}

	/** Translucent accent wash, matching StatusPill — emphasized secondary action. */
	public static RoundedButton accent(String text, Color accent)
	{
		RoundedButton button = new RoundedButton(text);
		button.fill = Style.withAlpha(accent, 28);
		button.hoverFill = Style.withAlpha(accent, 48);
		button.stroke = Style.withAlpha(accent, 120);
		button.setForeground(accent);
		return button;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(hovered && isEnabled() ? hoverFill : fill);
		g.fillRoundRect(0, 0, getWidth(), getHeight(), 10, 10);
		if (stroke != null)
		{
			g.setColor(stroke);
			g.drawRoundRect(0, 0, Math.max(0, getWidth() - 1), Math.max(0, getHeight() - 1), 10, 10);
		}
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JPanel;

/** Rounded-rectangle container with an optional 1px stroke. */
public class RoundedPanel extends JPanel
{
	private Color fill;
	private final int radius;
	private final Color stroke;

	public RoundedPanel(Color fill, int radius, Color stroke)
	{
		this.fill = fill;
		this.radius = radius;
		this.stroke = stroke;
		setOpaque(false);
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
	}

	/** Swaps the background fill, e.g. for hover states. */
	public void setFill(Color fill)
	{
		this.fill = fill;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(fill);
		g.fillRoundRect(0, 0, getWidth(), getHeight(), radius, radius);
		if (stroke != null)
		{
			g.setColor(stroke);
			g.setStroke(new BasicStroke(1f));
			g.drawRoundRect(0, 0, Math.max(0, getWidth() - 1), Math.max(0, getHeight() - 1), radius, radius);
		}
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import com.bautopilot.baautopilot.ui.kit.Style;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.util.function.Consumer;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.FontManager;

/**
 * Row of compact controls belonging to one section — attach it with
 * {@link SectionHeading#setControls} so it renders inside the heading
 * block, directly under the title. Mix text chips, state toggles and
 * icon buttons; align the row left, center or right.
 */
public class SectionControls extends JPanel
{
	private boolean hasControls;
	private int insertIndex;

	public SectionControls()
	{
		this(SwingConstants.LEFT);
	}

	public SectionControls(int alignment)
	{
		setOpaque(false);
		setLayout(new BoxLayout(this, BoxLayout.X_AXIS));
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setBorder(new EmptyBorder(4, 0, 0, 0));

		if (alignment != SwingConstants.LEFT)
		{
			add(Box.createHorizontalGlue());
			insertIndex = 1;
		}
		if (alignment != SwingConstants.RIGHT)
		{
			add(Box.createHorizontalGlue());
		}
	}

	/** Compact text-chip action. */
	public SectionControls addButton(String text, Runnable action)
	{
		RoundedButton button = compactButton(text);
		button.setForeground(Style.SOFT_TEXT);
		button.addActionListener(event -> action.run());
		addControl(button);
		return this;
	}

	/** Text chip carrying an on/off state (teal when on, muted when off). */
	public SectionControls addToggleButton(String text, boolean initial, Consumer<Boolean> onChange)
	{
		boolean[] state = {initial};
		RoundedButton button = compactButton(text);
		button.setForeground(state[0] ? Style.TEAL : Style.MUTED_TEXT);
		button.addActionListener(event ->
		{
			state[0] = !state[0];
			button.setForeground(state[0] ? Style.TEAL : Style.MUTED_TEXT);
			onChange.accept(state[0]);
		});
		addControl(button);
		return this;
	}

	/** Icon control with a hover circle (e.g. a {@link GearIcon}). */
	public SectionControls addIcon(Icon icon, String tooltip, Runnable action)
	{
		IconButton button = new IconButton(icon, tooltip);
		button.addActionListener(event -> action.run());
		addControl(button);
		return this;
	}

	private static RoundedButton compactButton(String text)
	{
		RoundedButton button = new RoundedButton(text);
		button.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
		button.setBorder(new EmptyBorder(3, 8, 3, 8));
		return button;
	}

	private void addControl(JComponent control)
	{
		if (hasControls)
		{
			add(Box.createHorizontalStrut(4), insertIndex);
			insertIndex++;
		}
		// Chips and icon buttons differ in height; center them on one line.
		control.setAlignmentY(Component.CENTER_ALIGNMENT);
		add(control, insertIndex);
		insertIndex++;
		hasControls = true;
		revalidate();
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import com.bautopilot.baautopilot.ui.kit.Style;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.FontManager;

/**
 * Section divider: stylized title with a rule running from the last
 * letter to the right edge, an optional faint subtitle, and room for a
 * trailing control such as a Show backups toggle. Ships with breathing
 * room above it — call {@link #noTopGap()} on the first heading of a
 * panel. Alignment defaults to left; pass {@code SwingConstants.CENTER}
 * or {@code RIGHT} for the others (the rule mirrors accordingly).
 */
public class SectionHeading extends JPanel
{
	private static final int TOP_GAP = 8;

	private SectionControls controls;

	public SectionHeading(String title, String subtitle)
	{
		this(title, subtitle, SwingConstants.LEFT);
	}

	public SectionHeading(String title, String subtitle, int alignment)
	{
		super(new BorderLayout(6, 0));
		setOpaque(false);
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setBorder(new EmptyBorder(TOP_GAP, 0, 0, 0));

		JPanel text = Style.transparentPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));

		JPanel titleRow = Style.transparentPanel();
		titleRow.setLayout(new BoxLayout(titleRow, BoxLayout.X_AXIS));
		titleRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		HeadingLabel titleLabel = new HeadingLabel(title);
		if (alignment == SwingConstants.CENTER)
		{
			titleRow.add(new HeadingRule());
			titleRow.add(Box.createHorizontalStrut(6));
			titleRow.add(titleLabel);
			titleRow.add(Box.createHorizontalStrut(6));
			titleRow.add(new HeadingRule());
		}
		else if (alignment == SwingConstants.RIGHT)
		{
			titleRow.add(new HeadingRule());
			titleRow.add(Box.createHorizontalStrut(6));
			titleRow.add(titleLabel);
		}
		else
		{
			titleRow.add(titleLabel);
			titleRow.add(Box.createHorizontalStrut(6));
			titleRow.add(new HeadingRule());
		}
		text.add(titleRow);

		if (subtitle != null && !subtitle.isEmpty())
		{
			JLabel subtitleLabel = new JLabel(subtitle);
			subtitleLabel.setFont(FontManager.getRunescapeSmallFont());
			subtitleLabel.setForeground(Style.FAINT_TEXT);
			// A full-width row with glue, not alignmentX: BoxLayout misplaces
			// children whose alignments differ from their siblings'.
			JPanel subtitleRow = Style.transparentPanel();
			subtitleRow.setLayout(new BoxLayout(subtitleRow, BoxLayout.X_AXIS));
			subtitleRow.setAlignmentX(Component.LEFT_ALIGNMENT);
			if (alignment != SwingConstants.LEFT)
			{
				subtitleRow.add(Box.createHorizontalGlue());
			}
			subtitleRow.add(subtitleLabel);
			if (alignment != SwingConstants.RIGHT)
			{
				subtitleRow.add(Box.createHorizontalGlue());
			}
			text.add(subtitleRow);
		}
		add(text, BorderLayout.CENTER);
	}

	/** Removes the built-in top padding — for the first heading of a panel. */
	public SectionHeading noTopGap()
	{
		setBorder(new EmptyBorder(0, 0, 0, 0));
		return this;
	}

	/**
	 * Attaches this section's control row under the title, inside the
	 * heading block. With {@code compact}, the row starts hidden behind a
	 * gear button on the heading (muted closed, teal open).
	 */
	public SectionHeading setControls(SectionControls controls, boolean compact)
	{
		this.controls = controls;
		add(controls, BorderLayout.SOUTH);
		if (compact)
		{
			controls.setVisible(false);
			IconButton gear = new IconButton(new GearIcon(Style.MUTED_TEXT), "Section controls");
			gear.addActionListener(event ->
			{
				boolean show = !controls.isVisible();
				controls.setVisible(show);
				gear.setIcon(new GearIcon(show ? Style.TEAL : Style.MUTED_TEXT));
				revalidate();
				repaint();
			});
			setTrailing(gear);
		}
		return this;
	}

	@Override
	public Dimension getMaximumSize()
	{
		// Grows with subtitle and controls row instead of a fixed cap.
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	/**
	 * Places a control (usually a {@link RoundedButton}) at the right edge.
	 * Trailing controls get the compact bold font — at full button size the
	 * pair "title + control" no longer fits the panel width and the title
	 * clips.
	 */
	public void setTrailing(Component component)
	{
		component.setFont(FontManager.getRunescapeSmallFont().deriveFont(java.awt.Font.BOLD));
		// Top-aligned wrapper: BorderLayout EAST would otherwise stretch the
		// control across the whole heading (title + subtitle + controls).
		JPanel wrap = Style.transparentPanel();
		wrap.setLayout(new BoxLayout(wrap, BoxLayout.Y_AXIS));
		wrap.add(component);
		wrap.add(Box.createVerticalGlue());
		add(wrap, BorderLayout.EAST);
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import com.bautopilot.baautopilot.ui.kit.Style;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JLabel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.FontManager;

/**
 * Small rounded chip: accent-colored text over a translucent wash of the
 * same accent ("PACKED", "BANK", "MISSING", combat style tags, ...).
 */
public class StatusPill extends JLabel
{
	private Color accent;

	public StatusPill(String text, Color accent)
	{
		super(text);
		this.accent = accent;
		setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
		setForeground(accent);
		setHorizontalAlignment(SwingConstants.CENTER);
		setOpaque(false);
		// Uneven insets: pill text is all-caps, so the font's descent space
		// below the baseline is dead — biasing the text down a pixel puts
		// the caps on the optical center of the wash.
		setBorder(new EmptyBorder(4, 6, 2, 6));
	}

	public void setAccent(Color accent)
	{
		this.accent = accent;
		setForeground(accent);
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(Style.withAlpha(accent, 28));
		g.fillRoundRect(0, 0, getWidth(), getHeight(), 10, 10);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import com.bautopilot.baautopilot.ui.kit.Style;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JList;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import javax.swing.plaf.basic.BasicComboBoxUI;
import javax.swing.plaf.basic.BasicComboPopup;
import javax.swing.plaf.basic.ComboPopup;
import net.runelite.client.ui.FontManager;

/**
 * Dropdown in the kit look: rounded SURFACE field with a chevron, dark
 * popup list with ROW_HOVER selection. Non-editable use is assumed.
 */
public class StyledComboBox<T> extends JComboBox<T>
{
	public StyledComboBox(T[] items)
	{
		super(items);
		setOpaque(false);
		setFont(FontManager.getRunescapeSmallFont());
		setForeground(Style.TEXT);
		setBackground(Style.SURFACE);
		setBorder(new EmptyBorder(1, 4, 1, 1));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setMaximumRowCount(8);
		setRenderer(new Renderer());
		setUI(new KitComboBoxUI());
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(Style.SURFACE);
		g.fillRoundRect(0, 0, getWidth(), getHeight(), 10, 10);
		g.setColor(hasFocus() || isPopupVisible() ? Style.GOLD : Style.BORDER);
		g.drawRoundRect(0, 0, Math.max(0, getWidth() - 1), Math.max(0, getHeight() - 1), 10, 10);
		g.dispose();
		super.paintComponent(graphics);
	}

	private static final class KitComboBoxUI extends BasicComboBoxUI
	{
		@Override
		protected JButton createArrowButton()
		{
			JButton button = new JButton()
			{
				@Override
				protected void paintComponent(Graphics graphics)
				{
					Graphics2D g = (Graphics2D) graphics.create();
					g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
					g.setColor(Style.MUTED_TEXT);
					int cx = getWidth() / 2;
					int cy = getHeight() / 2;
					g.drawLine(cx - 3, cy - 2, cx, cy + 2);
					g.drawLine(cx, cy + 2, cx + 3, cy - 2);
					g.dispose();
				}
			};
			button.setContentAreaFilled(false);
			button.setBorderPainted(false);
			button.setFocusPainted(false);
			button.setBorder(new EmptyBorder(0, 4, 0, 6));
			return button;
		}

		@Override
		public void paintCurrentValueBackground(Graphics graphics, Rectangle bounds, boolean hasFocus)
		{
			// The rounded field is painted by the component itself.
		}

		@Override
		protected ComboPopup createPopup()
		{
			BasicComboPopup popup = (BasicComboPopup) super.createPopup();
			popup.setBorder(new LineBorder(Style.BORDER));
			JList<?> list = popup.getList();
			list.setBackground(Style.SURFACE);
			list.setSelectionBackground(Style.ROW_HOVER);
			list.setSelectionForeground(Style.TEXT);
			return popup;
		}
	}

	private static final class Renderer extends DefaultListCellRenderer
	{
		@Override
		public Component getListCellRendererComponent(
			JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus)
		{
			super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
			setFont(FontManager.getRunescapeSmallFont());
			setBorder(new EmptyBorder(4, 8, 4, 8));
			if (index == -1)
			{
				// Current value inside the field: transparent over the rounded fill.
				setOpaque(false);
				setForeground(Style.TEXT);
			}
			else
			{
				setOpaque(true);
				setBackground(isSelected ? Style.ROW_HOVER : Style.SURFACE);
				setForeground(isSelected ? Style.TEXT : Style.SOFT_TEXT);
			}
			return this;
		}
	}
}

package com.bautopilot.baautopilot.ui.kit.components;

import com.bautopilot.baautopilot.ui.kit.Style;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.Icon;
import javax.swing.JToggleButton;
import net.runelite.client.ui.FontManager;

/**
 * Pill-shaped on/off switch: SUCCESS track with the thumb right when
 * on, raised surface with a muted thumb when off.
 */
public class ToggleSwitch extends JToggleButton
{
	public ToggleSwitch(String text)
	{
		super(text);
		setOpaque(false);
		setFocusPainted(false);
		setBorderPainted(false);
		setContentAreaFilled(false);
		setFont(FontManager.getRunescapeSmallFont());
		setForeground(Style.SOFT_TEXT);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setIconTextGap(7);
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setIcon(new TrackIcon(false));
		setSelectedIcon(new TrackIcon(true));
	}

	private static final class TrackIcon implements Icon
	{
		private static final int WIDTH = 27;
		private static final int HEIGHT = 15;
		private final boolean on;

		private TrackIcon(boolean on)
		{
			this.on = on;
		}

		@Override
		public void paintIcon(Component component, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			if (on)
			{
				g.setColor(Style.withAlpha(Style.SUCCESS, 55));
				g.fillRoundRect(x, y, WIDTH - 1, HEIGHT - 1, HEIGHT - 1, HEIGHT - 1);
				g.setColor(Style.SUCCESS);
				g.drawRoundRect(x, y, WIDTH - 1, HEIGHT - 1, HEIGHT - 1, HEIGHT - 1);
				g.fillOval(x + WIDTH - HEIGHT + 2, y + 2, HEIGHT - 5, HEIGHT - 5);
			}
			else
			{
				g.setColor(Style.SURFACE_RAISED);
				g.fillRoundRect(x, y, WIDTH - 1, HEIGHT - 1, HEIGHT - 1, HEIGHT - 1);
				g.setColor(Style.BORDER);
				g.drawRoundRect(x, y, WIDTH - 1, HEIGHT - 1, HEIGHT - 1, HEIGHT - 1);
				g.setColor(Style.MUTED_TEXT);
				g.fillOval(x + 2, y + 2, HEIGHT - 5, HEIGHT - 5);
			}
			g.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return WIDTH;
		}

		@Override
		public int getIconHeight()
		{
			return HEIGHT;
		}
	}
}

package com.bautopilot.baautopilot;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.bautopilot.baautopilot.state.ArenaPath;
import java.util.List;
import net.runelite.api.CollisionDataFlag;
import org.junit.Test;

public class ArenaPathTest
{
	private static int[][] open(int size)
	{
		return new int[size][size];
	}

	@Test
	public void straightAndDiagonalOnOpenGround()
	{
		List<int[]> path = ArenaPath.find(open(10), 1, 1, (x, y) -> x == 4 && y == 4, 50);
		assertEquals(4, path.size());
		assertArrayEquals(new int[]{1, 1}, path.get(0));
		assertArrayEquals(new int[]{4, 4}, path.get(3));
	}

	@Test
	public void goesAroundABlockedColumn()
	{
		int[][] flags = open(10);
		for (int y = 0; y < 8; y++)
		{
			flags[5][y] = CollisionDataFlag.BLOCK_MOVEMENT_OBJECT;
		}
		List<int[]> path = ArenaPath.find(flags, 2, 2, (x, y) -> x == 8 && y == 2, 60);
		assertTrue(path.size() > 7);
		for (int[] p : path)
		{
			assertTrue("walked through the wall at " + p[0] + "," + p[1], p[0] != 5 || p[1] >= 8);
		}
	}

	@Test
	public void respectsAWallOnATileEdge()
	{
		int[][] flags = open(6);
		// A wall on the east side of (2,y) for every y: you can't step from x=2 to x=3 anywhere
		for (int y = 0; y < 6; y++)
		{
			flags[2][y] |= CollisionDataFlag.BLOCK_MOVEMENT_EAST;
			flags[3][y] |= CollisionDataFlag.BLOCK_MOVEMENT_WEST;
		}
		assertTrue(ArenaPath.find(flags, 1, 1, (x, y) -> x == 4 && y == 1, 40).isEmpty());
	}

	@Test
	public void noCornerCutting()
	{
		int[][] flags = open(5);
		flags[2][1] = CollisionDataFlag.BLOCK_MOVEMENT_OBJECT;
		flags[1][2] = CollisionDataFlag.BLOCK_MOVEMENT_OBJECT;
		// (1,1) -> (2,2) diagonally would squeeze between two blocked tiles
		List<int[]> path = ArenaPath.find(flags, 1, 1, (x, y) -> x == 2 && y == 2, 20);
		assertTrue(path.isEmpty() || path.size() > 2);
	}

	@Test
	public void drawsDirectSegmentsInEveryDirectionOnOpenGround()
	{
		int[][] flags = open(15);
		for (int x = 1; x < 14; x++)
		{
			for (int y = 1; y < 14; y++)
			{
				if (x == 7 && y == 7)
				{
					continue;
				}
				int tx = x;
				int ty = y;
				List<int[]> route = ArenaPath.find(flags, 7, 7, (px, py) -> px == tx && py == ty, 50);
				List<int[]> drawn = ArenaPath.waypoints(flags, route);
				assertEquals("unnecessary bend toward " + x + "," + y, 2, drawn.size());
				assertArrayEquals(new int[]{7, 7}, drawn.get(0));
				assertArrayEquals(new int[]{x, y}, drawn.get(1));
			}
		}
	}

	@Test
	public void drawnSegmentsStillGoAroundObstacles()
	{
		int[][] flags = open(10);
		for (int y = 0; y < 8; y++)
		{
			flags[5][y] = CollisionDataFlag.BLOCK_MOVEMENT_OBJECT;
		}
		List<int[]> drawn = ArenaPath.waypoints(flags,
			ArenaPath.find(flags, 2, 2, (x, y) -> x == 8 && y == 2, 60));
		assertTrue("drew straight through the blocked column", drawn.size() > 2);
		assertArrayEquals(new int[]{2, 2}, drawn.get(0));
		assertArrayEquals(new int[]{8, 2}, drawn.get(drawn.size() - 1));
		for (int i = 1; i < drawn.size(); i++)
		{
			int[] a = drawn.get(i - 1);
			int[] b = drawn.get(i);
			if (Math.min(a[0], b[0]) <= 5 && Math.max(a[0], b[0]) >= 5 && a[0] != b[0])
			{
				double crossingY = a[1] + (5.0 - a[0]) * (b[1] - a[1]) / (b[0] - a[0]);
				assertTrue("segment crosses the blocked column", crossingY >= 7.5);
			}
		}
	}

	@Test
	public void drawnSegmentsRespectTileEdgeWalls()
	{
		int[][] flags = open(7);
		for (int y = 1; y <= 3; y++)
		{
			flags[2][y] |= CollisionDataFlag.BLOCK_MOVEMENT_EAST;
			flags[3][y] |= CollisionDataFlag.BLOCK_MOVEMENT_WEST;
		}
		List<int[]> drawn = ArenaPath.waypoints(flags,
			ArenaPath.find(flags, 1, 2, (x, y) -> x == 4 && y == 2, 40));
		assertTrue("smoothed through an edge wall", drawn.size() > 2);
	}

	@Test
	public void drawnSegmentsDoNotCutCornersOrSkipIntersectedTiles()
	{
		int[][] flags = open(7);
		flags[2][1] = CollisionDataFlag.BLOCK_MOVEMENT_OBJECT;
		flags[1][2] = CollisionDataFlag.BLOCK_MOVEMENT_OBJECT;
		List<int[]> corner = ArenaPath.waypoints(flags,
			ArenaPath.find(flags, 1, 1, (x, y) -> x == 2 && y == 2, 40));
		assertTrue("drew diagonally between blocked tiles", corner.size() > 2);

		flags[1][2] = 0;
		List<int[]> shallow = ArenaPath.waypoints(flags,
			ArenaPath.find(flags, 1, 1, (x, y) -> x == 5 && y == 3, 40));
		assertTrue("shallow line crossed a blocked tile between sampled centres", shallow.size() > 2);
	}
}

package com.bautopilot.baautopilot;

import com.bautopilot.baautopilot.state.BaTracker;
import com.bautopilot.baautopilot.state.Performance;
import com.bautopilot.baautopilot.state.Snapshot;
import com.bautopilot.baautopilot.tutorial.TutorialSteps;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.ui.BaAutopilotPanel;
import java.util.Map;
import javax.swing.SwingUtilities;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import java.lang.reflect.Field;
import org.junit.Test;
import static org.junit.Assert.*;

public class BaAutopilotIdleTest
{
	private static class ProgressPanel extends BaAutopilotPanel
	{
		int updates;
		Snapshot progress;
		@Override public void updateProgress(Snapshot snapshot)
		{
			updates++;
			progress = snapshot;
			super.updateProgress(snapshot);
		}
	}

	@Test public void sidebarProgressUpdatesOutsideTheArenaWithoutRepeatedSwingUpdates() throws Exception
	{
		BaAutopilotPlugin plugin = new BaAutopilotPlugin();
		Snapshot inactive = Snapshot.builder().build();
		Snapshot[] progress = {Snapshot.builder().roleLevels(Map.of(Role.HEALER, 3)).rolePoints(Map.of(Role.HEALER, 1200)).build()};
		set(plugin, "tracker", new BaTracker()
		{
			@Override public Snapshot snapshot() { return inactive; }
			@Override public Snapshot progress() { return progress[0]; }
		});
		ProgressPanel[] panel = new ProgressPanel[1];
		SwingUtilities.invokeAndWait(() -> { panel[0] = new ProgressPanel(); panel[0].updates = 0; });
		set(plugin, "panel", panel[0]);
		for (int i = 0; i < 1000; i++) plugin.onGameTick(null);
		SwingUtilities.invokeAndWait(() -> { });
		assertEquals(1, panel[0].updates);
		assertSame(progress[0], panel[0].progress);
		assertNull(plugin.getSnapshot());
		assertNull(plugin.getInstruction());
		progress[0] = progress[0].toBuilder().rolePoints(Map.of(Role.HEALER, 1000)).build();
		plugin.onGameTick(null);
		SwingUtilities.invokeAndWait(() -> { });
		assertEquals(2, panel[0].updates);
		assertSame(progress[0], panel[0].progress);
		GameStateChanged logout = new GameStateChanged();
		logout.setGameState(GameState.LOGIN_SCREEN);
		plugin.onGameStateChanged(logout);
		SwingUtilities.invokeAndWait(() -> { });
		assertEquals(3, panel[0].updates);
		assertNull(panel[0].progress);
	}
	private static void set(BaAutopilotPlugin plugin, String name, Object value) throws Exception
	{
		Field field = BaAutopilotPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(plugin, value);
	}

	@Test public void idleGameAndClientTicksNeedNoPlannerRendererCameraOrUiDependencies() throws Exception
	{
		BaAutopilotPlugin plugin = new BaAutopilotPlugin();
		Snapshot inactive = Snapshot.builder().build();
		set(plugin, "tracker", new BaTracker()
		{
			@Override public Snapshot snapshot() { return inactive; }
			@Override public Performance getPerformance() { throw new AssertionError("Repeated idle bookkeeping"); }
		});
		// Every other injected service remains null: any accidental hot-path call fails this test.
		for (int i = 0; i < 1000; i++)
		{
			plugin.onGameTick(null);
			plugin.onClientTick(null);
		}
		assertNull(plugin.getInstruction());
		assertNull(plugin.getSnapshot());
		assertFalse(plugin.isTutorialShown());
	}

	@Test public void aDisabledTutorialCannotTickEvenIfItsOldShownFlagRemains() throws Exception
	{
		BaAutopilotPlugin plugin = new BaAutopilotPlugin();
		set(plugin, "tutorialShown", true);
		plugin.onClientTick(null);
	}

	@Test public void enabledTutorialWaitingForItsLobbySceneDoesNotAnimate() throws Exception
	{
		BaAutopilotPlugin plugin = new BaAutopilotPlugin();
		set(plugin, "tutorialOn", true);
		plugin.onClientTick(null);
	}

	private static class TutorialTickReached extends RuntimeException { }

	@Test(expected = TutorialTickReached.class)
	public void enabledAndShownTutorialTicksWithNoArenaSnapshot() throws Exception
	{
		BaAutopilotPlugin plugin = new BaAutopilotPlugin();
		set(plugin, "tutorialOn", true);
		set(plugin, "tutorialShown", true);
		set(plugin, "tutorialSteps", new TutorialSteps(null)
		{
			@Override public void tick() { throw new TutorialTickReached(); }
		});
		assertNull(plugin.getSnapshot());
		plugin.onClientTick(null);
	}
}

