		JsonObject explicit = new JsonObject();
		explicit.addProperty("defenderMultiKill", true);
		assertTrue(RecordedRound.settings(explicit).isDefenderMultiKill());
	}

	@Test public void allDefenderCapturesUseContinuousUpkeepWithoutHoldingOrOffSpotRepairClicks() throws Exception
	{
		int ticks = 0, positioning = 0, repairs = 0;
		try (java.util.stream.Stream<Path> files = Files.list(Path.of("src/test/resources/recordings")))
		{
			for (Path file : (Iterable<Path>) files.filter(p -> p.toString().endsWith(".jsonl")).sorted()::iterator)
			{
				Planner planner = new Planner();
				for (RoundReplay.Frame frame : RoundReplay.run(RecordedRound.read(file),
					(s, settings) -> planner.plan(s, settings.toBuilder().defenderMultiKill(false).build())))
				{
					if (!frame.snapshot.isInArena() || frame.snapshot.getRole() != Role.DEFENDER || frame.snapshot.isQueenAlive()) continue;
					ticks++;
					Instruction ins = frame.instruction;
					Step step = ins.getStep() == Step.CALL && ins.getThen() != null ? ins.getThen() : ins.getStep();
					String context = file.getFileName() + " tick " + frame.snapshot.getTick();
					assertNotEquals(context, Step.DEF_HOLD, step);
					assertNotEquals(context, Step.DEF_STEP, step);
					if (step == Step.DEF_REPAIR_POSITION)
					{
						positioning++;
						assertEquals(context, ArenaTiles.trapFood(frame.snapshot.getWave()), ins.getTarget().getTile());
					}
					if (step == Step.DEF_REPAIR)
					{
						repairs++;
						assertEquals(context, ArenaTiles.trapFood(frame.snapshot.getWave()), frame.snapshot.getPlayerTile());
					}
				}
			}
		}
		assertTrue(ticks > 4000);
		assertTrue(positioning > 0);
		assertTrue(repairs > 0);
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.model.*;
import com.bautopilot.baautopilot.plan.*;
import com.bautopilot.baautopilot.state.Snapshot;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Collectors;

/** Compares continuous and opt-in multikill instructions on identical recorded observations. */
public final class DefenderModeAudit
{
	public static void main(String[] args) throws Exception
	{
		Path input = Path.of(args[0]), output = Path.of(args[1]);
		Files.createDirectories(output);
		List<Path> files;
		try (java.util.stream.Stream<Path> stream = Files.list(input))
		{
			files = stream.filter(p -> p.toString().endsWith(".jsonl")).sorted().collect(Collectors.toList());
		}
		List<String> rows = new ArrayList<>();
		rows.add("capture,mode,ticks,hold_prompts,timed_releases,repair_position_prompts,repair_clicks,off_spot_repair_clicks,broken_other_work,nearby_reserve_trips,clear_food_prompts");
		for (boolean advanced : new boolean[]{false, true})
		{
			int[] total = new int[9];
			for (Path file : files)
			{
				Planner planner = new Planner();
				int[] count = new int[9];
				for (RoundReplay.Frame frame : RoundReplay.run(RecordedRound.read(file),
					(s, settings) -> planner.plan(s, settings.toBuilder().defenderMultiKill(advanced).build())))
				{
					Snapshot s = frame.snapshot;
					if (!s.isInArena() || s.getRole() != Role.DEFENDER || s.isQueenAlive()) continue;
					Instruction ins = frame.instruction;
					Step step = ins.getStep() == Step.CALL && ins.getThen() != null ? ins.getThen() : ins.getStep();
					count[0]++;
					if (step == Step.DEF_HOLD) count[1]++;
					if (step == Step.DEF_STEP && "def.step".equals(ins.getTask())) count[2]++;
					if (step == Step.DEF_REPAIR_POSITION) count[3]++;
					if (step == Step.DEF_REPAIR)
					{
						count[4]++;
						if (!ArenaTiles.trapFood(s.getWave()).equals(s.getPlayerTile())) count[5]++;
					}
					if (s.getTrapCharges() == 0 && !s.getCleared().contains(PenanceType.RUNNER)
						&& ins.getStep() != Step.CALL && ins.getStep() != Step.RETREAT && !"def.repair".equals(ins.getTask())) count[6]++;
					if ("def.reserve".equals(ins.getTask()) && ArenaTiles.distance(s.getPlayerTile(), ArenaTiles.trapFood(s.getWave())) <= 5) count[7]++;
					if (step == Step.DEF_SERVICE && ArenaTiles.trapFood(s.getWave()).equals(s.getPlayerTile())) count[8]++;
				}
				if (count[0] == 0) continue;
				for (int i = 0; i < total.length; i++) total[i] += count[i];
				rows.add(csv(file.getFileName(), advanced ? "advanced_multikill" : "continuous", count));
			}
			String totals = csv("TOTAL", advanced ? "advanced_multikill" : "continuous", total);
			rows.add(totals);
			System.out.println(rows.get(0));
			System.out.println(totals);
		}
		Files.write(output.resolve("summary.csv"), rows);
	}

	private static String csv(Object capture, String mode, int[] values)
	{
		return "\"" + capture + "\"," + mode + "," + Arrays.stream(values).mapToObj(Integer::toString).collect(Collectors.joining(","));
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.plan.Instruction;
import com.bautopilot.baautopilot.plan.Planner;
import com.bautopilot.baautopilot.plan.Settings;
import com.bautopilot.baautopilot.plan.Step;
import com.bautopilot.baautopilot.plan.Target;
import com.bautopilot.baautopilot.state.Snapshot;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/** Separates task progress from proximity: vary only position, retaining every other observed fact. */
public final class DefenderProximityAudit
{
	private DefenderProximityAudit() { }

	public static void main(String[] args) throws Exception
	{
		Path directory = Path.of(args.length > 0 ? args[0] : "src/test/resources/recordings");
		Path output = Path.of(args.length > 1 ? args[1] : "build/reports/defender-proximity");
		Files.createDirectories(output);
		List<String> summary = new ArrayList<>(List.of("recording,ticks,step_changes,step_flips,target_changes,target_flips,position_probes,position_only_target_changes"));
		List<String> changes = new ArrayList<>(List.of("recording,tick,task,from_x,from_y,to_x,to_y,before,after"));
		List<Path> files;
		try (Stream<Path> listing = Files.list(directory))
		{
			files = listing.filter(p -> p.toString().endsWith(".jsonl")).sorted().collect(Collectors.toList());
		}
		for (Path file : files)
		{
			RecordedRound round = RecordedRound.read(file);
			List<RoundReplay.Frame> frames = RoundReplay.run(round).stream()
				.filter(f -> f.snapshot.isInArena() && f.snapshot.getRole() == Role.DEFENDER).collect(Collectors.toList());
			if (frames.isEmpty()) continue;
			Settings settings = round.header.settings == null ? Settings.builder().build() : round.header.settings;
			Planner planner = new Planner();
			int probes = 0, switched = 0;
			for (int i = 0; i + 1 < frames.size(); i++)
			{
				Snapshot s = frames.get(i).snapshot;
				Instruction current = frames.get(i).instruction;
				if (!Set.of("def.pattern", "def.tools", "def.repair").contains(current.getTask() == null ? "" : current.getTask())
					|| !(current.getStep() == Step.DEF_DROP || current.getStep() == Step.DEF_HAMMER || current.getStep() == Step.DEF_LOGS)
					|| current.getTarget().getTile() == null || s.getPlayerTile().equals(frames.get(i + 1).snapshot.getPlayerTile())) continue;
				Snapshot moved = s.toBuilder().playerTile(frames.get(i + 1).snapshot.getPlayerTile())
					.lastTask(current.getTask()).lastTargetTile(current.getTarget().getTile()).tasks(current.getTasks()).build();
				Instruction next = planner.plan(moved, settings);
				probes++;
				if (!current.getTarget().equals(next.getTarget()))
				{
					switched++;
					changes.add(round.name() + "," + s.getTick() + "," + current.getTask() + "," + (s.getPlayerTile().getX() & 63)
						+ "," + (s.getPlayerTile().getY() & 63) + "," + (moved.getPlayerTile().getX() & 63) + "," + (moved.getPlayerTile().getY() & 63)
						+ "," + current.getHeadline().replace(',', ';') + "," + next.getHeadline().replace(',', ';'));
				}
			}
			ReplayMetrics.Wave metrics = ReplayMetrics.measure(frames);
			summary.add(round.name() + "," + metrics.ticks + "," + metrics.stepChanges + "," + metrics.stepFlips + ","
				+ metrics.targetChanges + "," + metrics.targetFlips + "," + probes + "," + switched);
			System.out.println(round.name() + ": " + switched + "/" + probes + " position-only target changes; "
				+ metrics.targetFlips + " short target flip-backs on the recorded path");
		}
		Files.write(output.resolve("summary.csv"), summary);
		Files.write(output.resolve("position-changes.csv"), changes);
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.model.*;
import com.bautopilot.baautopilot.plan.*;
import com.bautopilot.baautopilot.state.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;

/** Describes observed Defender outcomes and guidance on the fixed recorded trajectory. */
public final class DefenderRunEvaluation
{
	public static void main(String[] args) throws Exception
	{
		Path input = Path.of(args[0]), output = Path.of(args[1]);
		Files.createDirectories(output);
		List<Path> files;
		try (java.util.stream.Stream<Path> stream = Files.list(input))
		{
			files = stream.filter(p -> p.toString().endsWith(".jsonl")).sorted().collect(Collectors.toList());
		}
		List<String> summary = new ArrayList<>(), timeline = new ArrayList<>(), episodes = new ArrayList<>();
		summary.add("capture,wave,ticks,runner_clear_tick,runner_clear_wave_tick,unique_southbound_despawns,team_runners_passed,step_changes,target_flips,recorded_early_support_ticks,current_early_support_ticks,broken_ticks,repair_work_ticks,broken_call_ticks,broken_without_repair_or_call_ticks,near_empty_bait_ticks,empty_bait_drop_work_ticks,prepare_ticks,changed_work_steps,max_uncertain_runners");
		timeline.add("capture,tick,wave_tick,recorded_step,current_step,task,player_x,player_y,target_x,target_y,charges,good_on_trap,near_runners,live_runners,unseen_runners,killed,uncertain,held_called,logs,hammer,fresh,call_left,headline,detail");
		episodes.add("capture,kind,start_tick,end_tick,ticks,first_headline,first_detail");
		for (Path file : files)
		{
			List<RoundReplay.Frame> all = RoundReplay.run(RecordedRound.read(file));
			List<RoundReplay.Frame> frames = all.stream().filter(f -> f.snapshot.isInArena()
				&& f.snapshot.getRole() == Role.DEFENDER && f.snapshot.getWaveTick() >= 0 && !f.snapshot.isQueenAlive()).collect(Collectors.toList());
			if (frames.isEmpty()) continue;
			ReplayMetrics.Wave metrics = ReplayMetrics.measure(frames);
			int clear = -1, clearWave = -1, oldSupport = 0, support = 0, broken = 0, repair = 0, calls = 0, delayed = 0,
				empty = 0, emptyWork = 0, prep = 0, changes = 0, uncertain = 0;
			Set<Integer> southbound = new HashSet<>();
			Map<Integer, PenanceView> previousNpcs = new HashMap<>();
			Integer passed = null;
			for (RoundReplay.Frame f : all) if (f.snapshot.getWaveStats() != null && f.snapshot.getWaveStats().getTeamRunnersPassed() != null)
				passed = f.snapshot.getWaveStats().getTeamRunnersPassed();
			Map<String, List<RoundReplay.Frame>> active = new LinkedHashMap<>();
			for (RoundReplay.Frame f : frames)
			{
				Snapshot s = f.snapshot;
				for (Rec.Event event : RoundInvariants.events(f.raw, "npcDespawn"))
				{
					PenanceView last = previousNpcs.get(event.npc);
					if (PenanceType.forNpcId(event.id) == PenanceType.RUNNER && last != null && last.getTile() != null && !last.isDying()
						&& last.getTile().getY() <= ArenaTiles.safety(s.getWave()).getY() - 5) southbound.add(event.npc);
				}
				previousNpcs.clear();
				s.getPenance().forEach(n -> previousNpcs.put(n.getNpcIndex(), n));
				Instruction ins = f.instruction;
				Step work = work(ins);
				WorldPoint food = ArenaTiles.trapFood(s.getWave()), target = ins.getTarget().getTile();
				boolean finished = s.getCleared().contains(PenanceType.RUNNER);
				if (finished && clear < 0) { clear = s.getTick(); clearWave = s.getWaveTick(); }
				String recorded = f.raw.live == null ? "" : f.raw.live.step;
				if (!finished && "DEF_SUPPORT".equals(recorded)) oldSupport++;
				if (!finished && work == Step.DEF_SUPPORT) support++;
				if (!Objects.equals(work.name(), recorded) && !"CALL".equals(recorded)) changes++;
				List<PenanceView> runners = s.alive(PenanceType.RUNNER);
				int near = (int) runners.stream().filter(p -> !p.isUnseen() && p.getTile() != null && ArenaTiles.distance(p.getTile(), food) <= 5).count();
				int live = (int) runners.stream().filter(p -> !p.isUnseen()).count(), unseen = runners.size() - live;
				int good = s.getGroundItems().stream().filter(g -> BaIds.BAIT.contains(g.getItemId()) && g.isGood() && food.equals(g.getTile())).mapToInt(GroundItemView::getQuantity).sum();
				boolean repairWork = work == Step.DEF_REPAIR || "def.repair".equals(ins.getTask()) || "def.fix".equals(ins.getTask());
				boolean isBroken = !finished && s.getTrapCharges() == 0;
				boolean nearEmpty = !finished && near > 0 && good == 0;
				boolean localDrop = work == Step.DEF_DROP && food.equals(target) || "def.trapfood".equals(ins.getTask());
				boolean owedCall = ins.getStep() == Step.CALL;
				if (isBroken) { broken++; if (owedCall) calls++; else if (repairWork) repair++; else delayed++; }
				if (nearEmpty) { empty++; if (localDrop) emptyWork++; }
				if ("def.prepare".equals(ins.getTask())) prep++;
				uncertain = Math.max(uncertain, s.getUncertainRunners());
				Map<String, Boolean> flags = new LinkedHashMap<>();
				flags.put("broken_no_repair", isBroken && !repairWork && !owedCall);
				flags.put("near_empty", nearEmpty);
				flags.put("current_early_support", !finished && work == Step.DEF_SUPPORT);
				flags.put("recorded_early_support", !finished && "DEF_SUPPORT".equals(recorded));
				flags.put("uncertain_runners", !finished && s.getUncertainRunners() > 0);
				for (Map.Entry<String, Boolean> flag : flags.entrySet())
				{
					if (flag.getValue()) active.computeIfAbsent(flag.getKey(), k -> new ArrayList<>()).add(f);
					else finish(episodes, file.getFileName().toString(), flag.getKey(), active.remove(flag.getKey()));
				}
				timeline.add(csv(file.getFileName(), s.getTick(), s.getWaveTick(), recorded, work, ins.getTask(),
					s.getPlayerTile().getX() & 63, s.getPlayerTile().getY() & 63, target == null ? "" : target.getX() & 63,
					target == null ? "" : target.getY() & 63, s.getTrapCharges(), good, near, live, unseen,
					s.getRunnersKilled(), s.getUncertainRunners(), s.getListenCall() == null ? 0 : s.count(s.getListenCall().getItemId()),
					s.count(BaIds.LOGS), s.isHasHammer(), s.isListenFresh(), s.getTicksToCallChange(), ins.getHeadline(), ins.getDetail()));
			}
			for (Map.Entry<String, List<RoundReplay.Frame>> entry : active.entrySet()) finish(episodes, file.getFileName().toString(), entry.getKey(), entry.getValue());
			String row = csv(file.getFileName(), metrics.wave, frames.size(), clear, clearWave, southbound.size(), passed == null ? "" : passed,
				metrics.stepChanges, metrics.targetFlips, oldSupport, support, broken, repair, calls, delayed, empty, emptyWork, prep, changes, uncertain);
			summary.add(row);
			System.out.println(row);
		}
		Files.write(output.resolve("summary.csv"), summary);
		Files.write(output.resolve("timeline.csv"), timeline);
		Files.write(output.resolve("episodes.csv"), episodes);
	}

	private static Step work(Instruction ins) { return ins.getStep() == Step.CALL && ins.getThen() != null ? ins.getThen() : ins.getStep(); }

	private static void finish(List<String> rows, String name, String kind, List<RoundReplay.Frame> frames)
	{
		if (frames == null || frames.isEmpty()) return;
		RoundReplay.Frame first = frames.get(0), last = frames.get(frames.size() - 1);
		rows.add(csv(name, kind, first.raw.t, last.raw.t, frames.size(), first.instruction.getHeadline(), first.instruction.getDetail()));
	}

	private static String csv(Object... values)
	{
		return Arrays.stream(values).map(v -> "\"" + String.valueOf(v).replace("\"", "\"\"") + "\"").collect(Collectors.joining(","));
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.model.*;
import com.bautopilot.baautopilot.plan.*;
import com.bautopilot.baautopilot.state.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;

/** Fixed-observation audit of trap releases, off-food hold markers and routine departures. */
public final class DefenderTrapAudit
{
	public static void main(String[] args) throws Exception
	{
		Path input = Path.of(args[0]), output = Path.of(args[1]);
		Files.createDirectories(output);
		List<Path> files;
		try (java.util.stream.Stream<Path> stream = Files.list(input))
		{
			files = stream.filter(p -> p.toString().endsWith(".jsonl")).sorted().collect(Collectors.toList());
		}
		List<String> rows = new ArrayList<>(), summary = new ArrayList<>();
		rows.add("capture,tick,wave,step,task,charges,on_food,stacked,arriving,unseen,recent_unseen,bounded_release,committed_release,routine_departure,release_with_arrivals,multi_without_two,off_food_hold,headline,detail");
		summary.add("capture,ticks,routine_departures,release_with_arrivals,multi_without_two,off_food_holds");
		for (Path file : files)
		{
			int ticks = 0, departures = 0, releases = 0, charges = 0, holds = 0;
			for (RoundReplay.Frame frame : RoundReplay.run(RecordedRound.read(file)))
			{
				Snapshot s = frame.snapshot;
				if (!s.isInArena() || s.getRole() != Role.DEFENDER || s.isQueenAlive()) continue;
				ticks++;
				WorldPoint food = ArenaTiles.trapFood(s.getWave());
				Instruction ins = frame.instruction;
				Step step = ins.getStep();
				List<PenanceView> runners = s.alive(PenanceType.RUNNER);
				long stacked = runners.stream().filter(p -> !p.isUnseen() && p.getTile() != null && ArenaTiles.distance(p.getTile(), food) <= 1).count();
				long arriving = runners.stream().filter(p -> !p.isUnseen() && p.getTile() != null
					&& ArenaTiles.distance(p.getTile(), food) > 1 && p.getTile().getY() >= food.getY() - 1).count();
				long unseen = runners.stream().filter(PenanceView::isUnseen).count();
				// One runner cycle: older unseen locations are unconfirmed, not an arrival deadline.
				long recentUnseen = runners.stream().filter(p -> p.isUnseen() && p.getUnseenTicks() <= 10).count();
				boolean onFood = food.equals(s.getPlayerTile());
				boolean multi = "def.step".equals(ins.getTask()) && step == Step.DEF_STEP;
				TaskMemory.Progress stack = s.getTasks().getEntries().get("def.stack");
				boolean bounded = multi && stack != null && s.getTick() - stack.getLastProgressTick() >= 10;
				Target committed = s.getTasks().target("def.step");
				boolean continuing = multi && committed != null && ArenaTiles.trapStep(s.getWave()).equals(committed.getTile());
				boolean premature = multi && arriving + recentUnseen > 0 && !bounded && !continuing;
				boolean one = multi && s.getTrapCharges() != 2;
				boolean offHold = step == Step.DEF_HOLD && onFood && ins.getTarget().getTile() != null
					&& !food.equals(ins.getTarget().getTile());
				boolean departure = onFood && stacked + arriving + unseen > 0 && step != Step.DEF_REPAIR
					&& ins.getTarget().getTile() != null && ArenaTiles.distance(food, ins.getTarget().getTile()) > 1;
				if (departure) departures++;
				if (premature) releases++;
				if (one) charges++;
				if (offHold) holds++;
				rows.add(csv(file.getFileName(), s.getTick(), s.getWave(), step, ins.getTask(), s.getTrapCharges(), onFood,
					stacked, arriving, unseen, recentUnseen, bounded, continuing, departure, premature, one, offHold, ins.getHeadline(), ins.getDetail()));
			}
			if (ticks > 0) summary.add(csv(file.getFileName(), ticks, departures, releases, charges, holds));
		}
		Files.write(output.resolve("decisions.csv"), rows);
		Files.write(output.resolve("summary.csv"), summary);
		System.out.println(String.join("\n", summary));
	}
	private static String csv(Object... values)
	{
		return Arrays.stream(values).map(v -> "\"" + String.valueOf(v).replace("\"", "\"\"") + "\"").collect(Collectors.joining(","));
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.model.WaveInfo;
import com.bautopilot.baautopilot.plan.Step;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/** Decision audit on the recorded path; deliberately makes no claim about counterfactual kills. */
public final class HealerPriorityAudit
{
	private HealerPriorityAudit() { }

	public static void main(String[] args) throws Exception
	{
		Path directory = Path.of(args.length > 0 ? args[0] : "src/test/resources/recordings");
		Path output = Path.of(args.length > 1 ? args[1] : "build/reports/healer-priority");
		Files.createDirectories(output);
		List<String> summary = new ArrayList<>(List.of("recording,ticks,feeding_opportunities,missed_refresh,wrong_poison_priority,wounded_before_healthy,full_poison_feeds,reserve_finish_ticks,unjustified_full_poison_feeds"));
		List<String> decisions = new ArrayList<>(List.of("recording,tick,step,target_order,target_poison,target_hp_fraction,lowest_poison,missed_refresh,wrong_poison_priority,wounded_before_healthy,healers,detail,task,killed,reserve_kills_needed,held_food,ticks_to_call,recorded_headline"));
		List<Path> files;
		try (Stream<Path> listing = Files.list(directory))
		{
			files = listing.filter(p -> p.toString().endsWith(".jsonl")).sorted().collect(Collectors.toList());
		}
		for (Path file : files)
		{
			RecordedRound round = RecordedRound.read(file);
			List<RoundReplay.Frame> frames = RoundReplay.run(round).stream()
				.filter(f -> f.snapshot.isInArena() && f.snapshot.getRole() == Role.HEALER).collect(Collectors.toList());
			if (frames.isEmpty()) continue;
			int opportunities = 0, missed = 0, wrong = 0, wounded = 0, full = 0, finishes = 0, unjustified = 0;
			for (RoundReplay.Frame frame : frames)
			{
				Snapshot s = frame.snapshot;
				Step step = frame.instruction.getStep();
				List<PenanceView> healers = s.alive(PenanceType.HEALER);
				PenanceView target = step != Step.HEAL_FEED ? null : healers.stream()
					.filter(h -> h.getNpcIndex() == frame.instruction.getTarget().getId()).findFirst().orElse(null);
				int poison = target == null ? -1 : target.nextPoisonHit(s.getTick());
				int lowest = healers.stream().mapToInt(h -> h.nextPoisonHit(s.getTick())).min().orElse(4);
				boolean work = Set.of(Step.HEAL_FEED, Step.HEAL_WAIT, Step.HEAL_SUPPORT, Step.HEAL_TAKE_FOOD).contains(step)
					&& s.isListenFresh() && s.getListenCall() != null && s.has(s.getListenCall().getItemId());
				boolean missedTick = work && lowest < 4 && target == null;
				boolean wrongTick = work && target != null && poison > lowest;
				boolean woundedTick = work && target != null && poison == 0 && target.hpFraction() <= 0.5
					&& healers.stream().anyMatch(h -> !h.isUnseen() && h.nextPoisonHit(s.getTick()) == 0 && h.hpFraction() >= 0.9);
				if (work && lowest < 4) opportunities++;
				if (missedTick) missed++;
				if (wrongTick) wrong++;
				if (woundedTick) wounded++;
				if (poison >= 4) full++;
				boolean finish = "heal.reserve".equals(frame.instruction.getTask());
				int reserveKills = Math.max(0, WaveInfo.healersTotal(s.getWave()) - WaveInfo.healersInitial(s.getWave()) - s.getHealersKilled());
				int held = s.getListenCall() == null ? 0 : s.count(s.getListenCall().getItemId());
				if (finish) finishes++;
				if (poison >= 4 && (!finish || reserveKills == 0 || lowest < 4 || target.isUnseen()
					|| s.walk(target.getTile()) > 8 || held <= Math.max(0, WaveInfo.healersTotal(s.getWave()) - s.getHealersKilled() - healers.size()))) unjustified++;
				String state = healers.stream().map(h -> h.getOrder() + ":p" + h.nextPoisonHit(s.getTick())
					+ ":hp" + h.getHealthRatio() + "/" + h.getHealthScale() + ":last" + h.getLastFoodTick()
					+ ":food" + h.getFoods() + ":d" + s.walk(h.getTile()) + (h.isUnseen() ? ":unseen" : "")).collect(Collectors.joining(";"));
				decisions.add(round.name() + "," + s.getTick() + "," + step + "," + (target == null ? -1 : target.getOrder())
					+ "," + poison + "," + (target == null ? -1 : target.hpFraction()) + "," + lowest + "," + missedTick
					+ "," + wrongTick + "," + woundedTick + "," + state + "," + clean(frame.instruction.getDetail())
					+ "," + frame.instruction.getTask() + "," + s.getHealersKilled() + "," + reserveKills + "," + held
					+ "," + s.getTicksToCallChange() + "," + clean(frame.raw.live == null ? "" : frame.raw.live.headline));
			}
			String line = round.name() + "," + frames.size() + "," + opportunities + "," + missed + "," + wrong + "," + wounded + "," + full + "," + finishes + "," + unjustified;
			summary.add(line);
			System.out.println(line);
		}
		Files.write(output.resolve("summary.csv"), summary);
		Files.write(output.resolve("decisions.csv"), decisions);
	}

	private static String clean(String text)
	{
		return text == null ? "" : text.replace(',', ';').replace('\n', '|').replace('\r', ' ');
	}
}

