		int id = at(frames, 2199).instruction.getTarget().getId();
		for (int tick : new int[]{2199, 2200, 2201, 2202})
		{
			RoundReplay.Frame frame = at(frames, tick);
			assertEquals("HEAL_SUPPORT", frame.raw.live.step);
			assertEquals("heal.reserve", frame.instruction.getTask());
			assertEquals(id, frame.instruction.getTarget().getId());
			assertTrue(frame.snapshot.alive(PenanceType.HEALER).stream().anyMatch(h -> h.getOrder() == 2
				&& h.getNpcIndex() == id));
		}
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.plan.Step;
import com.bautopilot.baautopilot.state.Snapshot;
import com.bautopilot.baautopilot.state.TeammateView;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

/** Fixed-observation audit of Queen healing versus egg prompts. */
public final class QueenHealerAudit
{
	public static void main(String[] args) throws Exception
	{
		RecordedRound round = RecordedRound.read(Path.of(args[0]));
		Path output = Path.of(args[1]);
		Files.createDirectories(output);
		List<String> rows = new ArrayList<>();
		rows.add("tick,step,own_hp,own_max,worst_name,worst_hp,worst_max,vial_charges,yellow,poisoned,egg_with_team_below_60,egg_with_self_below_60,score,reason");
		int ticks = 0, eggs = 0, own = 0, team = 0, fills = 0, riskyTeam = 0, riskySelf = 0;
		for (RoundReplay.Frame f : RoundReplay.run(round))
		{
			Snapshot s = f.snapshot;
			if (s.getRole() != Role.HEALER || !s.isInArena() || !s.isQueenAlive()) continue;
			ticks++;
			Step step = f.instruction.getStep();
			boolean egg = step == Step.QUEEN_DUNK || step == Step.QUEEN_PASS;
			TeammateView worst = s.getTeammates().stream().filter(t -> t.getMaxHp() > 0)
				.min(Comparator.comparingDouble(TeammateView::fraction)).orElse(null);
			boolean teamLow = egg && worst != null && worst.fraction() < .6;
			boolean selfLow = egg && s.hpFraction() < .6;
			if (egg) eggs++;
			if (step == Step.RETREAT) own++;
			if (step == Step.HEAL_TEAMMATE) team++;
			if (step == Step.HEAL_FILL_VIAL) fills++;
			if (teamLow) riskyTeam++;
			if (selfLow) riskySelf++;
			rows.add(csv(s.getTick(), step, s.getHp(), s.getMaxHp(), worst == null ? "" : worst.getName(),
				worst == null ? -1 : worst.getHp(), worst == null ? -1 : worst.getMaxHp(), BaIds.vialCharges(s::has),
				s.count(BaIds.EGG_YELLOW), s.count(BaIds.EGG_POISONED), teamLow, selfLow,
				f.instruction.getScore(), f.instruction.getDecidedBy()));
		}
		Files.write(output.resolve("decisions.csv"), rows);
		String summary = "queen_ticks,egg_ticks,self_heal_ticks,team_heal_ticks,vial_ticks,eggs_with_team_below_60,eggs_with_self_below_60\n"
			+ csv(ticks, eggs, own, team, fills, riskyTeam, riskySelf) + "\n";
		Files.writeString(output.resolve("summary.csv"), summary);
		System.out.print(summary);
	}
	private static String csv(Object... values)
	{
		return Arrays.stream(values).map(v -> "\"" + String.valueOf(v).replace("\"", "\"\"") + "\"").collect(Collectors.joining(","));
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.plan.Settings;
import com.bautopilot.baautopilot.model.Role;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.util.List;
import java.util.Map;

/**
 * The JSONL recording format: one {@link Header} line, then one {@link Tick} line per game tick.
 * Raw game inputs only (texts keep their tags), plus the live plugin's result under {@code live}.
 * Absent fields are null and left out of the line.
 */
final class Rec
{
	static final int VERSION = 1;

	/** Compact (one object per line); maps with int keys round-trip through string keys. */
	static final Gson GSON = new GsonBuilder().create();

	private Rec()
	{
	}

	static final class Header
	{
		String type = "header";
		int version = VERSION;
		/** Local wall time the segment started. */
		String started;
		String pluginVersion;
		/** Identifies the recorder/decision changes used for the next-run reliability validation. */
		String recorderBuild;
		/** Old recordings: the strategy mode they were made with (no longer used). */
		String strategy;
		Settings settings;
	}

	static final class Tick
	{
		String type = "tick";
		/** client.getTickCount() */
		int t;
		/** Milliseconds since the segment started. */
		long ms;
		boolean instance;
		/** Player template tile (instance template coordinates, as the tracker sees it). */
		Pos tile;
		/** RoundLogic.HUD_COMPONENTS that are visible -> raw widget text. */
		Map<Integer, String> hud;
		/** Inventory item id -> count. */
		Map<Integer, Integer> inv;
		int free;
		int ammo = -1;
		boolean imcandoWorn;
		int hp;
		int maxHp;
		/** NPC index the player is interacting with (attacking), null for none. */
		Integer interacting;
		/** Varbit id -> value: egg loads 3257/3258/3259/3266, AREAEXIT 3923. */
		Map<Integer, Integer> vb;
		/** Every penance NPC in the scene. */
		List<Npc> npcs;
		/** Tracked ground items (bait, eggs, logs, hammer). */
		List<Ground> ground;
		/** Tracked objects (machines, trap, hoppers, ...); only written when the set changed. */
		List<Obj> objects;
		/** Other players in the scene (names anonymised) with their spot-animations. */
		List<Plr> players;
		/** Graphics objects in the scene (id + tile), to find role rings drawn as effects. */
		List<Obj> gfx;
		/** Events since the previous tick line, in arrival order. */
		List<Event> ev;
		/** What the live plugin made of this tick. */
		Live live;
	}

	static final class Pos
	{
		int x;
		int y;
		int p;

		Pos(int x, int y, int p)
		{
			this.x = x;
			this.y = y;
			this.p = p;
		}
	}

	static final class Npc
	{
		int i;
		int id;
		Pos tile;
		int hr;
		int hs;
		boolean dead;
		int anim;
		/** NPC speech, e.g. a runner's good/bad-food reaction; absent in older captures. */
		String overhead;
		int[] spot;
	}

	static final class Plr
	{
		String n;
		Role role;
		Pos tile;
		int anim;
		/** Directed public interaction, anonymised; absent in old captures. */
		String interacting;
		int[] spot;
	}

	static final class Ground
	{
		/** Recorder-assigned identity of the TileItem (stable while it lies there). */
		int uid;
		int id;
		int qty;
		Pos tile;
	}

	static final class Obj
	{
		int id;
		Pos tile;

		Obj(int id, Pos tile)
		{
			this.id = id;
			this.tile = tile;
		}
	}

	/**
	 * A discrete event. {@code k} is one of chat, menu, npcSpawn, npcDespawn, death, graphic,
	 * itemSpawn, itemDespawn, gameState.
	 */
	static final class Event
	{
		int t;
		String k;
		/** chat: ChatMessageType name; gameState: GameState name; menu: MenuAction name. */
		String type;
		/** chat sender / dead player, anonymised ("Me", "Player2", ...). */
		String name;
		/** chat message (raw, with tags). */
		String text;
		String option;
		String target;
		/** NPC index (menu target, spawn, death, graphic). */
		Integer npc;
		/** NPC or item id. */
		Integer id;
		/** menu: the selected (used) widget's item id; the clicked item id. */
		Integer selected;
		Integer item;
		/** menu: the clicked interface component (packed group << 16 | child), for widget clicks. */
		Integer widget;
		Integer uid;
		Integer qty;
		Pos tile;
		int[] spot;
	}

	static final class Live
	{
		String role;
		int wave;
		int period;
		int toChange;
		int waveTick;
		String listen;
		boolean fresh;
		String source;
		String shout;
		boolean shoutDone;
		/** Null in older recordings; confirmed red/green ammunition consumption tick, -1 when unknown. */
		Integer lastLauncherShotTick;
		boolean coordinated;
		String step;
		String task;
		/** Unfinished obligation id -> current status and blocking reason, when any. */
		Map<String, String> tasks;
		String headline;
		String detail;
		List<Integer> items;
		/** Healer NPC index -> foods counted. */
		Map<Integer, Integer> foods;
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.model.HealCodeSet;
import com.bautopilot.baautopilot.plan.Settings;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.BufferedReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** A recording made by {@link BaRecorderPlugin}, read back from its JSONL file. */
public final class RecordedRound
{
	final Path source;
	final Rec.Header header;
	final List<Rec.Tick> ticks;

	RecordedRound(Path source, Rec.Header header, List<Rec.Tick> ticks)
	{
		this.source = source;
		this.header = header;
		this.ticks = Collections.unmodifiableList(ticks);
	}

	public static RecordedRound read(Path file) throws IOException
	{
		Rec.Header header = null;
		List<Rec.Tick> ticks = new ArrayList<>();
		try (BufferedReader in = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			String line;
			int n = 0;
			while ((line = in.readLine()) != null)
			{
				n++;
				if (line.trim().isEmpty())
				{
					continue;
				}
				JsonObject o;
				try
				{
					o = new JsonParser().parse(line).getAsJsonObject();
				}
				catch (RuntimeException e)
				{
					// The last line of a recording cut short by a crash may be partial
					continue;
				}
				String type = o.has("type") ? o.get("type").getAsString() : "";
				if ("header".equals(type))
				{
					header = Rec.GSON.fromJson(o, Rec.Header.class);
					if (o.has("settings") && o.get("settings").isJsonObject())
					{
						header.settings = settings(o.getAsJsonObject("settings"));
					}
				}
				else if ("tick".equals(type))
				{
					ticks.add(Rec.GSON.fromJson(o, Rec.Tick.class));
				}
				else
				{
					throw new IOException(file + ":" + n + ": unknown line type '" + type + "'");
				}
			}
		}
		if (header == null)
		{
			header = new Rec.Header();
		}
		if (header.version > Rec.VERSION)
		{
			throw new IOException(file + ": recording version " + header.version + " is newer than this reader (" + Rec.VERSION + ")");
		}
		return new RecordedRound(file, header, ticks);
	}

	/**
	 * Recorded settings laid over today's defaults: Gson skips Lombok's builder defaults, so a
	 * setting added after the recording would otherwise replay as false/null (safety bait off,
	 * no heal code). The old {@code healCodes} flag maps to the Regular codes or Off.
	 */
	static Settings settings(JsonObject recorded)
	{
		JsonObject merged = Rec.GSON.toJsonTree(Settings.builder().build()).getAsJsonObject();
		for (java.util.Map.Entry<String, com.google.gson.JsonElement> e : recorded.entrySet())
		{
			merged.add(e.getKey(), e.getValue());
		}
		if (recorded.has("healCodes") && !recorded.has("healCodeSet"))
		{
			merged.addProperty("healCodeSet", recorded.get("healCodes").getAsBoolean()
				? HealCodeSet.REGULAR.name() : HealCodeSet.OFF.name());
		}
		return Rec.GSON.fromJson(merged, Settings.class);
	}

	public String name()
	{
		return source == null ? "(in memory)" : source.getFileName().toString();
	}
}

package com.bautopilot.baautopilot.dev;

