	@Test
	public void everyRecordingHoldsItsInvariants() throws IOException
	{
		List<Path> files;
		try (Stream<Path> s = Files.isDirectory(RECORDINGS) ? Files.list(RECORDINGS) : Stream.empty())
		{
			files = s.filter(p -> p.getFileName().toString().endsWith(".jsonl")).sorted().collect(Collectors.toList());
		}
		Assume.assumeFalse("no recordings in " + RECORDINGS.toAbsolutePath(), files.isEmpty());

		StringBuilder failures = new StringBuilder();
		for (Path file : files)
		{
			RecordedRound round = RecordedRound.read(file);
			List<RoundReplay.Frame> frames = RoundReplay.run(round);
			RoundInvariants.Report report = RoundInvariants.check(round, frames);
			System.out.println(round.name() + ": " + frames.size() + " ticks, " + report.violations.size() + " violations");
			report.notes.forEach(n -> System.out.println("  " + n));
			if (!report.violations.isEmpty())
			{
				failures.append('\n').append(round.name()).append(':');
				report.violations.stream().limit(MAX_LISTED).forEach(v -> failures.append("\n  ").append(v));
				if (report.violations.size() > MAX_LISTED)
				{
					failures.append("\n  ... and ").append(report.violations.size() - MAX_LISTED).append(" more");
				}
			}
		}
		if (failures.length() > 0)
		{
			fail("Recorded rounds broke invariants (gradlew replay -Pfile=<file> shows the timeline):" + failures);
		}
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.state.CallClock;

import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.plan.Settings;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.TreeMap;
import java.util.function.Consumer;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.widgets.WidgetUtil;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The replay harness itself, on a synthetic healer wave written in the recorder's format: it must
 * read back, replay, pass the invariants, and flag a broken clock and an unreadable horn line.
 * This is not evidence about the game; real rounds go in src/test/resources/recordings.
 */
public class ReplayHarnessTest
{
	/** HUD flips below are at 155/205, so the wave message sits START_OFFSET + 50 ticks before 155. */
	private static final int WAVE_MSG = 155 - 50 - CallClock.START_OFFSET;
	private static final int HEALER_NPC = 50;

	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	@Test
	public void syntheticHealerWaveReplaysClean() throws IOException
	{
		RecordedRound round = roundTrip(healerWave(WAVE_MSG, null));
		assertEquals(5, round.header.settings.getCollectorLoadAt());

		List<RoundReplay.Frame> frames = RoundReplay.run(round);
		RoundInvariants.Report report = RoundInvariants.check(round, frames);
		assertEquals(report.violations.toString(), 0, report.violations.size());

		RoundReplay.Frame afterChat = frame(frames, 111);
		assertEquals(Role.HEALER, afterChat.snapshot.getRole());
		assertEquals(1, afterChat.snapshot.getWave());
		assertEquals(BaCall.POISON_WORMS, afterChat.snapshot.getListenCall());
		assertTrue(afterChat.snapshot.isListenFresh());

		// Own food is counted once; neither poison animation establishes another feed.
		assertEquals(1, frame(frames, 120).snapshot.getPenance().get(0).getFoods());
		assertEquals(1, frame(frames, 141).snapshot.getPenance().get(0).getFoods());

		// Second call: stale until the defender calls meat
		assertEquals(1, frame(frames, 157).snapshot.getCallPeriod());
		assertTrue(!frame(frames, 157).snapshot.isListenFresh());
		assertEquals(BaCall.POISON_MEAT, frame(frames, 161).snapshot.getListenCall());
		assertTrue(report.notes.toString(), report.notes.stream().anyMatch(n -> n.contains("call 1: +0")));
	}

	@Test
	public void poisonAnimationBeforeOurClickDoesNotCountAsFood() throws IOException
	{
		// An uninjured healer animates at 114; our food is only confirmed at 116.
		RecordedRound round = roundTrip(healerWave(WAVE_MSG, ticks -> at(ticks, 114).ev = events(graphic(114))));
		List<RoundReplay.Frame> frames = RoundReplay.run(round);
		assertEquals(0, frame(frames, 114).snapshot.getPenance().get(0).nextPoisonHit(114));
		assertEquals(1, frame(frames, 120).snapshot.getPenance().get(0).getFoods());
		RoundInvariants.Report report = RoundInvariants.check(round, frames);
		assertTrue(report.violations.toString(), report.violations.isEmpty());
	}

	@Test
	public void flagsACallJumpTheClockCannotFollow()
	{
		// The second flip comes 15 ticks early: beyond the clock's 10-tick re-anchor window
		Role me = Role.HEALER;
		List<RoundReplay.Frame> frames = RoundReplay.run(roundTripUnchecked(healerWave(WAVE_MSG, ticks ->
		{
			for (int t = 190; t < 205; t++)
			{
				at(ticks, t).hud.put(me.getShoutComponent(), "Crackers");
			}
		})));
		RoundInvariants.Report report = RoundInvariants.check(null, frames);
		assertTrue(report.violations.toString(), report.violations.stream().anyMatch(v -> v.startsWith("clock:")));
	}

	@Test
	public void flagsAnUnreadableHornLine()
	{
		List<RoundReplay.Frame> frames = RoundReplay.run(roundTripUnchecked(healerWave(WAVE_MSG,
			ticks -> at(ticks, 130).ev = events(chat(130, "PUBLICCHAT", "Player2", "Healer: Poison cake!")))));
		RoundInvariants.Report report = RoundInvariants.check(null, frames);
		assertTrue(report.violations.toString(), report.violations.stream().anyMatch(v -> v.contains("not understood")));
	}

	// ------------------------------------------------------------------ synthetic wave

	/** Ticks 90-229 of a wave-1 healer in the arena; {@code tweak} edits the lines before writing. */
	private static List<Object> healerWave(int waveMsg, Consumer<List<Rec.Tick>> tweak)
	{
		Role me = Role.HEALER;
		WorldPoint spot = WorldPoint.fromRegion(7509, 30, 30, 0);
		List<Rec.Tick> ticks = new ArrayList<>();
		int worms = 0;
		for (int t = 90; t < 230; t++)
		{
			Rec.Tick k = new Rec.Tick();
			k.t = t;
			k.instance = true;
			k.tile = new Rec.Pos(spot.getX(), spot.getY(), 0);
			k.hp = 99;
			k.maxHp = 99;
			k.free = 28;
			k.hud = new TreeMap<>();
			if (t >= 101)
			{
				k.hud.put(WidgetUtil.packComponentId(me.getHudGroup(), 0), "");
				k.hud.put(WidgetUtil.packComponentId(me.getHudGroup(), 5), "Wave 1");
				k.hud.put(me.getShoutComponent(), t < 105 ? "-" : t < 155 ? "Tofu" : t < 205 ? "Worms" : "Crackers");
				k.hud.put(me.getListenComponent(), t < 110 ? "-" : t < 160 ? "Pois. Worms" : "Pois. Meat");
			}
			if (t == 112)
			{
				worms = 3;
			}
			if (t == 116)
			{
				worms = 2;
			}
			k.inv = new TreeMap<>();
			if (worms > 0)
			{
				k.inv.put(ItemID.BARBASSAULT_POISION_02, worms);
			}
			if (t >= 106)
			{
				Rec.Npc n = new Rec.Npc();
				n.i = HEALER_NPC;
				n.id = NpcID.BARBASSAULT_PEN_HEALER_LV1;
				n.tile = new Rec.Pos(spot.getX() + 3, spot.getY(), 0);
				n.hr = -1;
				n.hs = -1;
				k.npcs = new ArrayList<>(List.of(n));
			}
			ticks.add(k);
		}
		at(ticks, waveMsg).ev = events(chat(waveMsg, "GAMEMESSAGE", null, "<col=ef1020>---- Wave: 1 ----</col>"));
		Rec.Event spawn = new Rec.Event();
		spawn.t = 106;
		spawn.k = "npcSpawn";
		spawn.npc = HEALER_NPC;
		spawn.id = NpcID.BARBASSAULT_PEN_HEALER_LV1;
		at(ticks, 106).ev = events(spawn);
		at(ticks, 110).ev = events(chat(110, "PUBLICCHAT", "Player2", "Healer: Poison worms!"));
		Rec.Event use = new Rec.Event();
		use.t = 115;
		use.k = "menu";
		use.type = "WIDGET_TARGET_ON_NPC";
		use.option = "Use";
		use.target = "Poisoned worms -> Penance Healer";
		use.npc = HEALER_NPC;
		use.id = NpcID.BARBASSAULT_PEN_HEALER_LV1;
		use.selected = ItemID.BARBASSAULT_POISION_02;
		at(ticks, 115).ev = events(use);
		at(ticks, 117).ev = events(graphic(117));
		at(ticks, 140).ev = events(graphic(140));
		at(ticks, 160).ev = events(chat(160, "PUBLICCHAT", "Player2", "Healer: Poison meat!"));
		if (tweak != null)
		{
			tweak.accept(ticks);
		}

		Rec.Header h = new Rec.Header();
		h.started = "synthetic";
		h.settings = Settings.builder().build();
		List<Object> lines = new ArrayList<>();
		lines.add(h);
		lines.addAll(ticks);
		return lines;
	}

	private static Rec.Tick at(List<Rec.Tick> ticks, int t)
	{
		return ticks.get(t - 90);
	}

	private static Rec.Event chat(int t, String type, String name, String text)
	{
		Rec.Event e = new Rec.Event();
		e.t = t;
		e.k = "chat";
		e.type = type;
		e.name = name;
		e.text = text;
		return e;
	}

	private static Rec.Event graphic(int t)
	{
		Rec.Event e = new Rec.Event();
		e.t = t;
		e.k = "graphic";
		e.npc = HEALER_NPC;
		e.id = NpcID.BARBASSAULT_PEN_HEALER_LV1;
		e.spot = new int[]{863};
		return e;
	}

	private static List<Rec.Event> events(Rec.Event... e)
	{
		return new ArrayList<>(List.of(e));
	}

	private static RoundReplay.Frame frame(List<RoundReplay.Frame> frames, int tick)
	{
		return frames.stream().filter(f -> f.raw.t == tick).findFirst().orElseThrow(AssertionError::new);
	}

	private RecordedRound roundTrip(List<Object> lines) throws IOException
	{
		Path file = tmp.newFile("synthetic.jsonl").toPath();
		try (BufferedWriter w = Files.newBufferedWriter(file, StandardCharsets.UTF_8))
		{
			for (Object line : lines)
			{
				w.write(Rec.GSON.toJson(line));
				w.newLine();
			}
		}
		return RecordedRound.read(file);
	}

	private RecordedRound roundTripUnchecked(List<Object> lines)
	{
		try
		{
			return roundTrip(lines);
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.plan.Instruction;
import com.bautopilot.baautopilot.plan.Step;
import com.bautopilot.baautopilot.plan.Target;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.TreeMap;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.api.coords.WorldPoint;

/**
 * Stability and timeliness of the guidance over one replayed wave: how often the instruction and
 * its target change (and flip back), how many ticks into each call period the call is first
 * prompted, and for the defender how escaping runners were answered. The player's moves come from
 * the recording, so these measure the planner on the path actually walked.
 *
 * <pre>gradlew metrics [-Pdir=src/test/resources/recordings]</pre>
 */
public final class ReplayMetrics
{
	/** A change back to what was shown before, after the other one lasted at most this long. */
	static final int FLIP_TICKS = 5;
	/** Same rule as the defender's relure: a runner this far south of the trap food is heading out. */
	static final int ESCAPING_SOUTH = 2;
	static final int STACK_RADIUS = 2;
	/** Same rule as RoundLogic.escaped: last seen this far south of the safety bait. */
	static final int ESCAPE_SOUTH_OF_SAFETY = 5;

	/** One wave's numbers. */
	public static final class Wave
	{
		public Role role;
		public int wave;
		public int ticks;
		/** Work-step changes (calls left out: a call is a horn click on the way, not a new task). */
		public int stepChanges;
		public int stepFlips;
		public int targetChanges;
		public int targetFlips;
		/** Ticks into each call period of the first call prompt, -1 when never prompted. */
		public final TreeMap<Integer, Integer> callPrompt = new TreeMap<>();
		/** Defender: runners that left through the exit, escape episodes, relure prompts, latency. */
		public int escapes;
		public int escaping;
		public int relured;
		public int relureLatency;

		public String line(String name)
		{
			String calls = callPrompt.entrySet().stream()
				.map(e -> (e.getKey() + 1) + ":" + (e.getValue() < 0 ? "-" : "+" + e.getValue()))
				.collect(Collectors.joining(" "));
			String def = role != Role.DEFENDER ? "" : String.format(" | runners heading out %d, relured %d (avg %.1f ticks to prompt), escaped %d",
				escaping, relured, relured == 0 ? 0.0 : relureLatency / (double) relured, escapes);
			return String.format("%-28s %-9s w%-2d %4d ticks | steps %3d (flips %2d) | targets %3d (flips %2d) | call prompt %s%s",
				name, role == null ? "-" : role.name().toLowerCase(), wave, ticks, stepChanges, stepFlips, targetChanges, targetFlips,
				calls, def);
		}
	}

	private ReplayMetrics()
	{
	}

	public static Wave measure(List<RoundReplay.Frame> frames)
	{
		Wave w = new Wave();
		List<Object> steps = new ArrayList<>();
		List<Object> targets = new ArrayList<>();
		int period = -1;
		List<int[]> heading = new ArrayList<>(); // {npcIndex, firstTick}
		java.util.Map<Integer, PenanceView> lastSeen = new java.util.HashMap<>();
		for (RoundReplay.Frame f : frames)
		{
			Snapshot s = f.snapshot;
			Instruction ins = f.instruction;
			if (!s.isInArena() || s.getRole() == null)
			{
				continue;
			}
			w.ticks++;
			w.role = s.getRole();
			w.wave = Math.max(w.wave, s.getWave());
			boolean prompting = ins.getStep() == Step.CALL || ins.getAlsoCall() != null;
			if (ins.getStep() != Step.CALL)
			{
				steps.add(ins.getStep());
			}
			targets.add(identity(ins.getTarget()));

			if (s.getTicksToCallChange() >= 0 && s.getCallPeriod() != period)
			{
				period = s.getCallPeriod();
				w.callPrompt.put(period, -1);
			}
			if (prompting && period >= 0 && w.callPrompt.get(period) < 0)
			{
				w.callPrompt.put(period, Math.max(0, s.ticksIntoCall()));
			}

			if (s.getRole() == Role.DEFENDER && s.getWave() > 0)
			{
				defender(w, f, heading, lastSeen);
			}
		}
		count(steps, true, w);
		count(targets, false, w);
		return w;
	}

	private static void defender(Wave w, RoundReplay.Frame f, List<int[]> heading, java.util.Map<Integer, PenanceView> lastSeen)
	{
		Snapshot s = f.snapshot;
		for (Rec.Event e : RoundInvariants.events(f.raw, "npcDespawn"))
		{
			PenanceView last = e.npc == null ? null : lastSeen.get(e.npc);
			if (PenanceType.forNpcId(e.id) == PenanceType.RUNNER && last != null && last.getTile() != null && !last.isDying()
				&& last.getTile().getY() <= ArenaTiles.safety(s.getWave()).getY() - ESCAPE_SOUTH_OF_SAFETY)
			{
				w.escapes++;
			}
		}
		lastSeen.clear();
		s.getPenance().forEach(p -> lastSeen.put(p.getNpcIndex(), p));

		WorldPoint trap = ArenaTiles.trapFood(s.getWave());
		boolean relure = f.instruction.getStep() == Step.DEF_RELURE;
		for (PenanceView p : s.penance(PenanceType.RUNNER))
		{
			boolean out = p.getTile() != null && p.getTile().getY() <= trap.getY() - ESCAPING_SOUTH
				&& ArenaTiles.distance(p.getTile(), trap) > STACK_RADIUS;
			int[] episode = heading.stream().filter(h -> h[0] == p.getNpcIndex()).findFirst().orElse(null);
			if (out && episode == null)
			{
				heading.add(new int[]{p.getNpcIndex(), f.raw.t, 0});
				w.escaping++;
				episode = heading.get(heading.size() - 1);
			}
			else if (!out && episode != null)
			{
				heading.remove(episode);
				episode = null;
			}
			if (episode != null && relure && episode[2] == 0)
			{
				episode[2] = 1;
				w.relured++;
				w.relureLatency += f.raw.t - episode[1];
			}
		}
	}

	/** Changes, and changes straight back after a short detour (A, B for at most FLIP_TICKS, A). */
	private static void count(List<Object> seq, boolean steps, Wave w)
	{
		int changes = 0;
		int flips = 0;
		Object before = null;
		Object current = null;
		int heldSince = 0;
		for (int i = 0; i < seq.size(); i++)
		{
			Object now = seq.get(i);
			if (i == 0)
			{
				current = now;
				continue;
			}
			if (!Objects.equals(now, current))
			{
				changes++;
				if (Objects.equals(now, before) && i - heldSince <= FLIP_TICKS)
				{
					flips++;
				}
				before = current;
				current = now;
				heldSince = i;
			}
		}
		if (steps)
		{
			w.stepChanges = changes;
			w.stepFlips = flips;
		}
		else
		{
			w.targetChanges = changes;
			w.targetFlips = flips;
		}
	}

	/** NPC targets by index (they move), the rest by kind and tile. */
	private static Object identity(Target t)
	{
		if (t.getKind() == Target.Kind.NPC)
		{
			return "npc" + t.getId();
		}
		if (t.getKind() == Target.Kind.PLAYER)
		{
			return "player" + t.getLabel();
		}
		return t.getKind() + "@" + (t.getTile() == null ? "-" : t.getTile().getX() + "," + t.getTile().getY());
	}

	public static void main(String[] args) throws Exception
	{
		Path dir = Paths.get(args.length > 0 && !args[0].isEmpty() ? args[0] : RecordedRoundsTest.RECORDINGS.toString());
		List<Path> files;
		try (Stream<Path> s = Files.list(dir))
		{
			files = s.filter(p -> p.getFileName().toString().endsWith(".jsonl")).sorted().collect(Collectors.toList());
		}
		// -Pdump=<dir>: also one line per in-arena tick per wave, to diff two versions of the planner
		Path dump = args.length > 1 && !args[1].isEmpty() ? Paths.get(args[1]) : null;
		if (dump != null)
		{
			Files.createDirectories(dump);
		}
		for (Path file : files)
		{
			RecordedRound round = RecordedRound.read(file);
			List<RoundReplay.Frame> frames = RoundReplay.run(round);
			System.out.println(measure(frames).line(round.name()));
			if (dump != null)
			{
				List<String> lines = new ArrayList<>();
				for (RoundReplay.Frame f : frames)
				{
					if (f.snapshot.isInArena() && f.snapshot.getRole() != null)
					{
						Instruction ins = f.instruction;
						WorldPoint me = f.snapshot.getPlayerTile();
						lines.add(f.raw.t + " w" + f.snapshot.getWaveTick() + (me == null ? "" : " @" + me.getX() + "," + me.getY())
							+ " " + ins.getStep() + " | " + ins.getHeadline()
							+ " | " + identity(ins.getTarget()) + (f.snapshot.getRole() != Role.DEFENDER ? ""
							: " | runners " + f.snapshot.alive(PenanceType.RUNNER).stream()
								.map(p -> p.getTile() == null ? "?" : p.getTile().getX() + "," + p.getTile().getY() + (p.isUnseen() ? "u" : ""))
								.collect(Collectors.joining(" "))));
					}
				}
				Files.write(dump.resolve(round.name() + ".txt"), lines);
			}
		}
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.state.RoundLogic;
import com.bautopilot.baautopilot.state.Snapshot;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import net.runelite.client.util.Text;

/**
 * Prints a recorded round tick by tick: the raw call texts and chat beside what the current code
 * tells the player (and, where it differs, what the live plugin told them).
 *
 * <pre>gradlew replay -Pfile=path/to/recording.jsonl [-Pall]</pre>
 * Without -Pall only ticks where something changed are printed.
 */
public final class ReplayTimeline
{
	private ReplayTimeline()
	{
	}

	public static void main(String[] args) throws Exception
	{
		String file = null;
		boolean all = false;
		for (String a : args)
		{
			if ("--all".equals(a))
			{
				all = true;
			}
			else if (!a.isEmpty())
			{
				file = a;
			}
		}
		if (file == null)
		{
			System.err.println("usage: gradlew replay -Pfile=path/to/recording.jsonl [-Pall]");
			System.exit(2);
		}
		Path path = Paths.get(file);
		if (!Files.exists(path))
		{
			System.err.println("no such file: " + path.toAbsolutePath());
			System.exit(2);
		}

		RecordedRound round = RecordedRound.read(path);
		List<RoundReplay.Frame> frames = RoundReplay.run(round);
		System.out.println(round.name() + " - " + frames.size() + " ticks, strategy " + round.header.strategy);
		System.out.printf("%-6s %-8s %-14s %-16s %-14s %-24s %s%n",
			"tick", "call", "shout(hud)", "listen(hud)", "horn", "listen call", "instruction");

		String last = null;
		for (RoundReplay.Frame f : frames)
		{
			Snapshot s = f.snapshot;
			Role role = s.getRole();
			RoundLogic.Hud hud = RoundReplay.hud(f.raw.hud);
			String shout = role == null ? null : hud.text(role.getShoutComponent());
			String listen = s.getListenText();
			String horn = role == null ? null : hud.text(role.getHornListenComponent());
			String call = s.getCallPeriod() + 1 + (s.getTicksToCallChange() < 0 ? "" : "+" + s.ticksIntoCall());
			String heard = s.getListenCall() == null ? "-"
				: s.getListenCall().name() + "(" + s.getListenSource() + (s.isListenFresh() ? "" : ",old") + ")";
			String step = f.instruction.getStep() + ": " + f.instruction.getHeadline();
			String liveNote = "";
			if (f.raw.live != null && !Objects.equals(f.raw.live.step, f.instruction.getStep() == null ? null : f.instruction.getStep().name()))
			{
				liveNote = "   [live: " + f.raw.live.step + ": " + f.raw.live.headline + "]";
			}

			List<String> events = new ArrayList<>();
			for (Rec.Event e : RoundInvariants.events(f.raw, null))
			{
				String line = describe(e);
				if (line != null)
				{
					events.add(line);
				}
			}

			String key = String.join("|", String.valueOf(shout), String.valueOf(listen), String.valueOf(horn), heard, step, liveNote,
				String.valueOf(s.getCallPeriod()));
			if (all || !events.isEmpty() || !key.equals(last))
			{
				for (String e : events)
				{
					System.out.printf("%-6d   %s%n", f.raw.t, e);
				}
				System.out.printf("%-6d %-8s %-14s %-16s %-14s %-24s %s%s%n", f.raw.t, call, cut(shout, 14), cut(listen, 16),
					cut(horn, 14), cut(heard, 24), step, liveNote);
			}
			last = key;
		}

		RoundInvariants.Report report = RoundInvariants.check(round, frames);
		System.out.println();
		report.notes.forEach(n -> System.out.println("note: " + n));
		report.violations.forEach(v -> System.out.println("VIOLATION: " + v));
		System.out.println(report.violations.isEmpty() ? "invariants hold" : report.violations.size() + " violations");
	}

	private static String describe(Rec.Event e)
	{
		switch (e.k)
		{
			case "chat":
				return "chat " + e.type + (e.name == null ? "" : " " + e.name) + ": " + Text.removeTags(e.text);
			case "menu":
				return "click " + e.option + " " + e.target + (e.selected == null ? "" : " (using " + e.selected + ")");
			case "npcSpawn":
			case "npcDespawn":
			case "death":
				return e.npc == null ? e.k + " " + e.name : e.k + " npc " + e.npc + " (" + e.id + ")";
			case "graphic":
				return "graphic npc " + e.npc + " spotanims " + Arrays.toString(e.spot);
			case "itemSpawn":
				return "item " + e.id + " x" + e.qty + " at " + (e.tile == null ? "?" : e.tile.x + "," + e.tile.y) + " (#" + e.uid + ")";
			case "gameState":
				return "game state " + e.type;
			default:
				return null;
		}
	}

	private static String cut(String s, int n)
	{
		if (s == null)
		{
			return "";
		}
		return s.length() <= n ? s : s.substring(0, n - 1) + "~";
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.model.WaveInfo;
import com.bautopilot.baautopilot.state.CallClock;
import com.bautopilot.baautopilot.state.ListenResolver;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.RoundLogic;
import com.bautopilot.baautopilot.plan.Step;
import com.bautopilot.baautopilot.plan.RunnerState;
import com.bautopilot.baautopilot.plan.Tier;
import com.bautopilot.baautopilot.plan.TurretChoice;
import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.state.Snapshot;
import com.bautopilot.baautopilot.state.WaveStats;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MenuAction;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.util.Text;

/**
 * Checks a replayed round against what the raw recording says happened. Each check works from the
 * raw fields independently of the plugin's logic, then compares with the replayed snapshots.
 */
public final class RoundInvariants
{
	/** The role must be known this many ticks after its HUD first shows. */
	static final int ROLE_TICKS = 2;
	/** A shout-text flip must land this close to a call boundary of the wave-message clock. */
	static final int FLIP_TOLERANCE = 2;

	private static final Pattern WAVE_MESSAGE = Pattern.compile("---- Wave: (10|[1-9]) ----");
	private static final String WRONG_FOOD = "wrong type of poisoned food";

	/** What one check found. */
	public static final class Report
	{
		public final List<String> violations = new ArrayList<>();
		/** Facts worth printing (e.g. measured flip offsets) that are not failures. */
		public final List<String> notes = new ArrayList<>();
	}

	private RoundInvariants()
	{
	}

	public static Report check(RecordedRound round, List<RoundReplay.Frame> frames)
	{
		Report r = new Report();
		roleDetected(frames, r);
		listenMatchesHorn(frames, r);
		flipsOnBoundaries(frames, r);
		healerFoodCounts(frames, r);
		initialPoisonNotDelayed(frames, r);
		fullPoisonNotRefed(frames, r);
		weakestPoisonFirst(frames, r);
		cannonInterruptsNeedEvidence(frames, r);

		itemsMatchFreshCall(frames, r);
		staleCallsNotUsed(frames, r);
		eggBagMatchesLoads(frames, r);
		wrongCallsNotDone(frames, r);
		performanceNotes(frames, r);
		attackSwitches(frames, r);
		liveAgreement(frames, r);
		r.notes.add("metrics: " + ReplayMetrics.measure(frames).line("").trim());
		return r;
	}

	/** Primary cannon interrupts require the observed runner threat or recent low-red firing. */
	static void cannonInterruptsNeedEvidence(List<RoundReplay.Frame> frames, Report r)
	{
		for (RoundReplay.Frame frame : frames)
		{
			Step step = frame.instruction.getStep();
			if (frame.instruction.getTier() != Tier.TEAM_BLOCKING || (step != Step.COL_LOAD && step != Step.COL_FIRE)) continue;
			Snapshot s = frame.snapshot;
			int shotAge = s.getLastLauncherShotTick() < 0 ? -1 : s.getTick() - s.getLastLauncherShotTick();
			boolean lowRedActive = s.getEggsRed() <= 2 && shotAge >= 0 && shotAge <= 8;
			boolean escapeInRange = s.getPenance().stream().anyMatch(p -> p.getType() == PenanceType.RUNNER
				&& !p.isDying() && !p.isUnseen() && RunnerState.of(s, p) == RunnerState.ESCAPING
				&& s.getObjects().stream().anyMatch(o -> BaIds.contains(BaIds.LAUNCHERS, o.getId())
					&& ArenaTiles.distance(o.getTile(), p.getTile()) <= TurretChoice.RANGE));
			if (!lowRedActive && !escapeInRange)
			{
				r.violations.add("cannon interrupt: tick " + frame.raw.t + ": " + frame.instruction.getDetail());
			}
		}
	}

	/** Follow-up food must not bypass a known untagged healer, including one last seen out of view. */
	static void initialPoisonNotDelayed(List<RoundReplay.Frame> frames, Report r)
	{
		int opportunities = 0;
		for (RoundReplay.Frame frame : frames)
		{
			Snapshot s = frame.snapshot;
			Step step = frame.instruction.getStep();
			if (!s.isInArena() || s.getRole() != Role.HEALER || !s.isListenFresh() || s.getListenCall() == null
				|| !s.has(s.getListenCall().getItemId())
				|| s.alive(PenanceType.HEALER).stream().noneMatch(h -> h.nextPoisonHit(s.getTick()) == 0))
			{
				continue;
			}
			// Calls, healing and Queen work can interrupt poisoning. Ordinary food work cannot.
			if (step == Step.HEAL_FEED || step == Step.HEAL_WAIT || step == Step.HEAL_SUPPORT || step == Step.HEAL_TAKE_FOOD)
			{
				opportunities++;
				boolean initial = step == Step.HEAL_FEED && s.alive(PenanceType.HEALER).stream()
					.anyMatch(h -> h.nextPoisonHit(s.getTick()) == 0 && h.getNpcIndex() == frame.instruction.getTarget().getId());
				if (!initial) r.violations.add("initial poison: tick " + frame.raw.t + ": " + frame.instruction.getHeadline());
			}
		}
		if (opportunities > 0) r.notes.add("initial poison: " + opportunities + " available decision ticks checked");
	}

	/** Full poison feeds need a real reserve-opening tactic, fresh food and protected future tags. */
	static void fullPoisonNotRefed(List<RoundReplay.Frame> frames, Report r)
	{
		for (RoundReplay.Frame frame : frames)
		{
			if (frame.instruction.getStep() != Step.HEAL_FEED) continue;
			for (PenanceView h : frame.snapshot.alive(PenanceType.HEALER))
			{
				if (h.getNpcIndex() == frame.instruction.getTarget().getId() && h.poisoned()
					&& h.nextPoisonHit(frame.snapshot.getTick()) >= WaveInfo.FOOD_DAMAGE)
				{
					Snapshot s = frame.snapshot;
					int futureTags = Math.max(0, WaveInfo.healersTotal(s.getWave()) - s.getHealersKilled() - s.alive(PenanceType.HEALER).size());
					boolean justified = "heal.reserve".equals(frame.instruction.getTask()) && s.isListenFresh()
						&& s.getListenCall() != null && s.count(s.getListenCall().getItemId()) > futureTags
						&& s.getHealersKilled() < WaveInfo.healersTotal(s.getWave()) - WaveInfo.healersInitial(s.getWave())
						&& s.alive(PenanceType.HEALER).stream().mapToInt(PenanceView::getOrder).max().orElse(0) < WaveInfo.healersTotal(s.getWave())
						&& !h.isUnseen() && s.walk(h.getTile()) <= 8;
					if (!justified) r.violations.add("full poison: tick " + frame.raw.t + ": " + frame.instruction.getHeadline());
				}
			}
		}
	}

	/** Code timing and previous targets cannot bypass a healer with weaker active poison. */
	static void weakestPoisonFirst(List<RoundReplay.Frame> frames, Report r)
	{
		for (RoundReplay.Frame frame : frames)
		{
			Snapshot s = frame.snapshot;
			Step step = frame.instruction.getStep();
			if (s.getRole() != Role.HEALER || !s.isListenFresh() || s.getListenCall() == null
				|| !s.has(s.getListenCall().getItemId()) || !(step == Step.HEAL_FEED || step == Step.HEAL_WAIT
				|| step == Step.HEAL_SUPPORT || step == Step.HEAL_TAKE_FOOD)) continue;
			int lowest = s.alive(PenanceType.HEALER).stream().mapToInt(h -> h.nextPoisonHit(s.getTick())).min().orElse(4);
			if (lowest >= 4) continue;
			boolean correct = step == Step.HEAL_FEED && s.alive(PenanceType.HEALER).stream()
				.anyMatch(h -> h.getNpcIndex() == frame.instruction.getTarget().getId() && h.nextPoisonHit(s.getTick()) == lowest);
			if (!correct) r.violations.add("weakest poison: tick " + frame.raw.t + ": " + frame.instruction.getHeadline());
		}
	}

	// ------------------------------------------------------------------ checks

	static void roleDetected(List<RoundReplay.Frame> frames, Report r)
	{
		for (int i = 0; i < frames.size(); i++)
		{
			Role hud = hudRole(frames.get(i).raw);
			if (hud == null)
			{
				continue;
			}
			int first = frames.get(i).raw.t;
			for (int j = i; j < frames.size() && frames.get(j).raw.t - first <= ROLE_TICKS; j++)
			{
				if (frames.get(j).snapshot.getRole() == hud)
				{
					return;
				}
			}
			r.violations.add("role: " + hud + " HUD showed at tick " + first + " but the role was not detected within "
				+ ROLE_TICKS + " ticks");
			return;
		}
	}

	/** Every horn chat line addressed to our role becomes the listen call on the tick it arrives. */
	static void listenMatchesHorn(List<RoundReplay.Frame> frames, Report r)
	{
		for (RoundReplay.Frame f : frames)
		{
			Role role = f.snapshot.getRole();
			if (role == null || !f.snapshot.isInArena())
			{
				continue;
			}
			ListenResolver.Addressed last = null;
			int lastTick = -1;
			for (Rec.Event e : events(f.raw, "chat"))
			{
				ListenResolver.Addressed line = ListenResolver.addressed(Text.removeTags(e.text));
				if (line == null || line.receiver != role)
				{
					continue;
				}
				if (line.call == null)
				{
					r.violations.add("listen: tick " + e.t + ": horn line to " + role + " not understood: '" + Text.removeTags(e.text) + "'");
					continue;
				}
				last = line;
				lastTick = e.t;
			}
			if (last != null && f.snapshot.getListenCall() != last.call)
			{
				r.violations.add("listen: tick " + f.raw.t + ": heard '" + last.call.name() + "' (chat at tick " + lastTick
					+ ") but the listen call is " + f.snapshot.getListenCall() + " via " + f.snapshot.getListenSource());
			}
		}
	}

	/**
	 * The call to give flips on the HUD at call boundaries; boundaries are the wave message tick +
	 * START_OFFSET + 50k. This is what validates the offset (8 recorded waves 2026-10-15: waves 2-8 all
	 * flipped wave message + 1 + 50k; wave 1's message arrived 6 ticks late, which the clock's
	 * re-anchor on the first flip absorbs, so wave 1 is reported but not failed).
	 */
	static void flipsOnBoundaries(List<RoundReplay.Frame> frames, Report r)
	{
		int waveTick = -1;
		int wave = 0;
		Integer firstOff = null;
		String lastShout = null;
		List<String> offsets = new ArrayList<>();
		for (RoundReplay.Frame f : frames)
		{
			for (Rec.Event e : events(f.raw, "chat"))
			{
				if (ChatMessageType.GAMEMESSAGE.name().equals(e.type) && WAVE_MESSAGE.matcher(Text.removeTags(e.text)).find())
				{
					waveTick = e.t;
					firstOff = null;
					java.util.regex.Matcher m = WAVE_MESSAGE.matcher(Text.removeTags(e.text));
					wave = m.find() && m.groupCount() >= 1 && m.group(1) != null ? Integer.parseInt(m.group(1)) : 0;
				}
			}
			Role role = hudRole(f.raw);
			if (role == null || waveTick < 0 || !f.snapshot.isInArena())
			{
				continue;
			}
			String shout = RoundReplay.hud(f.raw.hud).text(role.getShoutComponent());
			boolean flipped = shout != null && !shout.equals(lastShout) && BaCall.parse(role.partner(), shout) != null;
			if (flipped && f.raw.t > waveTick)
			{
				int since = f.raw.t - waveTick - CallClock.START_OFFSET;
				int k = Math.round(since / (float) WaveInfo.TICKS_PER_CALL);
				int off = since - k * WaveInfo.TICKS_PER_CALL;
				offsets.add("call " + (k + 1) + ": " + (off >= 0 ? "+" : "") + off);
				// The wave message can arrive a few ticks late, and a leader stall can shift the whole call
				// cycle (recorded: one 47-tick call in attacker wave 8). The clock re-anchors on every flip
				// within RESYNC_WINDOW of a boundary, so a shift up to that is a note; only a bigger jump,
				// which the clock would ignore, is a failure
				if (firstOff != null)
				{
					int shift = off - firstOff;
					if (Math.abs(shift) > CallClock.RESYNC_WINDOW)
					{
						r.violations.add("clock: tick " + f.raw.t + ": shout flipped to '" + shout + "' " + shift
							+ " ticks off the rhythm, too far for the clock to re-anchor");
					}
					else if (Math.abs(shift) > FLIP_TOLERANCE)
					{
						r.notes.add("clock: call cycle shifted " + shift + " ticks at tick " + f.raw.t + " (re-anchored)");
					}
				}
				firstOff = off;
			}
			if (shout != null)
			{
				lastShout = shout;
			}
		}
		if (!offsets.isEmpty())
		{
			r.notes.add("shout flips vs wave message + " + CallClock.START_OFFSET + " + 50k: " + String.join(", ", offsets));
		}
	}

	/**
	 * Healer only: the foods the ledger counted equal our own feeds (use-on-healer click followed by
	 * the food leaving the inventory, no wrong-food message, matching the heard call), plus at most
	 * one per poison graphic that was not our own.
	 */
	static void healerFoodCounts(List<RoundReplay.Frame> frames, Report r)
	{
		if (frames.stream().noneMatch(f -> f.snapshot.getRole() == Role.HEALER && f.snapshot.isInArena()))
		{
			return;
		}
		List<int[]> clicks = new ArrayList<>(); // {npcIndex, itemId, tick}
		Map<Integer, Integer> maxFoods = new HashMap<>();
		Map<Integer, Integer> confirmed = new HashMap<>();
		java.util.Set<Integer> died = new java.util.HashSet<>();
		Map<Integer, Integer> lastInv = new HashMap<>();
		int own = 0;
		int rejected = 0;
		for (RoundReplay.Frame f : frames)
		{
			for (Rec.Event e : events(f.raw, null))
			{
				if ("death".equals(e.k) && e.npc != null) died.add(e.npc);
				if ("npcSpawn".equals(e.k) && died.contains(e.npc))
				{
					// A dying NPC can re-enter view: its death event precedes its spawn event in this
					// tick (wave 10, 3484). Only a living replacement starts a fresh food count.
					boolean dying = f.raw.npcs != null && f.raw.npcs.stream().anyMatch(n -> n.i == e.npc && n.dead);
					if (!dying)
					{
						died.remove(e.npc);
						confirmed.remove(e.npc);
					}
				}
				if ("menu".equals(e.k) && MenuAction.WIDGET_TARGET_ON_NPC.name().equals(e.type) && e.npc != null
					&& e.selected != null && BaIds.POISON_FOOD.contains(e.selected) && PenanceType.forNpcId(e.id) == PenanceType.HEALER)
				{
					clicks.add(new int[]{e.npc, e.selected, e.t});
				}
				else if ("chat".equals(e.k) && Text.removeTags(e.text).toLowerCase().contains(WRONG_FOOD))
				{
					rejected += clicks.size();
					clicks.clear();
				}
			}
			int tick = f.raw.t;
			clicks.removeIf(c -> tick - c[2] > RoundLogic.FEED_CONFIRM_TICKS);
			Map<Integer, Integer> inv = f.raw.inv == null ? new HashMap<>() : f.raw.inv;
			BaCall call = f.snapshot.getListenCall();
			for (int food : BaIds.POISON_FOOD)
			{
				int dropped = lastInv.getOrDefault(food, 0) - inv.getOrDefault(food, 0);
				for (int i = 0; i < dropped; i++)
				{
					int[] match = clicks.stream().filter(c -> c[1] == food).findFirst().orElse(null);
					if (match == null)
					{
						break;
					}
					clicks.remove(match);
					if (call != null && call.getItemId() == food)
					{
						own++;
						confirmed.merge(match[0], 1, Integer::sum);
					}
				}
			}
			lastInv = inv;
			for (PenanceView p : f.snapshot.getPenance())
			{
				if (p.getType() == PenanceType.HEALER)
				{
					maxFoods.merge(p.getNpcIndex(), p.getFoods(), Math::max);
					int expected = confirmed.getOrDefault(p.getNpcIndex(), 0);
					if (p.getFoods() != expected) r.violations.add("healer food: tick " + tick + " NPC " + p.getNpcIndex()
						+ " counted " + p.getFoods() + " but " + expected + " own foods were confirmed");
				}
			}
		}
		int counted = maxFoods.values().stream().mapToInt(Integer::intValue).sum();
		r.notes.add("healer food: " + own + " own feeds from inventory, " + rejected + " rejected, ledger counted " + counted);
		// A final food can land on an NPC after it left the scene, so no final visible view is
		// guaranteed. Validate every observed NPC above rather than requiring its last view here.
		if (counted > own)
		{
			r.violations.add("healer food: ledger counted " + counted + ", more than " + own + " confirmed own feeds");
		}
	}

	/**
	 * Steps whose items are put away rather than used on the call: loading eggs (any colour goes in
	 * the hopper), destroying blue eggs, the defender's bad bait, and the queen's egg chain.
	 */
	private static final java.util.Set<Step> NOT_CALL_USE = java.util.EnumSet.of(
		Step.COL_LOAD, Step.COL_BLUE, Step.COL_DISCARD, Step.DEF_DROP, Step.DEF_RELURE,
		Step.QUEEN_COLLECT, Step.QUEEN_PASS, Step.QUEEN_DUNK, Step.QUEEN_LAVA, Step.QUEEN_SPIKE, Step.QUEEN_LOAD, Step.QUEEN_LOAD_ONE);

	/** A fresh call means the instruction must never point at a different item of the same kind. */
	static void itemsMatchFreshCall(List<RoundReplay.Frame> frames, Report r)
	{
		for (RoundReplay.Frame f : frames)
		{
			Snapshot s = f.snapshot;
			BaCall call = s.getListenCall();
			if (call == null || !s.isListenFresh() || s.getRole() == null || NOT_CALL_USE.contains(f.instruction.getStep()))
			{
				continue;
			}
			for (int item : f.instruction.getItems())
			{
				if (BaCall.isItemOf(s.getRole(), item) && item != call.getItemId())
				{
					r.violations.add("items: tick " + f.raw.t + ": call is " + call.name() + " but '" + f.instruction.getHeadline()
						+ "' outlines " + BaCall.forItem(s.getRole(), item).name());
				}
			}
		}
	}

	/** Missing or stale calls never authorize a new call-dependent action. */
	static void staleCallsNotUsed(List<RoundReplay.Frame> frames, Report r)
	{
		java.util.Set<Step> dependent = java.util.EnumSet.of(Step.ATT_ATTACK, Step.ATT_EQUIP,
			Step.HEAL_FEED, Step.COL_COLLECT, Step.DEF_DROP, Step.DEF_RELURE);
		for (RoundReplay.Frame frame : frames)
		{
			Step step = frame.instruction.getStep();
			if (frame.snapshot.isInArena() && !frame.snapshot.isListenFresh() && dependent.contains(step)
				&& (step != Step.DEF_RELURE || !frame.instruction.getItems().isEmpty()))
			{
				r.violations.add("stale call: tick " + frame.raw.t + ": " + frame.instruction.getHeadline());
			}
		}
	}

	/**
	 * Collector only: at every "You load the hopper." the hopper may grow by at most what the
	 * tracked bag plus the inventory held of each colour (capped at 5 loaded), read two ticks later.
	 * A hopper that grows by more means the bag counter missed eggs.
	 */
	static void eggBagMatchesLoads(List<RoundReplay.Frame> frames, Report r)
	{
		int checked = 0;
		int exact = 0;
		for (int i = 1; i + 2 < frames.size(); i++)
		{
			RoundReplay.Frame f = frames.get(i);
			if (events(f.raw, "chat").stream().noneMatch(e -> "You load the hopper.".equals(Text.removeTags(e.text))))
			{
				continue;
			}
			Snapshot before = frames.get(i - 1).snapshot;
			Snapshot after = frames.get(i + 2).snapshot;
			int[][] colours = {
				{BaIds.EGG_GREEN, before.getBagGreen(), before.getEggsGreen(), after.getEggsGreen()},
				{BaIds.EGG_RED, before.getBagRed(), before.getEggsRed(), after.getEggsRed()},
				{BaIds.EGG_BLUE, before.getBagBlue(), before.getEggsBlue(), after.getEggsBlue()},
			};
			boolean ok = true;
			boolean same = true;
			StringBuilder why = new StringBuilder();
			for (int[] c : colours)
			{
				int expected = Math.min(before.count(c[0]) + c[1], Math.max(0, 5 - c[2]));
				int actual = c[3] - c[2];
				same &= actual == expected;
				// Firing between the two reads can only make the hopper look emptier
				if (actual > expected)
				{
					ok = false;
					why.append(BaCall.forItem(Role.COLLECTOR, c[0])).append(" +").append(actual)
						.append(" (bag ").append(c[1]).append(", inventory ").append(before.count(c[0])).append(") ");
				}
			}
			checked++;
			if (same)
			{
				exact++;
			}
			if (!ok)
			{
				r.violations.add("bag: tick " + f.raw.t + ": hopper grew by more than bag + inventory: " + why.toString().trim());
			}
		}
		if (checked > 0)
		{
			r.notes.add("egg bag: " + exact + "/" + checked + " hopper loads exactly matched bag + inventory");
		}
	}

	/** A horn call that doesn't match the HUD's call-to-give must not count as the call made. */
	static void wrongCallsNotDone(List<RoundReplay.Frame> frames, Report r)
	{
		int wrong = 0;
		for (int i = 0; i + 2 < frames.size(); i++)
		{
			RoundReplay.Frame f = frames.get(i);
			Role role = f.snapshot.getRole();
			BaCall want = f.snapshot.getShoutCall();
			// Extra clicks after the call was already made (e.g. calling the next one early, recorded
			// in wave 10) and calls during the Queen don't count
			boolean alreadyDone = i > 0 && frames.get(i - 1).snapshot.isShoutDone();
			if (role == null || want == null || alreadyDone || f.snapshot.isQueenAlive())
			{
				continue;
			}
			for (Rec.Event e : events(f.raw, "menu"))
			{
				String option = e.option == null ? "" : e.option;
				if (option.startsWith("Tell-") && !option.equalsIgnoreCase(want.getHornOption()))
				{
					wrong++;
					Snapshot after = frames.get(i + 2).snapshot;
					boolean fixed = false;
					for (int j = i; j <= i + 2; j++)
					{
						fixed |= events(frames.get(j).raw, "menu").stream()
							.anyMatch(x -> want.getHornOption().equalsIgnoreCase(x.option));
					}
					if (after.isShoutDone() && !fixed && after.getShoutCall() == want)
					{
						r.violations.add("call: tick " + e.t + ": " + option + " on a " + want.getKeyword() + " call counted as done");
					}
					if (!fixed && after.getShoutWrong() == null && after.getShoutCall() == want)
					{
						r.violations.add("call: tick " + e.t + ": " + option + " on a " + want.getKeyword() + " call not flagged as wrong");
					}
				}
			}
		}
		if (wrong > 0)
		{
			r.notes.add("wrong calls: " + wrong);
		}
	}

	/** Not a failure: how often the attack target changed while the previous one was still alive. */
	static void attackSwitches(List<RoundReplay.Frame> frames, Report r)
	{
		switches(frames, r, Step.ATT_ATTACK, "attack");
		switches(frames, r, Step.HEAL_FEED, "feed");
	}

	private static void switches(List<RoundReplay.Frame> frames, Report r, Step step, String what)
	{
		int attacks = 0;
		int switches = 0;
		int last = -1;
		for (RoundReplay.Frame f : frames)
		{
			if (f.instruction.getStep() != step)
			{
				continue;
			}
			attacks++;
			int now = f.instruction.getTarget().getId();
			final int prev = last;
			boolean prevAlive = prev >= 0 && f.snapshot.getPenance().stream()
				.anyMatch(p -> p.getNpcIndex() == prev && !p.isDying());
			if (now != prev && prevAlive)
			{
				switches++;
			}
			last = now;
		}
		if (attacks > 0)
		{
			r.notes.add(what + " target switches while the previous target lived: " + switches + " in " + attacks + " " + what + " ticks");
		}
	}

	/** Not a failure: the performance numbers the plugin would show for this wave. */
	static void performanceNotes(List<RoundReplay.Frame> frames, Report r)
	{
		WaveStats w = null;
		int now = 0;
		for (RoundReplay.Frame f : frames)
		{
			if (f.snapshot.getWaveStats() != null)
			{
				w = f.snapshot.getWaveStats();
				now = f.raw.t;
			}
		}
		if (w == null)
		{
			return;
		}
		r.notes.add(String.format("performance: wave %d %s %s | your calls %d, avg %.1fs, worst %.1fs, missed %d"
				+ " | partner calls avg %.1fs, missed %d | eggs %d (+%d wrong), loads %d, shots %d, foods %d, kills F/R %d R %d",
			w.getWave(), w.getRole(), WaveStats.clock(w.durationTicks(now)),
			w.getCallReactions().size(), WaveStats.meanSeconds(w.getCallReactions()), WaveStats.worstSeconds(w.getCallReactions()),
			w.getCallsMissed(), WaveStats.meanSeconds(w.getPartnerDelays()), w.getPartnerMissed(),
			w.getEggsPicked(), w.getEggsWrong(), w.getLoads(), w.getShots(), w.getFoods(), w.getFighterRangerKills(), w.getRunnerKills()));
	}

	/** Not a failure: where the replay (current code) and the live plugin disagreed. */
	static void liveAgreement(List<RoundReplay.Frame> frames, Report r)
	{
		int compared = 0;
		int steps = 0;
		int listens = 0;
		String firstStep = null;
		for (RoundReplay.Frame f : frames)
		{
			Rec.Live live = f.raw.live;
			if (live == null)
			{
				continue;
			}
			compared++;
			String step = f.instruction.getStep() == null ? null : f.instruction.getStep().name();
			if (!Objects.equals(step, live.step))
			{
				steps++;
				if (firstStep == null)
				{
					firstStep = "tick " + f.raw.t + " live " + live.step + " / replay " + step;
				}
			}
			String listen = f.snapshot.getListenCall() == null ? null : f.snapshot.getListenCall().name();
			if (!Objects.equals(listen, live.listen))
			{
				listens++;
			}
		}
		if (compared > 0)
		{
			r.notes.add("live vs replay over " + compared + " ticks: " + steps + " step and " + listens + " listen-call differences"
				+ (firstStep == null ? "" : " (first: " + firstStep + ")"));
		}
	}

	// ------------------------------------------------------------------ helpers

	static Role hudRole(Rec.Tick t)
	{
		if (t.hud == null)
		{
			return null;
		}
		for (Role role : Role.values())
		{
			if (t.hud.containsKey(WidgetUtil.packComponentId(role.getHudGroup(), 0)))
			{
				return role;
			}
		}
		return null;
	}

	static List<Rec.Event> events(Rec.Tick t, String kind)
	{
		List<Rec.Event> out = new ArrayList<>();
		if (t.ev != null)
		{
			for (Rec.Event e : t.ev)
			{
				if (kind == null || kind.equals(e.k))
				{
					out.add(e);
				}
			}
		}
		return out;
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.plan.Target;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.plan.Instruction;
import com.bautopilot.baautopilot.plan.Planner;
import com.bautopilot.baautopilot.plan.Settings;
import com.bautopilot.baautopilot.state.BaTracker;
import com.bautopilot.baautopilot.state.GroundItemView;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.PlayerView;
import com.bautopilot.baautopilot.state.RoundLogic;
import com.bautopilot.baautopilot.state.Snapshot;
import com.google.common.collect.ImmutableList;
import com.google.common.collect.ImmutableMap;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BiFunction;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.util.Text;

/**
 * Re-runs a recorded round through the plugin's own logic: recorded events and HUD texts go into
 * {@link RoundLogic} exactly as {@link BaTracker} would pass them, and each rebuilt
 * {@link Snapshot} goes through the {@link Planner}. Each recording starts from a fresh round.
 */
public final class RoundReplay
{
	/** One replayed tick: the raw recorded line and what the current code makes of it. */
	public static final class Frame
	{
		public final Rec.Tick raw;
		public final Snapshot snapshot;
		public final Instruction instruction;

		Frame(Rec.Tick raw, Snapshot snapshot, Instruction instruction)
		{
			this.raw = raw;
			this.snapshot = snapshot;
			this.instruction = instruction;
		}
	}

	private RoundReplay()
	{
	}

	public static List<Frame> run(RecordedRound round)
	{
		return run(round, new Planner()::plan);
	}

	/** Same recorded inputs, with independent instruction history for the supplied decision policy. */
	public static List<Frame> run(RecordedRound round, BiFunction<Snapshot, Settings, Instruction> policy)
	{
		Settings settings = round.header.settings == null ? Settings.builder().build() : round.header.settings;
		RoundLogic logic = new RoundLogic();

		// Mirrors of the tracker's client-side state
		Set<Integer> tracked = new LinkedHashSet<>();
		Map<Integer, GroundItemView> groundMemory = new HashMap<>();
		List<Rec.Obj> objects = Collections.emptyList();
		RoundLogic.Hud hud = hud(null);

		List<Frame> frames = new ArrayList<>();
		Instruction previous = null;
		int lastNpc = -1;
		for (Rec.Tick t : round.ticks)
		{
			if (t.objects != null)
			{
				objects = t.objects;
			}
			if (t.ev != null)
			{
				for (Rec.Event e : t.ev)
				{
					switch (e.k)
					{
						case "chat":
							boolean game = ChatMessageType.GAMEMESSAGE.name().equals(e.type) || ChatMessageType.WELCOME.name().equals(e.type)
								|| ChatMessageType.MESBOX.name().equals(e.type) || ChatMessageType.SPAM.name().equals(e.type);
							if (logic.chat(game, Text.removeTags(e.text), "Me".equals(e.name), e.t))
							{
								tracked.clear();
							}
							break;
						case "menu":
							String option = e.option == null ? "" : e.option;
							logic.menuClicked(option, e.target == null ? null : Text.removeTags(e.target), e.t);
							if (logic.getRole() != null && option.startsWith("Tell-"))
							{
								// The shout text as of the previous tick line
								logic.tellClicked(option, hud);
							}
							else if (MenuAction.WIDGET_TARGET_ON_NPC.name().equals(e.type) && e.npc != null && e.selected != null)
							{
								logic.usedOnNpc(e.npc, PenanceType.forNpcId(e.id), e.selected, e.t);
							}
							break;
						case "npcSpawn":
						{
							PenanceType type = PenanceType.forNpcId(e.id);
							if (type != null)
							{
								tracked.add(e.npc);
								logic.npcSpawned(e.npc, type, e.t);
							}
							break;
						}
						case "npcDespawn":
							if (tracked.remove(e.npc))
							{
								int distance = e.tile == null || t.tile == null ? 0
									: Math.max(Math.abs(e.tile.x - t.tile.x), Math.abs(e.tile.y - t.tile.y));
								logic.npcDespawned(e.npc, PenanceType.forNpcId(e.id), distance);
							}
							break;
						case "death":
							if (e.npc != null)
							{
								logic.npcDied(e.npc, PenanceType.forNpcId(e.id));
							}
							break;
						case "hit":
							if (e.npc != null && e.qty != null && tracked.contains(e.npc))
							{
								int type = e.type == null ? -1 : Integer.parseInt(e.type);
								logic.hit(e.npc, e.qty, "Me".equals(e.name),
									type == net.runelite.api.HitsplatID.POISON || type == net.runelite.api.HitsplatID.VENOM, e.t);
							}
							break;
						case "overhead":
							logic.overhead(e.name, Text.removeTags(e.text), "Me".equals(e.name), e.t);
							break;
						case "itemSpawn":
							groundMemory.put(e.uid, logic.groundItemSpawned(e.id, point(e.tile), e.qty == null ? 1 : e.qty, e.t, point(t.tile)));
							break;
						case "itemDespawn":
							GroundItemView gone = groundMemory.remove(e.uid);
							if (gone != null) logic.groundItemDespawned(gone, e.t);
							break;
						case "gameState":
							if ("LOGIN_SCREEN".equals(e.type) || "HOPPING".equals(e.type))
							{
								logic.reset();
								tracked.clear();
							}
							break;
						default:
							break;
					}
				}
			}

			hud = hud(t.hud);
			WorldPoint here = point(t.tile);
			int region = here == null ? -1 : here.getRegionID();
			boolean inArena = t.instance && ArenaTiles.isArenaRegion(region);
			boolean inLobby = !t.instance && region == ArenaTiles.REGION_LOBBY;
			Map<Integer, Integer> inventory = t.inv == null ? ImmutableMap.of() : ImmutableMap.copyOf(t.inv);
			if (logic.tick(t.t, inArena, hud, inventory, varbit(t, VarbitID.BARBASSAULT_EGGCOUNT_POISON),
				varbit(t, VarbitID.BARBASSAULT_EGGCOUNT_EXPLOSIVE), varbit(t, VarbitID.BARBASSAULT_EGGCOUNT_STUN)))
			{
				tracked.clear();
			}

			logic.observeSelfHp(t.hp, t.maxHp);
			logic.observePosition(here);
			logic.observeQueenAmmo(varbit(t, VarbitID.BARBASSAULT_EGGCOUNT_OMEGA));
			Map<Integer, Rec.Npc> scene = new HashMap<>();
			if (t.npcs != null)
			{
				t.npcs.forEach(n -> scene.put(n.i, n));
			}
			ImmutableList.Builder<PenanceView> penance = ImmutableList.builder();
			boolean queen = false;
			for (int idx : tracked)
			{
				Rec.Npc n = scene.get(idx);
				PenanceType type = n == null ? null : PenanceType.forNpcId(n.id);
				if (type != null)
				{
					penance.add(logic.penance(n.i, type, point(n.tile), n.hr, n.hs, n.dead, n.anim, n.overhead));
					queen |= type == PenanceType.QUEEN;
				}
			}

			List<GroundItemView> ground = new ArrayList<>();
			if (t.ground != null)
			{
				for (Rec.Ground g : t.ground)
				{
					GroundItemView remembered = groundMemory.get(g.uid);
					ground.add(new GroundItemView(g.id, point(g.tile), g.qty, remembered != null && remembered.isGood(),
						remembered == null ? t.t : remembered.getSpawnTick()));
				}
			}
			ImmutableList.Builder<ObjectView> objectViews = ImmutableList.builder();
			List<Integer> objectIds = new ArrayList<>();
			for (Rec.Obj o : objects)
			{
				objectViews.add(new ObjectView(o.id, point(o.tile)));
				objectIds.add(o.id);
			}

			Map<String, WorldPoint> playerTiles = new java.util.LinkedHashMap<>();
			List<PlayerView> players = new ArrayList<>();
			Map<String, Role> playerRoles = new java.util.LinkedHashMap<>();
			if (t.players != null) for (Rec.Plr player : t.players)
			{
				if (player.n != null && player.tile != null) playerTiles.put(player.n, point(player.tile));
				players.add(new PlayerView(player.n, player.role, point(player.tile), player.anim, player.interacting));
				if (player.n != null && player.role != null) playerRoles.put(player.n, player.role);
			}
			players.add(new PlayerView("Me", logic.getRole(), here, -1, null));
			boolean queenAlive = logic.queenPhase(queen);
			logic.observeQueenPlayers(players);
			if (!playerRoles.isEmpty() && logic.getRole() != null) playerRoles.put("Me", logic.getRole());
			Snapshot s = logic.snapshot()
				.inLobby(inLobby)
				.inventory(inventory)
				.freeSlots(t.free)
				.ammoId(t.ammo)
				.hasHammer(BaTracker.hasHammer(inventory, t.imcandoWorn))
				.hp(t.hp)
				.maxHp(t.maxHp)
				.playerTile(here)
				.playerTiles(com.google.common.collect.ImmutableMap.copyOf(playerTiles))
				.team(com.google.common.collect.ImmutableMap.copyOf(playerRoles))
				.penance(penance.build())
				.groundItems(RoundLogic.mergeGround(ground))
				.objects(objectViews.build())
				.eggsRed(varbit(t, VarbitID.BARBASSAULT_EGGCOUNT_EXPLOSIVE))
				.eggsGreen(varbit(t, VarbitID.BARBASSAULT_EGGCOUNT_POISON))
				.eggsBlue(varbit(t, VarbitID.BARBASSAULT_EGGCOUNT_STUN))
				.eggsOmega(varbit(t, VarbitID.BARBASSAULT_EGGCOUNT_OMEGA))
				.trapCharges(RoundLogic.trapCharges(objectViews.build(), logic.getWave()))
				.roleLevels(roleLevels(t))
				.queenAlive(queenAlive)
				.lastTargetTile(previous == null ? null : previous.getTarget().getTile())
				.lastTargetNpc(lastNpc)
				.lastTask(previous == null ? null : previous.getTask())
				.lastStep(previous == null ? null : previous.getStep())
				.lastActionTarget(previous == null ? null : previous.getTarget())
				.tasks(previous == null ? com.bautopilot.baautopilot.plan.TaskMemory.empty() : previous.getTasks())
				.interactingNpc(t.interacting == null ? -1 : t.interacting)
				.build();
			Instruction ins = policy.apply(s, settings);
			frames.add(new Frame(t, s, ins));
			previous = ins;
			if (ins.getTarget().getKind() == Target.Kind.NPC)
			{
				lastNpc = ins.getTarget().getId();
			}
		}
		return frames;
	}

	/** Recorded levels belong to the recording player, matching the live tracker's varbits. */
	static Map<Role, Integer> roleLevels(Rec.Tick tick)
	{
		Map<Role, Integer> levels = new java.util.EnumMap<>(Role.class);
		for (Role role : Role.values())
		{
			int level = varbit(tick, roleLevelVarbit(role));
			if (level >= 1 && level <= 5) levels.put(role, level);
		}
		return levels;
	}

	static int roleLevelVarbit(Role role)
	{
		switch (role)
		{
			case ATTACKER: return VarbitID.BARBASSULT_ROLELEVEL_ATT;
			case DEFENDER: return VarbitID.BARBASSULT_ROLELEVEL_DEF;
			case COLLECTOR: return VarbitID.BARBASSULT_ROLELEVEL_COL;
			default: return VarbitID.BARBASSULT_ROLELEVEL_HEAL;
		}
	}

	/** The recorded HUD of one tick, read the way the live tracker reads widgets. */
	static RoundLogic.Hud hud(Map<Integer, String> recorded)
	{
		Map<Integer, String> texts = recorded == null ? Collections.emptyMap() : recorded;
		return new RoundLogic.Hud()
		{
			@Override
			public boolean visible(int component)
			{
				return texts.containsKey(component);
			}

			@Override
			public String text(int component)
			{
				String raw = texts.get(component);
				return raw == null ? null : Text.removeTags(raw);
			}
		};
	}

	static WorldPoint point(Rec.Pos p)
	{
		return p == null ? null : new WorldPoint(p.x, p.y, p.p);
	}

	private static int varbit(Rec.Tick t, int id)
	{
		return t.vb == null ? 0 : t.vb.getOrDefault(id, 0);
	}

	static boolean contains(int[] ids, int id)
	{
		if (ids != null)
		{
			for (int i : ids)
			{
				if (i == id)
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.Role;
import com.google.gson.JsonObject;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/** Lightweight capture index. Full round reconstruction happens only when a capture is selected. */
final class ScenarioCatalog
{
	static final class Entry
	{
		final String id;
		final String name;
		final Role role;
		final int wave;
		final int level;
		final String source;
		final transient Path path;

		Entry(Path path, Role role, int wave, int level, String source)
		{
			this.id = path.getFileName().toString();
			this.name = id;
			this.path = path;
			this.role = role;
			this.wave = wave;
			this.level = level;
			this.source = source;
		}
	}

	private final Path selected;
	private final List<Path> directories;
	private Map<String, Entry> entries = new LinkedHashMap<>();
	private final Map<String, ScenarioEngine> engines = new LinkedHashMap<>(4, .75f, true);
	private String defaultId;

	ScenarioCatalog(Path selected, List<Path> directories) throws IOException
	{
		this.selected = selected;
		this.directories = directories;
		refresh();
	}

	synchronized void refresh() throws IOException
	{
		Map<String, Entry> found = new LinkedHashMap<>();
		if (selected != null) add(found, selected, "Selected capture");
		for (Path directory : directories)
		{
			if (!Files.isDirectory(directory)) continue;
			try (Stream<Path> files = Files.list(directory))
			{
				for (Path file : files.filter(p -> p.getFileName().toString().endsWith(".jsonl"))
					.filter(Files::isRegularFile).sorted(Comparator.reverseOrder()).collect(Collectors.toList()))
					add(found, file, directory.endsWith("src/test/resources/recordings") ? "Saved example" : "Local recording");
			}
		}
		if (found.isEmpty()) throw new IOException("No playable BA captures found");
		entries = found;
		engines.clear();
		defaultId = selected != null && found.containsKey(selected.getFileName().toString())
			? selected.getFileName().toString() : found.keySet().stream().max(String::compareTo).get();
	}

	private static void add(Map<String, Entry> found, Path file, String source) throws IOException
	{
		if (!Files.isRegularFile(file) || found.containsKey(file.getFileName().toString())) return;
		Entry entry = inspect(file, source);
		if (entry != null) found.put(entry.id, entry);
	}

	/** Read only metadata fields, skipping bulky NPC/world payloads and incomplete trailing lines. */
	static Entry inspect(Path file, String source) throws IOException
	{
		try (BufferedReader in = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			String line;
			while ((line = in.readLine()) != null)
			{
				Rec.Tick tick = new Rec.Tick();
				try (JsonReader reader = new JsonReader(new StringReader(line)))
				{
					reader.beginObject();
					while (reader.hasNext())
					{
						String key = reader.nextName();
						if (reader.peek() == JsonToken.NULL) { reader.nextNull(); continue; }
						switch (key)
						{
							case "instance": tick.instance = reader.nextBoolean(); break;
							case "tile": tick.tile = Rec.GSON.fromJson(reader, Rec.Pos.class); break;
							case "live": tick.live = Rec.GSON.fromJson(reader, Rec.Live.class); break;
							case "vb":
								tick.vb = new LinkedHashMap<>();
								reader.beginObject();
								while (reader.hasNext()) tick.vb.put(Integer.parseInt(reader.nextName()), reader.nextInt());
								reader.endObject();
								break;
							default: reader.skipValue();
						}
					}
					reader.endObject();
					if (!tick.instance || tick.tile == null || tick.live == null || tick.live.wave < 1 || tick.live.wave > 10
						|| !ArenaTiles.isArenaRegion(RoundReplay.point(tick.tile).getRegionID()) || tick.live.role == null) continue;
					Role role = Role.valueOf(tick.live.role);
					return new Entry(file, role, tick.live.wave, RoundReplay.roleLevels(tick).getOrDefault(role, 0), source);
				}
				catch (RuntimeException | IOException malformedLine)
				{
					// A recording may still be open, or have been interrupted mid-line.
				}
			}
		}
		return null;
	}

	synchronized JsonObject listing()
	{
		JsonObject out = new JsonObject();
		out.addProperty("defaultId", defaultId);
		List<Entry> sorted = new ArrayList<>(entries.values());
		sorted.sort(Comparator.comparing((Entry entry) -> entry.name).reversed());
		out.add("captures", ScenarioEngine.JSON.toJsonTree(sorted));
		return out;
	}

	synchronized ScenarioEngine engine(String id) throws IOException
	{
		String chosen = id == null || id.isBlank() ? defaultId : id;
		Entry entry = entries.get(chosen);
		if (entry == null) throw new IllegalArgumentException("Capture is not in this library");
		ScenarioEngine engine = engines.get(chosen);
		if (engine == null)
		{
			engine = new ScenarioEngine(RecordedRound.read(entry.path));
			engines.put(chosen, engine);
			if (engines.size() > 2) engines.remove(engines.keySet().iterator().next());
		}
		return engine;
	}
}

package com.bautopilot.baautopilot.dev;

import com.bautopilot.baautopilot.model.Role;
import com.google.gson.JsonArray;
