import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class SceneOverlayTest
{
	@Test public void completedBadFoodMarksKeepTheirPurpleMeaning()
	{
		for (boolean done : new boolean[]{false, true})
		{
			Color color = SceneOverlay.markColour(new TileMark(ArenaTiles.trapFood(3), "Trail", done, false));
			assertEquals(Palette.BAD_BAIT.getRed(), color.getRed());
			assertEquals(Palette.BAD_BAIT.getGreen(), color.getGreen());
			assertEquals(Palette.BAD_BAIT.getBlue(), color.getBlue());
		}
	}

	@Test public void badFoodInstructionAndCarriedOpeningCallSharePurpleActionColour() throws Exception
	{
		RoundReplay.Frame trail = RoundReplay.run(RecordedRound.read(Path.of(
			"src/test/resources/recordings/2026-10-18_18-02-54-wave2.jsonl"))).stream().filter(f -> f.snapshot.getTick() == 3581).findFirst().get();
		assertEquals(Step.DEF_DROP, trail.instruction.getStep());
		assertTrue(trail.instruction.isBadBait());
		assertEquals(Palette.BAD_BAIT, Palette.action(trail.instruction, Color.GREEN));
		Instruction call = new Planner().plan(trail.snapshot.toBuilder().shoutCall(BaCall.POISON_WORMS)
			.shoutDone(false).callPeriod(0).build(), Settings.builder().build());
		assertEquals(Step.CALL, call.getStep());
		assertEquals(Step.DEF_DROP, call.getThen());
		assertEquals(Palette.BAD_BAIT, Palette.action(call, Color.GREEN));
	}

	@Test
	public void latestCapturedStackReachesTheWorldPickupBadge() throws Exception
	{
		List<RoundReplay.Frame> frames = RoundReplay.run(RecordedRound.read(Path.of(
			"src/test/resources/recordings/2026-10-18_15-32-31-wave1.jsonl")));
		for (int tick : new int[]{799, 800, 803, 804})
		{
			RoundReplay.Frame frame = frames.stream().filter(f -> f.snapshot.getTick() == tick).findFirst().get();
			assertEquals("Pick up Green eggs ×2", frame.instruction.getHeadline());
			assertEquals(Step.COL_COLLECT, frame.instruction.getStep());
			assertEquals(2, frame.instruction.getPickupCount());
			assertEquals("tick " + tick, "PICK UP ×2", SceneOverlay.targetTag(frame.instruction));
		}
	}

	@Test
	public void pickupBadgeCountsOnlySelectedColourAndUpdatesForCapacityTimeAndFirstCall()
	{
		net.runelite.api.coords.WorldPoint tile = ArenaTiles.attackerWait(3);
		Snapshot s = Snapshot.builder().tick(1000).wave(3).waveTick(10).inArena(true).role(Role.COLLECTOR)
			.playerTile(tile).hp(99).maxHp(99).freeSlots(10).listenCall(BaCall.GREEN_EGG).listenFresh(true)
			.shoutDone(true).ticksToCallChange(40).groundItems(RoundLogic.mergeGround(List.of(
				new GroundItemView(BaIds.EGG_GREEN, tile, 1, false, 990),
				new GroundItemView(BaIds.EGG_GREEN, tile, 2, false, 990),
				new GroundItemView(BaIds.EGG_RED, tile, 5, false, 990)))).build();
		Planner planner = new Planner();
		Settings settings = Settings.builder().build();
		assertEquals("PICK UP ×3", SceneOverlay.targetTag(planner.plan(s, settings)));
		assertEquals("PICK UP", SceneOverlay.targetTag(planner.plan(s.toBuilder().freeSlots(1).build(), settings)));
		assertEquals("PICK UP ×2", SceneOverlay.targetTag(planner.plan(s.toBuilder().ticksToCallChange(5).build(), settings)));
		Instruction call = planner.plan(s.toBuilder().shoutCall(BaCall.ACCURATE).shoutDone(false).shoutSettled(true).build(), settings);
		assertEquals(Step.CALL, call.getStep());
		assertEquals(Step.COL_COLLECT, call.getThen());
		assertEquals("PICK UP ×3", SceneOverlay.targetTag(call));
	}

	@Test
	public void queenPickupBadgeUsesRemainingBatchCount()
	{
		net.runelite.api.coords.WorldPoint tile = ArenaTiles.queenCollectorWatch();
		Snapshot s = Snapshot.builder().tick(1000).wave(10).waveTick(200).inArena(true).role(Role.COLLECTOR)
			.queenAlive(true).playerTile(tile).hp(99).maxHp(99).freeSlots(10).shoutDone(true)
			.groundItems(List.of(new GroundItemView(BaIds.EGG_YELLOW, tile, 3, false, 990))).build();
		Planner planner = new Planner();
		Settings settings = Settings.builder().build();
		assertEquals("PICK UP ×3", SceneOverlay.targetTag(planner.plan(s, settings)));
		Instruction last = planner.plan(s.toBuilder().inventory(Map.of(BaIds.EGG_YELLOW, 4)).build(), settings);
		assertEquals(1, last.getPickupCount());
		assertEquals("PICK UP", SceneOverlay.targetTag(last));
	}

	private static PenanceView enemy(int id, PenanceType type)
	{
		return PenanceView.builder().npcIndex(id).type(type).tile(ArenaTiles.attackerWait(8)).build();
	}

	private static Snapshot base()
	{
		return Snapshot.builder().inArena(true).role(Role.ATTACKER).wave(8).interactingNpc(5).lastTargetNpc(6)
			.penance(List.of(enemy(5, PenanceType.FIGHTER), enemy(6, PenanceType.RANGER))).build();
	}

	@Test
	public void missingOrStaleCallsWarnOverTheCurrentEnemyDuringOtherInstructions()
	{
		for (Step step : List.of(Step.ATT_WAIT_CALL, Step.CALL, Step.ATT_GET_ARROWS, Step.RETREAT))
		{
			Instruction ins = Instruction.of(step, "", "");
			for (Snapshot s : List.of(base(), base().toBuilder().listenCall(BaCall.ACCURATE).listenFresh(false).build()))
			{
				List<Target> warnings = SceneOverlay.attackWarnings(s, ins, false);
				assertEquals(step.toString(), 1, warnings.size());
				assertEquals(5, warnings.get(0).getId());
			}
		}
	}

	@Test
	public void freshCallClearsTheWarningAndAnEarlyHudFlipSuppressesOldAttackBadges()
	{
		Snapshot s = base().toBuilder().listenCall(BaCall.ACCURATE).listenFresh(true).build();
		Instruction ins = Instruction.builder().step(Step.ATT_ATTACK)
			.target(Target.npc(6, s.getPenance().get(1).getTile())).build();
		assertTrue(SceneOverlay.attackWarnings(s, ins, false).isEmpty());
		List<Target> warning = SceneOverlay.attackWarnings(s, ins, true);
		assertEquals(2, warning.size());
		assertEquals(5, warning.get(0).getId());
		assertTrue("The old ATTACK target must get the warning instead", warning.contains(ins.getTarget()));
	}

	@Test
	public void fallbackUsesTheLastLiveTargetButNeverDeadUnseenOrOtherRoleNpcs()
	{
		Instruction wait = Instruction.of(Step.ATT_WAIT_CALL, "", "");
		Snapshot s = base().toBuilder().interactingNpc(-1).build();
		assertEquals(6, SceneOverlay.attackWarnings(s, wait, false).get(0).getId());
		for (PenanceView p : List.of(enemy(6, PenanceType.RANGER).toBuilder().dying(true).build(),
			enemy(6, PenanceType.RANGER).toBuilder().unseen(true).build(), enemy(6, PenanceType.HEALER)))
		{
			assertTrue(SceneOverlay.attackWarnings(s.toBuilder().penance(List.of(p)).build(), wait, false).isEmpty());
		}
		assertTrue(SceneOverlay.attackWarnings(s.toBuilder().role(Role.HEALER).build(), wait, false).isEmpty());
		assertTrue(SceneOverlay.attackWarnings(s.toBuilder().inArena(false).build(), wait, false).isEmpty());
		assertTrue(SceneOverlay.attackWarnings(s.toBuilder().queenAlive(true).build(), wait, false).isEmpty());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.*;
import com.bautopilot.baautopilot.state.*;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID.BarbassaultTurret;
import static org.junit.Assert.*;

public class AttackerOpeningQueenTest
{
	private final Planner planner = new Planner();
	private static Snapshot base(int wave)
	{
		int region = wave == 10 ? ArenaTiles.REGION_WAVE_10 : ArenaTiles.REGION_WAVES_1_9;
		return Snapshot.builder().inArena(true).tick(1000).wave(wave).waveTick(5).role(Role.ATTACKER)
			.hp(77).maxHp(77).shoutDone(true).freeSlots(26).playerTile(ArenaTiles.p(region, 28, 16))
			.listenFresh(true).listenCall(BaCall.ACCURATE).ammoId(BaCall.ACCURATE.getItemId())
			.objects(List.of(new ObjectView(BaIds.ATTACKER_MACHINE, ArenaTiles.p(region, 29, 16)),
				new ObjectView(BaIds.MUSHROOMS[0], ArenaTiles.p(region, 28, 17)),
				new ObjectView(BaIds.LAUNCHERS[0], ArenaTiles.p(region, 22, 33))))
			.build();
	}
	private Instruction plan(Snapshot s) { return planner.plan(s, Settings.builder().build()); }

	@Test public void openingUsesTheWesternApproachBeforeEngagingOnBothArenas()
	{
		for (int wave : new int[]{1, 10})
		{
			Snapshot s = base(wave).toBuilder().listenCall(null).build();
			assertEquals(Step.ATT_POSITION, plan(s).getStep());
			assertEquals(ArenaTiles.collectorWestApproach(wave), plan(s).getTarget().getTile());
			Snapshot west = s.toBuilder().playerTile(ArenaTiles.collectorWestApproach(wave)).build();
			assertEquals(ArenaTiles.collectorBehindHill(wave), plan(west).getTarget().getTile());
			assertNotEquals(Step.ATT_POSITION, plan(s.toBuilder().attackerOpeningComplete(true).build()).getStep());
			assertNotEquals(Step.ATT_POSITION, plan(s.toBuilder().waveTick(60).build()).getStep());
		}
	}

	@Test public void waveTenGetsArrowsFirstAndDoesNotGetSpikesBetweenRegularSpawns()
	{
		Snapshot start = base(10).toBuilder().ammoId(-1).build();
		assertEquals(Step.ATT_GET_ARROWS, plan(start).getStep());
		Snapshot between = base(10).toBuilder().waveTick(100).attackerOpeningComplete(true).build();
		assertEquals(Step.ATT_SUPPORT, plan(between).getStep());
		assertTrue(plan(between).getPriorities().stream().noneMatch(p -> "att.spikes".equals(p.getTask())));
		PenanceView target = PenanceView.builder().type(PenanceType.FIGHTER).npcIndex(9)
			.tile(between.getPlayerTile().dy(2)).build();
		assertEquals(Step.ATT_ATTACK, plan(between.toBuilder().penance(List.of(target)).build()).getStep());
		Snapshot done = between.toBuilder().fighterRangerKills(WaveInfo.fightersTotal(10) + WaveInfo.rangersTotal(10)).build();
		assertEquals(Step.ATT_SPIKES, plan(done).getStep());
	}

	@Test public void completedOpeningIsRememberedAcrossLaterMovementAndResetForTheNextWave()
	{
		RoundLogic logic = new RoundLogic();
		RoundLogic.Hud hud = new RoundLogic.Hud() {
			public boolean visible(int id) { return id >>> 16 == Role.ATTACKER.getHudGroup(); }
			public String text(int id) { return null; }
		};
		logic.tick(100, true, hud, Map.of(), 0, 0, 0);
		logic.observePosition(ArenaTiles.collectorBehindHill(1));
		logic.observePosition(base(1).getPlayerTile());
		assertTrue(logic.snapshot().build().isAttackerOpeningComplete());
		logic.chat(true, "---- Wave: 2 ----", false, 101);
		assertFalse(logic.snapshot().build().isAttackerOpeningComplete());
	}

	@Test public void finishedEggsCueTheCannonBeforeLoadingAndRemainThroughTheVolley()
	{
		Snapshot waiting = base(10).toBuilder().queenAlive(true).queenSpikedPassed(5)
			.inventory(Map.of(BaIds.SPIKES, 3)).eggsRed(1).build();
		assertEquals(Step.QUEEN_WAIT, plan(waiting).getStep());
		Snapshot handoff = waiting.toBuilder().queenOmegaHandoffTick(999).build();
		assertEquals(Step.QUEEN_FIRE, plan(handoff).getStep());
		assertTrue(plan(handoff).getHeadline().contains("Get ready"));
		assertEquals(BarbassaultTurret.OMEGA_QUEEN, TurretChoice.pick(handoff));
		assertEquals(Step.QUEEN_FIRE, plan(waiting.toBuilder().eggsOmega(1).build()).getStep());
		assertEquals(Step.QUEEN_FIRE, plan(waiting.toBuilder().queenOmegaFired(1).build()).getStep());
		assertNotEquals(Step.QUEEN_FIRE, plan(handoff.toBuilder().queenDead(true).build()).getStep());
		assertEquals(Step.QUEEN_PASS, plan(handoff.toBuilder().inventory(Map.of(BaIds.EGG_SPIKED, 1)).build()).getStep());
		assertEquals(Step.QUEEN_SPIKE, plan(handoff.toBuilder().inventory(Map.of(BaIds.EGG_POISONED, 1, BaIds.SPIKES, 1)).build()).getStep());
	}
}

package com.bautopilot.baautopilot.plan;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.Arrays;
import java.util.Collections;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class ChooserTest
{
	private static final int R = ArenaTiles.REGION_WAVES_1_9;
	private static final WorldPoint ME = ArenaTiles.p(R, 40, 35);

	private static Candidate at(Tier tier, String task, int dx)
	{
		return Candidate.task(tier, task, Instruction.builder().step(Step.DEF_HOLD).headline(task)
			.target(Target.tile(ME.dx(dx), task)).build());
	}

	private static Snapshot me(String lastTask)
	{
		return Snapshot.builder().playerTile(ME).lastTask(lastTask).build();
	}

	@Test
	public void theDebuggerSeesEveryCandidateAndWhyOneWon()
	{
		Candidate near = at(Tier.MAINTENANCE, "near", 1);
		Candidate far = at(Tier.MAINTENANCE, "far", 20);
		Candidate top = at(Tier.TIME_CRITICAL, "top", 30);
		Instruction ins = Chooser.choose(me(null), Arrays.asList(near, far, top));
		assertEquals(3, ins.getPriorities().size());
		assertEquals("top", ins.getPriorities().get(0).getTask());
		assertEquals(true, ins.getPriorities().get(0).isChosen());
		assertEquals("Only TIME_CRITICAL candidate", ins.getDecidedBy());
		// Same tier: the shorter walk, and the reason says so
		assertEquals("Shortest walk in MAINTENANCE", Chooser.choose(me(null), Arrays.asList(near, far)).getDecidedBy());
		// A committed task is kept, and the reason says so
		assertEquals("Committed task far kept (no higher tier)", Chooser.choose(me("far"), Arrays.asList(near, far)).getDecidedBy());
	}

	@Test
	public void highestTierWins()
	{
		Candidate near = at(Tier.MAINTENANCE, "near", 1);
		Candidate far = at(Tier.TIME_CRITICAL, "far", 20);
		assertEquals("far", Chooser.pick(me(null), Arrays.asList(near, far)).getTask());
		assertNull(Chooser.pick(me(null), Collections.emptyList()));
	}

	@Test
	public void withinATierEarliestDeadlineThenShortestWalk()
	{
		Candidate near = at(Tier.TIME_CRITICAL, "near", 1);
		Candidate far = at(Tier.TIME_CRITICAL, "far", 20);
		assertEquals("near", Chooser.pick(me(null), Arrays.asList(far, near)).getTask());
		assertEquals("far", Chooser.pick(me(null), Arrays.asList(near, far.withDeadline(10))).getTask());
		assertEquals("near", Chooser.pick(me(null), Arrays.asList(far.withDeadline(10), near.withDeadline(5))).getTask());
	}

	@Test
	public void aCommittedTaskIsKeptUntilAHigherTierShowsUp()
	{
		Candidate trip = at(Tier.MAINTENANCE, "trip", 20);
		Candidate nearer = at(Tier.MAINTENANCE, "nearer", 1);
		// Fresh: the nearer one
		assertEquals("nearer", Chooser.pick(me(null), Arrays.asList(trip, nearer)).getTask());
		// Under way: the trip, even with something nearer or due sooner of the same tier
		assertEquals("trip", Chooser.pick(me("trip"), Arrays.asList(trip, nearer.withDeadline(0))).getTask());
		// A strictly higher tier interrupts it
		Candidate urgent = at(Tier.TIME_CRITICAL, "urgent", 30);
		assertEquals("urgent", Chooser.pick(me("trip"), Arrays.asList(trip, nearer, urgent)).getTask());
		// Done (no longer listed): back to ranking
		assertEquals("nearer", Chooser.pick(me("trip"), Collections.singletonList(nearer)).getTask());
		// Only sticky tasks are kept
		Candidate hold = trip.withSticky(false);
		assertEquals("nearer", Chooser.pick(me("trip"), Arrays.asList(hold, nearer)).getTask());
	}

	@Test
	public void theChosenInstructionCarriesItsTaskAndTier()
	{
		Instruction ins = Chooser.choose(me(null), Collections.singletonList(at(Tier.IDLE, "wait", 0)));
		assertEquals("wait", ins.getTask());
		assertEquals(Tier.IDLE, ins.getTier());
	}

	@Test
	public void weightedValueBeatsTierDeadlineAndStickyCommitment()
	{
		Candidate eggs = Candidate.of(Tier.MAINTENANCE, "eggs", Instruction.of(Step.COL_COLLECT, "Eggs", "")
			.toBuilder().score(80.0).scoreTerms(java.util.Map.of("reserve", 80.0)).build());
		Candidate cannon = Candidate.task(Tier.TEAM_BLOCKING, "trip", Instruction.of(Step.COL_LOAD, "Load", "")
			.toBuilder().score(35.0).scoreTerms(java.util.Map.of("support", 35.0)).build()).withDeadline(0);
		Instruction picked = Chooser.choose(me("trip"), Arrays.asList(cannon, eggs));
		assertEquals("eggs", picked.getTask());
		assertEquals(80, picked.getScore(), .001);
		assertEquals("eggs", picked.getPriorities().get(0).getTask());
		assertEquals(80, picked.getPriorities().get(0).getScoreTerms().get("reserve"), .001);
	}

	@Test(expected = IllegalArgumentException.class)
	public void missingScoresCannotSilentlyFallBackToTierPrecedence()
	{
		Candidate scored = Candidate.of(Tier.MAINTENANCE, "eggs", Instruction.of(Step.COL_COLLECT, "Eggs", "")
			.toBuilder().score(80.0).build());
		Chooser.choose(me(null), Arrays.asList(scored, at(Tier.TEAM_BLOCKING, "trip", 1)));
	}

	@Test
	public void walkingCostComesFromTheCollisionMapWhenKnown()
	{
		// A wall in the way: the straight-line nearer one is the longer walk
		Snapshot s = me(null).toBuilder().walkCost(tile -> tile.equals(ME.dx(1)) ? 15 : -1).build();
		Candidate behindWall = at(Tier.MAINTENANCE, "behindWall", 1);
		Candidate open = at(Tier.MAINTENANCE, "open", 5);
		assertEquals("open", Chooser.pick(s, Arrays.asList(behindWall, open)).getTask());
		assertEquals("behindWall", Chooser.pick(me(null), Arrays.asList(behindWall, open)).getTask());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.model.WaveInfo;
import com.bautopilot.baautopilot.state.GroundItemView;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertNotEquals;

public class CollectorBlueCallsTest
{
	private static final int R = ArenaTiles.REGION_WAVES_1_9;
	private static final WorldPoint ME = ArenaTiles.p(R, 40, 50);
	private static final WorldPoint HOPPER = ArenaTiles.p(R, 40, 30);
	private static final WorldPoint LAUNCHER = ArenaTiles.p(R, 41, 30);
	private static final Settings SETTINGS = Settings.builder().collectorLoadAt(15).build();
	private final Planner planner = new Planner();

	private static Snapshot base()
	{
		return Snapshot.builder().tick(1000).inArena(true).role(Role.COLLECTOR).wave(3).waveTick(70)
			.callPeriod(1).ticksToCallChange(30).listenCall(BaCall.BLUE_EGG).listenFresh(true).shoutDone(true)
			.playerTile(ME).hp(99).maxHp(99).freeSlots(15)
			.eggsRed(1).eggsGreen(1)
			.objects(List.of(new ObjectView(BaIds.HOPPERS[0], HOPPER), new ObjectView(BaIds.LAUNCHERS[0], LAUNCHER)))
			.penance(List.of(PenanceView.builder().npcIndex(9).type(PenanceType.RUNNER).tile(ArenaTiles.p(R, 44, 40)).build()))
			.groundItems(List.of(new GroundItemView(BaIds.EGG_BLUE, ME.dx(-1), 1, false, 810))).build();
	}

	@Test
	public void blueCallLoadsConfiguredBatchAcrossInventoryAndBagBeforeAnExpiringBlue()
	{
		Snapshot s = base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 13, BaIds.EGG_BLUE, 2)).bagRed(1).bagGreen(1)
			.lastTask("col.collect").lastTargetTile(ME.dx(-1)).build();
		Instruction ins = planner.plan(s, SETTINGS);
		assertEquals(Step.COL_LOAD, ins.getStep());
		assertEquals(Tier.TIME_CRITICAL, ins.getTier());
		assertEquals(HOPPER, ins.getTarget().getTile());
		assertTrue(ins.getDetail().contains("Blue call"));
		assertTrue(ins.getDetail().contains("4 red + 1 green fit"));
		assertFalse(ins.getItems().contains(BaIds.EGG_BLUE));
	}

	@Test
	public void loadingComesBeforeBlueDeletionWithAFullInventory()
	{
		Snapshot s = base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 3, BaIds.EGG_BLUE, 20)).freeSlots(0).build();
		assertEquals(Step.COL_LOAD, planner.plan(s, SETTINGS).getStep());
	}

	@Test
	public void ordinaryShootingYieldsToCollectionAndSpareCleanup()
	{
		Snapshot s = base().toBuilder().inventory(Map.of(BaIds.EGG_BLUE, 2)).lastTask("col.collect").build();
		Instruction fire = planner.plan(s, SETTINGS);
		assertNotEquals(Step.COL_FIRE, fire.getStep());
		// Cleanup is also spare work when there is no ground egg or no inventory room.
		assertEquals(Step.COL_BLUE, planner.plan(s.toBuilder().groundItems(List.of()).freeSlots(0).build(), SETTINGS).getStep());
	}

	@Test
	public void fullHoppersDoNotCauseAPointlessLoadAndOnlyFittingEggsCount()
	{
		Snapshot s = base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 20, BaIds.EGG_GREEN, 1))
			.eggsRed(5).eggsGreen(1).penance(List.of()).build();
		// Only one green fits; the twenty reds cannot justify this long trip.
		assertEquals(Step.COL_COLLECT, planner.plan(s, SETTINGS).getStep());
		Instruction full = planner.plan(base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 20, BaIds.EGG_BLUE, 2))
			.eggsRed(5).eggsGreen(5).build(), SETTINGS);
		assertNotEquals(Step.COL_FIRE, full.getStep());
		assertNotEquals(Step.COL_LOAD, full.getStep());
	}

	@Test
	public void bluesRemainFallbackWorkWhenNothingCanBeLoadedOrShot()
	{
		Snapshot s = base().toBuilder().eggsRed(0).eggsGreen(0).inventory(Map.of(BaIds.EGG_RED, 1)).build();
		Instruction collect = planner.plan(s, SETTINGS);
		assertEquals(Step.COL_COLLECT, collect.getStep());
		assertEquals(BaIds.EGG_BLUE, collect.getTarget().getId());
		assertEquals(Tier.IDLE, collect.getTier());
		Instruction delete = planner.plan(s.toBuilder().inventory(Map.of(BaIds.EGG_BLUE, 28)).freeSlots(0).build(), SETTINGS);
		assertEquals(Step.COL_BLUE, delete.getStep());
		assertEquals(Tier.IDLE, delete.getTier());
		// Loaded eggs alone do not justify firing if no launcher has an in-range target.
		assertEquals(Step.COL_COLLECT, planner.plan(base().toBuilder().penance(List.of()).build(), SETTINGS).getStep());
	}

	@Test
	public void blueCleanupAlsoYieldsToUsefulCollectionOnOtherCalls()
	{
		Snapshot s = base().toBuilder().listenCall(BaCall.RED_EGG).inventory(Map.of(BaIds.EGG_BLUE, 2))
			.penance(List.of()).groundItems(List.of(new GroundItemView(BaIds.EGG_RED, ME.dx(-1), 1, false, 990))).build();
		Instruction ins = planner.plan(s, SETTINGS);
		assertEquals(Step.COL_COLLECT, ins.getStep());
		assertEquals(BaIds.EGG_RED, ins.getTarget().getId());
	}

	@Test
	public void staleCallsDoNotOpenANewBlueOpportunityAndOwedCallsStillLead()
	{
		Snapshot s = base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 3)).build();
		assertEquals(Step.COL_WAIT_CALL, planner.plan(s.toBuilder().listenFresh(false).build(), SETTINGS).getStep());
		assertEquals(Step.CALL, planner.plan(s.toBuilder().shoutDone(false).shoutCall(BaCall.ACCURATE).build(), SETTINGS).getStep());
		assertEquals(Step.RETREAT, planner.plan(s.toBuilder().hp(5).build(), SETTINGS).getStep());
	}

	/** Penance all dead, cannon preloaded: spare eggs of every colour go (reported 2026-10-19: not only blue). */
	@Test
	public void queenPreparationClearsSpareEggsOfEveryColour()
	{
		Snapshot s = base().toBuilder().wave(10).penance(List.of()).inventory(Map.of(BaIds.EGG_BLUE, 2, BaIds.EGG_RED, 1))
			.fighterRangerKills(WaveInfo.fightersTotal(10) + WaveInfo.rangersTotal(10))
			.runnersKilled(WaveInfo.runnersTotal(10)).healersKilled(WaveInfo.healersTotal(10)).build();
		Instruction ins = planner.plan(s, SETTINGS);
		assertEquals(Step.COL_DISCARD, ins.getStep());
		assertTrue(ins.getItems().contains(BaIds.EGG_RED) && ins.getItems().contains(BaIds.EGG_BLUE));
		assertEquals(Step.COL_QUEEN_READY, planner.plan(s.toBuilder().inventory(Map.of()).build(), SETTINGS).getStep());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.RoundLogic;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class CollectorCannonPriorityTest
{
	private static final int R = ArenaTiles.REGION_WAVES_1_9;
	private static final WorldPoint ME = ArenaTiles.p(R, 40, 45);
	private static final Settings SETTINGS = Settings.builder().collectorLoadAt(15).build();
	private final Planner planner = new Planner();

	private static Snapshot base()
	{
		return Snapshot.builder().tick(1000).inArena(true).role(Role.COLLECTOR).wave(3).waveTick(70)
			.listenCall(BaCall.GREEN_EGG).listenFresh(true).shoutDone(true).freeSlots(10).hp(99).maxHp(99).playerTile(ME)
			.inventory(Map.of(BaIds.EGG_RED, 15)).eggsRed(2).eggsGreen(3)
			.objects(List.of(new ObjectView(BaIds.HOPPERS[0], ME.dy(-10)), new ObjectView(BaIds.LAUNCHERS[0], ME.dy(-9))))
			.groundItems(List.of(new com.bautopilot.baautopilot.state.GroundItemView(BaIds.EGG_GREEN, ME.dx(1), 1, false, 990)))
			.penance(List.of(npc(PenanceType.HEALER, ME.dy(-1)))).build();
	}

	private static PenanceView npc(PenanceType type, WorldPoint tile)
	{
		return PenanceView.builder().npcIndex(9).type(type).tile(tile).build();
	}

	@Test
	public void lowRedsRequireAConfirmedRecentShotRatherThanAnOldAverage()
	{
		Snapshot s = base().toBuilder().launcherShotsPerTick(0.8).build();
		assertFalse(CollectorPlanner.supportReady(s));
		double prior = Double.POSITIVE_INFINITY;
		for (int age : new int[]{0, 4, 8})
		{
			Instruction urgent = planner.plan(s.toBuilder().lastLauncherShotTick(1000 - age).build(), SETTINGS);
			double value = urgent.getPriorities().stream().filter(p -> p.getHeadline().startsWith("Load"))
				.findFirst().get().getScoreTerms().get("active shooter");
			assertTrue(value > 0 && value < prior);
			prior = value;
		}
		for (int shot : new int[]{-1, 991, 1001})
		{
			Snapshot inactive = s.toBuilder().lastLauncherShotTick(shot).build();
			assertFalse(CollectorPlanner.supportReady(inactive));
			Instruction supply = planner.plan(inactive, SETTINGS);
			assertEquals(Step.COL_LOAD, supply.getStep());
			assertEquals("col.load", supply.getTask());
			assertNotEquals(Tier.TEAM_BLOCKING, supply.getTier());
		}
	}

	@Test
	public void healthyRedsOrGreenOnlyInventoryDoNotJustifyARedRefill()
	{
		Snapshot active = base().toBuilder().lastLauncherShotTick(1000).build();
		assertFalse(CollectorPlanner.supportReady(active.toBuilder().eggsRed(3).build()));
		assertFalse(CollectorPlanner.supportReady(active.toBuilder().eggsRed(5).eggsGreen(0).build()));
		assertFalse(CollectorPlanner.supportReady(active.toBuilder().inventory(Map.of(BaIds.EGG_GREEN, 20)).build()));
		assertFalse(CollectorPlanner.supportReady(active.toBuilder().eggsRed(0).lastLauncherShotTick(-1).build()));
	}

	@Test
	public void onlyEscapingRunnersCreateTheRunnerException()
	{
		Snapshot empty = base().toBuilder().eggsRed(0).eggsGreen(0).build();
		WorldPoint trap = ArenaTiles.trapFood(3);
		for (WorldPoint tile : List.of(trap, trap.dy(5)))
		{
			assertFalse(CollectorPlanner.supportReady(empty.toBuilder().penance(List.of(npc(PenanceType.RUNNER, tile))).build()));
		}
		Snapshot escaping = empty.toBuilder().penance(List.of(npc(PenanceType.RUNNER, trap.dy(-4)))).build();
		assertTrue(CollectorPlanner.supportReady(escaping));
		assertEquals(Step.COL_LOAD, planner.plan(escaping, SETTINGS).getStep());
		assertFalse(CollectorPlanner.supportReady(escaping.toBuilder()
			.penance(List.of(npc(PenanceType.RUNNER, trap.dy(-40)))).build()));
	}

	@Test
	public void loadedAmmoDoesNotPullTheCollectorIntoOrdinaryShooting()
	{
		Snapshot s = base().toBuilder().eggsRed(5).inventory(Map.of(BaIds.EGG_GREEN, 20))
			.penance(List.of(npc(PenanceType.RUNNER, ArenaTiles.trapFood(3).dy(-4)))).build();
		assertFalse(CollectorPlanner.supportReady(s));
		Instruction fire = planner.plan(s, SETTINGS);
		assertEquals(Step.COL_COLLECT, fire.getStep());
		assertTrue(fire.getPriorities().stream().filter(p -> "col.escape.fire".equals(p.getTask()))
			.allMatch(p -> p.getScore() < fire.getScore()));
	}

	@Test
	public void anExpiredSupportTripCannotBecomeABlueBatchCommitment()
	{
		Snapshot s = base().toBuilder().listenCall(BaCall.BLUE_EGG).inventory(Map.of(BaIds.EGG_RED, 3))
			.eggsRed(1).eggsGreen(0).lastLauncherShotTick(1000).build();
		Instruction urgent = planner.plan(s, SETTINGS);
		assertEquals("col.support", urgent.getTask());
		Snapshot stale = s.toBuilder().tick(1009).eggsRed(0).tasks(urgent.getTasks()).lastTask(urgent.getTask())
			.lastTargetTile(urgent.getTarget().getTile()).groundItems(List.of(new com.bautopilot.baautopilot.state.GroundItemView(
				BaIds.EGG_BLUE, ME.dx(1), 1, false, 1000))).penance(List.of()).build();
		Instruction expired = planner.plan(stale, SETTINGS);
		assertNotEquals(Step.COL_LOAD, expired.getStep());
		assertNotEquals(Tier.TEAM_BLOCKING, expired.getTier());
		assertFalse(expired.getTasks().getEntries().containsKey("col.support"));
		assertEquals(-1, expired.getTasks().lastActive("col.load"));
	}

	@Test
	public void observedAmmoDropsRecordShotsButLoadingAndResetDoNot()
	{
		RoundLogic logic = new RoundLogic();
		RoundLogic.Hud hud = new RoundLogic.Hud()
		{
			public boolean visible(int component) { return false; }
			public String text(int component) { return null; }
		};
		logic.tick(1000, true, hud, Map.of(), 0, 5, 0);
		assertEquals(-1, logic.snapshot().build().getLastLauncherShotTick());
		logic.tick(1001, true, hud, Map.of(), 0, 4, 0);
		assertEquals(1001, logic.snapshot().build().getLastLauncherShotTick());
		logic.tick(1002, true, hud, Map.of(), 0, 5, 0);
		assertEquals(1001, logic.snapshot().build().getLastLauncherShotTick());
		logic.tick(1010, true, hud, Map.of(), 0, 5, 0);
		assertFalse(CollectorPlanner.activelyFiring(logic.snapshot().build()));
		logic.reset();
		assertEquals(-1, logic.snapshot().build().getLastLauncherShotTick());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.state.GroundItemView;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class CollectorFallbackTest
{
	private static final WorldPoint ME = ArenaTiles.p(ArenaTiles.REGION_WAVES_1_9, 20, 44);
	private final Planner planner = new Planner();
	private static Snapshot base(BaCall call)
	{
		return Snapshot.builder().tick(1000).wave(4).waveTick(100).inArena(true).role(Role.COLLECTOR)
			.collectorOpeningComplete(true).playerTile(ME).hp(77).maxHp(77).shoutDone(true)
			.listenCall(call).listenFresh(true).ticksToCallChange(40).freeSlots(10)
			.groundItems(List.of(new GroundItemView(call.getItemId(), ME.dx(10), 1, false, 990))).build();
	}
	private Instruction plan(Snapshot s) { return planner.plan(s, Settings.builder().build()); }

	@Test public void waitingForFutureRedsCannotBeatAReachableRedAlreadyOnTheGround()
	{
		Instruction decision = plan(base(BaCall.RED_EGG).toBuilder().inventory(Map.of(BaIds.EGG_RED, 4)).build());
		assertEquals(Step.COL_COLLECT, decision.getStep());
		assertTrue(decision.getPriorities().stream().filter(p -> "col.follow".equals(p.getTask()))
			.allMatch(p -> p.getScore() < decision.getScore() && p.getScoreTerms().get("visible egg before waiting") < 0));
	}

	@Test public void negativePickupScoresStillBeatWaitingWhenNoOtherWorkIsWorthMore()
	{
		for (BaCall call : List.of(BaCall.BLUE_EGG, BaCall.GREEN_EGG))
		{
			Snapshot s = base(call);
			WorldPoint pile = s.getGroundItems().get(0).getTile();
			s = s.toBuilder().penance(List.of(PenanceView.builder().npcIndex(1).type(PenanceType.HEALER).tile(pile).build())).build();
			Instruction decision = plan(s);
			assertEquals(call.name(), Step.COL_COLLECT, decision.getStep());
			assertTrue(decision.getScore() < 0);
			assertEquals(pile, decision.getTarget().getTile());
		}
	}

	@Test public void nearbyPilesStillBeatDistantOnesAndScoresRemainExplainable()
	{
		for (BaCall call : List.of(BaCall.RED_EGG, BaCall.GREEN_EGG, BaCall.BLUE_EGG))
		{
			Snapshot s = base(call).toBuilder().groundItems(List.of(
				new GroundItemView(call.getItemId(), ME.dx(10), 1, false, 990),
				new GroundItemView(call.getItemId(), ME.dx(2), 1, false, 990))).build();
			Instruction decision = plan(s);
			assertEquals(Step.COL_COLLECT, decision.getStep());
			assertEquals(ME.dx(2), decision.getTarget().getTile());
			for (PriorityLine line : decision.getPriorities())
			{
				assertTrue(Double.isFinite(line.getScore()));
				assertEquals(line.getScore(), line.getScoreTerms().values().stream().mapToDouble(Double::doubleValue).sum(), 1e-8);
			}
		}
	}

	@Test public void wrongColourStaleCallLatePickupsDistanceAndFullInventoryStillBlockCollection()
	{
		Snapshot s = base(BaCall.RED_EGG);
		for (Snapshot blocked : List.of(s.toBuilder().listenCall(BaCall.GREEN_EGG).build(), s.toBuilder().listenFresh(false).build(),
			s.toBuilder().ticksToCallChange(5).build(), s.toBuilder().freeSlots(0).build(),
			s.toBuilder().groundItems(List.of(new GroundItemView(BaIds.EGG_RED, ME.dx(13), 1, false, 990))).build()))
			assertNotEquals(Step.COL_COLLECT, plan(blocked).getStep());
		assertEquals(Step.COL_FOLLOW, plan(s.toBuilder().groundItems(List.of()).build()).getStep());
	}

	@Test public void waveTenBlueOnlyCountsAsUsefulWhenItEnablesAnEmptyCannon()
	{
		Snapshot s = base(BaCall.BLUE_EGG).toBuilder().wave(10).groundItems(List.of(
			new GroundItemView(BaIds.EGG_BLUE, ME.dx(1), 5, false, 990))).build();
		Instruction first = plan(s);
		assertEquals(Step.COL_COLLECT, first.getStep());
		assertEquals(1, first.getPickupCount());
		for (Snapshot supplied : List.of(s.toBuilder().eggsRed(1).build(), s.toBuilder().eggsBlue(1).build(),
			s.toBuilder().inventory(Map.of(BaIds.EGG_BLUE, 1)).build(), s.toBuilder().bagRed(1).build(), s.toBuilder().bagBlue(1).build()))
			assertNotEquals(Step.COL_COLLECT, plan(supplied).getStep());
	}
}

package com.bautopilot.baautopilot.plan;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.state.GroundItemView;
import com.bautopilot.baautopilot.state.RoundLogic;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

/**
 * Eggs a left-click takes come first; one under another item (right-click, Take) only wins when the
 * left-clickable one is much further away (reported 2026-10-19).
 */
public class CollectorLeftClickTest
{
	private static final int R = ArenaTiles.REGION_WAVES_1_9;
	private static final WorldPoint ME = ArenaTiles.p(R, 21, 40);
	private final Planner planner = new Planner();
	private final Settings settings = Settings.builder().build();

	private static Snapshot with(GroundItemView... eggs)
	{
		return Snapshot.builder().tick(1000).inArena(true).role(Role.COLLECTOR).wave(4).waveTick(120)
			.callPeriod(2).ticksToCallChange(30).listenCall(BaCall.RED_EGG).listenFresh(true).shoutDone(true)
			.collectorOpeningComplete(true).playerTile(ME).hp(99).maxHp(99).freeSlots(20)
			.groundItems(List.of(eggs)).build();
	}

	private static GroundItemView red(int dx, boolean underneath)
	{
		return new GroundItemView(BaIds.EGG_RED, ME.dx(dx), 1, false, 990, underneath);
	}

	@Test
	public void aLeftClickableEggBeatsASlightlyNearerOneUnderAnotherItem()
	{
		Instruction ins = planner.plan(with(red(1, true), red(-3, false)), settings);
		assertEquals(Step.COL_COLLECT, ins.getStep());
		assertEquals(ME.dx(-3), ins.getTarget().getTile());
		assertFalse(ins.isRightClick());
	}

	@Test
	public void aMuchNearerEggUnderAnotherItemWinsAndSaysToRightClick()
	{
		Instruction ins = planner.plan(with(red(1, true), red(-10, false)), settings);
		assertEquals(ME.dx(1), ins.getTarget().getTile());
		assertTrue(ins.isRightClick());
		assertTrue(ins.getHeadline().contains("right-click"));
	}

	@Test
	public void mergingAPileKeepsItLeftClickableWhenAnyPartIsOnTop()
	{
		List<GroundItemView> merged = RoundLogic.mergeGround(List.of(red(1, true), red(1, false)));
		assertEquals(1, merged.size());
		assertEquals(2, merged.get(0).getQuantity());
		assertFalse(merged.get(0).isUnderneath());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.state.GroundItemView;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.RoundLogic;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class CollectorNavigationTest
{
	private static final int R = ArenaTiles.REGION_WAVES_1_9;
	private static final WorldPoint ME = ArenaTiles.p(R, 20, 44);
	private final Planner planner = new Planner();
	private static Snapshot base()
	{
		return Snapshot.builder().tick(1000).inArena(true).role(Role.COLLECTOR).wave(3).waveTick(100)
			.collectorOpeningComplete(true).listenCall(BaCall.RED_EGG).listenFresh(true).shoutDone(true)
			.ticksToCallChange(40).freeSlots(10).hp(77).maxHp(77).playerTile(ME).build();
	}
	private Instruction plan(Snapshot s) { return planner.plan(s, Settings.builder().build()); }
	private static GroundItemView egg(WorldPoint tile, int quantity, int age)
	{
		return new GroundItemView(BaIds.EGG_RED, tile, quantity, false, 1000 - age);
	}
	private static Snapshot remembered(Snapshot s, WorldPoint tile)
	{
		return s.toBuilder().lastTask("col.collect").lastStep(Step.COL_COLLECT)
			.lastActionTarget(Target.groundItem(BaIds.EGG_RED, tile)).lastTargetTile(tile).build();
	}

	@Test public void nearbyTargetHoldsUnderTheMouseButADistantTargetCanYield()
	{
		WorldPoint old = ME.dx(2), near = ME.dx(1);
		Snapshot s = base().toBuilder().groundItems(List.of(egg(old, 1, 10), egg(near, 1, 180))).build();
		assertEquals(old, plan(remembered(s, old)).getTarget().getTile());
		assertEquals(near, plan(remembered(s.toBuilder().groundItems(List.of(egg(near, 1, 180))).build(), old)).getTarget().getTile());
		WorldPoint far = ME.dx(14);
		assertEquals(near, plan(remembered(s.toBuilder().groundItems(List.of(egg(far, 1, 180), egg(near, 1, 1))).build(), far)).getTarget().getTile());
	}

	@Test public void ageCannotPullUsPastAFreshNearbyEgg()
	{
		Snapshot s = base().toBuilder().groundItems(List.of(egg(ME.dx(20), 1, 180), egg(ME.dx(1), 1, 1))).build();
		assertEquals(ME.dx(1), plan(s).getTarget().getTile());
	}

	@Test public void blueTargetAlsoYieldsWhenANewEggIsMuchNearer()
	{
		Snapshot s = base().toBuilder().listenCall(BaCall.BLUE_EGG).groundItems(List.of(
			new GroundItemView(BaIds.EGG_BLUE, ME.dx(8), 1, false, 990),
			new GroundItemView(BaIds.EGG_BLUE, ME.dx(2), 1, false, 990)))
			.lastTask("col.collect").lastStep(Step.COL_COLLECT).lastActionTarget(Target.groundItem(BaIds.EGG_BLUE, ME.dx(8))).build();
		assertEquals(ME.dx(2), plan(s).getTarget().getTile());
	}

	@Test public void callDeadlineIncludesRunningReactionAndEachPickup()
	{
		GroundItemView pile = egg(ME.dx(3), 8, 1);
		Snapshot s = base().toBuilder().ticksToCallChange(7).groundItems(List.of(pile)).build();
		assertEquals(2, CollectorPlanner.pickable(s, pile));
		assertTrue(plan(s).getHeadline(), plan(s).getHeadline().endsWith("×2"));
		Snapshot late = remembered(s.toBuilder().ticksToCallChange(5).build(), pile.getTile());
		assertNotEquals(Step.COL_COLLECT, plan(late).getStep());
		assertEquals(0, CollectorPlanner.pickable(late, pile));
	}

	@Test public void pickupQuantityIsLimitedByBothSpaceAndDespawn()
	{
		GroundItemView pile = egg(ME, 5, 194);
		Snapshot s = base().toBuilder().freeSlots(2).groundItems(List.of(pile)).build();
		assertEquals(2, CollectorPlanner.pickable(s, pile));
		assertTrue(plan(s).getHeadline().endsWith("×2"));
		assertEquals(0, CollectorPlanner.pickable(s.toBuilder().freeSlots(0).build(), pile));
		assertEquals(0, CollectorPlanner.pickable(s, egg(ME, 5, 197)));
	}

	@Test public void changedColourOrStaleCallReleasesThePreviousPile()
	{
		Snapshot s = remembered(base().toBuilder().groundItems(List.of(egg(ME, 1, 1))).build(), ME);
		assertNotEquals(Step.COL_COLLECT, plan(s.toBuilder().listenCall(BaCall.GREEN_EGG).build()).getStep());
		assertNotEquals(Step.COL_COLLECT, plan(s.toBuilder().listenFresh(false).build()).getStep());
	}

	@Test public void sharedAmmunitionUsesNearHopperEvenWhenOnlyFarCannonCanRescue()
	{
		WorldPoint near = ME.dy(-9), far = ME.dx(20).dy(-9);
		Snapshot s = base().toBuilder().listenCall(BaCall.BLUE_EGG).inventory(Map.of(BaIds.EGG_RED, 20))
			.objects(List.of(new ObjectView(BaIds.HOPPERS[0], near), new ObjectView(BaIds.HOPPERS[1], far),
				new ObjectView(BaIds.LAUNCHERS[0], near.dx(-1)), new ObjectView(BaIds.LAUNCHERS[1], far.dx(-1))))
			.penance(List.of(PenanceView.builder().npcIndex(2).type(PenanceType.RUNNER)
				.tile(far.dy(-14)).build())).build();
		assertEquals(Step.COL_LOAD, plan(s).getStep());
		assertEquals(near, plan(s).getTarget().getTile());
	}

	@Test public void distantRescueShotDoesNotDragCollectorAcrossArena()
	{
		WorldPoint cannon = ME.dx(20).dy(-10);
		Snapshot s = base().toBuilder().listenCall(BaCall.BLUE_EGG).eggsRed(5)
			.objects(List.of(new ObjectView(BaIds.LAUNCHERS[0], cannon)))
			.penance(List.of(PenanceView.builder().npcIndex(2).type(PenanceType.RUNNER).tile(cannon.dy(-14)).build())).build();
		assertNotEquals(Step.COL_FIRE, plan(s).getStep());
		assertEquals(Step.COL_FIRE, plan(s.toBuilder().playerTile(cannon.dy(1)).build()).getStep());
	}

	@Test public void openingMovesBeforeTheEggCallThenStopsReturningToAFixedSpot()
	{
		Snapshot s = base().toBuilder().collectorOpeningComplete(false).waveTick(2).listenCall(null).listenFresh(false)
			.playerTile(ArenaTiles.p(R, 33, 16)).build();
		assertEquals(Step.COL_POSITION, plan(s).getStep());
		assertEquals(ArenaTiles.collectorWestApproach(3), plan(s).getTarget().getTile());
		assertEquals(ArenaTiles.collectorBehindHill(3), plan(s.toBuilder().playerTile(ArenaTiles.collectorWestApproach(3)).build()).getTarget().getTile());
		Snapshot returned = s.toBuilder().collectorOpeningComplete(true).build();
		assertEquals(Target.Kind.NONE, plan(returned).getTarget().getKind());
		assertEquals(Target.Kind.NONE, plan(s.toBuilder().waveTick(60).build()).getTarget().getKind());
	}

	@Test public void reachingTheHillIsRememberedUntilTheNextWave()
	{
		RoundLogic logic = new RoundLogic();
		logic.tick(100, true, new RoundLogic.Hud() {
			public boolean visible(int id) { return id >>> 16 == Role.COLLECTOR.getHudGroup(); }
			public String text(int id) { return null; }
		}, Map.of(), 0, 0, 0);
		logic.observePosition(ArenaTiles.collectorBehindHill(3));
		logic.observePosition(ArenaTiles.p(R, 20, 25));
		assertTrue(logic.snapshot().build().isCollectorOpeningComplete());
		logic.chat(true, "---- Wave: 4 ----", false, 101);
		assertFalse(logic.snapshot().build().isCollectorOpeningComplete());
	}

	@Test public void fullInventoryDiscardsGreenForNearbyRedsAndPrefersBlueWhenAvailable()
	{
		Snapshot s = base().toBuilder().freeSlots(0).bagGreen(4).inventory(Map.of(BaIds.EGG_GREEN, 20))
			.groundItems(List.of(egg(ME.dx(1), 3, 1))).build();
		Instruction discard = plan(s);
		assertEquals(Step.COL_DISCARD, discard.getStep());
		assertEquals(Set.of(BaIds.EGG_GREEN), discard.getItems());
		assertEquals(Set.of(BaIds.EGG_BLUE), plan(s.toBuilder().inventory(Map.of(BaIds.EGG_GREEN, 20, BaIds.EGG_BLUE, 1)).build()).getItems());
		Snapshot room = s.toBuilder().freeSlots(1).inventory(Map.of(BaIds.EGG_GREEN, 19)).build();
		assertEquals(Step.COL_COLLECT, plan(room).getStep());
	}

	@Test public void greenDiscardNeedsInventoryEggsAndTimeToCollectRed()
	{
		Snapshot s = base().toBuilder().freeSlots(0).inventory(Map.of(BaIds.EGG_GREEN, 20))
			.groundItems(List.of(egg(ME.dx(1), 1, 1))).build();
		for (Snapshot noDiscard : List.of(s.toBuilder().freeSlots(3).build(), s.toBuilder().ticksToCallChange(4).build(),
			s.toBuilder().groundItems(List.of()).build(), s.toBuilder().inventory(Map.of()).bagGreen(4).build()))
			assertFalse(plan(noDiscard).getPriorities().stream().anyMatch(p -> "col.room.green".equals(p.getTask())));
	}

	@Test public void displaySeparatesInventoryAndBagColours()
	{
		Snapshot s = base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 3, BaIds.EGG_GREEN, 8))
			.bagBlue(4).groundItems(List.of(egg(ME, 2, 1))).build();
		String detail = plan(s).getDetail();
		assertTrue(detail, detail.contains("Inventory: 3 red / 8 green / 0 blue; 10 free slots"));
		assertTrue(detail, detail.contains("Bag: 0 red / 0 green / 4 blue"));
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.*;
import com.bautopilot.baautopilot.state.*;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class CollectorPhaseTest
{
 private static final int R = ArenaTiles.REGION_WAVES_1_9;
 private static final WorldPoint ME = ArenaTiles.p(R, 40, 45);
 private static final Settings SETTINGS = Settings.builder().collectorLoadAt(15).build();
 private final Planner planner = new Planner();
 static Snapshot phase(BaCall call, int reds) {
  return Snapshot.builder().tick(1000).inArena(true).role(Role.COLLECTOR).wave(3).callPeriod(1).waveTick(70)
   .listenCall(call).listenFresh(true).shoutDone(true).freeSlots(10).hp(99).maxHp(99).playerTile(ME)
   .inventory(Map.of(BaIds.EGG_RED,reds)).eggsRed(0).eggsGreen(0)
   .objects(List.of(new ObjectView(BaIds.HOPPERS[0],ME.dy(-10)),new ObjectView(BaIds.LAUNCHERS[0],ME.dy(-9))))
   .groundItems(List.of(new GroundItemView(call.getItemId(),ME.dx(1),1,false,990)))
   .penance(List.of(PenanceView.builder().npcIndex(9).type(PenanceType.RUNNER).tile(ArenaTiles.trapFood(3).dy(-6)).build())).build();
 }
 private Instruction plan(Snapshot s) { return planner.plan(s,SETTINGS); }
 private static double loadScore(Instruction ins) { return ins.getPriorities().stream().filter(p->p.getTask().equals("col.load")||p.getTask().equals("col.support")).mapToDouble(PriorityLine::getScore).max().getAsDouble(); }

 @Test public void redValueFallsSmoothlyWithReserveAndTime() {
  double prior=Double.POSITIVE_INFINITY;
  for(int reds=0;reds<28;reds++) { double value=CollectorScoring.redValue(phase(BaCall.RED_EGG,reds));assertTrue(value<prior);prior=value; }
  Snapshot s=phase(BaCall.RED_EGG,2);
  assertTrue(CollectorScoring.redValue(s.toBuilder().callPeriod(0).build())>CollectorScoring.redValue(s));
  assertTrue(CollectorScoring.redValue(s)>CollectorScoring.redValue(s.toBuilder().callPeriod(4).build()));
 }
 @Test public void theSecondRedBeatsLoadingButTheTwelfthCanYieldToAnEscaper() {
  assertEquals(Step.COL_COLLECT,plan(phase(BaCall.RED_EGG,1)).getStep());
  assertEquals(Step.COL_COLLECT,plan(phase(BaCall.RED_EGG,4)).getStep());
  assertEquals(Step.COL_LOAD,plan(phase(BaCall.RED_EGG,11)).getStep());
 }
 @Test public void lowReserveStillWinsAfterAnInterruptedTrip() {
  Instruction trip=plan(phase(BaCall.RED_EGG,11));
  Snapshot red=phase(BaCall.RED_EGG,2).toBuilder().tasks(trip.getTasks()).lastTask(trip.getTask()).lastTargetTile(trip.getTarget().getTile()).build();
  assertEquals(Step.COL_COLLECT,plan(red).getStep());
 }
 @Test public void loadingDoesNotLeadStraightIntoShootingAndReloading() {
  Snapshot stocked=phase(BaCall.RED_EGG,11);
  Instruction load=plan(stocked);assertEquals(Step.COL_LOAD,load.getStep());
  Snapshot delivered=stocked.toBuilder().inventory(Map.of(BaIds.EGG_RED,6)).eggsRed(5).playerTile(ME.dy(-10))
   .tasks(load.getTasks()).lastTask(load.getTask()).lastTargetTile(load.getTarget().getTile()).build();
  // The recorded egg is now eleven tiles away; don't chase it or fire the cannon ourselves.
  assertNotEquals(Step.COL_FIRE,plan(delivered).getStep());
  assertNotEquals(Step.COL_LOAD,plan(delivered).getStep());
  assertEquals(Step.COL_COLLECT,plan(delivered.toBuilder().groundItems(List.of(
   new GroundItemView(BaIds.EGG_RED,delivered.getPlayerTile().dx(1),1,false,990))).build()).getStep());
 }
 @Test public void smallAndDistantLoadsLoseValueWithoutAHardBatchCutoff() {
  Snapshot one=phase(BaCall.BLUE_EGG,1).toBuilder().penance(List.of()).build();
  assertTrue(loadScore(plan(one.toBuilder().inventory(Map.of(BaIds.EGG_RED,5)).build()))>loadScore(plan(one)));
  assertEquals(Step.COL_COLLECT,plan(one).getStep());
 }
 @Test public void fullInventoryCanMakeRoomAndFullHoppersCannotBeLoaded() {
  Snapshot full=phase(BaCall.RED_EGG,4).toBuilder().freeSlots(0).penance(List.of()).build();
  assertEquals(Step.COL_LOAD,plan(full).getStep());
  assertEquals(Step.COL_DISCARD,plan(full.toBuilder().inventory(Map.of(BaIds.EGG_RED,4,BaIds.EGG_BLUE,1)).build()).getStep());
  assertFalse(plan(full.toBuilder().eggsRed(5).eggsGreen(5).build()).getPriorities().stream().anyMatch(p->p.getHeadline().startsWith("Load")));
 }
 @Test public void greenCollectionWinsBeforeBlueAndGainsPressureNearCapacity() {
  Snapshot green=phase(BaCall.GREEN_EGG,5).toBuilder().penance(List.of()).build();
  assertEquals(Step.COL_COLLECT,plan(green).getStep());
  assertTrue(loadScore(plan(green.toBuilder().freeSlots(1).build()))>loadScore(plan(green.toBuilder().freeSlots(4).build())));
  assertEquals(Step.COL_LOAD,plan(green.toBuilder().freeSlots(0).build()).getStep());
 }
 @Test public void waitingForOpeningDropsBeatsPointlessCannonTrips() {
  Snapshot s=phase(BaCall.RED_EGG,2).toBuilder().groundItems(List.of()).penance(List.of())
   .inventory(Map.of(BaIds.EGG_RED,2,BaIds.EGG_BLUE,1)).build();
  assertEquals(Step.COL_FOLLOW,plan(s).getStep());
 }
 @Test public void scoreTermsAreFiniteAndExplainTheTotal() {
  Instruction decision=plan(phase(BaCall.RED_EGG,11));
  for(PriorityLine line:decision.getPriorities()) {
   assertTrue(Double.isFinite(line.getScore()));assertEquals(line.getScore(),line.getScoreTerms().values().stream().mapToDouble(Double::doubleValue).sum(),1e-8);
  }
  assertEquals(decision.getScore(),decision.getPriorities().stream().mapToDouble(PriorityLine::getScore).max().getAsDouble(),1e-8);
 }
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.*;
import com.bautopilot.baautopilot.state.*;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class CollectorProactiveTest
{
	private static final WorldPoint ME = ArenaTiles.p(ArenaTiles.REGION_WAVES_1_9, 20, 44);
	private final Planner planner = new Planner();
	private static Snapshot base()
	{
		return Snapshot.builder().tick(1000).wave(3).waveTick(100).inArena(true).role(Role.COLLECTOR)
			.collectorOpeningComplete(true).playerTile(ME).hp(77).maxHp(77).shoutDone(true)
			.listenCall(BaCall.RED_EGG).listenFresh(true).ticksToCallChange(40).freeSlots(15)
			.objects(List.of(new ObjectView(BaIds.HOPPERS[0], ME.dy(-8))))
			.groundItems(List.of(egg(BaIds.EGG_RED, ME.dx(1)))).build();
	}
	private static GroundItemView egg(int item, WorldPoint tile) { return new GroundItemView(item, tile, 1, false, 990); }
	private Instruction plan(Snapshot s) { return planner.plan(s, Settings.builder().build()); }

	@Test public void largeRedReservesSupplyTheCannonWithoutVisibleThreatsOrShooting()
	{
		for (Snapshot s : List.of(base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 12)).build(),
			base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 4)).bagRed(8).build()))
		{
			Instruction load = plan(s);
			assertEquals(Step.COL_LOAD, load.getStep());
			assertEquals("col.load", load.getTask());
			assertEquals(Tier.MAINTENANCE, load.getTier());
			assertTrue(load.getScoreTerms().get("proactive red supply") > 0);
			assertFalse(load.getDetail().contains("escaping"));
		}
		Snapshot green = base().toBuilder().listenCall(BaCall.GREEN_EGG).inventory(Map.of(BaIds.EGG_RED, 15))
			.eggsRed(2).groundItems(List.of(egg(BaIds.EGG_GREEN, ME.dx(1)))).build();
		assertEquals(Step.COL_LOAD, plan(green).getStep());
	}

	@Test public void scarcityFullHoppersAndCompletedTargetsStillMatter()
	{
		assertEquals(Step.COL_COLLECT, plan(base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 2)).build()).getStep());
		assertEquals(Step.COL_COLLECT, plan(base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 20)).eggsRed(5).build()).getStep());
		Snapshot cleared = base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 12))
			.cleared(Set.of(PenanceType.RUNNER, PenanceType.HEALER)).build();
		assertTrue(plan(cleared).getPriorities().stream().filter(p -> "col.load".equals(p.getTask()))
			.allMatch(p -> p.getScoreTerms().get("proactive red supply") == 0));
	}

	@Test public void ordinaryEggsStayLocalEvenWhenTheyAreTheOnlyDrops()
	{
		Snapshot far = base().toBuilder().groundItems(List.of(egg(BaIds.EGG_RED, ME.dx(18)))).build();
		assertNotEquals(Step.COL_COLLECT, plan(far).getStep());
		assertNotEquals(Step.COL_DISCARD, plan(far.toBuilder().freeSlots(0).inventory(Map.of(BaIds.EGG_GREEN, 20)).build()).getStep());
		Snapshot detour = base().toBuilder().groundItems(List.of(egg(BaIds.EGG_RED, ME.dx(10)))).build();
		assertTrue(plan(detour).getPriorities().stream().filter(p -> "col.collect".equals(p.getTask()))
			.allMatch(p -> p.getScoreTerms().get("distant egg detour") < 0));
		assertNotEquals(Step.COL_COLLECT, plan(base().toBuilder().walkCost(tile -> 20).build()).getStep());
	}

	@Test public void idleTimeNeverOffersACentreCheck()
	{
		Snapshot idle = base().toBuilder().listenCall(BaCall.BLUE_EGG).groundItems(List.of()).eggsRed(5).build();
		for (WorldPoint tile : List.of(ME, ME.dx(20), ME.dy(-18)))
		{
			Instruction decision = plan(idle.toBuilder().playerTile(tile).build());
			assertEquals(Step.COL_FOLLOW, decision.getStep());
			assertEquals(Target.NONE, decision.getTarget());
			assertTrue(decision.getPriorities().stream().noneMatch(p -> "col.scan".equals(p.getTask())));
		}
	}

	@Test public void oldCentreCheckHistoryCannotResumeOrRetainAMarker()
	{
		TaskMemory old = new TaskMemory(Role.COLLECTOR, 3, Map.of("col.scan", new TaskMemory.Progress(
			Target.tile(ME.dy(6), "Check centre"), TaskMemory.Status.RUNNING, "", 990, 999, 999, 0, ME)));
		Instruction decision = plan(base().toBuilder().listenCall(BaCall.BLUE_EGG).groundItems(List.of()).eggsRed(5)
			.tasks(old).lastTask("col.scan").lastTargetTile(ME.dy(6)).build());
		assertEquals(Step.COL_FOLLOW, decision.getStep());
		assertEquals(Target.NONE, decision.getTarget());
		assertFalse(decision.getTasks().getEntries().containsKey("col.scan"));
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.*;
import com.bautopilot.baautopilot.state.*;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class CollectorWaveTenTest
{
	private static final WorldPoint ME = ArenaTiles.queenCollectorWatch();
	private final Planner planner = new Planner();
	private static Snapshot base()
	{
		return Snapshot.builder().tick(1000).inArena(true).wave(10).waveTick(100).role(Role.COLLECTOR)
			.playerTile(ME).hp(77).maxHp(77).shoutDone(true).listenCall(BaCall.RED_EGG).listenFresh(true)
			.freeSlots(15).ticksToCallChange(40).objects(List.of(new ObjectView(BaIds.HOPPERS[0], ME.dx(3))))
			.groundItems(List.of(new GroundItemView(BaIds.EGG_RED, ME.dx(1), 3, false, 990))).build();
	}
	private Instruction plan(Snapshot s) { return planner.plan(s, Settings.builder().build()); }
	private static Snapshot cleared(Snapshot s)
	{
		return s.toBuilder().fighterRangerKills(WaveInfo.fightersTotal(10) + WaveInfo.rangersTotal(10))
			.runnersKilled(WaveInfo.runnersTotal(10)).healersKilled(WaveInfo.healersTotal(10)).build();
	}

	@Test public void emptyCannonGetsAnyHeldColourIncludingBlueBeforeQueenWaiting()
	{
		for (int egg : new int[]{BaIds.EGG_RED, BaIds.EGG_GREEN, BaIds.EGG_BLUE})
		{
			Instruction preload = plan(cleared(base().toBuilder().inventory(Map.of(egg, 1)).build()));
			assertEquals(Step.COL_LOAD, preload.getStep());
			assertTrue(preload.getHeadline(), preload.getHeadline().contains("Preload"));
			assertTrue(preload.getItems().contains(egg));
		}
		assertEquals(Step.COL_LOAD, plan(cleared(base().toBuilder().bagBlue(1).build())).getStep());
		for (Snapshot loaded : List.of(base().toBuilder().eggsRed(1).build(), base().toBuilder().eggsGreen(1).build(), base().toBuilder().eggsBlue(1).build()))
			assertEquals(Step.COL_QUEEN_READY, plan(cleared(loaded)).getStep());
	}

	@Test public void earlyRedsAreUsefulButStockedCannonDoesNotCausePointHoarding()
	{
		assertEquals(Step.COL_COLLECT, plan(base()).getStep());
		assertEquals(Step.COL_COLLECT, plan(base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 1)).build()).getStep());
		assertEquals(Step.COL_LOAD, plan(base().toBuilder().inventory(Map.of(BaIds.EGG_RED, 3)).build()).getStep());
		assertEquals(5, plan(base().toBuilder().groundItems(List.of(new GroundItemView(BaIds.EGG_RED, ME.dx(1), 20, false, 990))).build()).getPickupCount());
		assertEquals(2, plan(base().toBuilder().listenCall(BaCall.GREEN_EGG).groundItems(List.of(
			new GroundItemView(BaIds.EGG_GREEN, ME.dx(1), 20, false, 990))).build()).getPickupCount());
		Snapshot stocked = base().toBuilder().eggsRed(5).inventory(Map.of(BaIds.EGG_RED, 5)).build();
		assertNotEquals(Step.COL_COLLECT, plan(stocked).getStep());
		assertNotEquals(Step.COL_COLLECT, plan(stocked.toBuilder().lastTask("col.collect").lastStep(Step.COL_COLLECT)
			.lastActionTarget(Target.groundItem(BaIds.EGG_RED, ME.dx(1))).build()).getStep());
	}

	@Test public void postClearOnlyOneSafelyCalledEggIsCollectedToEnablePreloading()
	{
		Instruction collect = plan(cleared(base()));
		assertEquals(Step.COL_COLLECT, collect.getStep());
		assertEquals(1, collect.getPickupCount());
		assertNotEquals(Step.COL_COLLECT, plan(cleared(base().toBuilder().listenFresh(false).build())).getStep());
		assertNotEquals(Step.COL_COLLECT, plan(cleared(base().toBuilder().ticksToCallChange(1).build())).getStep());
		Snapshot blue = cleared(base().toBuilder().listenCall(BaCall.BLUE_EGG).groundItems(List.of(
			new GroundItemView(BaIds.EGG_BLUE, ME.dx(1), 4, false, 990))).build());
		assertEquals(Step.COL_COLLECT, plan(blue).getStep());
		assertNotEquals(Step.COL_COLLECT, plan(blue.toBuilder().eggsBlue(1).build()).getStep());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.BaAutopilotConfig;
import com.bautopilot.baautopilot.model.*;
import com.bautopilot.baautopilot.state.*;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class DefenderContinuousTest
{
	private final Settings settings = Settings.builder().safetyBait(false).build();
	private final Planner planner = new Planner();
	private static final WorldPoint FOOD = ArenaTiles.trapFood(5);
	private static Snapshot base()
	{
		return Snapshot.builder().inArena(true).tick(1000).role(Role.DEFENDER).wave(5).waveTick(100)
			.callPeriod(2).ticksToCallChange(45).shoutDone(true).listenCall(BaCall.BAIT_WORMS).listenFresh(true)
			.playerTile(FOOD).hp(77).maxHp(77).freeSlots(8).trapCharges(2).hasHammer(true).logsTaken(4)
			.inventory(Map.of(BaIds.LOGS, 2, BaCall.BAIT_WORMS.getItemId(), 8,
				BaCall.BAIT_TOFU.getItemId(), 8, BaCall.BAIT_CRACKERS.getItemId(), 8))
			.groundItems(List.of(new GroundItemView(BaCall.BAIT_WORMS.getItemId(), FOOD, 4, true, 990),
				new GroundItemView(BaCall.BAIT_WORMS.getItemId(), ArenaTiles.mainstack(5), 4, true, 990),
				new GroundItemView(BaCall.BAIT_TOFU.getItemId(), ArenaTiles.defenderPattern(5).get(2).getTile(), 1, false, 990)))
			.objects(List.of(new ObjectView(BaIds.TRAP_FULL, FOOD.dy(-1))))
			.penance(List.of(PenanceView.builder().npcIndex(1).type(PenanceType.RUNNER).tile(FOOD.dx(1)).build(),
				PenanceView.builder().npcIndex(2).type(PenanceType.RUNNER).tile(FOOD.dy(1)).build())).build();
	}
	private Instruction plan(Snapshot s) { return planner.plan(s, settings); }

	@Test public void continuousUpkeepIsTheDefaultAndMultikillsAreExplicitlyOptIn()
	{
		assertFalse(new BaAutopilotConfig() { }.defenderMultiKill());
		assertFalse(Settings.builder().build().isDefenderMultiKill());
		Instruction aside = plan(base());
		assertEquals(Step.DEF_SERVICE, aside.getStep());
		assertEquals(ArenaTiles.defenderService(5), aside.getTarget().getTile());
		Instruction advanced = planner.plan(base(), settings.toBuilder().defenderMultiKill(true).build());
		assertEquals(Step.DEF_STEP, advanced.getStep());
		assertEquals("def.step", advanced.getTask());
	}

	@Test public void brokenTrapWalksToTheRepairSpotThenFixesBeforeAnyBaitOrStickyReserve()
	{
		for (int wave : new int[]{5, 10})
		{
			WorldPoint food = ArenaTiles.trapFood(wave);
			Snapshot broken = base().toBuilder().wave(wave).trapCharges(0).playerTile(food.dx(-3))
				.lastTask("def.trapfood").groundItems(List.of()).objects(List.of(new ObjectView(BaIds.TRAP_BROKEN, food.dy(-1)))).build();
			Instruction walk = plan(broken);
			assertEquals(Step.DEF_REPAIR_POSITION, walk.getStep());
			assertEquals(food, walk.getTarget().getTile());
			assertEquals("def.repair", walk.getTask());
			assertEquals("REPAIR SPOT", walk.getStep().getTag());
			Instruction fix = plan(broken.toBuilder().playerTile(food).lastTask(walk.getTask()).build());
			assertEquals(Step.DEF_REPAIR, fix.getStep());
			assertTrue(fix.getDetail().contains("Stay on the food tile"));
		}
	}

	@Test public void repairFoodAndStepAsideHaveClearCompletionConditions()
	{
		Snapshot onFood = base().toBuilder().trapCharges(0).groundItems(List.of()).build();
		assertEquals(Step.DEF_REPAIR, plan(onFood).getStep());
		Snapshot repaired = onFood.toBuilder().trapCharges(2).lastTask("def.repair").build();
		Instruction drop = plan(repaired);
		assertEquals(Step.DEF_DROP, drop.getStep());
		assertEquals(FOOD, drop.getTarget().getTile());
		Snapshot stocked = repaired.toBuilder().groundItems(base().getGroundItems()).lastTask(drop.getTask()).build();
		assertEquals(Step.DEF_SERVICE, plan(stocked).getStep());
		Instruction watch = plan(stocked.toBuilder().playerTile(ArenaTiles.defenderService(5)).lastTask("def.clear").build());
		assertEquals(Step.DEF_WATCH, watch.getStep());
		assertEquals(Target.NONE, watch.getTarget());
	}

	@Test public void routineUncalledBaitReservesCannotPullThePlayerAwayAfterSteppingAside()
	{
		Snapshot enough = base().toBuilder().playerTile(ArenaTiles.defenderService(5)).lastTask("def.reserve")
			.inventory(Map.of(BaIds.LOGS, 2, BaCall.BAIT_WORMS.getItemId(), 8, BaCall.BAIT_TOFU.getItemId(), 1,
				BaCall.BAIT_CRACKERS.getItemId(), 8)).build();
		assertEquals(Step.DEF_WATCH, plan(enough).getStep());
		assertNotEquals("def.reserve", plan(enough).getTask());
	}

	@Test public void staleCallsNeverDropNewFoodAndOneChargeDoesNotRequestAMultikill()
	{
		Snapshot waiting = base().toBuilder().trapCharges(1).listenFresh(false).groundItems(List.of()).build();
		Instruction result = plan(waiting);
		assertEquals(Step.DEF_WAIT_CALL, result.getStep());
		assertEquals(FOOD, result.getTarget().getTile());
		assertNotEquals(Step.DEF_DROP, result.getStep());
		assertNotEquals(Step.DEF_HOLD, result.getStep());
		assertNotEquals(Step.DEF_STEP, result.getStep());
		assertFalse(result.getDetail().contains("multi-kill"));
	}

	@Test public void repairToolsAreRequestedBeforeTheRepairPosition()
	{
		Snapshot missing = base().toBuilder().trapCharges(0).hasHammer(false)
			.groundItems(List.of(new GroundItemView(BaIds.HAMMER, FOOD.dx(-5), 1, false, 990))).build();
		assertEquals(Step.DEF_HAMMER, plan(missing).getStep());
		assertTrue(plan(missing).getDetail().contains("repair"));
		assertEquals(Step.DEF_HAMMER, plan(missing.toBuilder().groundItems(List.of()).build()).getStep());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.model.DefenderGuide;
import com.bautopilot.baautopilot.state.GroundItemView;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class DefenderTargetStabilityTest
{
	private static final int REGION = ArenaTiles.REGION_WAVES_1_9;
	private static final Settings SETTINGS = Settings.builder().build();
	private final Planner planner = new Planner();

	private static WorldPoint tile(int x, int y) { return ArenaTiles.p(REGION, x, y); }
	private static GroundItemView item(int id, WorldPoint tile, int count, boolean good)
	{
		return new GroundItemView(id, tile, count, good, 1);
	}

	private static Snapshot base()
	{
		return Snapshot.builder().tick(100).inArena(true).role(Role.DEFENDER).wave(3).waveTick(10)
			.callPeriod(0).ticksToCallChange(40).listenCall(BaCall.BAIT_WORMS).listenFresh(true).shoutDone(true)
			.hp(99).maxHp(99).freeSlots(4).hasHammer(true).logsTaken(2).trapCharges(2).playerTile(tile(42, 29))
			.inventory(Map.of(BaCall.BAIT_WORMS.getItemId(), 9, BaCall.BAIT_TOFU.getItemId(), 6,
				BaCall.BAIT_CRACKERS.getItemId(), 6, BaIds.LOGS, 2))
			.objects(List.of(new ObjectView(BaIds.TRAP_FULL, ArenaTiles.trapFood(3).dy(-1)))).build();
	}

	private static Snapshot next(Snapshot s, Instruction previous, WorldPoint tile)
	{
		return s.toBuilder().tick(s.getTick() + 1).waveTick(s.getWaveTick() + 1).playerTile(tile)
			.lastTask(previous.getTask()).lastTargetTile(previous.getTarget().getTile()).tasks(previous.getTasks()).build();
	}

	private Instruction plan(Snapshot s) { return planner.plan(s, SETTINGS); }

	private static List<GroundItemView> setup()
	{
		return new ArrayList<>(List.of(item(BaCall.BAIT_WORMS.getItemId(), ArenaTiles.trapFood(3), 4, true),
			item(BaCall.BAIT_WORMS.getItemId(), ArenaTiles.mainstack(3), 4, true),
			item(BaCall.BAIT_TOFU.getItemId(), ArenaTiles.safety(3), 1, false)));
	}

	@Test
	public void passingSafetyDoesNotDivertTheTripToTrapFood()
	{
		Snapshot s = base().toBuilder().badBaitLanded(Map.of(ArenaTiles.safety(3), 1)).build();
		Instruction trap = plan(s);
		assertEquals(ArenaTiles.trapFood(3), trap.getTarget().getTile());
		for (WorldPoint position : List.of(tile(43, 31), tile(43, 33), tile(45, 35)))
		{
			s = next(s, trap, position);
			trap = plan(s);
			assertEquals(ArenaTiles.trapFood(3), trap.getTarget().getTile());
		}
		// Actual bait placement, not arrival alone, completes this spot.
		Instruction advance = plan(next(s, trap, s.getPlayerTile()).toBuilder()
			.goodBaitLanded(Map.of(ArenaTiles.trapFood(3), 4)).build());
		assertNotEquals(ArenaTiles.trapFood(3), advance.getTarget().getTile());
	}

	@Test
	public void aChosenSafetyDropPersistsUntilDoneButYieldsToTheGoodBaitDeadline()
	{
		Snapshot s = base().toBuilder().playerTile(ArenaTiles.safety(3)).build();
		Instruction safety = plan(s);
		assertEquals(ArenaTiles.safety(3), safety.getTarget().getTile());
		Snapshot farther = next(s, safety, tile(43, 33));
		assertEquals(ArenaTiles.safety(3), plan(farther).getTarget().getTile());
		assertEquals(ArenaTiles.trapFood(3), plan(farther.toBuilder().ticksToCallChange(5).build()).getTarget().getTile());
		assertEquals(ArenaTiles.trapFood(3), plan(farther.toBuilder()
			.badBaitLanded(Map.of(ArenaTiles.safety(3), 1)).build()).getTarget().getTile());
	}

	@Test
	public void missingFirstCallAndAnOwedCallKeepTheOpeningDestination()
	{
		Snapshot waiting = base().toBuilder().listenCall(null).listenFresh(false).build();
		Instruction wait = plan(waiting);
		assertEquals(Step.DEF_WAIT_CALL, wait.getStep());
		assertEquals(ArenaTiles.safety(3), wait.getTarget().getTile());
		Snapshot heard = next(waiting, wait, tile(43, 31)).toBuilder().listenCall(BaCall.BAIT_WORMS).listenFresh(true).build();
		Instruction trap = plan(heard);
		assertEquals(ArenaTiles.safety(3), trap.getTarget().getTile());
		Instruction call = plan(next(heard, trap, tile(43, 31)).toBuilder().shoutDone(false).shoutCall(BaCall.POISON_WORMS).build());
		assertEquals(Step.CALL, call.getStep());
		Instruction resume = plan(next(heard, call, tile(43, 31)));
		assertEquals(ArenaTiles.safety(3), resume.getTarget().getTile());
	}

	@Test public void safetyIsFirstEvenWhenTrapOrMainstackIsCloserOnEveryWave()
	{
		for (int wave = 1; wave <= 10; wave++)
			for (WorldPoint position : List.of(ArenaTiles.trapFood(wave), ArenaTiles.mainstack(wave)))
			{
				Snapshot s = base().toBuilder().wave(wave).playerTile(position).build();
				for (DefenderGuide guide : List.of(DefenderGuide.WIKI, DefenderGuide.GAU_CHO))
				{
					Instruction first = planner.plan(s, SETTINGS.toBuilder().defenderGuide(guide).build());
					assertEquals("wave " + wave + " " + guide, ArenaTiles.safety(wave), first.getTarget().getTile());
					assertTrue(first.isBadBait());
					assertFalse(first.getItems().contains(BaCall.BAIT_WORMS.getItemId()));
				}
			}
	}

	@Test public void noSafetyDropdownVariantsStartAtTrapAndNeverMaintainSafetyBait()
	{
		for (DefenderGuide guide : List.of(DefenderGuide.WIKI_NO_SAFETY, DefenderGuide.GAU_CHO_NO_SAFETY))
		{
			Settings settings = SETTINGS.toBuilder().defenderGuide(guide).build();
			assertFalse(settings.isSafetyBait());
			for (int wave : List.of(3, 10))
			{
				Snapshot s = base().toBuilder().wave(wave).playerTile(ArenaTiles.safety(wave)).build();
				Instruction first = planner.plan(s, settings);
				assertEquals(ArenaTiles.trapFood(wave), first.getTarget().getTile());
				assertTrue(first.getMarks().stream().noneMatch(m -> m.getLabel().startsWith("Safety")));
				Instruction wait = planner.plan(s.toBuilder().listenCall(null).listenFresh(false).build(), settings);
				assertEquals(ArenaTiles.trapFood(wave), wait.getTarget().getTile());
			}
			Snapshot later = base().toBuilder().waveTick(70).callPeriod(1).playerTile(ArenaTiles.safety(3))
				.groundItems(setup().subList(0, 2)).build();
			assertNotEquals("def.safety", planner.plan(later, settings).getTask());
			assertEquals(com.bautopilot.baautopilot.model.WaveInfo.defenderLogs(9, guide.isGauCho() ? DefenderGuide.GAU_CHO : DefenderGuide.WIKI),
				com.bautopilot.baautopilot.model.WaveInfo.defenderLogs(9, guide));
		}
	}

	@Test
	public void toolsKeepTheirSelectedItemUntilPickedUpOrNoLongerVisible()
	{
		WorldPoint hammer = tile(32, 42), log = tile(29, 46);
		List<GroundItemView> ground = setup();
		ground.add(item(BaIds.HAMMER, hammer, 1, false));
		ground.add(item(BaIds.LOGS, log, 1, false));
		Snapshot s = base().toBuilder().waveTick(70).callPeriod(1).hasHammer(false).logsTaken(0)
			.inventory(Map.of(BaCall.BAIT_WORMS.getItemId(), 9, BaCall.BAIT_TOFU.getItemId(), 6, BaCall.BAIT_CRACKERS.getItemId(), 6))
			.playerTile(hammer).groundItems(ground).build();
		Instruction first = plan(s);
		assertEquals(Step.DEF_HAMMER, first.getStep());
		Snapshot nearerLog = next(s, first, log);
		assertEquals(first.getTarget(), plan(nearerLog).getTarget());
		assertEquals(Step.DEF_LOGS, plan(nearerLog.toBuilder().hasHammer(true).build()).getStep());
		ground.removeIf(g -> g.getItemId() == BaIds.HAMMER);
		assertEquals(Step.DEF_LOGS, plan(nearerLog.toBuilder().groundItems(ground).build()).getStep());
	}

	@Test
	public void theSameLogStaysSelectedWhenAnotherLogBecomesCloser()
	{
		WorldPoint firstLog = tile(29, 46), otherLog = tile(28, 47);
		List<GroundItemView> ground = setup();
		ground.add(item(BaIds.LOGS, firstLog, 1, false));
		ground.add(item(BaIds.LOGS, otherLog, 1, false));
		Snapshot s = base().toBuilder().wave(9).waveTick(70).callPeriod(1).logsTaken(0)
			.inventory(Map.of(BaCall.BAIT_WORMS.getItemId(), 9, BaCall.BAIT_TOFU.getItemId(), 6, BaCall.BAIT_CRACKERS.getItemId(), 6))
			.playerTile(firstLog).groundItems(ground).build();
		Instruction first = plan(s);
		assertEquals(firstLog, first.getTarget().getTile());
		Snapshot moved = next(s, first, otherLog);
		assertEquals(firstLog, plan(moved).getTarget().getTile());
		ground.removeIf(g -> g.getTile().equals(firstLog));
		assertEquals(otherLog, plan(moved.toBuilder().groundItems(ground).build()).getTarget().getTile());
	}

	@Test
	public void aPatternToolsTripIsNotInterruptedByWalkingNearBadBait()
	{
		WorldPoint log = tile(29, 46);
		List<GroundItemView> ground = setup();
		ground.add(item(BaIds.LOGS, log, 1, false));
		ground.add(item(BaIds.HAMMER, tile(32, 42), 1, false));
		Snapshot s = base().toBuilder().hasHammer(false).logsTaken(0).playerTile(ArenaTiles.mainstack(3))
			.inventory(Map.of(BaCall.BAIT_WORMS.getItemId(), 9, BaCall.BAIT_TOFU.getItemId(), 6, BaCall.BAIT_CRACKERS.getItemId(), 6))
			.groundItems(ground).build();
		Instruction first = plan(s);
		assertEquals("def.pattern", first.getTask());
		assertEquals(Step.DEF_LOGS, first.getStep());
		assertEquals(first.getTarget(), plan(next(s, first, tile(31, 44))).getTarget());
	}

	@Test
	public void waitingForOpeningLogsDoesNotTurnIntoAnUnfinishedHammerDetour()
	{
		Snapshot s = base().toBuilder().wave(9).waveTick(70).callPeriod(1).hasHammer(false)
			.playerTile(ArenaTiles.logSpawn(9)).groundItems(setup()).build();
		Instruction wait = plan(s);
		assertEquals(Step.DEF_LOGS, wait.getStep());
		assertEquals(Target.Kind.TILE, wait.getTarget().getKind());
		List<GroundItemView> ground = setup();
		ground.add(item(BaIds.HAMMER, tile(32, 42), 1, false));
		Snapshot hammerVisible = next(s, wait, tile(32, 42)).toBuilder().groundItems(ground).build();
		assertEquals(wait.getTarget(), plan(hammerVisible).getTarget());
		ground.add(item(BaIds.LOGS, ArenaTiles.logSpawn(9), 1, false));
		Instruction take = plan(hammerVisible.toBuilder().groundItems(ground).build());
		assertEquals(Target.Kind.GROUND_ITEM, take.getTarget().getKind());
		assertEquals(BaIds.LOGS, take.getTarget().getId());
	}

	@Test
	public void aBrokenTrapPreemptsAnUnfinishedPatternSpot()
	{
		Snapshot s = base();
		Instruction first = plan(s);
		Instruction repair = plan(next(s, first, tile(43, 31)).toBuilder().trapCharges(0)
			.objects(List.of(new ObjectView(BaIds.TRAP_BROKEN, ArenaTiles.trapFood(3).dy(-1)))).build());
		assertEquals(Step.DEF_REPAIR_POSITION, repair.getStep());
		assertEquals(ArenaTiles.trapFood(3), repair.getTarget().getTile());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.*;
import com.bautopilot.baautopilot.state.*;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class DefenderTrapGuardTest
{
	private static final WorldPoint FOOD = ArenaTiles.trapFood(5);
	private final Planner planner = new Planner();
	private static PenanceView runner(int id, WorldPoint tile)
	{
		return PenanceView.builder().npcIndex(id).type(PenanceType.RUNNER).tile(tile).build();
	}
	private static Snapshot base()
	{
		return Snapshot.builder().inArena(true).tick(1000).role(Role.DEFENDER).wave(5).waveTick(100)
			.callPeriod(2).ticksToCallChange(45).playerTile(FOOD).hp(77).maxHp(77).freeSlots(8)
			.shoutDone(true).listenCall(BaCall.BAIT_WORMS).listenFresh(true).trapCharges(2)
			.hasHammer(true).logsTaken(3).inventory(Map.of(BaIds.LOGS, 3, BaCall.BAIT_WORMS.getItemId(), 8,
				BaCall.BAIT_CRACKERS.getItemId(), 8, BaCall.BAIT_TOFU.getItemId(), 8))
			.objects(List.of(new ObjectView(BaIds.TRAP_FULL, FOOD.dy(-1)), new ObjectView(BaIds.DEFENDER_MACHINE, FOOD.dy(-15))))
			.groundItems(List.of(new GroundItemView(BaCall.BAIT_WORMS.getItemId(), FOOD, 6, true, 990),
				new GroundItemView(BaIds.HAMMER, ArenaTiles.mainstack(5), 1, false, 990),
				new GroundItemView(BaIds.LOGS, ArenaTiles.logSpawn(5), 1, false, 990)))
			.penance(List.of(runner(1, FOOD.dx(1)), runner(2, FOOD.dy(1)))).build();
	}
	private Instruction plan(Snapshot s) { return planner.plan(s, Settings.builder().defenderMultiKill(true).build()); }
	private static Snapshot next(Snapshot s, Instruction previous)
	{
		return s.toBuilder().tick(s.getTick() + 1).waveTick(s.getWaveTick() + 1)
			.ticksToCallChange(s.getTicksToCallChange() <= 1 ? 50 : s.getTicksToCallChange() - 1)
			.lastTask(previous.getTask()).lastStep(previous.getStep()).lastTargetTile(previous.getTarget().getTile())
			.tasks(previous.getTasks()).build();
	}

	@Test public void lateAndUnseenRunnersCannotBlockAReadyBatchForever()
	{
		for (boolean unseen : List.of(false, true))
		{
			PenanceView late = runner(3, FOOD.dy(12)).toBuilder().unseen(unseen).build();
			Snapshot s = unseen ? base().toBuilder().unseenPenance(List.of(late)).build()
				: base().toBuilder().penance(List.of(runner(1, FOOD.dx(1)), runner(2, FOOD.dy(1)), late)).build();
			for (int tick = 0; tick <= DefenderPlanner.MAX_STACK_WAIT; tick++)
			{
				Instruction instruction = plan(s);
				assertEquals("tick " + tick + " unseen " + unseen,
					tick < DefenderPlanner.MAX_STACK_WAIT ? Step.DEF_HOLD : Step.DEF_STEP, instruction.getStep());
				assertEquals(0, s.getRunnersKilled());
				s = next(s, instruction);
			}
			// The release prompt survives the one-tick timer mark until the player moves.
			Instruction release = plan(s);
			assertEquals(Step.DEF_STEP, release.getStep());
			assertEquals(ArenaTiles.trapStep(5), release.getTarget().getTile());
			Snapshot beside = next(s, release).toBuilder().playerTile(ArenaTiles.trapStep(5)).build();
			Instruction waitForEating = plan(beside);
			assertEquals("Stay off the food while the runners eat", waitForEating.getHeadline());
			assertEquals(ArenaTiles.trapStep(5), waitForEating.getTarget().getTile());
			assertEquals(Step.DEF_HOLD, plan(next(beside, waitForEating).toBuilder().trapCharges(1).build()).getStep());
			assertEquals(Step.DEF_REPAIR_POSITION, plan(next(beside, waitForEating).toBuilder().trapCharges(0).build()).getStep());
		}
	}

	@Test public void aSingletonWithUnspawnedReservesEventuallyGetsToEat()
	{
		Snapshot s = base().toBuilder().trapCharges(1).penance(List.of(runner(1, FOOD.dx(1))))
			.inventory(Map.of(BaIds.LOGS, 2, BaCall.BAIT_WORMS.getItemId(), 8,
				BaCall.BAIT_TOFU.getItemId(), 8, BaCall.BAIT_CRACKERS.getItemId(), 8)).build();
		for (int tick = 0; tick < DefenderPlanner.MAX_STACK_WAIT; tick++)
		{
			Instruction hold = plan(s);
			assertEquals(Step.DEF_HOLD, hold.getStep());
			s = next(s, hold);
		}
		Instruction release = plan(s);
		assertEquals(Step.DEF_STEP, release.getStep());
		assertEquals("def.last", release.getTask());
		assertTrue(release.getHeadline().contains("waiting runner"));
		assertNotEquals(Step.DEF_STEP, plan(s.toBuilder().trapCharges(-1).build()).getStep());
	}

	@Test public void aNewArrivalGetsItsOwnGatheringWindow()
	{
		Snapshot s = base().toBuilder().unseenPenance(List.of(runner(9, FOOD.dy(15)).toBuilder().unseen(true).build())).build();
		for (int tick = 0; tick < 8; tick++) s = next(s, plan(s));
		s = s.toBuilder().penance(List.of(runner(1, FOOD.dx(1)), runner(2, FOOD.dy(1)), runner(3, FOOD.dx(-1)))).build();
		for (int tick = 0; tick < DefenderPlanner.MAX_STACK_WAIT; tick++)
		{
			Instruction hold = plan(s);
			assertEquals(Step.DEF_HOLD, hold.getStep());
			s = next(s, hold);
		}
	}

	@Test public void staleUnseenPositionsDoNotBlockOrJoinTheVisibleStack()
	{
		PenanceView unseen = runner(3, FOOD.dy(1)).toBuilder().unseen(true).unseenTicks(30).build();
		Snapshot s = base().toBuilder().unseenPenance(List.of(unseen)).build();
		assertEquals(Step.DEF_STEP, plan(s).getStep());
		assertEquals(3, s.alive(PenanceType.RUNNER).size());
		assertEquals(0, s.getRunnersKilled());
		assertNotEquals("def.step", plan(s.toBuilder().penance(List.of(runner(1, FOOD.dx(1)))).build()).getTask());
	}

	@Test public void allRemainingRunnersGatheredReleaseAtTheTimingMark()
	{
		Snapshot s = base().toBuilder().runnersKilled(WaveInfo.runnersTotal(5) - 2).build();
		Instruction release = plan(s);
		assertEquals(Step.DEF_STEP, release.getStep());
		assertEquals("def.step", release.getTask());
		assertEquals(ArenaTiles.trapStep(5), release.getTarget().getTile());
		assertNotEquals(Step.DEF_STEP, plan(s.toBuilder().trapCharges(1).build()).getStep());
		assertNotEquals(Step.DEF_STEP, plan(s.toBuilder().trapCharges(-1).build()).getStep());
	}

	@Test public void aRunnerMovingAwayDoesNotKeepTheGatheredGroupWaiting()
	{
		PenanceView escaping = runner(3, FOOD.dy(-4)).toBuilder().previousTile(FOOD.dy(-3)).observedTick(1000).build();
		Snapshot s = base().toBuilder().penance(List.of(runner(1, FOOD.dx(1)), runner(2, FOOD.dy(1)), escaping)).build();
		assertEquals(Step.DEF_STEP, plan(s).getStep());
		assertEquals(3, s.alive(PenanceType.RUNNER).size());
		assertEquals(0, s.getRunnersKilled());
		assertEquals(0, s.getUncertainRunners());
	}

	@Test public void aRunnerAlreadyFarSouthIsNotMistakenForAnIncomingRunnerOrADeath()
	{
		Snapshot s = base().toBuilder().penance(List.of(runner(1, FOOD.dx(1)), runner(2, FOOD.dy(1)), runner(3, FOOD.dy(-12)))).build();
		Instruction release = plan(s);
		assertEquals(Step.DEF_STEP, release.getStep());
		assertEquals(ArenaTiles.trapStep(5), release.getTarget().getTile());
		assertEquals(3, s.alive(PenanceType.RUNNER).size());
		assertEquals(0, s.getRunnersKilled());
		assertFalse(s.getCleared().contains(PenanceType.RUNNER));
