	@Test public void lowReservesAndStickySupplyTripsCannotBreakAnActiveHold()
	{
		Snapshot low = base().toBuilder().inventory(Map.of(BaIds.LOGS, 3, BaCall.BAIT_WORMS.getItemId(), 1,
			BaCall.BAIT_TOFU.getItemId(), 8, BaCall.BAIT_CRACKERS.getItemId(), 8)).lastTask("def.reserve")
			.penance(List.of(runner(1, FOOD.dy(4)))).build();
		assertEquals(Step.DEF_HOLD, plan(low).getStep());
		assertEquals(FOOD, plan(low).getTarget().getTile());
		assertEquals(Step.DEF_TAKE_BAIT, plan(low.toBuilder().playerTile(FOOD.dy(-5)).build()).getStep());
		assertEquals(Step.DEF_HOLD, plan(low.toBuilder().hasHammer(false).lastTask("def.tools").build()).getStep());
	}

	@Test public void holdingStillAllowsMissingKillBaitAndBrokenTrapRecovery()
	{
		Snapshot empty = base().toBuilder().groundItems(List.of()).build();
		assertEquals(Step.DEF_DROP, plan(empty).getStep());
		assertEquals(FOOD, plan(empty).getTarget().getTile());
		assertEquals(Step.DEF_TAKE_BAIT, plan(empty.toBuilder().inventory(Map.of(BaIds.LOGS, 3)).build()).getStep());
		assertEquals(Step.DEF_REPAIR, plan(base().toBuilder().trapCharges(0).objects(List.of(new ObjectView(BaIds.TRAP_BROKEN, FOOD.dy(-1)))).build()).getStep());
	}

	@Test public void finalAdjacentSingletonKeepsItsOneChargeException()
	{
		Snapshot last = base().toBuilder().trapCharges(1).runnersKilled(WaveInfo.runnersTotal(5) - 1)
			.penance(List.of(runner(1, FOOD.dx(1)))).listenFresh(false).build();
		assertEquals("def.last", plan(last).getTask());
		assertEquals(Step.DEF_STEP, plan(last).getStep());
		assertNotEquals(Step.DEF_STEP, plan(last.toBuilder().penance(List.of(runner(1, FOOD.dy(2)))).build()).getStep());
	}

	@Test public void conflictingNearbyTrapStatesNeverGrantTwoChargesByListOrder()
	{
		ObjectView full = new ObjectView(BaIds.TRAP_FULL, FOOD.dy(-1)), worn = new ObjectView(BaIds.TRAP_ONE, FOOD.dy(-1));
		assertEquals(1, RoundLogic.trapCharges(List.of(full, worn), 5));
		assertEquals(1, RoundLogic.trapCharges(List.of(worn, full), 5));
		assertEquals(0, RoundLogic.trapCharges(List.of(full, new ObjectView(BaIds.TRAP_BROKEN, FOOD.dy(-1))), 5));
		assertEquals(2, RoundLogic.trapCharges(List.of(full, new ObjectView(BaIds.TRAP_BROKEN, FOOD.dx(-30))), 5));
	}

	@Test public void opportunisticPreparationUsesOnlySurplusHeldBaitAndNeverInterruptsReadyWork()
	{
		Snapshot waiting = base().toBuilder().penance(List.of(runner(1, FOOD.dy(3)), runner(2, FOOD.dy(5)), runner(3, FOOD.dy(7))))
			.groundItems(List.of(new GroundItemView(BaCall.BAIT_WORMS.getItemId(), FOOD, 2, true, 990))).build();
		assertEquals("def.prepare", plan(waiting).getTask());
		assertEquals(FOOD, plan(waiting).getTarget().getTile());
		assertNotEquals("def.prepare", plan(waiting.toBuilder().listenFresh(false).build()).getTask());
		assertNotEquals("def.prepare", plan(waiting.toBuilder().inventory(Map.of(BaCall.BAIT_WORMS.getItemId(), 2)).build()).getTask());
		assertNotEquals("def.prepare", plan(waiting.toBuilder().playerTile(FOOD.dy(-2)).build()).getTask());
		assertNotEquals("def.prepare", plan(base()).getTask());
		assertEquals(Step.DEF_STEP, plan(base()).getStep());
		assertEquals(Step.DEF_REPAIR, plan(base().toBuilder().trapCharges(1).build()).getStep());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.HealCodeSet;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.model.WaveInfo;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class HealerCoverageTest
{
	private static final WorldPoint ME = ArenaTiles.p(ArenaTiles.REGION_WAVES_1_9, 50, 50);
	private final Planner planner = new Planner();

	private static PenanceView healer(int id, int order, int fedTick)
	{
		return PenanceView.builder().npcIndex(id).order(order).type(PenanceType.HEALER).tile(ME.dy(2))
			.lastFoodTick(fedTick).foods(fedTick < 0 ? 0 : 1).foodsThisPeriod(0).build();
	}

	private static Snapshot base()
	{
		return Snapshot.builder().tick(1000).wave(8).waveTick(110).callPeriod(2).inArena(true).role(Role.HEALER)
			.playerTile(ME).hp(99).maxHp(99).freeSlots(20).listenFresh(true).shoutDone(true)
			.listenCall(BaCall.POISON_MEAT).inventory(Map.of(BaCall.POISON_MEAT.getItemId(), 20)).build();
	}

	@Test
	public void healthyUnpoisonedHealerPreemptsAWoundedCommittedCoverageTarget()
	{
		Snapshot wounded = base().toBuilder().penance(List.of(healer(1, 1, -1).toBuilder().healthRatio(3).healthScale(30).build())).build();
		Instruction first = planner.plan(wounded, Settings.builder().build());
		Snapshot newcomer = wounded.toBuilder().tick(1001).tasks(first.getTasks()).lastTargetNpc(1).lastTask("heal.cover")
			.penance(List.of(wounded.getPenance().get(0), healer(2, 2, -1))).build();
		assertEquals(2, planner.plan(newcomer, Settings.builder().build()).getTarget().getId());
	}

	@Test
	public void weakestPoisonPreemptsPreviousTargetVisibilityAndEveryGuideSetting()
	{
		for (HealCodeSet set : HealCodeSet.values())
		{
			for (int strength = 0; strength < 3; strength++)
			{
				PenanceView weak = healer(2, 2, strength == 0 ? 890 : strength == 1 ? 920 : 945).toBuilder().unseen(true).build();
				Snapshot s = base().toBuilder().penance(List.of(healer(1, 1, 970)))
					.unseenPenance(List.of(weak)).lastTargetNpc(1).lastTask("heal.feed").build();
				assertEquals(strength, weak.nextPoisonHit(s.getTick()));
				assertEquals(set + " poison " + strength, 2, planner.plan(s, Settings.builder().healCodeSet(set).build()).getTarget().getId());
			}
		}
	}

	@Test
	public void equalUrgencyKeepsItsTargetButActualPoisonEvidenceReleasesIt()
	{
		PenanceView a = healer(1, 1, 960);
		PenanceView b = healer(2, 2, 960);
		Snapshot s = base().toBuilder().penance(List.of(a, b)).lastTargetNpc(2).build();
		assertEquals(2, planner.plan(s, Settings.builder().build()).getTarget().getId());
		s = s.toBuilder().penance(List.of(a, b.toBuilder().lastPoisonDamage(4).lastPoisonTick(1000).build())).build();
		assertEquals(1, planner.plan(s, Settings.builder().build()).getTarget().getId());
	}

	@Test
	public void codeCountsAndSpamEntriesNeverForceFullPoisonFeedsWithoutBlockedReserves()
	{
		for (HealCodeSet set : HealCodeSet.values())
		{
			for (int wave = 1; wave <= 10; wave++)
			{
				for (int period = 0; period < 3; period++)
				{
					Snapshot s = base().toBuilder().wave(wave).callPeriod(period).waveTick(period * 50 + 40)
						.healersKilled(WaveInfo.healersTotal(wave) - WaveInfo.healersInitial(wave))
						.penance(List.of(healer(1, 1, 990), healer(2, 2, 990), healer(3, 3, 990))).lastTargetNpc(3).build();
					assertEquals(4, s.getPenance().get(2).nextPoisonHit(s.getTick()));
					Instruction ins = planner.plan(s, Settings.builder().healCodeSet(set).build());
					assertNotEquals(set + " wave " + wave + " period " + period, Step.HEAL_FEED, ins.getStep());
				}
			}
		}
	}

	@Test
	public void unseenUntaggedHealerPreemptsEvenADueCodeRefresh()
	{
		for (HealCodeSet set : HealCodeSet.values())
		{
			Snapshot s = base().toBuilder().penance(List.of(healer(1, 1, 960)))
				.unseenPenance(List.of(healer(9, 7, -1).toBuilder().unseen(true).build())).lastTargetNpc(1).lastTask("heal.feed")
				.team(Map.of("Partner", Role.HEALER, "Me", Role.HEALER)).selfName("Me").build();
			Instruction initial = planner.plan(s, Settings.builder().healCodeSet(set).build());
			assertEquals("heal.cover", initial.getTask());
			assertEquals(9, initial.getTarget().getId());
			assertTrue(initial.getHeadline().contains("out of view"));
		}
	}

	@Test
	public void oneConfirmedRefreshStopsAndANewSpawnTakesOver()
	{
		Snapshot s = base().toBuilder().healersKilled(2).penance(List.of(healer(3, 3, 960))).build();
		Settings settings = Settings.builder().build();
		Instruction refresh = planner.plan(s, settings);
		assertEquals(Step.HEAL_FEED, refresh.getStep());
		assertEquals(3, refresh.getTarget().getId());
		Snapshot confirmed = s.toBuilder().tick(1001).lastTargetNpc(3).lastTask(refresh.getTask()).tasks(refresh.getTasks())
			.penance(List.of(healer(3, 3, 1001).toBuilder().foods(2).foodsThisPeriod(1).build())).build();
		assertNotEquals(Step.HEAL_FEED, planner.plan(confirmed, settings).getStep());
		Instruction next = planner.plan(confirmed.toBuilder().penance(List.of(healer(3, 3, 1001), healer(9, 7, -1))).build(), settings);
		assertEquals("heal.cover", next.getTask());
		assertEquals(9, next.getTarget().getId());
	}

	@Test
	public void enoughFoodForUpcomingFirstTagsDoesNotTriggerATopupTrip()
	{
		Snapshot s = base().toBuilder().wave(6).inventory(Map.of(BaCall.POISON_MEAT.getItemId(), 6))
			.objects(List.of(new ObjectView(com.bautopilot.baautopilot.model.BaIds.HEALER_MACHINE, ME.dy(-25))))
			.penance(List.of(healer(1, 1, 995), healer(2, 2, 995))).build();
		Instruction ins = planner.plan(s, Settings.builder().build());
		assertEquals(Step.HEAL_SUPPORT, ins.getStep());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import com.bautopilot.baautopilot.state.TeammateView;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class HealerReserveTest
{
	private static final WorldPoint ME = ArenaTiles.p(ArenaTiles.REGION_WAVES_1_9, 50, 50);
	private static final Settings SETTINGS = Settings.builder().build();
	private final Planner planner = new Planner();

	private static PenanceView healer(int order, int hpBar)
	{
		return PenanceView.builder().npcIndex(order).order(order).type(PenanceType.HEALER).tile(ME.dy(1))
			.healthRatio(hpBar).healthScale(30).foods(1).lastFoodTick(995).build();
	}

	private static Snapshot base()
	{
		return Snapshot.builder().tick(1000).inArena(true).wave(5).waveTick(40).ticksToCallChange(10)
			.role(Role.HEALER).hp(77).maxHp(77).playerTile(ME).listenCall(BaCall.POISON_MEAT)
			.listenFresh(true).shoutDone(true).inventory(Map.of(BaCall.POISON_MEAT.getItemId(), 9))
			.penance(List.of(healer(1, 10), healer(2, 23), healer(3, 25), healer(4, 28))).build();
	}

	@Test
	public void finishTheLowestHpHealerRatherThanWaitAtFourPoison()
	{
		Instruction ins = planner.plan(base(), SETTINGS);
		assertEquals(Step.HEAL_FEED, ins.getStep());
		assertEquals("heal.reserve", ins.getTask());
		assertEquals(1, ins.getTarget().getId());
		assertTrue(ins.getHeadline().startsWith("Finish healer #1"));
		assertTrue(ins.getItems().contains(BaCall.POISON_MEAT.getItemId()));
		assertTrue(ins.getDetail().contains("1 reserve"));
	}

	@Test
	public void firstTagsAndWeakPoisonPreemptTheFinishTarget()
	{
		Instruction first = planner.plan(base(), SETTINGS);
		for (int fed : new int[]{-1, 960})
		{
			Snapshot next = base().toBuilder().tasks(first.getTasks()).lastTask(first.getTask()).lastTargetNpc(1)
				.penance(List.of(healer(1, 10), healer(2, 30).toBuilder().lastFoodTick(fed).build())).build();
			Instruction chosen = planner.plan(next, SETTINGS);
			assertEquals(2, chosen.getTarget().getId());
			assertEquals(fed < 0 ? "heal.cover" : "heal.feed", chosen.getTask());
		}
	}

	@Test
	public void savesFoodForFutureTagsAndCurrentHealersPoisonWillNotFinish()
	{
		Snapshot early = base().toBuilder().wave(8).penance(List.of(healer(1, 28), healer(2, 28))).build();
		// Five still to spawn, and these two need another feed later: keep seven.
		assertEquals(7, HealerPlanner.foodToKeep(early, early.alive(PenanceType.HEALER)));
		assertEquals("heal.reserve", planner.plan(early.toBuilder().inventory(Map.of(BaCall.POISON_MEAT.getItemId(), 8)).build(), SETTINGS).getTask());
		assertNotEquals("heal.reserve", planner.plan(early.toBuilder().inventory(Map.of(BaCall.POISON_MEAT.getItemId(), 7)).build(), SETTINGS).getTask());
	}

	@Test
	public void stopsOnceTheRequiredKillOpensTheLastReserveSlot()
	{
		Snapshot next = base().toBuilder().healersKilled(1).penance(base().getPenance().subList(1, 4)).build();
		assertEquals(0, HealerPlanner.reservesWaiting(next));
		assertNotEquals(Step.HEAL_FEED, planner.plan(next, SETTINGS).getStep());
		// The reserve itself is always tagged when it appears.
		Instruction spawn = planner.plan(next.toBuilder().penance(List.of(healer(2, 20), healer(5, 30).toBuilder().lastFoodTick(-1).build())).build(), SETTINGS);
		assertEquals("heal.cover", spawn.getTask());
		assertEquals(5, spawn.getTarget().getId());
	}

	@Test
	public void multipleReservesNeedMultipleKillsAndDyingIsNotCountedTwice()
	{
		Snapshot s = base().toBuilder().wave(7).healersKilled(1).penance(List.of(
			healer(1, 0).toBuilder().dying(true).build(), healer(2, 10), healer(3, 20), healer(4, 25))).build();
		assertEquals(2, HealerPlanner.reservesWaiting(s));
		assertEquals("heal.reserve", planner.plan(s, SETTINGS).getTask());
		assertEquals(2, planner.plan(s, SETTINGS).getTarget().getId());
	}

	@Test
	public void observedReserveSpawnsAlsoProveTheirSlotsOpened()
	{
		Snapshot s = base().toBuilder().penance(List.of(healer(5, 20))).build();
		assertEquals(0, HealerPlanner.reservesWaiting(s));
		assertNotEquals("heal.reserve", planner.plan(s, SETTINGS).getTask());
		// Two reserves are already observed on wave 7, and another slot will open next hit.
		Snapshot missedKill = base().toBuilder().wave(7).healersKilled(1)
			.penance(List.of(healer(3, 20), healer(6, 2))).build();
		assertEquals(0, HealerPlanner.reservesWaiting(missedKill));
	}

	@Test
	public void noSpareFeedingForWavesWithoutReservesOrAnImminentPoisonKill()
	{
		for (int wave : new int[]{1, 2})
			assertNotEquals("heal.reserve", planner.plan(base().toBuilder().wave(wave).build(), SETTINGS).getTask());
		Snapshot dyingSoon = base().toBuilder().penance(List.of(healer(1, 2), healer(2, 25))).build();
		assertEquals(0, HealerPlanner.reservesWaiting(dyingSoon));
		assertNotEquals("heal.reserve", planner.plan(dyingSoon, SETTINGS).getTask());
	}

	@Test
	public void extraFeedingDoesNotChaseUnseenOrDistantHealersOrCrossTheCallChange()
	{
		PenanceView target = healer(1, 10);
		assertNotEquals("heal.reserve", planner.plan(base().toBuilder().penance(List.of())
			.unseenPenance(List.of(target.toBuilder().unseen(true).build())).build(), SETTINGS).getTask());
		assertNotEquals("heal.reserve", planner.plan(base().toBuilder().penance(List.of(target.toBuilder().tile(ME.dy(9)).build())).build(), SETTINGS).getTask());
		assertNotEquals("heal.reserve", planner.plan(base().toBuilder().ticksToCallChange(3).build(), SETTINGS).getTask());
		assertNotEquals("heal.reserve", planner.plan(base().toBuilder().listenFresh(false).build(), SETTINGS).getTask());
	}

	@Test
	public void smallHealthChangesKeepTheFinishTargetButALargeDifferenceReleasesIt()
	{
		Instruction first = planner.plan(base().toBuilder().penance(List.of(healer(1, 10), healer(2, 11))).build(), SETTINGS);
		Snapshot next = base().toBuilder().lastTask(first.getTask()).lastTargetNpc(1).tasks(first.getTasks())
			.penance(List.of(healer(1, 10), healer(2, 9))).build();
		assertEquals(1, planner.plan(next, SETTINGS).getTarget().getId());
		assertEquals(2, planner.plan(next.toBuilder().penance(List.of(healer(1, 20), healer(2, 7))).build(), SETTINGS).getTarget().getId());
	}

	@Test
	public void callsAndEmergencyHealingStillInterruptExtraFood()
	{
		assertEquals(Step.CALL, planner.plan(base().toBuilder().shoutCall(BaCall.BAIT_CRACKERS).shoutDone(false).build(), SETTINGS).getStep());
		Snapshot urgent = base().toBuilder().inventory(Map.of(BaCall.POISON_MEAT.getItemId(), 9, BaIds.VIAL_FULL, 1))
			.teammates(List.of(new TeammateView("Hurt", 10, 99))).build();
		assertEquals(Step.HEAL_TEAMMATE, planner.plan(urgent, SETTINGS).getStep());
	}

	@Test
	public void finishFocusSurvivesTheCallInterruptionAndClearsWhenItsSlotOpens()
	{
		Instruction started = planner.plan(base(), SETTINGS);
		Snapshot call = base().toBuilder().tasks(started.getTasks()).lastTask(started.getTask()).lastTargetNpc(1)
			.listenFresh(false).build();
		Instruction interrupted = planner.plan(call, SETTINGS);
		assertEquals(TaskMemory.Status.BLOCKED, interrupted.getTasks().getEntries().get("heal.reserve").getStatus());
		Snapshot resumed = base().toBuilder().tasks(interrupted.getTasks()).lastTask("call").lastTargetNpc(-1)
			.penance(List.of(healer(1, 10), healer(2, 9))).build();
		assertEquals(1, planner.plan(resumed, SETTINGS).getTarget().getId());
		Instruction complete = planner.plan(resumed.toBuilder().healersKilled(1).build(), SETTINGS);
		assertFalse(complete.getTasks().getEntries().containsKey("heal.reserve"));
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.state.GroundItemView;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class QueenCollectorTest
{
	private static final WorldPoint HOPPER = ArenaTiles.p(ArenaTiles.REGION_WAVE_10, 22, 34);
	private static final WorldPoint WATCH = ArenaTiles.queenCollectorWatch();
	private final Planner planner = new Planner();
	private static Snapshot base(int yellow)
	{
		return Snapshot.builder().tick(1000).inArena(true).role(Role.COLLECTOR).wave(10).waveTick(200)
			.queenAlive(true).shoutDone(true).hp(77).maxHp(77).freeSlots(20).playerTile(WATCH)
			.inventory(Map.of(BaIds.EGG_YELLOW, yellow)).team(Map.of("Zed", Role.HEALER))
			.groundItems(List.of(new GroundItemView(BaIds.EGG_YELLOW, WATCH.dx(1), 3, false, 990)))
			.objects(List.of(new ObjectView(BaIds.HOPPERS[0], HOPPER), new ObjectView(BaIds.LAUNCHERS[0], HOPPER.dx(-1))))
			.build();
	}
	private Instruction plan(Snapshot s) { return planner.plan(s, Settings.builder().build()); }

	@Test public void fiveEggDefaultFinishesCollectionBeforePassing()
	{
		for (int n = 0; n < 5; n++)
		{
			Instruction ins = plan(base(n));
			assertEquals(Step.QUEEN_COLLECT, ins.getStep());
			assertTrue(ins.getHeadline().contains(n + "/5"));
		}
		assertEquals(Step.QUEEN_PASS, plan(base(5)).getStep());
		assertEquals(Step.QUEEN_PASS, planner.plan(base(3), Settings.builder().queenEggBatch(3).build()).getStep());
		assertEquals(Step.QUEEN_PASS, plan(base(2).toBuilder().freeSlots(0).build()).getStep());
	}

	@Test public void passingKeepsFinishingTheBatchThroughInventoryDropsAndSurvival()
	{
		Instruction pass = plan(base(5));
		Snapshot partial = base(4).toBuilder().tasks(pass.getTasks()).build();
		assertEquals(Step.QUEEN_PASS, plan(partial).getStep());
		Instruction interrupted = plan(partial.toBuilder().hp(5).build());
		assertEquals(Step.RETREAT, interrupted.getStep());
		assertEquals(Step.QUEEN_PASS, plan(base(1).toBuilder().tasks(interrupted.getTasks()).build()).getStep());
		assertEquals(Step.QUEEN_COLLECT, plan(base(0).toBuilder().tasks(pass.getTasks()).build()).getStep());
	}

	@Test public void healerRecipientSurvivesRosterReorderingAndLaterBatches()
	{
		Instruction first = plan(base(5));
		assertEquals("Zed", first.getTarget().getLabel());
		Snapshot two = base(4).toBuilder().team(Map.of("Amy", Role.HEALER, "Zed", Role.HEALER)).tasks(first.getTasks()).build();
		assertEquals("Zed", plan(two).getTarget().getLabel());
		Instruction empty = plan(two.toBuilder().inventory(Map.of()).build());
		assertEquals("Zed", plan(two.toBuilder().inventory(Map.of(BaIds.EGG_YELLOW, 5)).tasks(empty.getTasks()).build()).getTarget().getLabel());
		assertEquals("Amy", plan(two.toBuilder().team(Map.of("Amy", Role.HEALER)).build()).getTarget().getLabel());
	}

	@Test public void aPartialBatchWaitsNorthForDropsInsteadOfPassingOrReturningToThePool()
	{
		Snapshot s = base(2).toBuilder().groundItems(List.of()).playerTile(WATCH.dy(-18)).build();
		Instruction watch = plan(s);
		assertEquals(Step.QUEEN_WAIT, watch.getStep());
		assertEquals(WATCH, watch.getTarget().getTile());
		assertTrue(watch.getHeadline().contains("2/5"));
		assertEquals(Target.NONE, plan(s.toBuilder().playerTile(WATCH).build()).getTarget());
	}

	@Test public void omegaDeliveryInterruptsGatheringAndPositionsForSingleLoadingByDefault()
	{
		Snapshot s = base(2).toBuilder().inventory(Map.of(BaIds.EGG_YELLOW, 2, BaIds.EGG_OMEGA, 3)).build();
		Instruction position = plan(s);
		assertEquals(Step.QUEEN_LOAD_POSITION, position.getStep());
		assertEquals(HOPPER.dy(-2), position.getTarget().getTile());
		assertTrue(position.getItems().contains(BaIds.EGG_OMEGA));
		Snapshot at = s.toBuilder().playerTile(HOPPER.dy(-2)).build();
		assertEquals(Step.QUEEN_LOAD_ONE, plan(at).getStep());
		Instruction hold = plan(at.toBuilder().eggsOmega(1).build());
		assertEquals(Step.QUEEN_WAIT, hold.getStep());
		assertTrue(hold.getItems().contains(BaIds.EGG_OMEGA));
		assertEquals(Step.QUEEN_LOAD_ONE, plan(at.toBuilder().eggsOmega(0).build()).getStep());
	}

	@Test public void bulkLoadingRequiresAnExplicitOptOut()
	{
		Snapshot s = base(0).toBuilder().inventory(Map.of(BaIds.EGG_OMEGA, 3)).build();
		assertEquals(Step.QUEEN_LOAD, planner.plan(s, Settings.builder().queenSingleLoads(false).build()).getStep());
	}

	@Test public void extraYellowsStayReservedUntilTheInitialVolleyIsFiredAndSettled()
	{
		Snapshot reserve = base(3).toBuilder().queenYellowPassed(5).build();
		assertEquals("Hold the Queen reserve", plan(reserve).getHeadline());
		assertEquals(Step.QUEEN_WAIT, plan(reserve).getStep());
		assertEquals(Step.QUEEN_COLLECT, plan(reserve.toBuilder().inventory(Map.of(BaIds.EGG_YELLOW, 1)).build()).getStep());
		assertNotEquals(Step.QUEEN_PASS, plan(reserve.toBuilder().queenOmegaFired(4).lastQueenOmegaShotTick(990).build()).getStep());
		assertNotEquals(Step.QUEEN_PASS, plan(reserve.toBuilder().queenOmegaFired(5).lastQueenOmegaShotTick(999).build()).getStep());
		Snapshot ready = reserve.toBuilder().queenOmegaFired(5).lastQueenOmegaShotTick(997).build();
		assertEquals(Step.QUEEN_PASS, plan(ready).getStep());
		assertTrue(plan(ready).getHeadline().contains("3 yellow eggs"));
		assertEquals("Queen defeated", plan(ready.toBuilder().queenDead(true).build()).getHeadline());
	}

	@Test public void initialHandoffKeepsExtrasAndReserveIsConfigurableAndFinite()
	{
		Instruction pass = plan(base(8));
		assertTrue(pass.getHeadline(), pass.getHeadline().contains("5 yellow eggs"));
		assertEquals(Step.QUEEN_WAIT, plan(base(3).toBuilder().queenYellowPassed(5).tasks(pass.getTasks()).build()).getStep());
		Snapshot empty = base(0).toBuilder().queenYellowPassed(5).build();
		Instruction two = planner.plan(empty, Settings.builder().queenEggBuffer(2).build());
		assertEquals(2, two.getPickupCount());
		assertEquals(Step.QUEEN_WAIT, planner.plan(empty, Settings.builder().queenEggBuffer(0).build()).getStep());
		assertEquals(Step.QUEEN_WAIT, plan(empty.toBuilder().queenYellowPassed(8).queenOmegaFired(5).lastQueenOmegaShotTick(990).build()).getStep());
		assertEquals(Step.QUEEN_LOAD_POSITION, plan(empty.toBuilder().inventory(Map.of(BaIds.EGG_OMEGA, 1)).build()).getStep());
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.model.WaveInfo;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.Snapshot;
import com.bautopilot.baautopilot.state.TeammateView;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class QueenHealerPlannerTest
{
	private static final WorldPoint SPRING = new WorldPoint(1877, 5409, 0);
	private static final WorldPoint CRATER = new WorldPoint(1897, 5425, 0);
	private final Planner planner = new Planner();

	private Snapshot base()
	{
		return Snapshot.builder().tick(1000).wave(10).waveTick(300).inArena(true).role(Role.HEALER)
			.queenAlive(true).shoutDone(true).hp(77).maxHp(77).playerTile(SPRING.dx(1))
			.inventory(Map.of(BaIds.VIAL_FULL, 1)).teammates(List.of(new TeammateView("Attacker", 99, 99)))
			.playerTiles(Map.of("Attacker", SPRING.dx(2)))
			.objects(List.of(new ObjectView(BaIds.SPRING, SPRING), new ObjectView(BaIds.POISON_CRATERS[0], CRATER),
				new ObjectView(BaIds.HEALER_MACHINE, SPRING.dx(15))))
			.team(Map.of("Attacker", Role.ATTACKER)).build();
	}

	private Instruction plan(Snapshot s) { return planner.plan(s, Settings.builder().build()); }

	private Snapshot after(Snapshot s, Instruction previous)
	{
		return s.toBuilder().tick(s.getTick() + 1).lastTask(previous.getTask()).lastStep(previous.getStep())
			.lastActionTarget(previous.getTarget()).lastTargetTile(previous.getTarget().getTile()).tasks(previous.getTasks()).build();
	}

	@Test
	public void healthyFillerTopUpsNeverReceiveAContinuationBonus()
	{
		Snapshot filler = base().toBuilder().teammates(List.of(new TeammateView("Attacker", 95, 99))).build();
		Instruction heal = plan(filler);
		assertEquals(Step.HEAL_TEAMMATE, heal.getStep());
		Instruction again = plan(after(filler, heal));
		assertEquals(Step.HEAL_TEAMMATE, again.getStep());
		assertEquals(0, again.getScoreTerms().get("continue current action"), .001);
		assertEquals(Step.QUEEN_DUNK, plan(after(filler, heal).toBuilder()
			.inventory(Map.of(BaIds.VIAL_FULL, 1, BaIds.EGG_YELLOW, 1)).build()).getStep());
	}

	@Test
	public void routineVialReadinessYieldsToAnEggInsteadOfHoldingItsTrip()
	{
		Snapshot filler = base().toBuilder()
			.inventory(Map.of(net.runelite.api.gameval.ItemID.BARBASSAULT_VIAL_04_3Q, 1)).build();
		Instruction refill = plan(filler);
		assertEquals(Step.HEAL_FILL_VIAL, refill.getStep());
		assertEquals(0, plan(after(filler, refill)).getScoreTerms().get("continue current action"), .001);
		assertEquals(Step.QUEEN_DUNK, plan(after(filler, refill).toBuilder()
			.inventory(Map.of(net.runelite.api.gameval.ItemID.BARBASSAULT_VIAL_04_3Q, 1, BaIds.EGG_YELLOW, 1)).build()).getStep());
	}

	@Test
	public void absoluteHpMattersMoreThanItsFractionAndSafeHpDoesNotBlockDunking()
	{
		for (int max : new int[]{77, 99})
		{
			Snapshot s = base().toBuilder().hp(47).maxHp(max).playerTile(CRATER.dx(2))
				.inventory(Map.of(BaIds.VIAL_FULL, 1, BaIds.EGG_YELLOW, 1)).build();
			assertEquals(Step.QUEEN_DUNK, plan(s).getStep());
			assertEquals(Step.RETREAT, plan(s.toBuilder().hp(29).build()).getStep());
		}
	}

	@Test
	public void aSmallHpDropDoesNotReverseAnEggTripButDangerDoes()
	{
		Snapshot s = base().toBuilder().hp(47).inventory(Map.of(BaIds.VIAL_FULL, 1, BaIds.EGG_YELLOW, 1)).build();
		Instruction dunk = plan(s);
		assertEquals(Step.QUEEN_DUNK, dunk.getStep());
		Snapshot lower = s.toBuilder().hp(45).build();
		assertEquals("Without action history the close-to-spring top-up wins", Step.RETREAT, plan(lower).getStep());
		Instruction held = plan(after(lower, dunk));
		assertEquals(Step.QUEEN_DUNK, held.getStep());
		assertTrue(held.getScoreTerms().get("continue current action") > 0);
		assertEquals(Step.RETREAT, plan(after(lower.toBuilder().hp(20).build(), dunk)).getStep());
	}

	@Test
	public void healingTargetsAlsoNeedAMeaningfulAdvantageToSwitch()
	{
		Snapshot s = base().toBuilder().teammates(List.of(new TeammateView("A", 42, 99), new TeammateView("B", 42, 99)))
			.playerTiles(Map.of("A", SPRING.dx(2), "B", SPRING.dx(2))).build();
		Instruction first = plan(s);
		assertEquals("A", first.getTarget().getLabel());
		Snapshot small = after(s, first).toBuilder()
			.playerTiles(Map.of("A", SPRING.dx(4), "B", SPRING.dx(2)))
			.teammates(List.of(new TeammateView("A", 42, 99), new TeammateView("B", 41, 99))).build();
		assertEquals("A", plan(small).getTarget().getLabel());
		assertEquals("B", plan(small.toBuilder()
			.teammates(List.of(new TeammateView("A", 42, 99), new TeammateView("B", 20, 99))).build()).getTarget().getLabel());
	}

	@Test
	public void completedStepsAndUnavailableTargetsLoseTheirContinuationBonus()
	{
		Snapshot s = base().toBuilder().inventory(Map.of(BaIds.VIAL_FULL, 1, BaIds.EGG_YELLOW, 1)).build();
		Instruction dunk = plan(s);
		Snapshot poisoned = after(s, dunk).toBuilder().inventory(Map.of(BaIds.VIAL_FULL, 1, BaIds.EGG_POISONED, 1)).build();
		Instruction pass = plan(poisoned);
		assertEquals(Step.QUEEN_PASS, pass.getStep());
		assertEquals(0, pass.getScoreTerms().get("continue current action"), .001);
		assertEquals(Step.QUEEN_WAIT, plan(after(base(), pass)).getStep());
		ObjectView nearer = new ObjectView(BaIds.POISON_CRATERS[0], SPRING.dx(2));
		Snapshot moved = after(s, dunk).toBuilder().objects(List.of(new ObjectView(BaIds.SPRING, SPRING),
			new ObjectView(BaIds.POISON_CRATERS[0], CRATER), nearer)).build();
		assertEquals(CRATER, plan(moved).getTarget().getTile());
		Instruction lost = plan(moved.toBuilder().objects(List.of(new ObjectView(BaIds.SPRING, SPRING), nearer)).build());
		assertEquals(nearer.getTile(), lost.getTarget().getTile());
		assertEquals(0, lost.getScoreTerms().get("continue current action"), .001);
	}

	@Test
	public void recentDamageAddsASmallPreferenceForWeakPlayersWithoutDominatingActualHp()
	{
		Snapshot s = base().toBuilder().teammates(List.of(new TeammateView("A", 42, 99), new TeammateView("B", 42, 99)))
			.playerTiles(Map.of("A", SPRING.dx(2), "B", SPRING.dx(2)))
			.teammateDamagePerTick(Map.of("B", 3.0)).build();
		Instruction pressured = plan(s);
		assertEquals("B", pressured.getTarget().getLabel());
		double pressure = pressured.getScoreTerms().get("recent damage pressure");
		assertTrue(pressure > 0 && pressure <= 8);
		assertEquals("A", plan(s.toBuilder().teammates(List.of(new TeammateView("A", 30, 99),
			new TeammateView("B", 48, 99))).teammateDamagePerTick(Map.of("B", 100.0)).build()).getTarget().getLabel());
		Snapshot safe = base().toBuilder().hp(47).playerTile(CRATER.dx(1)).selfDamagePerTick(100)
			.inventory(Map.of(BaIds.VIAL_FULL, 1, BaIds.EGG_YELLOW, 1)).build();
		assertEquals(Step.QUEEN_DUNK, plan(safe).getStep());
	}

	private Snapshot cleared(int wave)
	{
		return base().toBuilder().wave(wave).queenAlive(false)
			.fighterRangerKills(WaveInfo.fightersTotal(wave) + WaveInfo.rangersTotal(wave))
			.runnersKilled(WaveInfo.runnersTotal(wave)).healersKilled(WaveInfo.healersTotal(wave)).build();
	}

	@Test
	public void preQueenTopUpsNameThePlayerAndMarkTheVialAndObservedPosition()
	{
		Snapshot s = cleared(10).toBuilder().teammates(List.of(new TeammateView("Attacker", 98, 99)))
			.playerTiles(Map.of("Attacker", SPRING.dx(40))).build();
		for (boolean stack : new boolean[]{false, true})
		{
			Instruction ins = planner.plan(s, Settings.builder().queenStack(stack).build());
			assertEquals(Step.HEAL_TEAMMATE, ins.getStep());
			assertEquals("Attacker", ins.getTarget().getLabel());
			assertEquals(SPRING.dx(40), ins.getTarget().getTile());
			assertTrue(ins.getItems().contains(BaIds.VIAL_FULL));
			assertTrue(ins.getDetail().contains("Before the Queen: use the vial on Attacker"));
			assertEquals(Step.QUEEN_WAIT, planner.plan(s.toBuilder()
				.teammates(List.of(new TeammateView("Attacker", 99, 99))).build(), Settings.builder().queenStack(stack).build()).getStep());
		}
	}

	@Test
	public void preparationRefillsBeforeHealingAndEndsWhenTheQueenArrives()
	{
		Snapshot s = cleared(10).toBuilder().inventory(Map.of(BaIds.VIAL_EMPTY, 1))
			.teammates(List.of(new TeammateView("Attacker", 60, 99))).build();
		Instruction refill = plan(s);
		assertEquals(Step.HEAL_FILL_VIAL, refill.getStep());
		assertEquals(SPRING, refill.getTarget().getTile());
		assertTrue(refill.getDetail().contains("Before the Queen:"));
		Instruction heal = plan(s.toBuilder().inventory(Map.of(BaIds.VIAL_FULL, 1)).build());
		assertEquals(Step.HEAL_TEAMMATE, heal.getStep());
		assertFalse(plan(s.toBuilder().queenAlive(true).inventory(Map.of(BaIds.VIAL_FULL, 1)).build())
			.getDetail().contains("Before the Queen:"));
	}

	@Test
	public void otherCompletedWavesDoNotRequestRoutineTopUps()
	{
		for (int wave = 1; wave < 10; wave++)
		{
			Instruction ins = plan(cleared(wave).toBuilder().listenCall(BaCall.POISON_MEAT).listenFresh(true)
				.teammates(List.of(new TeammateView("Attacker", 40, 99))).build());
			assertEquals("wave " + wave, Step.HEAL_SUPPORT, ins.getStep());
			assertEquals("Wave complete", ins.getHeadline());
			assertEquals(Target.NONE, ins.getTarget());
			assertFalse(ins.getDetail().contains("Top up"));
		}
		Instruction partial = plan(base().toBuilder().queenAlive(false).listenCall(BaCall.POISON_MEAT).listenFresh(true)
			.healersKilled(WaveInfo.healersTotal(10)).build());
		assertEquals(Step.HEAL_SUPPORT, partial.getStep());
		assertFalse(partial.getDetail().contains("before the next wave"));
		assertFalse(partial.getDetail().contains("Before the Queen"));
	}

	@Test
	public void passingThePoisonedEggBeatsHealingAtFortyEightHp()
	{
		Snapshot s = base().toBuilder().inventory(Map.of(BaIds.VIAL_FULL, 1, BaIds.EGG_POISONED, 1))
			.teammates(List.of(new TeammateView("Attacker", 48, 85))).build();
		assertEquals(Step.QUEEN_PASS, plan(s).getStep());
		assertEquals(Step.HEAL_TEAMMATE, plan(s.toBuilder()
			.teammates(List.of(new TeammateView("Attacker", 38, 85))).build()).getStep());
	}

	@Test
	public void holdingEitherEggDoesNotBlockHealingAtFortyFivePercent()
	{
		for (int egg : new int[]{BaIds.EGG_YELLOW, BaIds.EGG_POISONED})
		{
			Instruction ins = plan(base().toBuilder().inventory(Map.of(BaIds.VIAL_FULL, 1, egg, 1))
				.teammates(List.of(new TeammateView("Attacker", 38, 85))).build());
			assertEquals(Step.HEAL_TEAMMATE, ins.getStep());
			assertEquals("Attacker", ins.getTarget().getLabel());
			assertEquals(SPRING.dx(2), ins.getTarget().getTile());
			assertTrue(ins.getScoreTerms().containsKey("low HP buffer"));
		}
	}

	@Test
	public void lowAbsoluteHpBeatsEggsEvenForALowerMaxHpPlayerFarAway()
	{
		Instruction ins = plan(base().toBuilder().inventory(Map.of(BaIds.VIAL_FULL, 1, BaIds.EGG_POISONED, 1))
			.teammates(List.of(new TeammateView("Attacker", 30, 50)))
			.playerTiles(Map.of("Attacker", SPRING.dx(50))).build());
		assertEquals(Step.HEAL_TEAMMATE, ins.getStep());
	}

	@Test
	public void ownLowHealthBeatsRoutineTeamCareAndHeldEggs()
	{
		for (int vial : new int[]{BaIds.VIAL_FULL, BaIds.VIAL_EMPTY})
		{
			Instruction ins = plan(base().toBuilder().hp(29).inventory(Map.of(vial, 1, BaIds.EGG_YELLOW, 1))
				.teammates(List.of(new TeammateView("Attacker", 63, 99))).build());
			assertEquals(Step.RETREAT, ins.getStep());
			assertEquals(SPRING, ins.getTarget().getTile());
		}
	}

	@Test
	public void waitingTimeTopsUpTheTeamAndSelfBeforeTheyBecomeCritical()
	{
		assertEquals(Step.HEAL_TEAMMATE, plan(base().toBuilder()
			.teammates(List.of(new TeammateView("Attacker", 85, 99))).build()).getStep());
		assertEquals(Step.RETREAT, plan(base().toBuilder().hp(64).build()).getStep());
		assertEquals(Step.HEAL_FILL_VIAL, plan(base().toBuilder()
			.inventory(Map.of(net.runelite.api.gameval.ItemID.BARBASSAULT_VIAL_04_HALF, 1)).build()).getStep());
	}

	@Test
	public void dryOrMissingVialBecomesAnImmediateCareTaskWhenSomeoneIsInDanger()
	{
		for (int vial : new int[]{BaIds.VIAL_EMPTY, -1})
		{
			Snapshot s = base().toBuilder().teammates(List.of(new TeammateView("Attacker", 15, 99)))
				.inventory(vial < 0 ? Map.of(BaIds.EGG_YELLOW, 1) : Map.of(BaIds.EGG_YELLOW, 1, vial, 1)).build();
			Instruction ins = plan(s);
			assertEquals(Step.HEAL_FILL_VIAL, ins.getStep());
			assertTrue(ins.getDetail().contains("Attacker needs it"));
			assertEquals(Urgency.HIGH, ins.getUrgency());
			assertEquals(vial < 0 ? BaIds.HEALER_MACHINE : BaIds.SPRING, ins.getTarget().getId());
		}
	}

	@Test
	public void safeEggWorkResumesAfterHealingAndDoesNotDemandAFullVial()
	{
		Snapshot holding = base().toBuilder().playerTile(CRATER.dx(1))
			.inventory(Map.of(net.runelite.api.gameval.ItemID.BARBASSAULT_VIAL_04_HALF, 1, BaIds.EGG_YELLOW, 1)).build();
		assertEquals(Step.QUEEN_DUNK, plan(holding).getStep());
		Instruction heal = plan(holding.toBuilder().teammates(List.of(new TeammateView("Attacker", 20, 99))).build());
		assertEquals(Step.HEAL_TEAMMATE, heal.getStep());
		assertEquals(Step.QUEEN_DUNK, plan(holding.toBuilder().lastTask(heal.getTask()).tasks(heal.getTasks()).build()).getStep());
		assertEquals(Step.QUEEN_PASS, plan(base().toBuilder()
			.inventory(Map.of(BaIds.VIAL_FULL, 1, BaIds.EGG_POISONED, 1)).build()).getStep());
	}

	@Test
