package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.WaveInfo;
import com.bautopilot.baautopilot.state.Snapshot;
import java.util.List;
import java.util.function.BiFunction;
import java.util.stream.Collectors;

/** Experimental decision policies for replay comparisons only; never part of the plugin jar. */
public final class StrategyPolicies
{
	private StrategyPolicies()
	{
	}

	public static BiFunction<Snapshot, Settings, Instruction> proposal(boolean strictCalls, boolean trapFirst, boolean ordinaryKills)
	{
		Planner planner = new Planner();
		DefenderPlanner defender = new DefenderPlanner();
		return (snapshot, settings) ->
		{
			Snapshot s = strictCalls && !snapshot.isListenFresh()
				? snapshot.toBuilder().listenCall(null).build() : snapshot;
			Instruction result = planner.plan(s, settings);
			boolean unclassifiedDrop = strictCalls && !snapshot.isListenFresh() && !result.getItems().isEmpty();
			if (result.getStep() == Step.DEF_RELURE && ((trapFirst && mainSetupAtRisk(s)) || unclassifiedDrop))
			{
				// Reuse real candidates; preserve call and emergency overrides from Planner.
				List<Candidate> options = defender.candidates(Planner.gate(s), settings).stream()
					.filter(c -> !DefenderPlanner.RELURE_TASK.equals(c.getTask())).collect(Collectors.toList());
				Instruction other = Chooser.choose(s, options);
				if (other != null)
				{
					result = other.toBuilder().advice(result.getAdvice()).build();
				}
			}
			if (ordinaryKills && (result.getStep() == Step.DEF_HOLD || result.getStep() == Step.DEF_STAND)
				&& s.getTrapCharges() > 0 && goodKillBait(s) > 0)
			{
				boolean blocking = ArenaTiles.trapFood(s.getWave()).equals(s.getPlayerTile());
				result = result.toBuilder().step(blocking ? Step.DEF_STEP : Step.DEF_HOLD)
					.headline(blocking ? "Step off the food: let the working trap kill" : "Wait beside the working trap")
					.detail("Experimental ordinary-kill policy: no minimum stack size or release timer")
					.target(Target.tile(ArenaTiles.trapStep(s.getWave()), "Beside trap"))
					.task("review.def.ordinary").build();
			}
			return result;
		};
	}

	public static boolean mainSetupAtRisk(Snapshot s)
	{
		return (s.getWaveTick() >= 0 && s.getWaveTick() < WaveInfo.TICKS_PER_CALL)
			|| s.getTrapCharges() <= 0 || goodKillBait(s) == 0;
	}

	public static int goodKillBait(Snapshot s)
	{
		return s.getGroundItems().stream()
			.filter(g -> BaIds.BAIT.contains(g.getItemId()) && g.isGood()
				&& ArenaTiles.trapFood(s.getWave()).equals(g.getTile()))
			.mapToInt(g -> g.getQuantity()).sum();
	}
}

package com.bautopilot.baautopilot.plan;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import com.bautopilot.baautopilot.model.BaIds;
import com.bautopilot.baautopilot.model.HealCodeSet;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import com.bautopilot.baautopilot.state.ObjectView;
import com.bautopilot.baautopilot.state.PenanceView;
import com.bautopilot.baautopilot.state.Snapshot;
import com.bautopilot.baautopilot.state.TeammateView;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class TaskMemoryTest
{
	private static final WorldPoint ME = ArenaTiles.p(ArenaTiles.REGION_WAVES_1_9, 40, 35);
	private static final Settings SETTINGS = Settings.builder().build();
	private final Planner planner = new Planner();

	private static PenanceView healer(int id, int order, boolean fed)
	{
		return PenanceView.builder().npcIndex(id).order(order).type(PenanceType.HEALER).tile(ME.dy(10))
			.foods(fed ? 1 : 0).foodsThisPeriod(fed ? 1 : 0).lastFoodTick(fed ? 100 : -1).build();
	}

	private static Snapshot healerSnapshot()
	{
		return Snapshot.builder().tick(100).inArena(true).role(Role.HEALER).wave(10).waveTick(15)
			.playerTile(ME).hp(99).maxHp(99).freeSlots(5).shoutDone(true).listenFresh(true)
			.listenCall(BaCall.POISON_TOFU).inventory(Map.of(BaCall.POISON_TOFU.getItemId(), 20, BaIds.VIAL_FULL, 1))
			.objects(List.of(new ObjectView(BaIds.HEALER_MACHINE, ME.dy(-10))))
			.penance(List.of(healer(7, 1, false), healer(8, 2, false))).build();
	}

	private static Snapshot next(Snapshot s, Instruction previous)
	{
		return s.toBuilder().tick(s.getTick() + 1).waveTick(s.getWaveTick() + 1)
			.tasks(previous.getTasks()).lastTask(previous.getTask()).lastTargetNpc(previous.getTarget().getId()).build();
	}

	@Test
	public void coverageResumesAfterCallsHealingAndRestocking()
	{
		Snapshot s = healerSnapshot();
		Instruction first = planner.plan(s, SETTINGS);
		assertEquals("heal.cover", first.getTask());
		assertEquals(7, first.getTarget().getId());

		s = next(s, first).toBuilder().shoutDone(false).shoutCall(BaCall.BAIT_TOFU).build();
		Instruction call = planner.plan(s, SETTINGS);
		assertEquals(Step.CALL, call.getStep());
		assertEquals(TaskMemory.Status.RUNNING, call.getTasks().getEntries().get("call").getStatus());
		assertEquals(TaskMemory.Status.SUSPENDED, call.getTasks().getEntries().get("heal.cover").getStatus());
		assertEquals(7, call.getTasks().target("heal.cover").getId());

		s = next(s, call).toBuilder().shoutDone(true).teammates(List.of(new TeammateView("Hurt", 5, 99))).build();
		Instruction emergency = planner.plan(s, SETTINGS);
		assertEquals(Step.HEAL_TEAMMATE, emergency.getStep());
		assertEquals(TaskMemory.Status.SUSPENDED, emergency.getTasks().getEntries().get("heal.cover").getStatus());

		// The NPC list can arrive in a different order after the interruption.
		s = next(s, emergency).toBuilder().teammates(List.of()).penance(List.of(healer(8, 2, false), healer(7, 1, false)))
			.inventory(Map.of(BaIds.VIAL_FULL, 1)).build();
		Instruction stock = planner.plan(s, SETTINGS);
		assertEquals(Step.HEAL_TAKE_FOOD, stock.getStep());
		assertEquals(TaskMemory.Status.BLOCKED, stock.getTasks().getEntries().get("heal.cover").getStatus());
		assertEquals("Waiting for correct food", stock.getTasks().getEntries().get("heal.cover").getReason());

		s = next(s, stock).toBuilder().inventory(healerSnapshot().getInventory()).build();
		Instruction resume = planner.plan(s, SETTINGS);
		assertEquals(Step.HEAL_FEED, resume.getStep());
		assertEquals(7, resume.getTarget().getId());
		assertFalse(resume.getTasks().getEntries().containsKey("heal.stock"));
		assertEquals(first.getTasks().getEntries().get("heal.cover").getStartedTick(),
			resume.getTasks().getEntries().get("heal.cover").getStartedTick());
	}

	@Test
	public void confirmationAdvancesCoverageAndStaleCallsBlockIt()
	{
		Snapshot s = healerSnapshot();
		Instruction first = planner.plan(s, SETTINGS);
		// A recommendation alone is not evidence that food landed.
		assertEquals(7, planner.plan(next(s, first), SETTINGS).getTarget().getId());
		Instruction movingNpc = planner.plan(next(s, first).toBuilder()
			.penance(List.of(healer(7, 1, false).toBuilder().tile(ME.dy(12)).build(), healer(8, 2, false))).build(), SETTINGS);
		assertEquals("The NPC walking is not our progress", 100,
			movingNpc.getTasks().getEntries().get("heal.cover").getLastProgressTick());
		s = next(s, first).toBuilder().penance(List.of(healer(7, 1, true), healer(8, 2, false)))
			.listenFresh(false).build();
		Instruction blocked = planner.plan(s, SETTINGS);
		assertNotEquals(Step.HEAL_FEED, blocked.getStep());
		assertEquals(TaskMemory.Status.BLOCKED, blocked.getTasks().getEntries().get("heal.cover").getStatus());
		assertEquals(s.getTick(), blocked.getTasks().getEntries().get("heal.cover").getLastProgressTick());
		Instruction fresh = planner.plan(next(s, blocked).toBuilder().listenFresh(true).build(), SETTINGS);
		assertEquals(8, fresh.getTarget().getId());
		Instruction complete = planner.plan(next(s, fresh).toBuilder().listenFresh(true)
			.penance(List.of(healer(7, 1, true), healer(8, 2, true))).build(), SETTINGS);
		assertFalse(complete.getTasks().getEntries().containsKey("heal.cover"));
	}

	@Test
	public void guideDelaysNeverBlockCoverageOrWeakPoisonRefreshes()
	{
		for (HealCodeSet set : Arrays.asList(HealCodeSet.REGULAR, HealCodeSet.ONE_OS, HealCodeSet.TWO_OS))
		{
			for (int wave : new int[]{6, 7, 9, 10})
			{
				Instruction first = planner.plan(healerSnapshot().toBuilder().wave(wave)
					.penance(List.of(healer(7, 1, false))).build(), SETTINGS.toBuilder().healCodeSet(set).build());
				assertEquals(set + " wave " + wave, Step.HEAL_FEED, first.getStep());
				assertEquals("heal.cover", first.getTask());
			}
		}
		Snapshot tagged = healerSnapshot().toBuilder().penance(List.of(healer(7, 1, true))).build();
		assertNotEquals(Step.HEAL_FEED, planner.plan(tagged.toBuilder().waveTick(40).build(), SETTINGS).getStep());
		tagged = tagged.toBuilder().penance(List.of(healer(7, 1, true).toBuilder().lastFoodTick(70).build())).build();
		Instruction early = planner.plan(tagged, SETTINGS);
		assertEquals(Step.HEAL_FEED, early.getStep());
		assertTrue(early.getDetail().contains("refresh once to 4"));
		Instruction due = planner.plan(tagged.toBuilder().waveTick(35).build(), SETTINGS);
		assertEquals(Step.HEAL_FEED, due.getStep());
		assertTrue(due.getDetail().contains("refresh once to 4"));
	}

	@Test
	public void invalidCoverageTargetIsReplacedAndLateSpawnsAreCovered()
	{
		Snapshot s = healerSnapshot();
		Instruction first = planner.plan(s, SETTINGS);
		Instruction replacement = planner.plan(next(s, first).toBuilder().penance(List.of(healer(8, 2, false))).build(), SETTINGS);
		assertEquals(8, replacement.getTarget().getId());
		Snapshot later = next(s, replacement).toBuilder().callPeriod(2).waveTick(130)
			.penance(List.of(healer(8, 2, true), healer(9, 6, false))).build();
		Instruction reserve = planner.plan(later, SETTINGS);
		assertEquals("heal.cover", reserve.getTask());
		assertEquals(9, reserve.getTarget().getId());
	}

	@Test
	public void interruptedTripResumesWhileCompletionIsObservedInTheBackground()
	{
		Snapshot s = healerSnapshot().toBuilder().role(Role.COLLECTOR).wave(3).penance(List.of())
			.inventory(Map.of(BaIds.EGG_RED, 3)).build();
		Candidate trip = Candidate.task(Tier.MAINTENANCE, "col.load", Instruction.builder().step(Step.COL_LOAD)
			.target(Target.tile(ME.dy(-15), "Hopper")).build());
		Candidate nearer = Candidate.task(Tier.MAINTENANCE, "other", Instruction.builder().step(Step.COL_COLLECT)
			.target(Target.tile(ME.dy(1), "Egg")).build());
		TaskMemory started = TaskMemory.empty().observe(s, SETTINGS).advance(s, SETTINGS, Chooser.choose(s, List.of(trip)));
		s = s.toBuilder().tick(101).tasks(started).inventory(Map.of(BaIds.EGG_RED, 1)).build();
		TaskMemory interrupted = started.observe(s, SETTINGS).advance(s, SETTINGS, Instruction.builder().step(Step.CALL).build());
		assertEquals(TaskMemory.Status.SUSPENDED, interrupted.getEntries().get("col.load").getStatus());
		assertEquals(101, interrupted.getEntries().get("col.load").getLastProgressTick());
		assertEquals("col.load", Chooser.choose(s.toBuilder().tasks(interrupted).lastTask("call").build(), List.of(nearer, trip)).getTask());
		// Empty inventory completes the trip even if the top instruction was still a call.
		TaskMemory complete = interrupted.observe(s.toBuilder().inventory(Map.of()).build(), SETTINGS);
		assertFalse(complete.getEntries().containsKey("col.load"));
		assertEquals("other", Chooser.choose(s.toBuilder().tasks(complete).lastTask("call").build(), List.of(nearer, trip)).getTask());
	}

	@Test
	public void fullHopperBlocksTripAndRoleWaveOrLobbyClearsCommitment()
	{
		Snapshot s = healerSnapshot();
		TaskMemory tasks = planner.plan(s, SETTINGS).getTasks();
		assertTrue(tasks.observe(s.toBuilder().inArena(false).build(), SETTINGS).getEntries().isEmpty());
		assertEquals(-1, tasks.observe(s.toBuilder().wave(9).build(), SETTINGS).lastActive("heal.cover"));
		TaskMemory collector = tasks.observe(s.toBuilder().role(Role.COLLECTOR).inventory(Map.of(BaIds.EGG_RED, 3))
			.eggsRed(5).build(), SETTINGS);
		assertFalse(collector.getEntries().containsKey("heal.cover"));
		assertEquals(TaskMemory.Status.BLOCKED, collector.getEntries().get("col.load").getStatus());
	}
}

package com.bautopilot.baautopilot.state;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.Role;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.BiFunction;
import java.lang.reflect.Method;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.widgets.Widget;
import net.runelite.api.gameval.NpcID;
import org.junit.Test;
import static org.junit.Assert.*;

public class BaTrackerIdleTest
{
	private static final class Harness
	{
		boolean instance;
		boolean activeReads;
		int region = ArenaTiles.REGION_WAVES_1_9;
		GameState state = GameState.LOGGED_IN;
		WorldPoint outside = new WorldPoint(3200, 3200, 0);
		int tick = 100;
		int playerIterations;
		final Map<String, Integer> calls = new HashMap<>();
		final Map<Integer, Widget> widgets = new HashMap<>();
		final WorldView world;
		final Player player;
		final Client client;
		final BaTracker tracker = new BaTracker();

		Harness() throws Exception
		{
			IndexedObjectSet<?> players = proxy(IndexedObjectSet.class, (method, args) ->
			{
				if (method.getName().equals("iterator")) { playerIterations++; return Collections.emptyIterator(); }
				return primitive(method.getReturnType());
			});
			world = proxy(WorldView.class, (method, args) ->
			{
				switch (method.getName())
				{
					case "isInstance": return instance;
					case "getInstanceTemplateChunks":
						int[][][] chunks = new int[4][13][13];
						WorldPoint template = WorldPoint.fromRegion(region, 50, 50, 0);
						chunks[0][6][6] = (template.getX() / 8 << 14) | (template.getY() / 8 << 3);
						return chunks;
					case "players": return players;
					default: return primitive(method.getReturnType());
				}
			});
			LocalPoint local = new LocalPoint(50 * 128 + 64, 50 * 128 + 64, world);
			player = proxy(Player.class, (method, args) ->
			{
				switch (method.getName())
				{
					case "getWorldLocation": return outside;
					case "getLocalLocation": return local;
					case "getName": return "Me";
					default: return primitive(method.getReturnType());
				}
			});
			client = proxy(Client.class, (method, args) ->
			{
				String name = method.getName();
				calls.merge(name, 1, Integer::sum);
				switch (name)
				{
					case "getGameState": return state;
					case "getTopLevelWorldView": case "getWorldView": return world;
					case "getLocalPlayer": return player;
					case "getTickCount": return tick;
					case "getWidget":
						assertTrue("HUD read outside arena/lobby", activeReads || ArenaTiles.isLobby(outside));
						return widgets.get(args.length == 1 ? (int) args[0] : ((int) args[0] << 16) | (int) args[1]);
					case "getItemContainer": case "getVarbitValue": case "getBoostedSkillLevel": case "getRealSkillLevel":
						assertTrue("Active client read while idle: " + name, activeReads); return primitive(method.getReturnType());
					default: return primitive(method.getReturnType());
				}
			});
			Field field = BaTracker.class.getDeclaredField("client");
			field.setAccessible(true);
			field.set(tracker, client);
		}

		void showWave(int wave)
		{
			widgets.clear();
			widgets.put(Role.DEFENDER.getHudGroup() << 16, widget(""));
			widgets.put((Role.DEFENDER.getHudGroup() << 16) | 5, widget("Wave " + wave));
		}

		private Widget widget(String text)
		{
			return proxy(Widget.class, (method, args) -> method.getName().equals("getText") ? text
				: method.getName().equals("getModelId") ? -1 : primitive(method.getReturnType()));
		}
	}

	@SuppressWarnings("unchecked")
	private static <T> T proxy(Class<T> type, BiFunction<Method, Object[], Object> call)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (self, method, args) ->
		{
			if (method.getDeclaringClass() == Object.class)
			{
				if (method.getName().equals("hashCode")) return System.identityHashCode(self);
				if (method.getName().equals("equals")) return self == args[0];
				return type.getSimpleName();
			}
			return call.apply(method, args);
		});
	}

	private static Object primitive(Class<?> type)
	{
		if (type == boolean.class) return false;
		if (type == int.class) return 0;
		if (type == long.class) return 0L;
		if (type == float.class) return 0F;
		if (type == double.class) return 0D;
		return null;
	}

	@Test public void aThousandIdleTicksReuseOneSnapshotWithoutScanningActiveInputs() throws Exception
	{
		Harness h = new Harness();
		Snapshot first = h.tracker.snapshot();
		for (int i = 0; i < 1000; i++)
		{
			h.tick++;
			assertSame(first, h.tracker.snapshot());
			h.tracker.onChatMessage(null);
			h.tracker.onMenuOptionClicked(null);
			h.tracker.onOverheadTextChanged(null);
			h.tracker.onHitsplatApplied(null);
			h.tracker.onActorDeath(null);
			h.tracker.onNpcSpawned(null);
			h.tracker.onNpcDespawned(null);
			h.tracker.onItemSpawned(null);
			h.tracker.onItemDespawned(null);
		}
		assertFalse(first.isInArena());
		assertEquals(0, h.playerIterations);
		assertFalse(h.calls.containsKey("getItemContainer"));
		assertFalse(h.calls.containsKey("getVarbitValue"));
		assertFalse(h.calls.containsKey("getWidget"));
	}

	@Test public void unrelatedInstancesAlsoStayIdle() throws Exception
	{
		Harness h = new Harness();
		h.instance = true;
		h.region = 12850;
		assertFalse(h.tracker.snapshot().isInArena());
		assertEquals(0, h.playerIterations);
		assertFalse(h.calls.containsKey("getItemContainer"));
	}

	@Test public void lobbyOnlyReadsTheRecruitmentWidget() throws Exception
	{
		Harness h = new Harness();
		h.outside = WorldPoint.fromRegion(ArenaTiles.REGION_LOBBY, 20, 20, 0);
		for (int i = 0; i < 10; i++) h.tracker.snapshot();
		assertEquals(Integer.valueOf(10), h.calls.get("getWidget"));
		assertEquals(0, h.playerIterations);
		assertFalse(h.calls.containsKey("getItemContainer"));
	}

	@Test public void arenaEventsBeforeTheFirstTickAreRetainedAndExitOnlyFinalisesOnce() throws Exception
	{
		Harness h = new Harness();
		h.instance = true;
		h.activeReads = true;
		NPC npc = proxy(NPC.class, (method, args) ->
		{
			switch (method.getName())
			{
				case "getId": return NpcID.BARBASSAULT_PEN_HEALER_LV1;
				case "getIndex": return 7;
				case "getLocalLocation": return h.player.getLocalLocation();
				case "getHealthRatio": case "getHealthScale": return -1;
				default: return primitive(method.getReturnType());
			}
		});
		h.tracker.onNpcSpawned(new NpcSpawned(npc));
		assertTrue(h.tracker.getNpcs().containsKey(7));
		Snapshot active = h.tracker.snapshot();
		assertTrue(active.isInArena());
		assertEquals(1, active.getPenance().size());
		assertEquals(1, h.playerIterations);
		h.instance = false;
		assertFalse(h.tracker.snapshot().isInArena());
		assertTrue(h.tracker.getNpcs().isEmpty());
		int reads = h.calls.get("getWidget");
		h.activeReads = false;
		for (int i = 0; i < 100; i++) h.tracker.snapshot();
		assertEquals(Integer.valueOf(reads), h.calls.get("getWidget"));
		assertEquals(1, h.playerIterations);
	}

	@Test public void consecutiveWavesUseTheNewHudEvenIfTheStartMessageWasMissed() throws Exception
	{
		Harness h = new Harness();
		h.instance = h.activeReads = true;
		h.showWave(1);
		assertEquals(1, h.tracker.snapshot().getWave());
		for (int wave = 2; wave <= 10; wave++)
		{
			h.instance = false;
			h.outside = WorldPoint.fromRegion(ArenaTiles.REGION_LOBBY, 20, 20, 0);
			h.tick += 10;
			assertFalse(h.tracker.snapshot().isInArena());
			h.instance = true;
			h.region = wave == 10 ? ArenaTiles.REGION_WAVE_10 : ArenaTiles.REGION_WAVES_1_9;
			h.showWave(wave);
			h.tick += 10;
			Snapshot current = h.tracker.snapshot();
			assertEquals("wave " + wave, wave, current.getWave());
			assertEquals(Role.DEFENDER, current.getRole());
			assertEquals(0, current.getWaveTick());
		}
	}

	@Test public void waveStartBeforeAnyArenaSnapshotKeepsItsOriginalClockAnchor() throws Exception
	{
		Harness h = new Harness();
		h.state = GameState.LOADING;
		GameStateChanged loading = new GameStateChanged();
		loading.setGameState(GameState.LOADING);
		h.tracker.onGameStateChanged(loading);
		h.tracker.snapshot();
		h.tracker.onChatMessage(new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "", "---- Wave: 10 ----", "", 0));
		h.tick += 4;
		h.state = GameState.LOGGED_IN;
		h.instance = h.activeReads = true;
		h.region = ArenaTiles.REGION_WAVE_10;
		h.showWave(10);
		Snapshot current = h.tracker.snapshot();
		assertEquals(10, current.getWave());
		assertEquals(3, current.getWaveTick());
	}
}

package com.bautopilot.baautopilot.state;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.BaCall;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class BaitMemoryTest
{
	private static final WorldPoint TILE = ArenaTiles.mainstack(6);
	private static final int WORMS = BaCall.BAIT_WORMS.getItemId();

	@Test public void sameTickReplacementPreservesEachDropsQualityAndAgeWithoutLandingAgain()
	{
		BaitMemory memory = new BaitMemory();
		for (boolean good : new boolean[]{true, false})
		{
			memory.despawn(new GroundItemView(WORMS, TILE, 1, good, 100), 200);
			GroundItemView restored = memory.spawn(WORMS, TILE, 1, 200, TILE, () -> {
				fail("A scene replacement is not a new drop"); return !good;
			});
			assertEquals(good, restored.isGood());
			assertEquals(100, restored.getSpawnTick());
		}
	}

	@Test public void aRealPickupAndRedropUsesTheNewCallEvenWithinTheSameTick()
	{
		BaitMemory memory = new BaitMemory();
		memory.despawn(new GroundItemView(WORMS, TILE, 1, true, 100), 200);
		memory.menu("Drop", "Worms", 200);
		GroundItemView redropped = memory.spawn(WORMS, TILE, 1, 200, TILE, () -> false);
		assertFalse(redropped.isGood());
		assertEquals(200, redropped.getSpawnTick());
	}

	@Test public void removedFoodIsNotResurrectedAcrossTicksTilesOrWaves()
	{
		BaitMemory memory = new BaitMemory();
		memory.despawn(new GroundItemView(WORMS, TILE, 1, true, 100), 200);
		assertFalse(memory.spawn(WORMS, TILE.dx(1), 1, 200, TILE, () -> false).isGood());
		assertFalse(memory.spawn(WORMS, TILE, 1, 201, TILE, () -> false).isGood());
		memory.despawn(new GroundItemView(WORMS, TILE, 1, true, 100), 202);
		memory.reset();
		assertFalse(memory.spawn(WORMS, TILE, 1, 202, TILE, () -> false).isGood());
	}
}

package com.bautopilot.baautopilot.state;

import static org.junit.Assert.assertEquals;

import com.bautopilot.baautopilot.model.PenanceType;
import org.junit.Test;

public class DamageLogTest
{
	@Test
	public void totalsAndRollingDamagePerSecond()
	{
		DamageLog d = new DamageLog();
		d.hit(1, 100, 6, true, false);
		d.hit(1, 102, 3, false, false);
		d.hit(1, 104, 2, false, true);
		d.hit(2, 104, 4, true, false);
		assertEquals(11, d.total(1));
		assertEquals(6, d.mine(1));
		assertEquals(2, d.poison(1));
		// 11 damage over the 6 s window
		assertEquals(11 / 6.0, d.dps(1, 105), 1e-9);
		assertEquals(10 / 6.0, d.myDps(105), 1e-9);
		assertEquals(15 / 6.0, d.teamDps(105), 1e-9);
		// The first two hits leave the window; totals stay
		assertEquals(2 / 6.0, d.dps(1, 112), 1e-9);
		assertEquals(11, d.total(1));
		assertEquals(10, d.myTotal());
	}

	@Test
	public void hpLeftAndTimeToKillFromDamageAndTheHealthBar()
	{
		// 12 damage took the bar to 60%: max ~30, 18 left; at 3/s, 6 s
		PenanceView p = PenanceView.builder().npcIndex(1).type(PenanceType.FIGHTER)
			.healthRatio(18).healthScale(30).damageTaken(12).dps(3).build();
		assertEquals(18, p.estimatedHpLeft());
		assertEquals(6.0, p.secondsToKill(), 1e-9);
		// Unknown before any damage or bar
		assertEquals(-1, PenanceView.builder().type(PenanceType.FIGHTER).build().estimatedHpLeft());
	}
}

package com.bautopilot.baautopilot.state;

import com.bautopilot.baautopilot.model.ArenaTiles;
import com.bautopilot.baautopilot.model.PenanceType;
import com.bautopilot.baautopilot.model.Role;
import java.util.Collections;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class DefenderAreaTest
{
	@Test
	public void occupiedHoldingTilesAreProtectedInBothArenas()
	{
		for (int wave : new int[]{3, 10})
		{
			WorldPoint food = ArenaTiles.trapFood(wave);
			Snapshot s = Snapshot.builder().inArena(true).role(Role.HEALER).wave(wave).build();
			assertEquals(food, DefenderArea.heldTile(s, List.of(food)));
			assertNull(DefenderArea.heldTile(s, List.of(food.dx(1))));
			assertNull(DefenderArea.heldTile(s.toBuilder().role(Role.DEFENDER).build(), List.of(food)));
			assertNull(DefenderArea.heldTile(s.toBuilder().inArena(false).build(), List.of(food)));
			assertNull(DefenderArea.heldTile(s.toBuilder().cleared(Collections.singleton(PenanceType.RUNNER)).build(), List.of(food)));
		}
	}

	@Test
	public void routesAndSmoothedLinesAvoidTheHoldingAreaWithoutChangingTheMap()
	{
		int[][] original = new int[11][11];
		int[][] protectedMap = DefenderArea.avoid(original, 5, 5, 1, 5, false);
		List<int[]> path = ArenaPath.find(protectedMap, 1, 5, (x, y) -> x == 9 && y == 5, 30);
		assertFalse(path.isEmpty());
		for (int[] tile : path)
		{
			assertTrue(Math.abs(tile[0] - 5) > 1 || Math.abs(tile[1] - 5) > 1);
		}
		assertTrue(ArenaPath.waypoints(protectedMap, path).size() > 2);
		for (int[] column : original)
		{
			for (int flag : column)
			{
				assertEquals(0, flag);
			}
		}
	}

	@Test
	public void healingCanApproachTheHolderWithoutSteppingOnItsTile()
	{
		int[][] map = DefenderArea.avoid(new int[11][11], 5, 5, 1, 5, true);
		List<int[]> path = ArenaPath.find(map, 1, 5,
			(x, y) -> Math.max(Math.abs(x - 5), Math.abs(y - 5)) == 1, 30);
		assertFalse(path.isEmpty());
		for (int[] tile : path)
		{
			assertFalse(tile[0] == 5 && tile[1] == 5);
		}
		assertTrue(ArenaPath.find(map, 1, 5, (x, y) -> x == 5 && y == 5, 30).isEmpty());
	}

	@Test
	public void someoneInsideTheMarginCanLeave()
	{
		for (int startX : new int[]{4, 5})
		{
			int[][] map = DefenderArea.avoid(new int[11][11], 5, 5, startX, 5, false);
			assertFalse(ArenaPath.find(map, startX, 5, (x, y) -> x == 9 && y == 5, 30).isEmpty());
		}
	}
}

package com.bautopilot.baautopilot.state;

import com.bautopilot.baautopilot.model.PenanceType;
import org.junit.Test;
import static org.junit.Assert.*;

public class HealerPoisonEvidenceTest
{
	@Test
	public void observedPoisonDoesNotInventFoodsAndCanRevealAPartnerRefresh()
	{
		HealerLedger ledger = new HealerLedger();
		ledger.spawned(42);
		ledger.endTick();
		ledger.poisonHit(42, 3, 100);
		HealerLedger.Entry e = ledger.get(42);
		assertEquals(0, e.getFoods());
		assertEquals(-1, e.getLastFoodTick());
		PenanceView h = PenanceView.builder().type(PenanceType.HEALER)
			.lastPoisonDamage(e.getLastPoisonDamage()).lastPoisonTick(e.getLastPoisonTick()).build();
		assertTrue(h.poisoned());
		assertEquals(3, h.nextPoisonHit(100));
		assertEquals(2, h.nextPoisonHit(125));
		// A newer hit is authoritative even when our last own food was long ago.
		h = h.toBuilder().lastFoodTick(0).lastPoisonDamage(4).lastPoisonTick(105).build();
		assertEquals(4, h.nextPoisonHit(105));
	}

	@Test
	public void observedWeakPoisonOverridesARecentFoodEstimateAndConfirmedFoodRestoresFour()
	{
		PenanceView h = PenanceView.builder().lastFoodTick(90).lastPoisonTick(100).lastPoisonDamage(2).build();
		assertEquals(2, h.nextPoisonHit(100));
		assertEquals(4, h.toBuilder().lastFoodTick(100).build().nextPoisonHit(100));
		h = h.toBuilder().lastFoodTick(101).build();
		assertEquals(4, h.nextPoisonHit(101));
	}

	@Test
	public void zeroAndOutOfRangeDamageDoNotBecomePoisonEvidence()
	{
		HealerLedger ledger = new HealerLedger();
		ledger.spawned(42);
		ledger.poisonHit(42, 0, 100);
		ledger.poisonHit(42, 8, 100);
		assertEquals(-1, ledger.get(42).getLastPoisonTick());
	}
}

